window.VOCES={"autores":[{"s":"seneca","n":"Séneca","r":"/recursos/voces-que-nos-habitan/autores/seneca/","y":"c. 4 a. C.–65","e":"fil","en":"Filosofía","p":"clasico","d":["Filosofía","Ética"]},{"s":"marco-aurelio","n":"Marco Aurelio","r":"/recursos/voces-que-nos-habitan/autores/marco-aurelio/","y":"121–180","e":"fil","en":"Filosofía","p":"clasico","d":["Filosofía","Ética"]},{"s":"sigmund-freud","n":"Sigmund Freud","r":"/recursos/voces-que-nos-habitan/autores/sigmund-freud/","y":"1856–1939","e":"pa","en":"Psicoanálisis","p":"moderno","d":["Psicoanálisis","Medicina","Psicología"]},{"s":"william-james","n":"William James","r":"/recursos/voces-que-nos-habitan/autores/william-james/","y":"1842–1910","e":"ini","en":"Los comienzos","p":"moderno","d":["Psicología","Filosofía","Medicina"]},{"s":"alfred-adler","n":"Alfred Adler","r":"/recursos/voces-que-nos-habitan/autores/alfred-adler/","y":"1870–1937","e":"pa","en":"Psicoanálisis","p":"moderno","d":["Psicología","Medicina","Psiquiatría"]},{"s":"otto-rank","n":"Otto Rank","r":"/recursos/voces-que-nos-habitan/autores/otto-rank/","y":"1884–1939","e":"pa","en":"Psicoanálisis","p":"moderno","d":["Psicoanálisis","Psicología"]},{"s":"karen-horney","n":"Karen Horney","r":"/recursos/voces-que-nos-habitan/autores/karen-horney/","y":"1885–1952","e":"pa","en":"Psicoanálisis","p":"moderno","d":["Psicoanálisis","Psiquiatría","Medicina"]},{"s":"platon","n":"Platón","r":"/recursos/voces-que-nos-habitan/autores/platon/","y":"c. 428–348 a. C.","e":"fil","en":"Filosofía","p":"clasico","d":["Filosofía"]},{"s":"aristoteles","n":"Aristóteles","r":"/recursos/voces-que-nos-habitan/autores/aristoteles/","y":"384–322 a. C.","e":"fil","en":"Filosofía","p":"clasico","d":["Filosofía","Ciencias naturales"]},{"s":"epicteto","n":"Epicteto","r":"/recursos/voces-que-nos-habitan/autores/epicteto/","y":"c. 50–135","e":"fil","en":"Filosofía","p":"clasico","d":["Filosofía","Ética"]},{"s":"baruch-spinoza","n":"Baruch Spinoza","r":"/recursos/voces-que-nos-habitan/autores/baruch-spinoza/","y":"1632–1677","e":"fil","en":"Filosofía","p":"moderno","d":["Filosofía"]},{"s":"immanuel-kant","n":"Immanuel Kant","r":"/recursos/voces-que-nos-habitan/autores/immanuel-kant/","y":"1724–1804","e":"fil","en":"Filosofía","p":"moderno","d":["Filosofía"]},{"s":"hegel","n":"G. W. F. Hegel","r":"/recursos/voces-que-nos-habitan/autores/hegel/","y":"1770–1831","e":"fil","en":"Filosofía","p":"moderno","d":["Filosofía"]},{"s":"arthur-schopenhauer","n":"Arthur Schopenhauer","r":"/recursos/voces-que-nos-habitan/autores/arthur-schopenhauer/","y":"1788–1860","e":"fil","en":"Filosofía","p":"moderno","d":["Filosofía"]},{"s":"soren-kierkegaard","n":"Søren Kierkegaard","r":"/recursos/voces-que-nos-habitan/autores/soren-kierkegaard/","y":"1813–1855","e":"fil","en":"Filosofía","p":"moderno","d":["Filosofía","Teología"]},{"s":"friedrich-nietzsche","n":"Friedrich Nietzsche","r":"/recursos/voces-que-nos-habitan/autores/friedrich-nietzsche/","y":"1844–1900","e":"fil","en":"Filosofía","p":"moderno","d":["Filosofía","Filología"]},{"s":"rene-descartes","n":"René Descartes","r":"/recursos/voces-que-nos-habitan/autores/rene-descartes/","y":"1596–1650","e":"fil","en":"Filosofía","p":"moderno","d":["Filosofía","Matemáticas","Ciencias naturales"]},{"s":"john-locke","n":"John Locke","r":"/recursos/voces-que-nos-habitan/autores/john-locke/","y":"1632–1704","e":"fil","en":"Filosofía","p":"moderno","d":["Filosofía","Medicina","Política"]},{"s":"buda","n":"Buda","r":"/recursos/voces-que-nos-habitan/autores/buda/","y":"s. VI–IV a. C.","e":"ori","en":"Tradiciones orientales","p":"clasico","d":["Espiritualidad","Filosofía"]},{"s":"lao-tse","n":"Lao-tse","r":"/recursos/voces-que-nos-habitan/autores/lao-tse/","y":"fechas inciertas","e":"ori","en":"Tradiciones orientales","p":"clasico","d":["Filosofía","Espiritualidad"]},{"s":"patanjali","n":"Patanjali","r":"/recursos/voces-que-nos-habitan/autores/patanjali/","y":"c. 400","e":"ori","en":"Tradiciones orientales","p":"clasico","d":["Espiritualidad","Filosofía"]},{"s":"sandor-ferenczi","n":"Sándor Ferenczi","r":"/recursos/voces-que-nos-habitan/autores/sandor-ferenczi/","y":"1873–1933","e":"pa","en":"Psicoanálisis","p":"moderno","d":["Psicoanálisis","Medicina"]},{"s":"ivan-pavlov","n":"Iván Pávlov","r":"/recursos/voces-que-nos-habitan/autores/ivan-pavlov/","y":"1849–1936","e":"cc","en":"Conductuales y cognitivos","p":"moderno","d":["Fisiología","Psicología"]},{"s":"lev-vygotsky","n":"Lev Vygotski","r":"/recursos/voces-que-nos-habitan/autores/lev-vygotsky/","y":"1896–1934","e":"des","en":"Desarrollo y apego","p":"moderno","d":["Psicología del desarrollo","Psicología"]},{"s":"wilhelm-wundt","n":"Wilhelm Wundt","r":"/recursos/voces-que-nos-habitan/autores/wilhelm-wundt/","y":"1832–1920","e":"ini","en":"Los comienzos","p":"moderno","d":["Psicología","Filosofía","Fisiología"]},{"s":"edmund-husserl","n":"Edmund Husserl","r":"/recursos/voces-que-nos-habitan/autores/edmund-husserl/","y":"1859–1938","e":"fil","en":"Filosofía","p":"moderno","d":["Filosofía","Matemática","Lógica"]}],"temas":{"conocimiento":["Conocimiento",true],"vinculos":["Vínculos",true],"conciencia":["Conciencia",true],"identidad":["Identidad",true],"infancia":["Infancia",true],"emociones":["Emociones",true],"deseo":["Deseo",true],"cuerpo":["El cuerpo",true],"habitos":["Hábitos",true],"sociedad":["Sociedad",true],"responsabilidad":["Responsabilidad",true],"libertad":["Libertad",true],"autoconocimiento":["Autoconocimiento",true],"verdad":["La verdad",true],"autoestima":["Autoestima",true],"felicidad":["Felicidad",true],"cambio":["Cambio",true],"angustia":["Angustia",true],"ira":["Ira y agresión",true],"amor":["Amor",true],"sufrimiento":["Sufrimiento",true],"terapia":["Terapia",true],"inconsciente":["Lo inconsciente",true],"miedo":["Miedo",true],"autenticidad":["Autenticidad",true],"aceptacion":["Aceptación",true],"regulacion-emocional":["Regulación emocional",true],"cultura":["Cultura",true],"sentido-de-vida":["Sentido de la vida",true],"resiliencia":["Resiliencia",true],"muerte":["La muerte",true],"atencion":["Atención",true],"educacion":["Aprender y enseñar",true],"tiempo":["El tiempo",true],"presencia":["Presencia",true],"salud-mental":["Salud mental",true],"existencia":["Existencia",true],"trascendencia":["Trascendencia",true],"transformacion-personal":["Transformación personal",true],"esperanza":["Esperanza",true],"amistad":["Amistad",true],"desarrollo-humano":["Desarrollo humano",true],"compasion":["Compasión",true],"poder":["Poder",true],"comunicacion":["Comunicación",true],"alegria":["Alegría",true],"trabajo":["Trabajo",true],"silencio":["Silencio",true],"incertidumbre":["Incertidumbre",true],"culpa":["Culpa",true],"voluntad":["Voluntad",true],"soledad":["Soledad",true],"naturaleza":["Naturaleza",true],"repeticion":["Repetición",true],"memoria":["Memoria",true],"creatividad":["Creatividad",true],"sexualidad":["Sexualidad",false],"familia":["Familia",true],"encuentro":["El encuentro",true],"duelo":["Duelo",true],"tristeza":["Tristeza",true],"perdida":["Pérdida",true],"humor":["Humor",true],"espiritualidad":["Espiritualidad",false],"gratitud":["Gratitud",false],"suenos":["Sueños",false],"trauma":["Trauma",false],"empatia":["Empatía",false],"tecnologia":["Tecnología",false],"conexion":["Conexión",false],"lenguaje":["Lenguaje",false]},"citas":[{"i":"seneca-001","a":"seneca","t":"Hacelo así, querido Lucilio: reclamate para vos mismo.","o":"Ita fac, mi Lucili: vindica te tibi","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 1, 1","te":["autoconocimiento","libertad","tiempo"]},{"i":"seneca-002","a":"seneca","t":"Una gran parte de la vida se escapa haciendo mal, la mayor parte sin hacer nada, y la vida entera haciendo otra cosa.","o":"magna pars vitae elabitur male agentibus, maxima nihil agentibus, tota vita aliud agentibus","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 1, 1","te":["tiempo","sentido-de-vida"]},{"i":"seneca-003","a":"seneca","t":"¿A quién podrás mostrarme que le dé algún valor al tiempo, que aprecie cada día, que entienda que muere cada día?","o":"Quem mihi dabis qui aliquod pretium tempori ponat, qui diem aestimet, qui intellegat se cotidie mori?","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 1, 2","te":["tiempo","muerte"]},{"i":"seneca-004","a":"seneca","t":"Todo el tiempo que quedó atrás ya lo tiene la muerte.","o":"quidquid aetatis retro est mors tenet","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 1, 2","te":["tiempo","muerte"]},{"i":"seneca-005","a":"seneca","t":"Mientras se la posterga, la vida pasa.","o":"Dum differtur vita transcurrit.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 1, 3","te":["tiempo","cambio"]},{"i":"seneca-006","a":"seneca","t":"Todo, Lucilio, es ajeno: solo el tiempo es nuestro.","o":"Omnia, Lucili, aliena sunt, tempus tantum nostrum est","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 1, 3","te":["tiempo","libertad"]},{"i":"seneca-007","a":"seneca","t":"No está en ninguna parte quien está en todas.","o":"Nusquam est qui ubique est.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 2, 2","te":["presencia","atencion"]},{"i":"seneca-008","a":"seneca","t":"No es pobre quien tiene poco, sino quien desea más.","o":"non qui parum habet, sed qui plus cupit, pauper est","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 2, 6","te":["deseo","felicidad"]},{"i":"seneca-009","a":"seneca","t":"Deliberá todo con tu amigo, pero antes deliberá sobre él.","o":"Tu vero omnia cum amico delibera, sed de ipso prius","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 3, 2","te":["amistad","vinculos"]},{"i":"seneca-010","a":"seneca","t":"Las dos cosas son un error: confiar en todos y no confiar en nadie.","o":"utrumque enim vitium est, et omnibus credere et nulli","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 3, 4","te":["vinculos","amistad"]},{"i":"seneca-011","a":"seneca","t":"Ningún bien se disfruta si no se lo comparte.","o":"nullius boni sine socio iucunda possessio est","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 6, 4","te":["amistad","alegria","encuentro"]},{"i":"seneca-012","a":"seneca","t":"Más te servirán la voz viva y la convivencia que los discursos.","o":"Plus tamen tibi et viva vox et convictus quam oratio proderit","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 6, 5","te":["encuentro","educacion"]},{"i":"seneca-013","a":"seneca","t":"Retirate en vos mismo cuanto puedas; tratá con quienes te harán mejor y recibí a quienes vos podés hacer mejores.","o":"Recede in te ipse quantum potes; cum his versare qui te meliorem facturi sunt, illos admitte quos tu potes facere meliores.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 7, 8","te":["vinculos","autoconocimiento","transformacion-personal"]},{"i":"seneca-014","a":"seneca","t":"Esto es recíproco: los seres humanos, mientras enseñan, aprenden.","o":"Mutuo ista fiunt, et homines dum docent discunt.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 7, 8","te":["educacion","encuentro"]},{"i":"seneca-015","a":"seneca","t":"Para tener por quién morir, para tener a quién seguir al exilio. (Respuesta a “¿para qué buscás un amigo?”)","o":"Ut habeam pro quo mori possim, ut habeam quem in exsilium sequar","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 9, 10","te":["amistad","amor"]},{"i":"seneca-016","a":"seneca","t":"Son más, Lucilio, las cosas que nos asustan que las que nos aplastan, y sufrimos más a menudo por la opinión que por la realidad.","o":"Plura sunt, Lucili, quae nos terrent quam quae premunt, et saepius opinione quam re laboramus.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 13, 4","te":["miedo","sufrimiento","angustia"]},{"i":"seneca-017","a":"seneca","t":"Algunas cosas nos atormentan más de lo que deberían, otras antes de lo que deberían, y otras cuando no deberían atormentarnos en absoluto.","o":"Quaedam ergo nos magis torquent quam debent, quaedam ante torquent quam debent, quaedam torquent cum omnino non debeant","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 13, 5","te":["angustia","miedo","sufrimiento"]},{"i":"seneca-018","a":"seneca","t":"La filosofía no es un arte para el público ni hecho para la ostentación: no está en las palabras sino en los hechos.","o":"Non est philosophia populare artificium nec ostentationi paratum; non in verbis sed in rebus est.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 16, 3","te":["sentido-de-vida","autenticidad"]},{"i":"seneca-019","a":"seneca","t":"La naturaleza desea poco; la opinión, lo inmenso.","o":"Exiguum natura desiderat, opinio immensum.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 16, 8","te":["deseo","felicidad"]},{"i":"seneca-020","a":"seneca","t":"¿Qué es la sabiduría? Querer siempre lo mismo y rechazar siempre lo mismo.","o":"quid est sapientia? semper idem velle atque idem nolle.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 20, 5","te":["identidad","autenticidad"]},{"i":"seneca-021","a":"seneca","t":"Antes que nada, querido Lucilio, hacé esto: aprendé a alegrarte.","o":"Hoc ante omnia fac, mi Lucili: disce gaudere.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 23, 3","te":["alegria","felicidad"]},{"i":"seneca-022","a":"seneca","t":"La verdadera alegría es una cosa seria.","o":"verum gaudium res severa est","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 23, 4","te":["alegria","felicidad"]},{"i":"seneca-023","a":"seneca","t":"Quien dice esto [“meditá sobre la muerte”] nos manda meditar sobre la libertad. Quien aprendió a morir desaprendió a servir.","o":"qui hoc dicit meditari libertatem iubet. Qui mori didicit servire dedidicit","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 26, 10","te":["muerte","libertad"]},{"i":"seneca-024","a":"seneca","t":"Una mente buena no se presta ni se compra.","o":"Bona mens nec commodatur nec emitur","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 27, 8","te":["autoconocimiento","transformacion-personal"]},{"i":"seneca-025","a":"seneca","t":"Morimos cada día: cada día se nos quita una parte de la vida, y aun cuando crecemos, la vida decrece.","o":"Cotidie morimur; cotidie enim demitur aliqua pars vitae, et tunc quoque cum crescimus vita decrescit.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 24, 20","te":["muerte","tiempo","cambio"]},{"i":"seneca-026","a":"seneca","t":"Tenés que cambiar de ánimo, no de cielo.","o":"Animum debes mutare, non caelum.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 28, 1","te":["transformacion-personal","cambio"]},{"i":"seneca-027","a":"seneca","t":"¿Te preguntás por qué esa huida no te ayuda? Huís con vos mismo.","o":"Quaeris quare te fuga ista non adiuvet? tecum fugis.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 28, 2","te":["autoconocimiento","cambio","sufrimiento"]},{"i":"seneca-028","a":"seneca","t":"Dios está cerca de vos, está con vos, está adentro.","o":"prope est a te deus, tecum est, intus est.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 41, 1","te":["trascendencia","conciencia"]},{"i":"seneca-029","a":"seneca","t":"Dentro de nosotros habita un espíritu sagrado, observador y guardián de nuestros males y nuestros bienes.","o":"sacer intra nos spiritus sedet, malorum bonorumque nostrorum observator et custos","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 41, 2","te":["conciencia","trascendencia"]},{"i":"seneca-030","a":"seneca","t":"“Son esclavos”. No: son seres humanos.","o":"'Servi sunt.' Immo homines.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 47, 1","te":["sociedad","encuentro"]},{"i":"seneca-031","a":"seneca","t":"Si querés vivir para vos, tenés que vivir para otro.","o":"alteri vivas oportet, si vis tibi vivere.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 48, 2","te":["vinculos","sentido-de-vida","encuentro"]},{"i":"seneca-032","a":"seneca","t":"Nuestro mal no viene de afuera: está dentro de nosotros, asentado en las mismas entrañas.","o":"non est extrinsecus malum nostrum: intra nos est, in visceribus ipsis sedet","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 50, 4","te":["sufrimiento","autoconocimiento"]},{"i":"seneca-033","a":"seneca","t":"Nadie es lo bastante fuerte para salir a flote solo: hace falta que alguien le tienda la mano, que alguien lo saque.","o":"Nemo per se satis valet ut emergat; oportet manum aliquis porrigat, aliquis educat.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 52, 2","te":["vinculos","terapia","resiliencia"]},{"i":"seneca-034","a":"seneca","t":"Que los ojos no estén secos al perder a un amigo, ni desborden: hay que llorar, no lamentarse a gritos.","o":"Nec sicci sint oculi amisso amico nec fluant; lacrimandum est, non plorandum.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 63, 1","te":["duelo","tristeza","perdida"]},{"i":"seneca-035","a":"seneca","t":"Aquel a quien creés perdido, solo se adelantó.","o":"quem putas perisse praemissus est","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 81, 7","te":["duelo","muerte","perdida"]},{"i":"seneca-036","a":"seneca","t":"Nadie muere sino en su día.","o":"nemo nisi suo die moritur","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 69, 6","te":["muerte"]},{"i":"seneca-037","a":"seneca","t":"Lo bueno no es vivir, sino vivir bien.","o":"non enim vivere bonum est, sed bene vivere.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 70, 4","te":["sentido-de-vida"]},{"i":"seneca-038","a":"seneca","t":"Para quien no sabe a qué puerto se dirige, ningún viento es favorable.","o":"ignoranti quem portum petat nullus suus ventus est","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 71, 3","te":["sentido-de-vida","incertidumbre"]},{"i":"seneca-039","a":"seneca","t":"Hay que aprender mientras no sepas; y si creemos al proverbio, mientras vivas.","o":"Tamdiu discendum est quamdiu nescias; si proverbio credimus, quamdiu vivas.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 74, 3","te":["educacion","desarrollo-humano"]},{"i":"seneca-040","a":"seneca","t":"El dolor es leve si la opinión no le agrega nada.","o":"levis est dolor si nihil illi opinio adiecerit","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 74, 13","te":["sufrimiento","aceptacion"]},{"i":"seneca-041","a":"seneca","t":"El ocio sin estudio es muerte y sepultura del ser humano vivo.","o":"otium sine litteris mors est et hominis vivi sepultura","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 81, 3","te":["sentido-de-vida","educacion"]},{"i":"seneca-042","a":"seneca","t":"El ser humano, cosa sagrada para el ser humano.","o":"Homo, sacra res homini","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 81, 33","te":["sociedad","encuentro"]},{"i":"seneca-043","a":"seneca","t":"Sufre más de lo necesario quien sufre antes de lo necesario.","o":"Plus dolet quam necesse est qui ante dolet quam necesse est","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 81, 8","te":["angustia","sufrimiento","miedo"]},{"i":"seneca-044","a":"seneca","t":"No tenés que estar en otra parte, sino ser otro.","o":"non aliubi sis oportet sed alius","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 81, 8","te":["transformacion-personal","cambio"]},{"i":"seneca-045","a":"seneca","t":"Considerá una gran cosa ser un solo hombre: ser siempre el mismo.","o":"Magnam rem puta unum hominem agere.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 81, 33","te":["identidad","autenticidad"]},{"i":"seneca-046","a":"seneca","t":"No es que tengamos poco tiempo, sino que perdemos mucho.","o":"Non exiguum temporis habemus, sed multum perdidimus.","l":"la","ob":"Sobre la brevedad de la vida","an":"c. 49","u":"1, 3","te":["tiempo"]},{"i":"seneca-047","a":"seneca","t":"La vida, si sabés usarla, es larga.","o":"uita, si uti scias, longa est","l":"la","ob":"Sobre la brevedad de la vida","an":"c. 49","u":"2, 1","te":["tiempo","sentido-de-vida"]},{"i":"seneca-048","a":"seneca","t":"El mayor obstáculo para vivir es la espera, que depende del mañana y pierde el hoy.","o":"Maximum uiuendi impedimentum est exspectatio, quae pendet ex crastino, perdit hodiernum.","l":"la","ob":"Sobre la brevedad de la vida","an":"c. 49","u":"9, 1","te":["tiempo","presencia"]},{"i":"seneca-049","a":"seneca","t":"Todo lo que vendrá está en lo incierto: viví ahora.","o":"Omnia quae uentura sunt in incerto iacent: protinus uiue.","l":"la","ob":"Sobre la brevedad de la vida","an":"c. 49","u":"9, 1","te":["incertidumbre","presencia","tiempo"]},{"i":"seneca-050","a":"seneca","t":"A vivir hay que aprender toda la vida y, lo que quizás te asombre más, toda la vida hay que aprender a morir.","o":"uiuere tota uita discendum est et, quod magis fortasse miraberis, tota uita discendum est mori.","l":"la","ob":"Sobre la brevedad de la vida","an":"c. 49","u":"7, 3","te":["muerte","desarrollo-humano","sentido-de-vida"]},{"i":"seneca-051","a":"seneca","t":"Nada es menos propio de una persona atareada que vivir: no hay ciencia más difícil.","o":"Nihil minus est hominis occupati quam uiuere: nullius rei difficilior scientia est.","l":"la","ob":"Sobre la brevedad de la vida","an":"c. 49","u":"7, 3","te":["tiempo","trabajo","sentido-de-vida"]},{"i":"seneca-052","a":"seneca","t":"El mayor remedio de la ira es la demora.","o":"Maximum remedium irae mora est.","l":"la","ob":"Sobre la ira","an":"c. 41","u":"Libro 2, 29, 1","te":["ira","regulacion-emocional"]},{"i":"seneca-053","a":"seneca","t":"El fuego prueba el oro; la desgracia, a los valientes.","o":"Ignis aurum probat, miseria fortes uiros.","l":"la","ob":"Sobre la providencia","an":"c. 64","u":"5, 9","te":["resiliencia","sufrimiento"]},{"i":"marco-aurelio-001","a":"marco-aurelio","t":"Empezá la mañana diciéndote: hoy me voy a encontrar con el entrometido, el desagradecido, el arrogante, el mentiroso, el envidioso, el insociable.","o":"Begin the morning by saying to thyself, I shall meet with the busybody, the ungrateful, arrogant, deceitful, envious, unsocial.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 2, 1","te":["vinculos","aceptacion"]},{"i":"marco-aurelio-002","a":"marco-aurelio","t":"Recordá cuánto tiempo hace que venís postergando estas cosas.","o":"Remember how long thou hast been putting off these things","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 2, 4","te":["tiempo","cambio"]},{"i":"marco-aurelio-003","a":"marco-aurelio","t":"Nadie pierde otra vida que la que vive ahora, ni vive otra que la que ahora pierde.","o":"no man loses any other life than this which he now lives, nor lives any other than this which he now loses","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 2, 14","te":["tiempo","presencia","muerte"]},{"i":"marco-aurelio-004","a":"marco-aurelio","t":"Cada uno vive solo este momento presente, que es un punto indivisible; todo lo demás de su vida ya pasó o es incierto.","o":"every man lives only this present time, which is an indivisible point, and that all the rest of his life is either past or it is uncertain","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 3, 10","te":["presencia","tiempo","incertidumbre"]},{"i":"marco-aurelio-005","a":"marco-aurelio","t":"En ningún lugar encuentra una persona un retiro más tranquilo y libre de inquietud que en su propia alma.","o":"nowhere either with more quiet or more freedom from trouble does a man retire than into his own soul","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 3","te":["silencio","presencia","autoconocimiento"]},{"i":"marco-aurelio-006","a":"marco-aurelio","t":"El universo es transformación; la vida, opinión.","o":"The universe is transformation: life is opinion.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 3","te":["cambio","conciencia"]},{"i":"marco-aurelio-007","a":"marco-aurelio","t":"Quitá tu opinión y se quita la queja “me hicieron daño”.","o":"Take away thy opinion, and then there is taken away the complaint, \"I have been harmed.\"","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 7","te":["sufrimiento","aceptacion"]},{"i":"marco-aurelio-008","a":"marco-aurelio","t":"No actúes como si fueras a vivir diez mil años. La muerte pende sobre vos. Mientras vivas, mientras esté en tu poder, sé bueno.","o":"Do not act as if thou wert going to live ten thousand years. Death hangs over thee. While thou livest, while it is in thy power, be good.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 17","te":["muerte","tiempo","responsabilidad"]},{"i":"marco-aurelio-009","a":"marco-aurelio","t":"Cuántas molestias se ahorra quien no mira lo que dice, hace o piensa el vecino, sino solo lo que hace él mismo.","o":"How much trouble he avoids who does not look to see what his neighbor says or does or thinks, but only to what he does himself","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 18","te":["autoconocimiento","responsabilidad"]},{"i":"marco-aurelio-010","a":"marco-aurelio","t":"Sé como el promontorio contra el que rompen sin cesar las olas: se mantiene firme y amansa la furia del agua a su alrededor.","o":"Be like the promontory against which the waves continually break, but it stands firm and tames the fury of the water around it.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 49","te":["resiliencia","regulacion-emocional"]},{"i":"marco-aurelio-011","a":"marco-aurelio","t":"Como sean tus pensamientos habituales, así será el carácter de tu mente: el alma se tiñe de sus pensamientos.","o":"Such as are thy habitual thoughts, such also will be the character of thy mind; for the soul is dyed by the thoughts.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 5, 16","te":["conciencia","habitos","identidad"]},{"i":"marco-aurelio-012","a":"marco-aurelio","t":"La mejor manera de vengarte es no volverte como quien te hizo daño.","o":"The best way of avenging thyself is not to become like","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 6, 6","te":["ira","vinculos"]},{"i":"marco-aurelio-013","a":"marco-aurelio","t":"Mirá hacia adentro. Adentro está la fuente del bien, y siempre brotará si siempre cavás.","o":"Look within. Within is the fountain of good, and it will ever bubble up, if thou wilt ever dig.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 7, 59","te":["autoconocimiento","conciencia"]},{"i":"marco-aurelio-014","a":"marco-aurelio","t":"Si algo externo te duele, no es esa cosa la que te perturba, sino tu propio juicio sobre ella.","o":"If thou art pained by any external thing, it is not this thing that disturbs thee, but thy own judgment about it.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 8, 47","te":["sufrimiento","regulacion-emocional","conciencia"]},{"i":"marco-aurelio-015","a":"marco-aurelio","t":"No sigas discutiendo cómo debe ser un hombre bueno: selo.","o":"No longer talk at all about the kind of man that a good man ought to be, but be such.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 10, 16","te":["autenticidad","responsabilidad"]},{"i":"marco-aurelio-016","a":"marco-aurelio","t":"Considerá cuánto más dolor nos causan la ira y el fastidio por esos actos que los actos mismos.","o":"consider how much more pain is brought on us by the anger and vexation caused by such acts than by the acts themselves","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 11, 18","te":["ira","sufrimiento"]},{"i":"marco-aurelio-017","a":"marco-aurelio","t":"[Cada uno se ama más que a nadie, y sin embargo] valora menos su propia opinión sobre sí que la opinión de los demás.","o":"sets less value on his own opinion of himself than on the opinion of others","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 12, 4","te":["identidad","autenticidad"]},{"i":"marco-aurelio-018","a":"marco-aurelio","t":"Cuidate de no volverte un César, de no teñirte con ese tinte.","o":"Take care that thou art not made into a Caesar, that thou art not dyed with this dye","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 6, 30","te":["poder","identidad"]},{"i":"marco-aurelio-019","a":"marco-aurelio","t":"La perfección del carácter consiste en vivir cada día como si fuera el último.","o":"The perfection of moral character consists in this, in passing every day as the last","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 7, 69","te":["muerte","presencia"]},{"i":"marco-aurelio-020","a":"marco-aurelio","t":"Los seres humanos existen los unos para los otros. Enseñales, entonces, o soportalos.","o":"Men exist for the sake of one another. Teach them then, or bear with them.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 8, 59","te":["vinculos","aceptacion"]},{"i":"marco-aurelio-021","a":"marco-aurelio","t":"Lo que es obstáculo en el camino nos ayuda en ese camino.","o":"that which is an obstacle on the road helps us on this road","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 5, 20","te":["resiliencia","cambio"]},{"i":"marco-aurelio-022","a":"marco-aurelio","t":"Cuando te ofenda la desvergüenza de alguien, preguntate enseguida: ¿es posible que no haya desvergonzados en el mundo? No es posible.","o":"When thou art offended with any man's shameless conduct, immediately ask thyself, Is it possible, then, that shameless men should not be in the world? It is not possible.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 9, 42","te":["aceptacion","ira"]},{"i":"marco-aurelio-023","a":"marco-aurelio","t":"Que no te perturbe lo que vendrá: llegarás a ello, si hace falta, con la misma razón que hoy usás para lo presente.","o":"Let not future things disturb thee, for thou wilt come to them, if it shall be necessary, having with thee the same reason which now thou usest for present things.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 7, 8","te":["incertidumbre","angustia","presencia"]},{"i":"marco-aurelio-024","a":"marco-aurelio","t":"Puesto que es posible que dejes la vida en este mismo momento, regulá cada acto y cada pensamiento en consecuencia.","o":"Since it is possible that thou mayest depart from life this very moment, regulate every act and thought accordingly.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 2, 11","te":["muerte","presencia"]},{"i":"marco-aurelio-025","a":"marco-aurelio","t":"“Ocupate de pocas cosas si querés estar tranquilo”, dice el filósofo. Pero pensá si no sería mejor decir: hacé lo necesario.","o":"Occupy thyself with few things, says the philosopher, if thou wouldst be tranquil.--But consider if it would not be better to say, Do what is necessary","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 24","te":["presencia","trabajo"]},{"i":"marco-aurelio-026","a":"marco-aurelio","t":"Si alguien puede convencerme y mostrarme que no pienso o no actúo bien, cambiaré con gusto: busco la verdad, y nadie fue jamás dañado por ella.","o":"If any man is able to convince me and show me that I do not think or act right, I will gladly change; for I seek the truth, by which no man was ever injured.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 6, 21","te":["verdad","cambio","transformacion-personal"]},{"i":"marco-aurelio-027","a":"marco-aurelio","t":"No malgastes lo que te queda de vida en pensamientos sobre los demás.","o":"Do not waste the remainder of thy life in thoughts about others","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 3, 4","te":["tiempo","autoconocimiento"]},{"i":"marco-aurelio-028","a":"marco-aurelio","t":"A la mañana, cuando te levantes de mala gana, tené presente este pensamiento: me levanto para hacer la obra de un ser humano.","o":"In the morning when thou risest unwillingly, let this thought be present,--I am rising to the work of a human being.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 5, 1","te":["trabajo","sentido-de-vida"]},{"i":"marco-aurelio-029","a":"marco-aurelio","t":"Es propio del ser humano amar incluso a quienes obran mal.","o":"It is peculiar to man to love even those who do wrong.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 7, 22","te":["amor","compasion"]},{"i":"marco-aurelio-030","a":"marco-aurelio","t":"No te perturbes pensando en la totalidad de tu vida.","o":"Do not disturb thyself by thinking of the whole of thy life.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 8, 36","te":["angustia","presencia"]},{"i":"marco-aurelio-031","a":"marco-aurelio","t":"Cuando quieras alegrarte, pensá en las virtudes de quienes viven con vos.","o":"When thou wishest to delight thyself, think of the virtues of those who live with thee","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 6, 48","te":["alegria","vinculos","gratitud"]},{"i":"marco-aurelio-032","a":"marco-aurelio","t":"Todas las cosas están entrelazadas unas con otras, y el lazo es sagrado.","o":"All things are implicated with one another, and the bond is holy","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 7, 9","te":["conexion","naturaleza"]},{"i":"marco-aurelio-033","a":"marco-aurelio","t":"De la vida humana, el tiempo es un punto y la sustancia, un flujo.","o":"Of human life the time is a point, and the substance is in a flux","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 2, 17","te":["tiempo","cambio"]},{"i":"marco-aurelio-034","a":"marco-aurelio","t":"Si algo te resulta difícil de lograr, no pienses que es imposible para el ser humano.","o":"If a thing is difficult to be accomplished by thyself, do not think that it is impossible for man","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 6, 19","te":["resiliencia"]},{"i":"marco-aurelio-035","a":"marco-aurelio","t":"No desprecies la muerte: aceptala de buen grado, porque también ella es una de las cosas que la naturaleza quiere.","o":"Do not despise death, but be well content with it, since this too is one of those things which nature wills.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 9, 3","te":["muerte","aceptacion","naturaleza"]},{"i":"marco-aurelio-036","a":"marco-aurelio","t":"Si alguien se equivoca, enseñale con amabilidad y mostrale su error.","o":"If a man is mistaken, instruct him kindly and show him his error.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 10, 4","te":["comunicacion","compasion"]},{"i":"marco-aurelio-037","a":"marco-aurelio","t":"Considerá que también vos hacés muchas cosas mal, y que sos un ser humano como los demás.","o":"consider that thou also doest many things wrong, and that thou art a man like others","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 11, 18","te":["compasion","autoconocimiento"]},{"i":"marco-aurelio-038","a":"marco-aurelio","t":"Quien obra mal, obra mal contra sí mismo.","o":"He who does wrong does wrong against himself.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 9, 4","te":["responsabilidad"]},{"i":"marco-aurelio-039","a":"marco-aurelio","t":"Tu opinión presente fundada en la comprensión, tu conducta presente orientada al bien común y tu disposición presente de contento con todo lo que sucede: eso basta.","o":"Thy present opinion founded on understanding, and thy present conduct directed to social good, and thy present disposition of contentment with everything which happens--that is enough.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 9, 6","te":["presencia","aceptacion"]},{"i":"marco-aurelio-040","a":"marco-aurelio","t":"Que no te importe tener frío o calor si estás cumpliendo tu deber.","o":"Let it make no difference to thee whether thou art cold or warm, if thou art doing thy duty","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 6, 2","te":["responsabilidad","trabajo"]},{"i":"marco-aurelio-041","a":"marco-aurelio","t":"Acostumbrate a atender con cuidado lo que dice otro y, en lo posible, a estar en la mente de quien habla.","o":"Accustom thyself to attend carefully to what is said by another, and as much as it is possible, be in the speaker's mind.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 6, 53","te":["comunicacion","encuentro","atencion"]},{"i":"marco-aurelio-042","a":"marco-aurelio","t":"Borrá la fantasía. Detené el tirón de los hilos. Limitate al presente.","o":"Wipe out the imagination. Stop the pulling of the strings. Confine thyself to the present.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 7, 29","te":["presencia","atencion"]},{"i":"marco-aurelio-043","a":"marco-aurelio","t":"A nadie le sucede nada que no esté formado por naturaleza para soportar.","o":"Nothing happens to any man which he is not formed by nature to bear.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 5, 18","te":["resiliencia","aceptacion"]},{"i":"marco-aurelio-044","a":"marco-aurelio","t":"Todo dura solo un día: lo que recuerda y lo recordado.","o":"Everything is only for a day, both that which remembers and that which is remembered.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 35","te":["tiempo","muerte"]},{"i":"marco-aurelio-045","a":"marco-aurelio","t":"Amá el oficio que aprendiste, por modesto que sea, y contentate con él.","o":"Love the art, poor as it may be, which thou hast learned, and be content with it","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 31","te":["trabajo","aceptacion"]},{"i":"marco-aurelio-046","a":"marco-aurelio","t":"El arte de vivir se parece más al del luchador que al del bailarín.","o":"The art of life is more like the wrestler's art than the dancer's","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 7, 61","te":["resiliencia","sentido-de-vida"]},{"i":"marco-aurelio-047","a":"marco-aurelio","t":"Que haya serenidad frente a lo que viene de una causa externa.","o":"Let there be freedom from perturbations with respect to the things which come from the external cause","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 9, 31","te":["regulacion-emocional","aceptacion"]},{"i":"marco-aurelio-048","a":"marco-aurelio","t":"Retirate en vos mismo. La razón que gobierna tiene esta naturaleza: se contenta consigo cuando obra con justicia, y así asegura la tranquilidad.","o":"Retire into thyself. The rational principle which rules has this nature, that it is content with itself when it does what is just, and so secures tranquillity.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 7, 28","te":["silencio","autoconocimiento"]},{"i":"marco-aurelio-049","a":"marco-aurelio","t":"No es justo ofenderse con los demás: tu deber es cuidarlos y soportarlos con dulzura.","o":"it is no way right to be offended with men, but it is thy duty to care for them and to bear with them gently","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 9, 3","te":["vinculos","compasion"]},{"i":"marco-aurelio-050","a":"marco-aurelio","t":"Qué ridículo y qué extraño a la vida es quien se sorprende de cualquier cosa que sucede en ella.","o":"How ridiculous and what a stranger he is who is surprised at anything which happens in life.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 12, 13","te":["aceptacion","existencia"]},{"i":"sigmund-freud-001","a":"sigmund-freud","t":"La intención de que el ser humano sea “feliz” no está contenida en el plan de la “Creación”.","o":"die Absicht, daß der Mensch \"glücklich\" sei, ist im Plan der \"Schöpfung\" nicht enthalten","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["felicidad","sufrimiento"]},{"i":"sigmund-freud-002","a":"sigmund-freud","t":"El sufrimiento nos amenaza desde tres lados: desde el propio cuerpo, condenado a la decadencia y la disolución, que ni siquiera puede prescindir del dolor y la angustia como señales de alarma; desde el mundo exterior, que puede abatirse sobre nosotros con fuerzas hiperpotentes, implacables y destructivas; y por último, desde los vínculos con otros seres humanos.","o":"Von drei Seiten droht das Leiden, vom eigenen Körper her, der, zu Verfall und Auflösung bestimmt, sogar Schmerz und Angst als Warnungssignale nicht entbehren kann, von der Außenwelt, die mit übermächtigen, unerbittlichen, zerstörenden Kräften gegen uns wüten kann, und endlich aus den Beziehungen zu anderen Menschen.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["sufrimiento","vinculos","cuerpo"]},{"i":"sigmund-freud-003","a":"sigmund-freud","t":"El sufrimiento que proviene de esta fuente [los vínculos] lo sentimos quizás más dolorosamente que cualquier otro.","o":"Das Leiden, das aus dieser Quelle stammt, empfinden wir vielleicht schmerzlicher als jedes andere","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["sufrimiento","vinculos"]},{"i":"sigmund-freud-004","a":"sigmund-freud","t":"Nunca estamos más desprotegidos frente al sufrimiento que cuando amamos; nunca más desamparadamente infelices que cuando perdimos al objeto amado o su amor.","o":"Niemals sind wir ungeschützter gegen das Leiden, als wenn wir lieben, niemals hilfloser unglücklich, als wenn wir das geliebte Objekt oder seine Liebe verloren haben.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["amor","perdida","duelo"]},{"i":"sigmund-freud-005","a":"sigmund-freud","t":"La vida, tal como nos es impuesta, resulta demasiado pesada: nos trae demasiados dolores, desengaños, tareas insolubles.","o":"Das Leben, wie es uns auferlegt ist, ist zu schwer für uns, es bringt uns zuviel Schmerzen, Enttäuschungen, unlösbare Aufgaben.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["sufrimiento","existencia"]},{"i":"sigmund-freud-006","a":"sigmund-freud","t":"El ser humano se ha convertido, por así decir, en una especie de dios con prótesis: bastante magnífico cuando se coloca todos sus órganos auxiliares, pero estos no se le han integrado.","o":"Der Mensch ist sozusagen eine Art Prothesengott geworden, recht großartig, wenn er alle seine Hilfsorgane anlegt, aber sie sind nicht mit ihm verwachsen","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 3","te":["tecnologia","cultura"]},{"i":"sigmund-freud-007","a":"sigmund-freud","t":"La felicidad, en ese sentido moderado en que se la reconoce posible, es un problema de la economía libidinal de cada individuo.","o":"Das Glück in jenem ermäßigten Sinn, in dem es als möglich erkannt wird, ist ein Problem der individuellen Libidoökonomie.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["felicidad","deseo"]},{"i":"sigmund-freud-008","a":"sigmund-freud","t":"El goce de la belleza tiene un carácter sensorial particular, suavemente embriagador.","o":"Der Genuß an der Schönheit hat einen besonderen, milde berauschenden Empfindungscharakter.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["alegria","cultura"]},{"i":"sigmund-freud-009","a":"sigmund-freud","t":"La utilidad de la belleza no es evidente, su necesidad cultural no se ve, y sin embargo la cultura no podría prescindir de ella.","o":"Ein Nutzen der Schönheit liegt nicht klar zutage, ihre kulturelle Notwendigkeit ist nicht einzusehen, und doch könnte man sie in der Kultur nicht vermissen.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["cultura"]},{"i":"sigmund-freud-010","a":"sigmund-freud","t":"Esta actitud estética ante la meta de la vida protege poco contra los sufrimientos que amenazan, pero puede compensar muchas cosas.","o":"Diese ästhetische Einstellung zum Lebensziel bietet wenig Schutz gegen drohende Leiden, vermag aber für vieles zu entschädigen.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["sufrimiento","cultura"]},{"i":"sigmund-freud-011","a":"sigmund-freud","t":"Quien emprende este camino hacia la felicidad [rehacer el mundo según sus deseos] con una rebeldía desesperada, por lo general no logrará nada: la realidad es demasiado fuerte para él.","o":"Wer in verzweifelter Empörung diesen Weg zum Glück einschlägt, wird in der Regel nichts erreichen; die Wirklichkeit ist zu stark für ihn.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["felicidad","deseo"]},{"i":"sigmund-freud-012","a":"sigmund-freud","t":"La tarea es desplazar las metas pulsionales de manera que la frustración que impone el mundo exterior no pueda alcanzarlas.","o":"Die zu lösende Aufgabe ist, die Triebziele solcherart zu verlegen, daß sie von der Versagung der Außenwelt nicht getroffen werden können.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["deseo","sufrimiento"]},{"i":"sigmund-freud-013","a":"sigmund-freud","t":"Y sin embargo, las personas valoran poco el trabajo como camino hacia la felicidad.","o":"Und dennoch wird Arbeit als Weg zum Glück von den Menschen wenig geschätzt.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["trabajo","felicidad"]},{"i":"sigmund-freud-014","a":"sigmund-freud","t":"El ser humano civilizado cambió una parte de posibilidad de felicidad por una parte de seguridad.","o":"Der Kulturmensch hat für ein Stück Glücksmöglichkeit ein Stück Sicherheit eingetauscht.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 5","te":["cultura","felicidad","sociedad"]},{"i":"sigmund-freud-015","a":"sigmund-freud","t":"La cultura tiene que movilizarlo todo para poner límites a las pulsiones agresivas de los seres humanos.","o":"Die Kultur muß alles aufbieten, um den Aggressionstrieben der Menschen Schranken zu setzen","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 5","te":["cultura","ira","sociedad"]},{"i":"sigmund-freud-016","a":"sigmund-freud","t":"Siempre es posible ligar amorosamente entre sí a una multitud mayor de personas, con tal de que queden otras para manifestarles la agresión.","o":"Es ist immer möglich, eine größere Menge von Menschen in Liebe aneinander zu binden, wenn nur andere für die Äußerung der Aggression übrigbleiben.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 5","te":["sociedad","ira","poder"]},{"i":"sigmund-freud-017","a":"sigmund-freud","t":"Las pasiones pulsionales son más fuertes que los intereses racionales.","o":"triebhafte Leidenschaften sind stärker als vernünftige Interessen","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 5","te":["deseo","sociedad"]},{"i":"sigmund-freud-018","a":"sigmund-freud","t":"La agresión es introyectada, interiorizada, en verdad devuelta al lugar de donde vino: vuelta contra el propio yo.","o":"Die Aggression wird introjiziert, verinnerlicht, eigentlich aber dorthin zurückgeschickt, woher sie gekommen ist, also gegen das eigene Ich gewendet.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 7","te":["culpa","ira","inconsciente"]},{"i":"sigmund-freud-019","a":"sigmund-freud","t":"A la tensión entre el severo superyó y el yo que le está sometido la llamamos conciencia de culpa; se manifiesta como necesidad de castigo.","o":"Die Spannung zwischen dem gestrengen Über-Ich und dem ihm unterworfenen Ich heißen wir Schuldbewußtsein; sie äußert sich als Strafbedürfnis.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 7","te":["culpa","inconsciente"]},{"i":"sigmund-freud-020","a":"sigmund-freud","t":"Lo malo es, al principio, aquello por lo cual se nos amenaza con la pérdida del amor; por angustia ante esa pérdida hay que evitarlo.","o":"Das Böse ist also anfänglich dasjenige, wofür man mit Liebesverlust bedroht wird; aus Angst vor diesem Verlust muß man es vermeiden.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 7","te":["culpa","miedo","amor"]},{"i":"sigmund-freud-021","a":"sigmund-freud","t":"La agresión de la conciencia moral conserva la agresión de la autoridad.","o":"Die Aggression des Gewissens konserviert die Aggression der Autorität.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 7","te":["culpa","poder"]},{"i":"sigmund-freud-022","a":"sigmund-freud","t":"Las religiones, al menos, nunca desconocieron el papel del sentimiento de culpa en la cultura.","o":"Die Religionen wenigstens haben die Rolle des Schuldgefühls in der Kultur nie verkannt.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 8","te":["culpa","cultura","trascendencia"]},{"i":"sigmund-freud-023","a":"sigmund-freud","t":"Eros y Ananké [amor y necesidad] se convirtieron también en los padres de la cultura humana.","o":"Eros und Ananke sind auch die Eltern der menschlichen Kultur geworden.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 4","te":["amor","cultura"]},{"i":"sigmund-freud-024","a":"sigmund-freud","t":"[Mi propósito era] presentar el sentimiento de culpa como el problema más importante del desarrollo cultural.","o":"das Schuldgefühl als das wichtigste Problem der Kulturentwicklung hinzustellen","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 8","te":["culpa","cultura"]},{"i":"sigmund-freud-025","a":"sigmund-freud","t":"No sabría indicar una necesidad de la infancia tan intensa como la de la protección paterna.","o":"Ein ähnlich starkes Bedürfnis aus der Kindheit wie das nach dem Vaterschutz wüßte ich nicht anzugeben.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 1","te":["familia","infancia"]},{"i":"sigmund-freud-026","a":"sigmund-freud","t":"El beneficio del orden es innegable: permite al ser humano aprovechar mejor el espacio y el tiempo, mientras ahorra sus fuerzas psíquicas.","o":"Die Wohltat der Ordnung ist ganz unleugbar, sie ermöglicht dem Menschen die beste Ausnützung von Raum und Zeit, während sie seine psychischen Kräfte schont.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 3","te":["habitos","cultura"]},{"i":"sigmund-freud-027","a":"sigmund-freud","t":"El orden es una especie de compulsión de repetición que, establecida una vez, decide cuándo, dónde y cómo debe hacerse algo.","o":"Die Ordnung ist eine Art Wiederholungszwang, die durch einmalige Einrichtung entscheidet, wann, wo und wie etwas getan werden soll","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 3","te":["habitos","inconsciente"]},{"i":"sigmund-freud-028","a":"sigmund-freud","t":"El amor de meta inhibida fue en su origen amor plenamente sensual, y lo sigue siendo en lo inconsciente del ser humano.","o":"Die zielgehemmte Liebe war eben ursprünglich vollsinnliche Liebe und ist es im Unbewußten des Menschen noch immer.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 4","te":["amor","inconsciente","deseo"]},{"i":"sigmund-freud-029","a":"sigmund-freud","t":"La voz del intelecto es baja, pero no descansa hasta hacerse oír.","o":"die Stimme des Intellekts ist leise, aber sie ruht nicht, ehe sie sich Gehör geschafft hat","l":"de","ob":"El porvenir de una ilusión","an":"1927","u":"Capítulo 9","te":["verdad","conciencia"]},{"i":"sigmund-freud-030","a":"sigmund-freud","t":"No, nuestra ciencia no es una ilusión. Pero sería una ilusión creer que podríamos obtener de otra parte lo que ella no puede darnos.","o":"Nein, unsere Wissenschaft ist keine Illusion. Eine Illusion aber wäre es zu glauben, daß wir anderswoher bekommen könnten, was sie uns nicht geben kann.","l":"de","ob":"El porvenir de una ilusión","an":"1927","u":"Capítulo 9","te":["verdad","conocimiento"]},{"i":"sigmund-freud-031","a":"sigmund-freud","t":"El ser humano no puede seguir siendo niño para siempre: tiene que salir, finalmente, a la “vida hostil”.","o":"Der Mensch kann nicht ewig Kind bleiben, er muß endlich hinaus ins \"feindliche Leben\".","l":"de","ob":"El porvenir de una ilusión","an":"1927","u":"Capítulo 8","te":["desarrollo-humano","infancia","responsabilidad"]},{"i":"sigmund-freud-032","a":"sigmund-freud","t":"No hay ninguna instancia por encima de la razón.","o":"Es gibt keine Instanz über der Vernunft.","l":"de","ob":"El porvenir de una ilusión","an":"1927","u":"Capítulo 4","te":["verdad"]},{"i":"sigmund-freud-033","a":"sigmund-freud","t":"Como estamos dispuestos a renunciar a buena parte de nuestros deseos infantiles, podemos soportar que algunas de nuestras expectativas resulten ser ilusiones.","o":"Da wir bereit sind, auf ein gutes Stück unserer infantilen Wünsche zu verzichten, können wir es vertragen, wenn sich einige unserer Erwartungen als Illusionen herausstellen.","l":"de","ob":"El porvenir de una ilusión","an":"1927","u":"Capítulo 9","te":["deseo","aceptacion","desarrollo-humano"]},{"i":"sigmund-freud-034","a":"sigmund-freud","t":"Podemos insistir cuanto queramos en que el intelecto humano carece de fuerza frente a la vida pulsional, y tener razón.","o":"Wir mögen noch so oft betonen, der menschliche Intellekt sei kraftlos im Vergleich zum menschlichen Triebleben, und recht damit haben.","l":"de","ob":"El porvenir de una ilusión","an":"1927","u":"Capítulo 9","te":["deseo","conciencia"]},{"i":"sigmund-freud-035","a":"sigmund-freud","t":"El yo es, ante todo, un yo corporal: no es solo un ser de superficie, sino él mismo la proyección de una superficie.","o":"Das Ich ist vor allem ein körperliches, es ist nicht nur ein Oberflächenwesen, sondern selbst die Projektion einer Oberfläche.","l":"de","ob":"El yo y el ello","an":"1923","u":"Capítulo 2","te":["identidad","cuerpo"]},{"i":"sigmund-freud-036","a":"sigmund-freud","t":"El yo es la verdadera sede de la angustia.","o":"Das Ich ist ja die eigentliche Angststätte.","l":"de","ob":"El yo y el ello","an":"1923","u":"Capítulo 5","te":["angustia","identidad"]},{"i":"sigmund-freud-037","a":"sigmund-freud","t":"[Vemos] al mismo yo como una pobre criatura, sometida a tres servidumbres y que, por eso, sufre la amenaza de tres peligros.","o":"dasselbe Ich als armes Ding, welches unter dreierlei Dienstbarkeiten steht und demzufolge unter den Drohungen von dreierlei Gefahren leidet","l":"de","ob":"El yo y el ello","an":"1923","u":"Capítulo 5","te":["identidad","sufrimiento"]},{"i":"sigmund-freud-038","a":"sigmund-freud","t":"El psicoanálisis es un instrumento que debe permitirle al yo la conquista progresiva del ello.","o":"Die Psychoanalyse ist ein Werkzeug, welches dem Ich die fortschreitende Eroberung des Es ermöglichen soll.","l":"de","ob":"El yo y el ello","an":"1923","u":"Capítulo 5","te":["terapia","inconsciente"]},{"i":"sigmund-freud-039","a":"sigmund-freud","t":"[El yo] ni siquiera es dueño en su propia casa, sino que depende de escasas noticias sobre lo que ocurre de manera inconsciente en su vida anímica.","o":"daß es nicht einmal Herr ist im eigenen Hause, sondern auf kärgliche Nachrichten angewiesen bleibt von dem, was unbewußt in seinem Seelenleben vorgeht","l":"de","ob":"Conferencias de introducción al psicoanálisis","an":"1917","u":"Capítulo 18","te":["inconsciente","identidad","autoconocimiento"]},{"i":"sigmund-freud-040","a":"sigmund-freud","t":"Las palabras fueron en su origen magia, y la palabra conserva todavía hoy mucho de su antiguo poder mágico.","o":"Worte waren ursprünglich Zauber, und das Wort hat noch heute viel von seiner alten Zauberkraft bewahrt.","l":"de","ob":"Conferencias de introducción al psicoanálisis","an":"1917","u":"Capítulo 1","te":["comunicacion","terapia"]},{"i":"sigmund-freud-041","a":"sigmund-freud","t":"Con palabras una persona puede hacer dichosa a otra o empujarla a la desesperación.","o":"Durch Worte kann ein Mensch den anderen selig machen oder zur Verzweiflung treiben","l":"de","ob":"Conferencias de introducción al psicoanálisis","an":"1917","u":"Capítulo 1","te":["comunicacion","vinculos"]},{"i":"sigmund-freud-042","a":"sigmund-freud","t":"En el tratamiento analítico no ocurre otra cosa que un intercambio de palabras entre el analizado y el médico.","o":"In der analytischen Behandlung geht nichts anderes vor als ein Austausch von Worten zwischen dem Analysierten und dem Arzt.","l":"de","ob":"Conferencias de introducción al psicoanálisis","an":"1917","u":"Capítulo 1","te":["terapia","comunicacion"]},{"i":"sigmund-freud-043","a":"sigmund-freud","t":"Los sentimientos hostiles significan un lazo afectivo tanto como los tiernos.","o":"Die feindlichen Gefühle bedeuten ebenso eine Gefühlsbindung wie die zärtlichen","l":"de","ob":"Conferencias de introducción al psicoanálisis","an":"1917","u":"Capítulo 27","te":["vinculos","ira","amor"]},{"i":"sigmund-freud-047","a":"sigmund-freud","t":"Donde era ello, ha de advenir yo. Es un trabajo de cultura, como la desecación del Zuiderzee.","o":"Wo Es war, soll Ich werden. Es ist Kulturarbeit etwa wie die Trockenlegung der Zuydersee.","l":"de","ob":"Nuevas conferencias de introducción al psicoanálisis","an":"1933","u":"Capítulo 3","te":["inconsciente","terapia","transformacion-personal"]},{"i":"sigmund-freud-044","a":"sigmund-freud","t":"La interpretación de los sueños es la vía regia hacia el conocimiento de lo inconsciente en la vida anímica.","o":"Die Traumdeutung aber ist die Via regia zur Kenntnis des Unbewußten im Seelenleben.","l":"de","ob":"La interpretación de los sueños","an":"1900","u":"Capítulo 7","te":["suenos","inconsciente"]},{"i":"sigmund-freud-045","a":"sigmund-freud","t":"El sueño es el cumplimiento (disfrazado) de un deseo (sofocado, reprimido).","o":"Der Traum ist die (verkleidete) Erfüllung eines (unterdrückten, verdrängten) Wunsches","l":"de","ob":"La interpretación de los sueños","an":"1900","u":"Capítulo 4","te":["suenos","deseo","inconsciente"]},{"i":"sigmund-freud-046","a":"sigmund-freud","t":"La meta de toda vida es la muerte.","o":"Das Ziel alles Lebens ist der Tod","l":"de","ob":"Más allá del principio del placer","an":"1920","u":"Capítulo 5","te":["muerte"]},{"i":"sigmund-freud-050","a":"sigmund-freud","t":"El psicoanálisis consideró desde el comienzo que ese destino [que parece perseguir a algunas personas] es en gran parte autoprovocado y está determinado por influencias de la primera infancia.","o":"die Psychoanalyse hat vom Anfang an solches Schicksal für zum großen Teil selbstbereitet und durch frühinfantile Einflüsse determiniert gehalten","l":"de","ob":"Más allá del principio del placer","an":"1920","u":"Capítulo 3","te":["repeticion","infancia","inconsciente"]},{"i":"sigmund-freud-048","a":"sigmund-freud","t":"Nuestras enfermas histéricas sufren de reminiscencias.","o":"Unsere hysterisch Kranken leiden an Reminiszenzen.","l":"de","ob":"Sobre psicoanálisis (Cinco conferencias)","an":"1910","u":"Capítulo 1","te":["sufrimiento","memoria","trauma"]},{"i":"sigmund-freud-049","a":"sigmund-freud","t":"La interpretación de los sueños es, en realidad, la vía regia hacia el conocimiento de lo inconsciente, el fundamento más seguro del psicoanálisis.","o":"Die Traumdeutung ist in Wirklichkeit die Via Regia zur Kenntnis des Unbewußten, die sicherste Grundlage der Psychoanalyse","l":"de","ob":"Sobre psicoanálisis (Cinco conferencias)","an":"1910","u":"Capítulo 3","te":["suenos","inconsciente"]},{"i":"william-james-001","a":"william-james","t":"El hábito es así el enorme volante de la sociedad, su más preciado agente conservador.","o":"Habit is thus the enormous fly-wheel of society, its most precious conservative agent.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","sociedad"]},{"i":"william-james-002","a":"william-james","t":"Lo importante en toda educación es hacer de nuestro sistema nervioso un aliado y no un enemigo.","o":"make our nervous system our ally instead of our enemy","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","educacion"]},{"i":"william-james-003","a":"william-james","t":"Si los jóvenes comprendieran qué pronto se convertirán en meros manojos ambulantes de hábitos, prestarían más atención a su conducta mientras todavía son moldeables.","o":"Could the young but realize how soon they will become mere walking bundles of habits, they would give more heed to their conduct while in the plastic state.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","desarrollo-humano"]},{"i":"william-james-004","a":"william-james","t":"Estamos hilando nuestro propio destino, bueno o malo, y no hay manera de deshacerlo.","o":"We are spinning our own fates, good or evil, and never to be undone.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","responsabilidad"]},{"i":"william-james-005","a":"william-james","t":"Cada mínimo trazo de virtud o de vicio deja su cicatriz, por pequeña que sea.","o":"Every smallest stroke of virtue or of vice leaves its never so little scar.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","identidad"]},{"i":"william-james-006","a":"william-james","t":"No permitas ninguna excepción hasta que el nuevo hábito esté firmemente arraigado en tu vida.","o":"Never suffer an exception to occur till the new habit is securely rooted in your life","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","cambio"]},{"i":"william-james-007","a":"william-james","t":"Aprovechá la primera oportunidad posible para actuar según cada resolución que tomes.","o":"Seize the very first possible opportunity to act on every resolution you make","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","cambio"]},{"i":"william-james-008","a":"william-james","t":"Mantené viva en vos la capacidad de esfuerzo con un pequeño ejercicio gratuito cada día.","o":"Keep the faculty of effort alive in you by a little gratuitous exercise every day","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","voluntad"]},{"i":"william-james-009","a":"william-james","t":"[La conciencia] no está hecha de piezas articuladas: fluye. “Río” o “corriente” son las metáforas que mejor la describen.","o":"It is nothing jointed; it flows. A 'river' or a 'stream' are the metaphors by which it is most naturally described.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 9","te":["conciencia"]},{"i":"william-james-010","a":"william-james","t":"Llamémosla corriente del pensamiento, de la conciencia o de la vida subjetiva.","o":"let us call it the stream of thought, of consciousness, or of subjective life","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 9","te":["conciencia"]},{"i":"william-james-011","a":"william-james","t":"Todo pensamiento tiende a formar parte de una conciencia personal.","o":"Every thought tends to be part of a personal consciousness.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 9","te":["conciencia","identidad"]},{"i":"william-james-012","a":"william-james","t":"Ningún estado, una vez pasado, puede repetirse idéntico a lo que fue.","o":"no state once gone can recur and be identical with what it was before","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 9","te":["conciencia","cambio"]},{"i":"william-james-013","a":"william-james","t":"Mi experiencia es aquello a lo que acepto prestar atención.","o":"My experience is what I agree to attend to.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 11","te":["atencion","conciencia"]},{"i":"william-james-014","a":"william-james","t":"Sin un interés selectivo, la experiencia es un caos absoluto.","o":"without selective interest, experience is an utter chaos","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 11","te":["atencion","conciencia"]},{"i":"william-james-015","a":"william-james","t":"Todo el mundo sabe qué es la atención.","o":"Every one knows what attention is.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 11","te":["atencion"]},{"i":"william-james-016","a":"william-james","t":"La capacidad de traer de vuelta voluntariamente una atención que se dispersa, una y otra vez, es la raíz misma del juicio, del carácter y de la voluntad.","o":"the faculty of voluntarily bringing back a wandering attention, over and over again, is the very root of judgment, character, and will","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 11","te":["atencion","voluntad","presencia"]},{"i":"william-james-017","a":"william-james","t":"Una persona tiene tantos “yo” sociales como individuos la reconocen.","o":"a man has as many social selves as there are individuals who recognize him","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 10","te":["identidad","vinculos"]},{"i":"william-james-018","a":"william-james","t":"En su sentido más amplio, el “sí mismo” de una persona es la suma total de todo lo que puede llamar suyo.","o":"a man's Self is the sum total of all that he","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 10","te":["identidad"]},{"i":"william-james-019","a":"william-james","t":"Autoestima = éxito / pretensiones.","o":"Self-esteem = Success/ Pretensions.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 10","te":["autoestima","identidad"]},{"i":"william-james-020","a":"william-james","t":"Renunciar a las pretensiones es un alivio tan bendito como verlas satisfechas.","o":"To give up pretensions is as blessed a relief as to get them gratified","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 10","te":["autoestima","aceptacion"]},{"i":"william-james-021","a":"william-james","t":"El bebé, asaltado a la vez por ojos, oídos, nariz, piel y entrañas, lo siente todo como una gran confusión floreciente y zumbante.","o":"The baby, assailed by eyes, ears, nose, skin, and entrails at once, feels it all as one great blooming, buzzing confusion","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 13","te":["desarrollo-humano","infancia"]},{"i":"william-james-045","a":"william-james","t":"Solo el interés da acento y énfasis, luz y sombra, fondo y primer plano.","o":"Interest alone gives accent and emphasis, light and shade, background and foreground","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 11","te":["atencion","conciencia"]},{"i":"william-james-048","a":"william-james","t":"Solo las cosas que noto le dan forma a mi mente.","o":"Only those items which I","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 11","te":["atencion","conciencia"]},{"i":"william-james-049","a":"william-james","t":"El infierno que nos espera en el más allá, del que habla la teología, no es peor que el infierno que nos fabricamos en este mundo al moldear habitualmente nuestro carácter de la manera equivocada.","o":"The hell to be endured hereafter, of which theology tells, is no worse than the hell we make for ourselves in this world by habitually fashioning our characters in the wrong way.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","sufrimiento","responsabilidad"]},{"i":"william-james-022","a":"william-james","t":"El arte de ser sabio es el arte de saber qué pasar por alto.","o":"the art of being wise is the art of knowing what to overlook","l":"en","ob":"Principios de psicología, vol. 2","an":"1890","u":"Capítulo 22","te":["atencion","conocimiento"]},{"i":"william-james-023","a":"william-james","t":"Nos sentimos tristes porque lloramos, enojados porque golpeamos, asustados porque temblamos.","o":"we feel sorry because we cry, angry because we strike, afraid because we tremble","l":"en","ob":"Principios de psicología, vol. 2","an":"1890","u":"Capítulo 25","te":["emociones","cuerpo"]},{"i":"william-james-024","a":"william-james","t":"Una emoción humana puramente desencarnada no es nada.","o":"A purely disembodied human emotion is a nonentity.","l":"en","ob":"Principios de psicología, vol. 2","an":"1890","u":"Capítulo 25","te":["emociones","cuerpo"]},{"i":"william-james-025","a":"william-james","t":"Si queremos vencer tendencias emocionales indeseadas, debemos atravesar con asiduidad, y al principio a sangre fría, los movimientos externos de las disposiciones contrarias que preferimos cultivar.","o":"we must assiduously, and in the first instance cold-bloodedly, go through the","l":"en","ob":"Principios de psicología, vol. 2","an":"1890","u":"Capítulo 25","te":["regulacion-emocional","habitos"]},{"i":"william-james-026","a":"william-james","t":"El logro esencial de la voluntad es atender a un objeto difícil y sostenerlo firme ante la mente.","o":"to_ ATTEND _to a difficult object and hold it fast before the mind","l":"en","ob":"Principios de psicología, vol. 2","an":"1890","u":"Capítulo 26","te":["atencion","voluntad"]},{"i":"william-james-047","a":"william-james","t":"Así como el arte de leer (a partir de cierta etapa de la formación) es el arte de saltear…","o":"As the art of reading (after a certain stage in one's education) is the art of skipping","l":"en","ob":"Principios de psicología, vol. 2","an":"1890","u":"Capítulo 22","te":["educacion","atencion"]},{"i":"william-james-050","a":"william-james","t":"El genio, en verdad, no es mucho más que la capacidad de percibir de una manera no habitual.","o":"Genius, in truth, means little more than the faculty of perceiving in an unhabitual way.","l":"en","ob":"Principios de psicología, vol. 2","an":"1890","u":"Capítulo 19","te":["creatividad","conciencia"]},{"i":"william-james-041","a":"william-james","t":"[La religión significará para nosotros] los sentimientos, actos y experiencias de las personas en su soledad, en la medida en que se perciben en relación con lo que consideren divino.","o":"the feelings, acts, and experiences of individual men in their solitude, so far as they apprehend themselves to stand in relation to whatever they may consider the divine","l":"en","ob":"Las variedades de la experiencia religiosa","an":"1902","u":"Conferencia 2","te":["trascendencia","soledad"]},{"i":"william-james-042","a":"william-james","t":"[Nuestra conciencia de vigilia] no es más que un tipo especial de conciencia; a su alrededor, separadas por la más fina de las pantallas, hay formas potenciales de conciencia completamente distintas.","o":"is but one special type of consciousness, whilst all about it, parted from it by the filmiest of screens, there lie potential forms of consciousness entirely different","l":"en","ob":"Las variedades de la experiencia religiosa","an":"1902","u":"Conferencia 13","te":["conciencia","trascendencia"]},{"i":"william-james-043","a":"william-james","t":"El mundo de nuestra conciencia presente es solo uno entre muchos mundos de conciencia que existen.","o":"the world of our present consciousness is only one out of many worlds of consciousness that exist","l":"en","ob":"Las variedades de la experiencia religiosa","an":"1902","u":"Conferencia 20","te":["conciencia"]},{"i":"william-james-044","a":"william-james","t":"La religión, sea lo que sea, es la reacción total de una persona ante la vida.","o":"Religion, whatever it is, is a man's total reaction upon life","l":"en","ob":"Las variedades de la experiencia religiosa","an":"1902","u":"Conferencia 2","te":["trascendencia","sentido-de-vida"]},{"i":"william-james-038","a":"william-james","t":"La verdad de una idea no es una propiedad estancada que le es inherente. La verdad le sucede a una idea: se vuelve verdadera, los acontecimientos la hacen verdadera.","o":"The truth of an idea is not a stagnant property inherent in it. Truth HAPPENS to an idea. It BECOMES true, is MADE true by events.","l":"en","ob":"Pragmatismo","an":"1907","u":"Conferencia 6","te":["verdad"]},{"i":"william-james-039","a":"william-james","t":"Como seres humanos, podemos ser mentes sanas un día y almas enfermas al siguiente.","o":"as human beings we can be healthy minds on one day and sick souls on the next","l":"en","ob":"Pragmatismo","an":"1907","u":"Conferencia 8","te":["salud-mental","sufrimiento"]},{"i":"william-james-040","a":"william-james","t":"Cualquiera sea el universo en que crea un profesor, tiene que ser al menos un universo que se preste a discursos largos.","o":"Whatever universe a professor believes in must at any rate be a universe that lends itself to lengthy discourse.","l":"en","ob":"Pragmatismo","an":"1907","u":"Conferencia 1","te":["educacion","humor"]},{"i":"william-james-027","a":"william-james","t":"Dondequiera que un proceso vital le comunica entusiasmo a quien lo vive, allí la vida se vuelve verdaderamente significativa.","o":"Wherever a process of life communicates an eagerness to him who lives it, there the life becomes genuinely significant.","l":"en","ob":"Charlas a los maestros sobre psicología y a los estudiantes sobre algunos ideales de la vida","an":"1899","u":"«On A Certain Blindness In Human Beings»","te":["sentido-de-vida","alegria"]},{"i":"william-james-028","a":"william-james","t":"Ni toda la verdad ni todo el bien se revelan a un solo observador.","o":"neither the whole of truth nor the whole of good is revealed to any single observer","l":"en","ob":"Charlas a los maestros sobre psicología y a los estudiantes sobre algunos ideales de la vida","an":"1899","u":"«On A Certain Blindness In Human Beings»","te":["verdad","encuentro"]},{"i":"william-james-029","a":"william-james","t":"La ceguera que todos padecemos respecto de los sentimientos de criaturas y personas distintas de nosotros.","o":"the blindness with which we all are afflicted in regard to the feelings of creatures and people different from ourselves","l":"en","ob":"Charlas a los maestros sobre psicología y a los estudiantes sobre algunos ideales de la vida","an":"1899","u":"«On A Certain Blindness In Human Beings»","te":["empatia","vinculos"]},{"i":"william-james-030","a":"william-james","t":"La acción parece seguir al sentimiento, pero en realidad acción y sentimiento van juntos.","o":"Action seems to follow feeling, but really action and feeling go together","l":"en","ob":"Charlas a los maestros sobre psicología y a los estudiantes sobre algunos ideales de la vida","an":"1899","u":"«The Gospel Of Relaxation»","te":["emociones","regulacion-emocional"]},{"i":"william-james-031","a":"william-james","t":"El camino voluntario soberano hacia la alegría, si perdimos la espontánea, es enderezarnos con alegría, mirar alrededor con alegría [y actuar y hablar como si ya estuviera allí].","o":"the sovereign voluntary path to cheerfulness, if our spontaneous cheerfulness be lost, is to sit up cheerfully, to look round cheerfully","l":"en","ob":"Charlas a los maestros sobre psicología y a los estudiantes sobre algunos ideales de la vida","an":"1899","u":"«The Gospel Of Relaxation»","te":["alegria","regulacion-emocional"]},{"i":"william-james-032","a":"william-james","t":"Somos seres prácticos, cada uno con funciones y deberes limitados que cumplir.","o":"We are practical beings, each of us with limited functions and duties to perform.","l":"en","ob":"Charlas a los maestros sobre psicología y a los estudiantes sobre algunos ideales de la vida","an":"1899","u":"«On A Certain Blindness In Human Beings»","te":["trabajo","identidad"]},{"i":"william-james-046","a":"william-james","t":"Cada recaída es como dejar caer un ovillo que uno estaba enrollando con cuidado.","o":"Each lapse is like the letting fall of a ball of string which one is carefully winding up","l":"en","ob":"Charlas a los maestros sobre psicología y a los estudiantes sobre algunos ideales de la vida","an":"1899","u":"«The Laws Of Habit»","te":["habitos","cambio"]},{"i":"william-james-033","a":"william-james","t":"No le tengas miedo a la vida. Creé que la vida vale la pena, y tu creencia ayudará a crear el hecho.","o":"Be not afraid of life. Believe that life","l":"en","ob":"La voluntad de creer y otros ensayos","an":"1897","u":"«Is Life Worth Living?»","te":["sentido-de-vida","miedo","esperanza"]},{"i":"william-james-034","a":"william-james","t":"Solo arriesgándonos de una hora a la otra vivimos realmente.","o":"It is only by risking our persons from one hour to another that we live at all.","l":"en","ob":"La voluntad de creer y otros ensayos","an":"1897","u":"«Is Life Worth Living?»","te":["libertad","incertidumbre"]},{"i":"william-james-035","a":"william-james","t":"A menudo, nuestra fe anticipada en un resultado incierto es lo único que hace que el resultado se cumpla.","o":"our faith beforehand in an uncertified result","l":"en","ob":"La voluntad de creer y otros ensayos","an":"1897","u":"«Is Life Worth Living?»","te":["esperanza","incertidumbre"]},{"i":"william-james-036","a":"william-james","t":"Nuestra naturaleza pasional no solo puede legítimamente, sino que debe, decidir entre proposiciones [cuando se trata de una opción genuina que el intelecto no puede zanjar].","o":"Our passional nature not only lawfully may, but must, decide an option between propositions","l":"en","ob":"La voluntad de creer y otros ensayos","an":"1897","u":"«The Will To Believe»","te":["deseo","verdad","libertad"]},{"i":"william-james-037","a":"william-james","t":"Podemos decir que esta vida vale la pena, ya que es lo que hacemos de ella, desde el punto de vista moral.","o":"This life is worth living, we can say,","l":"en","ob":"La voluntad de creer y otros ensayos","an":"1897","u":"«Is Life Worth Living?»","te":["sentido-de-vida","responsabilidad"]},{"i":"william-james-051","a":"william-james","t":"Una regla de pensamiento que me impidiera absolutamente reconocer ciertos tipos de verdad, si esas verdades realmente existieran, [sería una regla irracional].","o":"a rule of thinking which would absolutely prevent me from acknowledging certain kinds of truth if those kinds of truth were really there","l":"en","ob":"La voluntad de creer y otros ensayos","an":"1897","u":"«The Will To Believe»","te":["verdad","conocimiento"]},{"i":"alfred-adler-001","a":"alfred-adler","t":"La psicología individual comparada ve en cada acontecimiento psíquico la huella, por así decir el símbolo, de un plan de vida orientado de manera unitaria.","o":"Die vergleichende Individualpsychose erblickt in jedem psychischen Geschehen den Abdruck, sozusagen ein Symbol des einheitlich gerichteten Lebensplanes","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["identidad","sentido-de-vida"]},{"i":"alfred-adler-002","a":"alfred-adler","t":"Y se revela como la obra demoníaca de un afán de dominio desatado que estrangula o aprovecha con astucia el inmortal sentimiento de comunidad de la humanidad.","o":"Und er entschleiert sich als das dämonische Werk der allgemein entfesselten Herrschsucht, die das unsterbliche Gemeinschaftsgefühl der Menschheit drosselt oder listig missbraucht.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["poder","sociedad"]},{"i":"alfred-adler-003","a":"alfred-adler","t":"Lo aprendido le impondrá una tarea de vida: ir adelante en el desmontaje del afán de poder y en la educación para la comunidad.","o":"Die gewonnenen Erkenntnisse werden ihn dann freilich mit einer Lebensaufgabe belasten: voranzugehen bei dem Abbau des Strebens nach Macht und bei der Erziehung zur Gemeinschaft.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["poder","educacion","sociedad"]},{"i":"alfred-adler-004","a":"alfred-adler","t":"El desarrollo psíquico de una persona y sus fracasos, incluidas las neurosis y las psicosis, provienen de su posición frente a la lógica absoluta de la convivencia humana.","o":"dass die seelische Entwicklung eines Menschen und deren Fehlschlage, auch die Neurosen und Psychosen, aus seiner Stellungnahme zur absoluten Logik des menschlichen Zusammenlebens stammen.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["vinculos","salud-mental","sociedad"]},{"i":"alfred-adler-005","a":"alfred-adler","t":"[No llega a esa contradicción por la estructura de su cerebro,] sino por un sentimiento de inferioridad adquirido en una posición difícil de la infancia.","o":"durch ein in einer schwierigen Position der Kindheit erworbenes Minderwertigkeitsgefühl.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["autoestima","infancia"]},{"i":"alfred-adler-006","a":"alfred-adler","t":"La psicología individual exige desmontar sin condiciones el afán de poder y desplegar el sentimiento de comunidad.","o":"Die Anschauungen unserer Individualpsychologie verlangen den bedingungslosen Abbau des Machtstrebens und die Entfaltung des Gemeinschaftsgefühls.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["poder","vinculos","sociedad"]},{"i":"alfred-adler-007","a":"alfred-adler","t":"Lo que llamamos la esencia de la neurosis consiste en un gasto aumentado de los recursos psíquicos disponibles.","o":"Was wir das Wesen der Neurose nennen, besteht aus dem vermehrten Aufwand der verfügbaren psychischen Mittel.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["salud-mental"]},{"i":"alfred-adler-008","a":"alfred-adler","t":"En las personas nerviosas no se encuentran rasgos de carácter completamente nuevos: ni uno solo que no pueda hallarse también en las personas “normales”.","o":"Es linden sich bei den Nervösen keine vollkommen neuen Charakterzüge, kein einziger Zug, der nicht auch beim Normalen nachzuweisen wäre.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["salud-mental","identidad"]},{"i":"alfred-adler-009","a":"alfred-adler","t":"Los rasgos de carácter acentuados ya se encuentran con claridad en la disposición del alma infantil.","o":"Die verschärften Charakterzüge sind schon deutlich in der neurotischen Disposition der Kinderseele vorzufinden","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["infancia","identidad"]},{"i":"alfred-adler-010","a":"alfred-adler","t":"Así desenmascaramos al carácter neurótico como servidor de una finalidad ficticia y establecimos su dependencia de una meta final.","o":"Somit haben wir auch den neurotischen Charakter als den Diener eines fiktiven Zweckes entlarvt und seine Abhängigkeit von einem Endziel festgestellt.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["sentido-de-vida","inconsciente"]},{"i":"alfred-adler-011","a":"alfred-adler","t":"Entre estas protecciones están también la fijación y el refuerzo de los rasgos de carácter, que en el caos de la vida forman líneas directrices útiles y así reducen la inseguridad.","o":"Zu diesen Sicherungen gehören auch die Fixierung und Verstärkung der Charakterzüge, die im Chaos des Lebens brauchbare Leitlinien bilden und so die Unsicherheit verringern.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["identidad","incertidumbre"]},{"i":"alfred-adler-012","a":"alfred-adler","t":"Pero su querer y su pensar se construyen siempre sobre la base de un sentimiento de inferioridad.","o":"Immer aber baut sich sein Wollen und Denken über der Grundlage eines Gefühls der Minderwertigkeit auf.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["autoestima"]},{"i":"alfred-adler-013","a":"alfred-adler","t":"Este sentimiento debe entenderse siempre como relativo: nace de los vínculos con su entorno o con sus metas.","o":"Dieses Gefühl ist stets als relativ zu verstehen, ist aus den Beziehungen zu seiner Umgebung erwachsen oder zu seinen Zielen.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["autoestima","vinculos"]},{"i":"alfred-adler-014","a":"alfred-adler","t":"Siempre lo precedió un medirse, un compararse con otros: primero con el padre, el más fuerte de la familia; a veces con la madre, con los hermanos; más tarde con cada persona que se le presenta.","o":"Stets ist ein Messen, ein Vergleichen mit anderen vorausgegangen, erst mit dem Vater, dem Stärksten in der Familie, zuweilen mit der Mutter, mit den Geschwistern, später mit jeder Person, die dem Patienten entgegentritt.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["autoestima","familia","vinculos"]},{"i":"alfred-adler-015","a":"alfred-adler","t":"Mirando de cerca se reconoce que todo niño, sobre todo el más desfavorecido por naturaleza, hizo una evaluación severa de sí mismo.","o":"Bei näherer Einsicht erkennt man, dass jedes Kind, insbesondere aber das von Natur aus bedrängtere, eine scharfe Selbsteinschätzung vorgenommen hat.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["infancia","autoestima"]},{"i":"alfred-adler-016","a":"alfred-adler","t":"Pronto el niño aprende a valorar también su debilidad, su desamparo, su miedo y sus muchas incapacidades como medios que le aseguran la ayuda, el apoyo y el interés de los suyos.","o":"Bald aber lernt das Kind auch in seiner Schwäche und Hilflosigkeit, in seiner Angst und in seinen mannigfachen Unfähigkeiten Mittel schätzen, die ihm die Hilfe und Unterstützung seiner Angehörigen, ihr Interesse sichern.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["infancia","vinculos","miedo"]},{"i":"alfred-adler-017","a":"alfred-adler","t":"En los niños con una desventaja física de origen, el sentimiento de sí que despierta queda siempre disminuido: se valoran menos porque sus posibilidades de satisfacción son mucho más pobres.","o":"Bei konstitutionell minderwertigen Kindern wird das erwachende Persönlichkeitsgefühl stets herabgedrückt, ihre Selbsteinschätzung fällt geringer aus, weil ihre Befriedigungsmöglichkeit weitaus dürftiger ist.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["infancia","autoestima","cuerpo"]},{"i":"alfred-adler-018","a":"alfred-adler","t":"Su sentimiento de inferioridad frente a las personas y las cosas, su inseguridad en el mundo, lo empujan a reforzar sus líneas directrices.","o":"Sein Minderwertigkeitsgefühl den Personen und Dingen gegenüber, seine Unsicherheit in der Welt drängen ihn zur Verstärkung der Leitlinien.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["autoestima","incertidumbre"]},{"i":"alfred-adler-019","a":"alfred-adler","t":"Su ficción directriz, actuar como si tuviera que ser superior a todos, puede tomar por eso también la forma de comportarse como si fuera un niño.","o":"Seine leitende Fiktion, so zu handeln, als ob er allen überlegen sein müsste, kann deshalb auch die Form annehmen, sich so zu benehmen, als ob er ein Kind wäre.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["identidad","inconsciente"]},{"i":"alfred-adler-020","a":"alfred-adler","t":"Sería un error suponer que solo la persona neurótica tiene estas líneas directrices.","o":"Es wäre gefehlt, anzunehmen, dass nur der Neurotiker solche Leitlinien aufweist.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["identidad","salud-mental"]},{"i":"alfred-adler-021","a":"alfred-adler","t":"La persona nerviosa lleva consigo constantemente el sentimiento de inseguridad.","o":"Der Nervöse trägt das Gefühl der Unsicherheit ständig mit sich.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["angustia","incertidumbre"]},{"i":"alfred-adler-022","a":"alfred-adler","t":"Se encadenó tanto a sus líneas directrices, las toma tan al pie de la letra y busca tan solo cumplirlas, que sin saberlo renunció a encarar sin prejuicios la solución de los problemas reales.","o":"Er hat sich so sehr an Leitlinien gekettet, nimmt diese wörtlich und sucht nur sie zu realisieren, dass er, ohne es zu wissen, darauf verzichtet hat, unbefangen, ohne Vorurteil an die Lösung realer Fragen zu gehen.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["libertad","inconsciente","cambio"]},{"i":"alfred-adler-023","a":"alfred-adler","t":"La forma y el contenido de la línea directriz neurótica provienen de las impresiones del niño que se siente relegado.","o":"Form und Inhalt der neurotischen Leitlinie stammen aus den Eindrücken des Kindes, das sich zurückgesetzt fühlt.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["infancia","autoestima"]},{"i":"alfred-adler-024","a":"alfred-adler","t":"La mirada de la persona neurótica se dirige también, por su sentimiento de inseguridad, mucho más lejos hacia el futuro.","o":"Der Blick des Neurotikers richtet sich auch - wegen des Gefühls der Unsicherheit - viel weiter in die Zukunft.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["angustia","tiempo"]},{"i":"alfred-adler-025","a":"alfred-adler","t":"Estos rasgos le dan con regularidad la sensación de una carga inmensa que, junto con su enfermedad, le hace creer que tiene un papel de héroe y de mártir.","o":"Regelmässig verschaffen ihm diese Züge das Gefühl einer immensen Belastung, die ihm in Verbindung mit seinem Kranksein eine Helden- und Märtyrerrolle vorgaukelt.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["identidad","sufrimiento"]},{"i":"alfred-adler-026","a":"alfred-adler","t":"Al mismo tiempo, esos reproches eternos sirven para mantener despiertos su sentimiento y su atención, para demostrarse que lo dejan de lado y no cuentan con él.","o":"Gleichzeitig dienen diese ewigen Vorwürfe dazu, sein Gefühl, seine Aufmerksamkeit wach zu halten, sich zu beweisen, dass man ihn zurücksetze, nicht mit ihm rechne.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["autoestima","vinculos"]},{"i":"alfred-adler-027","a":"alfred-adler","t":"Si retrocede ante empresas prometedoras, como suele hacerlo también ante delitos o actos inmorales, es porque teme por su sentimiento de sí.","o":"Wenn er vor Gewinn versprechenden Unternehmungen zurückschreckt, wie meist auch vor Verbrechen und unmoralischen Handlungen, so deshalb, weil er für sein Persönlichkeitsgefühl fürchtet.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["miedo","autoestima"]},{"i":"alfred-adler-028","a":"alfred-adler","t":"[A la persona sana] tampoco se le dividen los fenómenos del mundo en opuestos rígidos.","o":"Ebensowenig zerfallen ihm die Erscheinungen der Welt in starre Gegensätze","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["salud-mental","aceptacion"]},{"i":"alfred-adler-029","a":"alfred-adler","t":"Más bien procura siempre desprender su pensar y su actuar de la línea directriz irreal y ponerlos en armonía con la realidad.","o":"er ist vielmehr jederzeit bestrebt, sein Denken und Handeln von der irrealen Leitlinie loszulösen und mit der Wirklichkeit in Einklang zu bringen.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["salud-mental","transformacion-personal"]},{"i":"alfred-adler-030","a":"alfred-adler","t":"Que use ficciones como medio para un fin se debe a su utilidad para poder siquiera plantear las cuentas de la vida.","o":"Dass er überhaupt Fiktionen als Mittel zum Zweck benützt, liegt in der Brauchbarkeit der Fiktion, um die Rechnung des Lebens überhaupt ansetzen zu können.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["conocimiento","sentido-de-vida"]},{"i":"alfred-adler-031","a":"alfred-adler","t":"Desde entonces su integración en la comunidad queda impedida: el trabajo, la sociedad y el amor no se adaptan a su actitud de lucha, suelen ser evitados con timidez o, en el mejor de los casos, se convierten en el escenario de su ambiciosa embriaguez de poder.","o":"Seine Einfügung in die Gemeinschaft ist fortan gehindert, Beruf, Gesellschaft und Liebe fügen sich nicht seiner Kämpferstellung, werden meist scheu umgangen oder bilden bestenfalls den Tummelplatz seines ehrgeizigen Machtrausches.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["trabajo","amor","sociedad"]},{"i":"alfred-adler-032","a":"alfred-adler","t":"De una inferioridad física de origen, y de posiciones de la infancia que obran de modo parecido, nace así un sentimiento de inferioridad que exige una compensación: elevar el sentimiento de sí.","o":"Aus der konstitutionellen Minderwertigkeit und aus ähnlich wirkenden Positionen der Kindheit erwächst also ein Gefühl der Minderwertigkeit, das eine Kompensation im Sinne der Erhöhung des Persönlichkeitsgefühls verlangt.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["autoestima","infancia"]},{"i":"alfred-adler-033","a":"alfred-adler","t":"La ficción directriz tiene un esquema simple, infantil, e influye en la percepción y en el mecanismo de la memoria.","o":"Die leitende Fiktion hat ein einfaches, infantiles Schema und beeinflusst die Apperzeption und den Mechanismus des Gedächtnisses.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["memoria","infancia","inconsciente"]},{"i":"alfred-adler-034","a":"alfred-adler","t":"En este y otros trabajos pude mostrar cómo la inferioridad de un órgano influye de manera duradera en la psique: en el actuar y el pensar, en los sueños, en la elección de oficio, en las inclinaciones y capacidades artísticas.","o":"Ich konnte in dieser und anderen Arbeiten darauf verweisen, wie die Minderwertigkeit eines Organs dauernd die Psyche beeinflusst, im Handeln und Denken, im Träumen, in der Berufswahl, in künstlerischen Neigungen und Fähigkeiten","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["cuerpo","identidad","creatividad"]},{"i":"alfred-adler-035","a":"alfred-adler","t":"La persona nerviosa viene de esta esfera de inseguridad y estuvo en la infancia bajo la presión de su inferioridad física de origen.","o":"Der nervöse Mensch kommt aus dieser Sphäre der Unsicherheit und stand in der Kindheit unter dem Drucke seiner konstitutionellen Minderwertigkeit.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["infancia","incertidumbre"]},{"i":"alfred-adler-036","a":"alfred-adler","t":"Y para encontrar una línea directriz toma como segundo punto fijo al padre o a la madre, a quienes dota de todas las fuerzas de este mundo.","o":"Und um eine Leitlinie zu finden, nimmt es als zweiten fixen Punkt Vater oder Mutter, die es nun mit allen Kräften dieser Welt ausstattet.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["familia","infancia"]},{"i":"alfred-adler-037","a":"alfred-adler","t":"Las satisfacciones infantiles del afán de poder se vuelven así un modelo y refuerzan la línea directriz.","o":"Die kindlichen Befriedigungen des Machtstrebens werden so vorbildlich und verstärken die Leitlinie.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["poder","infancia","repeticion"]},{"i":"alfred-adler-038","a":"alfred-adler","t":"También la persona sana tendría que renunciar a orientarse en el mundo si no ordenara su imagen del mundo y su experiencia según ficciones.","o":"Der Gesunde müsste ebenfalls auf die Orientierung in der Welt verziehten, wenn er nicht nach Fiktionen das Weltbild und sein Erleben einordnete.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["conocimiento","salud-mental"]},{"i":"alfred-adler-039","a":"alfred-adler","t":"Estas impresiones, que surgen necesariamente de un sentimiento originario de inferioridad, generan una actitud agresiva cuyo fin es superar la inseguridad.","o":"Diese Eindrücke, die sich aus einem ursprünglichen Gefühl der Minderwertigkeit mit Notwendigkeit herausheben, rufen eine Aggressionsstellung ins Leben, deren Zweck die Überwindung der Unsicherheit ist.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["ira","autoestima","incertidumbre"]},{"i":"alfred-adler-040","a":"alfred-adler","t":"Al superar esta dificultad que él mismo arregló y creó, busca y encuentra una vez más la elevación de su sentimiento de sí.","o":"In der Überwindung dieser arrangierten, selbstgeschaffenen Schwierigkeit sucht und findet er noch einmal die Erhöhung seines Persönlichkeit^gefühls.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["autoestima","repeticion"]},{"i":"alfred-adler-041","a":"alfred-adler","t":"La crisis neurótica, comparable a una lucha por el poder, tiene la función de proteger el sentimiento de sí de las humillaciones.","o":"Der neurotische Anfall endlich, dem Kampf um die Macht vergleichbar, hat die Aufgabe, das Persönlichkeitsgefühl vor Herabsetzungen zu bewahren.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["salud-mental","autoestima"]},{"i":"alfred-adler-042","a":"alfred-adler","t":"El fin ficticio del afán de poder adquiere así una influencia enorme y arrastra en su dirección todas las fuerzas psíquicas.","o":"Dabei kommt der fiktive Endzweck des Machtstrebens zu ungeheurem Einfluss und zieht alle psychischen Kräfte in seine Richtung.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["poder","inconsciente"]},{"i":"alfred-adler-043","a":"alfred-adler","t":"La realidad se desvaloriza en distinto grado, y los caminos correctores, adaptados a la comunidad, resultan cada vez más insuficientes.","o":"Die Realität wird dabei in verschiedenem Grade entwertet, und die korrigierenden, der Gemeinschaft angepassten Bahnen erweisen sich immer mehr als insuffizient.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["salud-mental","sociedad"]},{"i":"alfred-adler-044","a":"alfred-adler","t":"La angustia aparece con frecuencia; a menudo sirve para demostrar que uno no puede estar solo.","o":"Angst findet sich häufig; sie dient oft dem Beweise, dass man nicht allein sein könne.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["angustia","soledad","vinculos"]},{"i":"alfred-adler-045","a":"alfred-adler","t":"Hacia el final de la lactancia, la terquedad y el negativismo infantil ya pueden estar claramente desarrollados.","o":"Gegen Ende der Säuglingszeit kann der Trotz und der kindliche Negativismus schon deutlich entwickelt sein.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["infancia","desarrollo-humano"]},{"i":"alfred-adler-046","a":"alfred-adler","t":"Es fácil entender que se vuelvan incapaces de amor y de amistad.","o":"Dass sie zur Liebe und zur Freundschaft unfähig werden, ist leicht zu verstehen.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["amor","amistad"]},{"i":"alfred-adler-047","a":"alfred-adler","t":"El arreglo se ve con más claridad en el alcoholismo y en la adicción a la morfina y a la cocaína, que solo se curan del todo cuando crece el sentimiento de comunidad y disminuye la vanidad.","o":"Am deutlichsten ist das Arrangement bei Alkoholismus, Morphinismus und Kokainismus, die restlos nur heilen, wenn das Gemeinschaftsgefühl wächst und die Eitelkeit abnimmt.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["salud-mental","vinculos","terapia"]},{"i":"alfred-adler-048","a":"alfred-adler","t":"Con razón puede dudarse de que, en personas sanas, el amor sea capaz de semejante transformación [en odio].","o":"Es ist mit Recht zu bezweifeln, dass Liebe bei gesunden Menschen einer solchen Umwandlung fähig wäre.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["amor","ira"]},{"i":"alfred-adler-049","a":"alfred-adler","t":"En general sería demasiado doloroso reconocerse a sí mismo el “amor rechazado”.","o":"Es wäre in der Regel zu schmerzhaft, sich die \"verschmähte Liebe\" einzugestehen.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["amor","perdida","inconsciente"]},{"i":"alfred-adler-050","a":"alfred-adler","t":"Como motivo siempre disponible para nuevos estallidos y presiones queda todavía el pasado, el recuerdo de privaciones anteriores.","o":"Als stets bereiter Anlass zu erneuten Heftigkeiten und Bedrängungen bleibt immer noch die Vergangenheit und die Erinnerung an frühere Entbehrungen","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["memoria","ira","repeticion"]},{"i":"alfred-adler-051","a":"alfred-adler","t":"Nuestra investigación nos llevó a comprender cómo, a partir de la inferioridad absoluta del niño, [se desarrolla una valoración de sí que produce el sentimiento de inferioridad].","o":"Unsere Betrachtung hat uns dahingeführt zu verstehen, wie sich aus der absoluten Minderwertigkeit des Kindes","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["infancia","autoestima"]},{"i":"otto-rank-001","a":"otto-rank","t":"Traducción propia de Lo que te habita (a partir de la versión inglesa).","o":"The psychic patient, from whose material and by whose help Psychoanalysis was discovered and developed, will always remain the native source for further investigation and extension of the doctrine.","l":"en","ob":"El trauma del nacimiento","an":"1929","u":"","te":["autoconocimiento","terapia"]},{"i":"otto-rank-002","a":"otto-rank","t":"Traducción propia de Lo que te habita (a partir de la versión inglesa).","o":"The patient's \" rebirth-phantasy \" is simply a repetition in the analysis of his own birth.","l":"en","ob":"El trauma del nacimiento","an":"1929","u":"","te":["terapia","infancia"]},{"i":"otto-rank-003","a":"otto-rank","t":"Traducción propia de Lo que te habita (a partir de la versión inglesa).","o":"The analysis finally turns out to he a belated accomplishment of the incomfleted mastery of the birth trauma.","l":"en","ob":"El trauma del nacimiento","an":"1929","u":"","te":["terapia","trauma"]},{"i":"otto-rank-004","a":"otto-rank","t":"Traducción propia de Lo que te habita (a partir de la versión inglesa).","o":"We shall take as our guiding principle Freud's statement that all anxiety goes back originally to the anxiety at birth","l":"en","ob":"El trauma del nacimiento","an":"1929","u":"","te":["angustia","infancia"]},{"i":"otto-rank-005","a":"otto-rank","t":"Traducción propia de Lo que te habita (a partir de la versión inglesa).","o":"Every child has anxiety, and from the standpoint of the average healthy adult, one can, with a certain amount of justification, designate the childhood of individuals as their normal neurosis.","l":"en","ob":"El trauma del nacimiento","an":"1929","u":"","te":["infancia","angustia"]},{"i":"otto-rank-006","a":"otto-rank","t":"Traducción propia de Lo que te habita (a partir de la versión inglesa).","o":"Only this may continue into adult life in the case of certain individuals, the neurotics, who therefore remain infantile or are called infantile.","l":"en","ob":"El trauma del nacimiento","an":"1929","u":"","te":["infancia","salud-mental"]},{"i":"otto-rank-007","a":"otto-rank","t":"Traducción propia de Lo que te habita (a partir de la versión inglesa).","o":"In thoroughly investigating the conditions under which the child's anxiety arises, we find that the anxiety experienced at parturition really continues, undisposed of, to influence the child.","l":"en","ob":"El trauma del nacimiento","an":"1929","u":"","te":["angustia","infancia"]},{"i":"otto-rank-008","a":"otto-rank","t":"Traducción propia de Lo que te habita (a partir de la versión inglesa).","o":"In this way the partial change of the primal anxiety into the (sexual) guilt feeling occurs.","l":"en","ob":"El trauma del nacimiento","an":"1929","u":"","te":["culpa","angustia"]},{"i":"otto-rank-009","a":"otto-rank","t":"Traducción propia de Lo que te habita (a partir de la versión inglesa).","o":"Soon the child's every game will somehow be subordinated to the viewpoint of its unreality.","l":"en","ob":"El trauma del nacimiento","an":"1929","u":"","te":["infancia","creatividad"]},{"i":"otto-rank-010","a":"otto-rank","t":"Traducción propia de Lo que te habita (a partir de la versión inglesa).","o":"The identification of death with the return to the mother also explains why the dead must not be disturbed in their rest and why such a disturbance is regarded as the greatest punishment.","l":"en","ob":"El trauma del nacimiento","an":"1929","u":"","te":["muerte","vinculos"]},{"i":"otto-rank-011","a":"otto-rank","t":"Traducción propia de Lo que te habita (a partir de la versión inglesa).","o":"This proves the secondary nature of the whole rebirth phantasy, which has no other meaning than to re-establish the original condition and remain there.","l":"en","ob":"El trauma del nacimiento","an":"1929","u":"","te":["repeticion","infancia"]},{"i":"otto-rank-012","a":"otto-rank","t":"Traducción propia de Lo que te habita (a partir de la versión inglesa).","o":"The equally frequent anxiety about small animals, which, however, is usually accompanied by dread, has the same foundation","l":"en","ob":"El trauma del nacimiento","an":"1929","u":"","te":["miedo","infancia"]},{"i":"otto-rank-013","a":"otto-rank","t":"Traducción propia de Lo que te habita (a partir de la versión inglesa).","o":"The profound and extensive research of modern investigations has shown that not India, but rather Babylonia, may be regarded as the first home of the myths.","l":"en","ob":"El mito del nacimiento del héroe","an":"1914","u":"","te":["sociedad","creatividad"]},{"i":"otto-rank-014","a":"otto-rank","t":"Traducción propia de Lo que te habita (a partir de la versión inglesa).","o":"All of us, perhaps, were doomed to direct the first sexual emotion towards the mother, the first hatred and aggressive desire against the father; our dreams convince us of this truth.","l":"en","ob":"El mito del nacimiento del héroe","an":"1914","u":"","te":["vinculos","infancia"]},{"i":"otto-rank-015","a":"otto-rank","t":"Traducción propia de Lo que te habita (a partir de la versión inglesa).","o":"Innumerable fairy tales, stories, and poems of all times, up to the most recent dramatic and novelistic literature, show very distinct individual main motives of this myth.","l":"en","ob":"El mito del nacimiento del héroe","an":"1914","u":"","te":["creatividad","repeticion"]},{"i":"otto-rank-016","a":"otto-rank","t":"Traducción propia de Lo que te habita (a partir de la versión inglesa).","o":"But Abraham casts out his own son Ishmael, with Hagar, the boy's mother","l":"en","ob":"El mito del nacimiento del héroe","an":"1914","u":"","te":["vinculos","familia"]},{"i":"otto-rank-017","a":"otto-rank","t":"Traducción propia de Lo que te habita (a partir de la versión inglesa).","o":"The king was frightened, and at once ordered the death of all newborn children of the Israelites in the entire country.","l":"en","ob":"El mito del nacimiento del héroe","an":"1914","u":"","te":["miedo","infancia"]},{"i":"otto-rank-018","a":"otto-rank","t":"Traducción propia de Lo que te habita (a partir de la versión inglesa).","o":"King Nimrod means to have the child killed immediately after its birth.","l":"en","ob":"El mito del nacimiento del héroe","an":"1914","u":"","te":["poder","miedo"]},{"i":"otto-rank-019","a":"otto-rank","t":"La tesis freudiana de que todo afecto de angustia se remonta en el fondo a la angustia fisiológica del nacimiento (ahogo) nos servirá de guía.","o":"Der Freudsche Satz, daß jeder Angstaffekt im Grunde auf die physiologische Geburtsangst (Atemnot) zurückgehe, soll uns dabei als Leitlinie dienen.","l":"de","ob":"El trauma del nacimiento y su significado para el psicoanálisis","an":"1924","u":"","te":["angustia","infancia"]},{"i":"otto-rank-020","a":"otto-rank","t":"Para el niño, estar muerto equivale a estar ido (Freud), es decir, estar separado, lo que toca directamente el trauma originario.","o":"Totsein ist für das Kind gleichbedeutend mit Fortsein (Freud), d.h. getrennt sein, was unmittelbar an das Urtrauma rührt.","l":"de","ob":"El trauma del nacimiento y su significado para el psicoanálisis","an":"1924","u":"","te":["muerte","infancia"]},{"i":"otto-rank-021","a":"otto-rank","t":"El niño acepta, pues, la representación consciente de la muerte, identificándola inconscientemente con la separación originaria.","o":"Das Kind akzeptiert also die bewußte Todesvorstellung, indem es sie unbewußt mit der Urtrennung identifiziert.","l":"de","ob":"El trauma del nacimiento y su significado para el psicoanálisis","an":"1924","u":"","te":["muerte","inconsciente"]},{"i":"otto-rank-022","a":"otto-rank","t":"En general, el niño no conoce una representación abstracta de la muerte: reacciona solo ante la muerte vivida o descrita (explicada) de las personas que le son cercanas.","o":"Überhaupt kennt das Kind keine abstrakte Todesvorstellung, es reagiert nur auf den erlebten Todesfall oder den geschilderten (erklärten) inbezug auf die ihm nahestehenden Personen.","l":"de","ob":"El trauma del nacimiento y su significado para el psicoanálisis","an":"1924","u":"","te":["muerte","infancia"]},{"i":"otto-rank-023","a":"otto-rank","t":"El sobresalto, a menudo consciente, de las mujeres neuróticas ante la pregunta de cómo ha de entrar en ellas aquella cosa tan grande toca directamente la represión originaria del trauma del nacimiento.","o":"Der oft bewußte Schreck neurotischer Frauen, wie denn das große Ding in sie hineingehen solle, rührt unmittelbar an die Urverdrängung des Geburtstraumas.","l":"de","ob":"El trauma del nacimiento y su significado para el psicoanálisis","an":"1924","u":"","te":["cuerpo","angustia"]},{"i":"otto-rank-024","a":"otto-rank","t":"En el miedo a estar solo se recuerda, pues, al parecer, el afecto de angustia de la primera separación del objeto libidinal, y precisamente mediante un revivir real, por reproducción y descarga.","o":"In der Angst vor dem Alleinsein wird also offenbar der Angstaffekt der ersten Trennung vom Libidoobjekt er-innert, und zwar durch reales Wiedererleben, durch Reproduktion und Abfuhr.","l":"de","ob":"El trauma del nacimiento y su significado para el psicoanálisis","an":"1924","u":"","te":["miedo","vinculos"]},{"i":"otto-rank-025","a":"otto-rank","t":"A ese mismo proceso corresponden todas las formas de desarrollo neurótico de la angustia, incluidas las fobias, por la vía de los mecanismos que descubre el análisis.","o":"Dem gleichen Vorgang entsprechen alle Formen neurotischer Angstentwicklung, einschließlich der Phobien, auf dem Wege der durch die Analyse aufgedeckten Mechanismen.","l":"de","ob":"El trauma del nacimiento y su significado para el psicoanálisis","an":"1924","u":"","te":["angustia","terapia"]},{"i":"otto-rank-026","a":"otto-rank","t":"Pero parece ser este el mecanismo por el que surge la angustia, que es, por así decirlo, el primer contenido psíquico del que el ser humano llega a ser consciente.","o":"Dieser Weg scheint aber der Mechanismus zu sein, auf dem die Angst entsteht, die sozusagen der erste psychische Inhalt ist, dessen sich der Mensch bewußt wird.","l":"de","ob":"El trauma del nacimiento y su significado para el psicoanálisis","an":"1924","u":"","te":["angustia","conciencia"]},{"i":"otto-rank-027","a":"otto-rank","t":"El rechazo sexual tan marcado que se manifiesta en el ataque histérico es una consecuencia de la fijación a la madre.","o":"Die eminente Sexualablehnung, die sich im hysterischen Anfall so deutlich manifestiert, ist eine Folge der Mutterfixierung.","l":"de","ob":"El trauma del nacimiento y su significado para el psicoanálisis","an":"1924","u":"","te":["deseo","vinculos"]},{"i":"otto-rank-028","a":"otto-rank","t":"La enferma niega, en el “lenguaje de los órganos”, junto con el deseo sexual, también el deseo de volver al seno materno, que es justamente lo que le impide la empatía sexual normal.","o":"Die Kranke verleugnet in der \"Organsprache\" zugleich mit dem Sexualwunsch auch den, Wunsch der Rückkehr in den Mutterleib, welcher sie eben an der normalen sexuellen Einfühlung hindert.","l":"de","ob":"El trauma del nacimiento y su significado para el psicoanálisis","an":"1924","u":"","te":["cuerpo","deseo"]},{"i":"otto-rank-029","a":"otto-rank","t":"La menstruación, que también prolonga “periódicamente” la existencia en el seno materno, parece haber quedado incluida, en el ser humano civilizado, en la represión general del trauma del nacimiento.","o":"Die Menstruation, welche ja auch \"periodisch\" die Mutterleibsexistenz fortsetzt, scheint beim Kulturmenschen in die allgemeine Verdrängung des Geburtstraumas einbezogen worden zu sein.","l":"de","ob":"El trauma del nacimiento y su significado para el psicoanálisis","an":"1924","u":"","te":["cuerpo","inconsciente"]},{"i":"otto-rank-030","a":"otto-rank","t":"Pero este odio, que debe servir para desprenderse del amor a la madre, no es sino otra forma de fijación a la madre, a quien uno queda ahora ligado en el odio.","o":"Dieser Haß, der dazu dienen soll, von der Liebe zur Mutter loszukommen, bedeutet aber nur eine andere Art der Fixierung an die Mutter, an die man nun in Haß gebunden ist.","l":"de","ob":"El trauma del nacimiento y su significado para el psicoanálisis","an":"1924","u":"","te":["ira","vinculos"]},{"i":"otto-rank-031","a":"otto-rank","t":"El punto de vista aquí sostenido sobre la importancia fundamental del trauma del nacimiento parece acercarnos, en efecto, a la solución.","o":"Der hier vertretene Gesichtspunkt von der fundamentalen Bedeutung des Geburtstraumas scheint uns nun tatsächlich der Lösung nahe zu bringen.","l":"de","ob":"El trauma del nacimiento y su significado para el psicoanálisis","an":"1924","u":"","te":["terapia","inconsciente"]},{"i":"otto-rank-032","a":"otto-rank","t":"¿No podría ser el estupor catatónico, que representa un rechazo completo del mundo exterior, una regresión al seno materno?","o":"Könnte der katatone Stupor, der eine vollkommene Ablehnung der Außenwelt darstellt, nicht eine Zurückversetzung in den Mutterleib sein?","l":"de","ob":"El trauma del nacimiento y su significado para el psicoanálisis","an":"1924","u":"","te":["inconsciente","cuerpo"]},{"i":"otto-rank-033","a":"otto-rank","t":"También se considera a la diosa de la luna auxiliar del parto (comadrona), lo que se relaciona con su influjo sobre la menstruación.","o":"Auch gilt die Mondgöttin als Beistand der Geburt (Hebamme), was mit ihrem Einfluß auf die Menstruation zusammenhängt.","l":"de","ob":"El trauma del nacimiento y su significado para el psicoanálisis","an":"1924","u":"","te":["cultura","cuerpo"]},{"i":"otto-rank-034","a":"otto-rank","t":"Así, los síntomas corporales de la neurosis (en pacientes mujeres) resultaron ser el depósito de la libido desplazada de modo patológico hacia el padre (identificación con la madre).","o":"Die körperlichen Symptome der Neurose erwiesen sich so (bei weiblichen Patienten) als Niederschlag der in pathologischer Weise auf den Vater verschobenen Libido (Mutteridentifizierung).","l":"de","ob":"El trauma del nacimiento y su significado para el psicoanálisis","an":"1924","u":"","te":["cuerpo","deseo"]},{"i":"otto-rank-035","a":"otto-rank","t":"El intento de investir sexualmente el genital (materno) cargado de angustia produce sentimiento de culpa, pues la angustia materna se liga al padre según el mecanismo de la fobia.","o":"Der Versuch, das angstbesetzte (mütterliche) Genitale sexuell zu besetzen, macht Schuldgefühl, indem die maternale Angst nach dem Mechanismus der Phobie an den Vater gebunden wird.","l":"de","ob":"El trauma del nacimiento y su significado para el psicoanálisis","an":"1924","u":"","te":["angustia","vinculos"]},{"i":"otto-rank-036","a":"otto-rank","t":"Esto muestra la tendencia a la sustitución inmediata de la madre in statu nascendi.","o":"Dies zeigt die Tendenz zur unmittelbaren Ersetzung der Mutter in \"statu nascendi\".","l":"de","ob":"El trauma del nacimiento y su significado para el psicoanálisis","an":"1924","u":"","te":["vinculos","cambio"]},{"i":"otto-rank-037","a":"otto-rank","t":"Además, también las perversiones, que según Freud constituyen el positivo de la neurosis, se remontan de modo decisivo a la situación infantil originaria.","o":"Weiters gehen aber auch die Perversionen, die ja nach Freud das Positiv der Neurose darstellen, in entscheidender Weise auf die infantile Ursituation zurück.","l":"de","ob":"El trauma del nacimiento y su significado para el psicoanálisis","an":"1924","u":"","te":["infancia","deseo"]},{"i":"otto-rank-038","a":"otto-rank","t":"Por otro lado, una mujer que había dado a luz a su hijo bajo anestesia tuvo la sensación de que no era suyo, porque había estado inconsciente durante el parto.","o":"Anderseits hatte eine Frau, die ihr Kind in Narkose zur Welt gebracht hatte, das Gefühl, es sei nicht ihres, weil sie bei der Geburt bewußtlos gewesen sei.","l":"de","ob":"El trauma del nacimiento y su significado para el psicoanálisis","an":"1924","u":"","te":["identidad","vinculos"]},{"i":"otto-rank-039","a":"otto-rank","t":"Por lo demás, según algunas averiguaciones aisladas, parece que los niños nacidos por operación se desarrollan efectivamente mejor en cierto sentido.","o":"Übrigens hat es nach vereinzelten Erkundigungen den Anschein, als ob Kinder, die operativ zur Welt gebracht wurden, sich tatsächlich in gewisser Beziehung besser entwickelten.","l":"de","ob":"El trauma del nacimiento y su significado para el psicoanálisis","an":"1924","u":"","te":["infancia","cuerpo"]},{"i":"otto-rank-040","a":"otto-rank","t":"Quizá también se podría creer que esto debe resultar, al final, como consecuencia de análisis prolongados en exceso.","o":"Auch könnte man vielleicht glauben, daß dies als Resultat übermäßig lange fortgeführter Analysen sich schließlich auch ergeben müsse.","l":"de","ob":"El trauma del nacimiento y su significado para el psicoanálisis","an":"1924","u":"","te":["terapia"]},{"i":"otto-rank-041","a":"otto-rank","t":"También las típicas molestias menstruales se comprenden fácilmente en este sentido, pues en realidad el parto no es más que una menstruación colectiva.","o":"Auch die typischen Menstrualbeschwerden lassen sich leicht in diesem Sinne verstehen, wie ja tatsächlich die Geburt nur eine Kollektiv-Menstruation darstellt.","l":"de","ob":"El trauma del nacimiento y su significado para el psicoanálisis","an":"1924","u":"","te":["cuerpo","inconsciente"]},{"i":"otto-rank-042","a":"otto-rank","t":"Con las teorías mencionadas solo podría explicarse la variedad y la difusión del mito, pero no su origen.","o":"Durch die genannten Theorien könnte nur die Mannigfaltigkeit und Verbreitung, nicht aber die Herkunft des Mythus erklärt werden.","l":"de","ob":"El mito del nacimiento del héroe","an":"1909 (2.ª ed. 1922)","u":"","te":["cultura"]},{"i":"otto-rank-043","a":"otto-rank","t":"Quizá a todos nos ha tocado dirigir el primer impulso sexual hacia la madre y el primer odio y deseo violento contra el padre; nuestros sueños nos convencen de ello.","o":"Uns allen vielleicht war es beschieden, die erste sexuelle Regung auf die Mutter, den ersten Haß und gewalttätigen Wunsch gegen den Vater zu richten; unsere Träume überzeugen uns davon.","l":"de","ob":"El mito del nacimiento del héroe","an":"1909 (2.ª ed. 1922)","u":"","te":["deseo","infancia"]},{"i":"otto-rank-044","a":"otto-rank","t":"Antes de su nacimiento, el rey Abimelec es advertido en sueños de que no toque a Sara, pues de lo contrario tendría que morir.","o":"Vor seiner Geburt wird König Abimelech im Traum gewarnt, die Sarah zu berühren, da er sonst sterben müsse.","l":"de","ob":"El mito del nacimiento del héroe","an":"1909 (2.ª ed. 1922)","u":"","te":["cultura","miedo"]},{"i":"otto-rank-045","a":"otto-rank","t":"Antes de su nacimiento se revela al rey Nimrod, a partir de las estrellas, que el niño esperado derribará del trono a poderosos príncipes y tomará posesión de sus tierras.","o":"Vor seiner Geburt wird dem König Nimrod aus den Sternen geoffenbart, das zu erwartende Kind werde mächtige Fürsten vom Throne stürzen und ihre Länder in Besitz nehmen.","l":"de","ob":"El mito del nacimiento del héroe","an":"1909 (2.ª ed. 1922)","u":"","te":["cultura","identidad"]},{"i":"otto-rank-046","a":"otto-rank","t":"Entrega entonces a un niño ajeno, mientras oculta a su propio hijo en una cueva bajo la tierra, donde Dios le hace chupar leche de un dedo de la mano derecha.","o":"Er liefert dann ein fremdes Kind aus, während er seinen eigenen Sohn in einer Höhle unter der Erde verbirgt, wo Gott ihn Milch aus einem Finger der rechten Hand saugen läßt.","l":"de","ob":"El mito del nacimiento del héroe","an":"1909 (2.ª ed. 1922)","u":"","te":["infancia","cultura"]},{"i":"otto-rank-047","a":"otto-rank","t":"Alarmado por ello, el rey dictó de inmediato la orden de matar a todos los recién nacidos de los israelitas en todo el país.","o":"Der dadurch geängstigte König erließ sogleich den Befehl, alle neugeborenen Kinder der Israeliten im ganzen Lande zu töten.","l":"de","ob":"El mito del nacimiento del héroe","an":"1909 (2.ª ed. 1922)","u":"","te":["miedo","cultura"]},{"i":"otto-rank-048","a":"otto-rank","t":"Así nació el rey Vikrama, y de modo parecido su hijo Vikramaditya; por eso ambos son designados en el libro de los héroes como “no nacidos”.","o":"So kam König Vikräma zur Welt und ähnlich auch sein Sohn Vikrämaditya, die darum beide im Heldenbuche als \"ungeboren\" bezeichnet werden.","l":"de","ob":"El mito del nacimiento del héroe","an":"1909 (2.ª ed. 1922)","u":"","te":["cultura","identidad"]},{"i":"otto-rank-049","a":"otto-rank","t":"También el héroe comienza, como muestra su separación de los padres, su trayectoria en oposición a la generación anterior: es rebelde e innovador a la vez, es revolucionario.","o":"Auch der Held beginnt ja, wie seine Ablösung von den Eltern zeigt, seine Laufbahn im Gegensatz zur alten Generation; er ist Empörer und Erneuerer zugleich, er ist Revolutionär.","l":"de","ob":"El mito del nacimiento del héroe","an":"1909 (2.ª ed. 1922)","u":"","te":["identidad","vinculos"]},{"i":"otto-rank-050","a":"otto-rank","t":"Durante muchos años sufrió la angustia inexplicable de volver a ver a esa persona.","o":"Seit vielen Jahren litt er an der unerklärlichen Angst, diesen Menschen wiederzusehen.","l":"de","ob":"El mito del nacimiento del héroe","an":"1909 (2.ª ed. 1922)","u":"","te":["angustia","sufrimiento"]},{"i":"otto-rank-051","a":"otto-rank","t":"En el análisis se revela que todos estos sentimientos se dirigen al padre real, al que está fijado con todos sus sentimientos positivos y negativos.","o":"In der Analyse ergibt sich, daß alle diese Gefühle dem wirklichen Vater gelten, an den er mit allen seinen positiven und negativen Gefühlen fixiert ist.","l":"de","ob":"El mito del nacimiento del héroe","an":"1909 (2.ª ed. 1922)","u":"","te":["vinculos","emociones"]},{"i":"karen-horney-001","a":"karen-horney","t":"El propósito de este libro no es mostrar lo que está mal en el psicoanálisis, sino, eliminando los elementos discutibles, permitirle desarrollarse hasta lo más alto de sus posibilidades.","o":"Thus the purpose of this book is not to show what is wrong with psychoanalysis, but, through eliminating the debatable elements, to enable psychoanalysis to develop to the height of its potentialities.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"","te":["terapia","conocimiento"]},{"i":"karen-horney-002","a":"karen-horney","t":"Mi convicción, en pocas palabras, es que el psicoanálisis debe superar los límites que le impone ser una psicología instintivista y genética.","o":"My conviction, expressed in a nutshell, is that psychoanalysis should outgrow the limitations set by its being an instinctivistic and a genetic psychology.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"","te":["terapia","cambio"]},{"i":"karen-horney-003","a":"karen-horney","t":"La deformación del yo espontáneo de la persona debe reconocerse como un factor fundamental en el origen y el sostenimiento de las neurosis.","o":"The warping of the spontaneous individual self must then be recognized as a paramount factor in the genesis and maintenance of neuroses.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"","te":["identidad","autenticidad","salud-mental"]},{"i":"karen-horney-004","a":"karen-horney","t":"Su esencia misma [de las neurosis] consiste en perturbaciones de la relación con uno mismo y con los demás, y en los conflictos que surgen de ellas.","o":"Their very essence consists of disturbances in the relations to self and others, and conflicts arising on these grounds.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"","te":["vinculos","identidad","salud-mental"]},{"i":"karen-horney-005","a":"karen-horney","t":"Más allá de este objetivo asoma una meta terapéutica completamente nueva: devolver a la persona a sí misma, ayudarla a recuperar su espontaneidad y a encontrar en sí misma su centro de gravedad.","o":"Beyond this aim there looms an entirely new tlierapeutic goal, which is to restore the individual to himself, to help him regain his spontaneity and find his center of gravity in himself.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"","te":["terapia","autenticidad","transformacion-personal"]},{"i":"karen-horney-006","a":"karen-horney","t":"A mi juicio, liberar al paciente de la angustia es solo un medio. El fin es ayudarlo a recuperar su espontaneidad, a encontrar en sí mismo sus propias medidas de valor; en suma, a darle el coraje de ser él mismo.","o":"In my judgment, freeing the patient from anxiety is only a means to an end. The end is to help him to regain his spontaneity, to find his measurements of value in himself, in short, to give him the courage to be himself.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 16","te":["terapia","autenticidad","angustia"]},{"i":"karen-horney-007","a":"karen-horney","t":"Es un peligro serio porque contradice la meta de la terapia, que es o debería ser ayudar al paciente a convertirse en una personalidad libre e independiente.","o":"This is a serious danger because it counteracts the goal of therapy, which is or should be to help the patient to become a free and independent personality.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 9","te":["terapia","libertad"]},{"i":"karen-horney-008","a":"karen-horney","t":"Para quien nunca tuvo la experiencia de descubrir en sí actitudes o metas cuya fuerza ignoraba, este concepto [el inconsciente] es probablemente difícil de captar.","o":"Probably to anyone who has not had the experience of discovering within himself attitudes or goals whose power he was unaware of, this concept is difficult to grasp.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 1","te":["inconsciente","autoconocimiento"]},{"i":"karen-horney-009","a":"karen-horney","t":"Decirle que en realidad no le gustan [las personas], sino que se siente obligado a que le gusten, puede impactarle enseguida: siente que siempre lo supo de manera confusa, pero no se atrevía a reconocerlo.","o":"Our assertion that he does not like them but that he only feels obliged to do so may strike home at once; his feeling is that he was always dimly aware of this, but did not dare recognize it.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 1","te":["inconsciente","vinculos","autenticidad"]},{"i":"karen-horney-010","a":"karen-horney","t":"El proceso de proyección no es esencialmente distinto de la tendencia a suponer ingenuamente que los demás sienten o reaccionan como nosotros.","o":"The process of projection is not essentially different from the tendency to assume naively that others feel or react in the same manner as we ourselves do.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 1","te":["vinculos","inconsciente"]},{"i":"karen-horney-011","a":"karen-horney","t":"Si un paciente se desprecia por estar enredado en toda clase de conflictos, no puede sino suponer que el analista también lo desprecia.","o":"If a patient, for example, despises himself for being entangled in all sorts of conflicts, he cannot but assume that the analyst despises him likewise.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 1","te":["autoestima","terapia"]},{"i":"karen-horney-012","a":"karen-horney","t":"Además, si una persona está irritada consigo misma, su irritación puede aparecer contra cualquiera que la rodee.","o":"Also, if an individual feels irritated at himself his irritation may appear against anyone in the environment.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 1","te":["ira","vinculos"]},{"i":"karen-horney-013","a":"karen-horney","t":"Un enojo definido con uno mismo o con otros puede aparecer, por ejemplo, como un estado general y difuso de irritación.","o":"A definite anger at the self or others may, for example, appear as a general diffuse state of irritation.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 1","te":["ira","emociones"]},{"i":"karen-horney-014","a":"karen-horney","t":"Una angustia ligada a un dilema concreto puede aparecer como una angustia vaga, sin contenido.","o":"An anxiety connected with a definite dilemma may appear as a vague anxiety without any content.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 1","te":["angustia"]},{"i":"karen-horney-015","a":"karen-horney","t":"La incapacidad de reprochar algo a alguien o de defender los propios intereses puede aparecer en la conciencia como amable consideración por los sentimientos ajenos o como capacidad de comprender a la gente.","o":"An incapacity to accuse someone or to defend one's own interests may appear in awareness as a kind consideration for the feelings of others, or as a capacity to understand people.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 1","te":["vinculos","inconsciente","autoestima"]},{"i":"karen-horney-016","a":"karen-horney","t":"La incapacidad de ir a buscar lo que uno quiere puede aparecer como generosidad; un miedo hipocondríaco, como el deber de cuidarse.","o":"An incapacity to reach out for what one wants may appear as unselfishness; a hypochondriacal fear, as duty to take care of oneself.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 1","te":["deseo","miedo","inconsciente"]},{"i":"karen-horney-017","a":"karen-horney","t":"Por último, los deseos o miedos reprimidos pueden reaparecer en sueños y fantasías.","o":"Fourth, and finally, repressed wishes or fears may reappear in dreams and fantasies.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 1","te":["suenos","inconsciente"]},{"i":"karen-horney-018","a":"karen-horney","t":"Lo que a menudo se describe como resistencia del paciente a curarse suele ser su negativa a abandonar sus ilusiones.","o":"what is very often described as a patient's reluctance to get well is often his unwillingness to abandon his illusions.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 1","te":["terapia","cambio"]},{"i":"karen-horney-019","a":"karen-horney","t":"En las neurosis, la función más importante de los sueños es buscar tranquilidad frente a una angustia o soluciones de compromiso para conflictos que no tienen solución en la vida real.","o":"In neuroses the most important function of dreams is the attempt to find either reassurance for an anxiety or compromise solutions for conflicts insoluble in real life.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 1","te":["suenos","angustia"]},{"i":"karen-horney-020","a":"karen-horney","t":"La relación analítica, que es una forma de relación humana, nos da posibilidades inéditas para comprender estos procesos.","o":"The psychoanalytical relationship, which is one form of human relations, provides us with unheard-of possibilities in understanding these processes.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 1","te":["terapia","vinculos"]},{"i":"karen-horney-021","a":"karen-horney","t":"Por resistencia se entiende la energía con la que una persona protege sentimientos o pensamientos reprimidos para que no lleguen a la conciencia.","o":"By resistance is meant the energy with which an individual protects repressed feelings or thoughts against their integration into conscious awareness.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 1","te":["terapia","inconsciente"]},{"i":"karen-horney-022","a":"karen-horney","t":"El principio de esta regla fundamental de la terapia es que existe una continuidad de pensamientos y sentimientos aunque no sea evidente.","o":"The working principle used in this fundamental rule of psychoanalytical therapy is that a continuity of thoughts and feelings exists even if it is not apparent.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 1","te":["terapia","inconsciente"]},{"i":"karen-horney-023","a":"karen-horney","t":"El afán sádico de poder nace de la debilidad, la angustia y los impulsos de venganza; el afán no sádico de poder nace de un sentimiento de fuerza, de una capacidad de liderazgo o de la entrega a una causa.","o":"A sadistic striving for power is born of weakness, anxiety and revenge impulses, while a non-sadistic striving for power is born of a feeling of strength, a capacity for leadership or devotion to a cause.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 3","te":["poder","angustia"]},{"i":"karen-horney-024","a":"karen-horney","t":"Para quienes, como yo, consideramos las neurosis el resultado último de perturbaciones en las relaciones humanas, esas perturbaciones aparecerán necesariamente en toda relación, sexual o no.","o":"To those who, as I do, regard neuroses as the ultimate outcome of disturbances in human relationships, these disturbances must of necessity appear in every relationship, sexual or non-sexual.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 3","te":["vinculos","salud-mental"]},{"i":"karen-horney-025","a":"karen-horney","t":"En realidad, las personas sanas, niños y adultos, pueden soportar una cantidad considerable de frustración sin reaccionar con hostilidad.","o":"Actually, however, healthy personschildren as well as adults- are well able to endure a considerable amount of frustration without any reaction of hostility.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 3","te":["resiliencia","ira"]},{"i":"karen-horney-026","a":"karen-horney","t":"La angustia básica, definida como un sentimiento de desamparo [frente a un mundo potencialmente hostil].","o":"basic anxiety, defined as a feeling of helplessness","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 3","te":["angustia","infancia"]},{"i":"karen-horney-027","a":"karen-horney","t":"[El niño] siente en peligro su individualidad, su libertad, su posibilidad de ser feliz.","o":"He feels in danger of his individuality being obliterated, his freedom taken away, his happiness prevented.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 3","te":["infancia","angustia","libertad"]},{"i":"karen-horney-028","a":"karen-horney","t":"Por lo general está demasiado intimidado para expresar su resentimiento o sus reproches, y cuando los expresa lo hacen sentir culpable.","o":"He is usually too intimidated to express his resentment or his accusations, and when he does express them he is made to feel guilty.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 3","te":["infancia","culpa","ira"]},{"i":"karen-horney-029","a":"karen-horney","t":"La hostilidad que debe reprimirse precipita la angustia, porque es peligrosa cuando se dirige contra alguien de quien uno se siente dependiente.","o":"The hostility which has to he repressed precipitates anxiety, because hostility is a danger when directed against someone on whom one feels dependent.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 3","te":["angustia","ira","vinculos"]},{"i":"karen-horney-030","a":"karen-horney","t":"Cuanto más frágil es la estructura de una persona, menor es el incidente necesario para alterar su equilibrio y arrojarla a la angustia, la depresión u otros síntomas.","o":"The more shaky a person's structure, the slighter an incident need be in order to disturb his equilibrium and throw him into anxieties, depressions or other neurotic symptoms.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 8","te":["salud-mental","resiliencia"]},{"i":"karen-horney-031","a":"karen-horney","t":"Las experiencias adversas de este tipo hacen que un niño pierda tempranamente su confianza espontánea en la bondad y la justicia de los demás.","o":"Adverse experiences of the kind described will make a child lose at an early age his spontaneous trust in the benevolence and justice of others.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 8","te":["infancia","vinculos","trauma"]},{"i":"karen-horney-032","a":"karen-horney","t":"En general, el paciente no conoce sus reacciones ni lo que las provoca, y tiene un interés definido, aunque oculto, en no conocerlas.","o":"The patient in general does not know his reactions or the conditions provoking them, and has a definite though hidden interest not to know them.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 9","te":["inconsciente","autoconocimiento"]},{"i":"karen-horney-033","a":"karen-horney","t":"El paciente siente alivio al reconocer que hay algo compulsivo, algo no genuino, en sus sentimientos de amor.","o":"The patient feels relieved because he recognizes that there is something compulsory, something not genuine, in his feelings of love.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 9","te":["amor","autenticidad"]},{"i":"karen-horney-034","a":"karen-horney","t":"En la mente del propio paciente, por razones de peso, esta necesidad de afecto aparece casi siempre como amor y devoción.","o":"In the patient's own mind, for many stringent reasons, this need for affection appears mostly as love and devotion.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 9","te":["amor","inconsciente"]},{"i":"karen-horney-035","a":"karen-horney","t":"Por eso, cuando el paciente muestra un apego mayor que el habitual hacia el analista, este debe relacionarlo primero con indicios de angustia o inseguridad.","o":"Therefore whenever the patient shows a more than usual attachment to the analyst, the latter should in the first instance connect it with existing indications of anxiety or insecurity.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 9","te":["terapia","vinculos","angustia"]},{"i":"karen-horney-036","a":"karen-horney","t":"En la relación analítica, como en las demás, es toda la estructura actual de la personalidad la que decide si alguien se siente atraído por otros y por qué.","o":"In the analytical relationship, as in others, it is the entire actual structure of the personality which decides whether and why an individual feels attracted to others.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 9","te":["vinculos","identidad"]},{"i":"karen-horney-037","a":"karen-horney","t":"Como el análisis inevitablemente ataca defensas que hasta entonces cumplían funciones importantes, despierta angustia y hostilidad defensiva.","o":"As analysis unavoidably attacks defenses which hitherto fulfilled important functions, it is bound to stir up anxiety and arouse defensive hostility.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 9","te":["terapia","angustia"]},{"i":"karen-horney-038","a":"karen-horney","t":"Un paciente tiene que defender sus defensas mientras las necesite, y es natural que vea al analista como un intruso peligroso.","o":"A patient has to defend his defenses as long as they are necessary for him, and he is bound to resent the analyst as a dangerous intruder.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 9","te":["terapia","aceptacion"]},{"i":"karen-horney-039","a":"karen-horney","t":"Puede llevar al analista a negarse que tiene reacciones emocionales hacia el paciente, cuando sería más adecuado aconsejarle que comprenda sus reacciones personales frente a él.","o":"It may delude the analyst into denying to himself that he has any emotional reactions to the patient, whereas it would be more appropriate to advise that the analyst should understand his personal reactions to the patient.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 9","te":["terapia","autoconocimiento"]},{"i":"karen-horney-040","a":"karen-horney","t":"Es imposible, por ejemplo, analizar todas las implicancias de la ambición neurótica o de la dependencia masoquista si uno no trabajó esos problemas en sí mismo.","o":"It is impossible, for instance, to analyze all the implications of neurotic ambition or of masochistic dependency if one has not worked out these problems in oneself.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 9","te":["terapia","autoconocimiento"]},{"i":"karen-horney-041","a":"karen-horney","t":"El desarrollo neurótico de una persona surge, en última instancia, de sentimientos de alienación, hostilidad, miedo y menor confianza en sí misma.","o":"A neurotic development in the individual arises ultimately from feelings of alienation, hostility, fear and diminished self-confidence.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 10","te":["salud-mental","autoestima","miedo"]},{"i":"karen-horney-042","a":"karen-horney","t":"Entre los factores de la civilización occidental que generan hostilidad, el primero es probablemente que esta cultura está construida sobre la competencia individual.","o":"Among the factors in western civilization which engender potential hostility, the fact that this culture is built on individual competitiveness probably ranks first.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 10","te":["sociedad","cultura","ira"]},{"i":"karen-horney-043","a":"karen-horney","t":"[La confianza en uno mismo] se daña con cualquier fracaso que la persona atribuye a sus propias carencias, sea en la vida social, profesional o amorosa.","o":"It is impaired by any failure which the individual ascribes to his own deficiencies, whether the failure occur in social, professional or love life.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 10","te":["autoestima"]},{"i":"karen-horney-044","a":"karen-horney","t":"Además, en nuestra cultura la persona por lo general no está preparada para las hostilidades y luchas que le esperan.","o":"Furthermore, the individual in our culture is as a rule not prepared for the hostilities and struggles that are in store for him.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 10","te":["sociedad","educacion"]},{"i":"karen-horney-045","a":"karen-horney","t":"Esta contradicción entre las tensiones hostiles que existen de hecho y la prédica del amor fraternal puede también, creo, influir decisivamente en la pérdida de confianza en uno mismo.","o":"This contradiction between factually existing hostile tensions and the gospel of brotherly love may also, I believe, have a decisive influence on lowering self-confidence.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 10","te":["sociedad","autoestima"]},{"i":"karen-horney-046","a":"karen-horney","t":"Los problemas que se repiten en las neurosis no son esencialmente distintos de los de la persona sana en nuestra cultura.","o":"The types of problems which recur in neuroses are not essentially different from those of the healthy individual in our culture.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 10","te":["salud-mental","sociedad"]},{"i":"karen-horney-047","a":"karen-horney","t":"También ella tiene tendencias contradictorias entre competencia y afecto, egocentrismo y solidaridad, engrandecimiento y sentimientos de inferioridad, egoísmo y altruismo.","o":"He too has contradictory tendencies in regard to competition and affection, egocentricity and solidarity, self-aggrandizement and inferiority feelings, egoism and altruism.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 10","te":["identidad","sociedad"]},{"i":"karen-horney-048","a":"karen-horney","t":"Quienes sucumben a una neurosis son quienes fueron golpeados con más dureza por las dificultades existentes, sobre todo en la infancia.","o":"The persons who succumb to a neurosis are those who have been more severely hit by the existing difficulties, particularly in their childhood.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 10","te":["infancia","salud-mental"]},{"i":"karen-horney-049","a":"karen-horney","t":"Parte del aguijón personal desaparece cuando el analista ayuda al paciente a ver que el destino no fue injusto solo con él, sino que, en última instancia, comparte su destino con sus semejantes.","o":"Some of the personal sting for the patient is removed when the analyst can help him to realize that fate has not been especially unfair to him alone, but that ultimately he shares his fate with his fellow beings.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 10","te":["terapia","aceptacion","vinculos"]},{"i":"karen-horney-050","a":"karen-horney","t":"Por eso la autoestima y la autoinflación se excluyen mutuamente.","o":"Hence selfesteem and self-inflation are mutually exclusive.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 5","te":["autoestima"]},{"i":"karen-horney-051","a":"karen-horney","t":"Sus lazos afectivos positivos con los demás se debilitan; pierde la capacidad de amar.","o":"His positive emotional ties with others become thin; he loses the capacity to love.","l":"en","ob":"Nuevos caminos en psicoanálisis","an":"1939","u":"Capítulo 5","te":["amor","vinculos"]},{"i":"platon-012","a":"platon","t":"El comienzo es la parte más importante de cualquier obra, sobre todo cuando se trata de algo joven y tierno.","o":"the beginning is the most important part of any work, especially in the case of a young and tender thing","l":"en","ob":"La República","an":"c. 375 a. C.","u":"Libro 2","te":["infancia","educacion"]},{"i":"platon-013","a":"platon","t":"La ciudad donde los gobernantes tienen menos ganas de gobernar es siempre la mejor y la más tranquila; aquella donde más lo desean, la peor.","o":"the State in which the rulers are most reluctant to govern is always the best and most quietly governed, and the State in which they are most eager, the worst.","l":"en","ob":"La República","an":"c. 375 a. C.","u":"Libro 7","te":["poder","sociedad"]},{"i":"platon-014","a":"platon","t":"Hasta que los filósofos sean reyes, o los reyes y príncipes de este mundo tengan el espíritu y la fuerza de la filosofía…","o":"Until philosophers are kings, or the kings and princes of this world have the spirit and power of philosophy","l":"en","ob":"La República","an":"c. 375 a. C.","u":"Libro 5","te":["poder","sociedad"]},{"i":"platon-015","a":"platon","t":"El ejercicio físico, aunque sea obligatorio, no daña el cuerpo; pero el conocimiento adquirido por obligación no echa raíces en la mente.","o":"Bodily exercise, when compulsory, does no harm to the body; but knowledge which is acquired under compulsion obtains no hold on the mind.","l":"en","ob":"La República","an":"c. 375 a. C.","u":"Libro 7","te":["educacion","libertad"]},{"i":"platon-016","a":"platon","t":"El alma es como el ojo: cuando se posa sobre aquello en que brillan la verdad y el ser, percibe, comprende y resplandece de inteligencia.","o":"And the soul is like the eye: when resting upon that on which truth and being shine, the soul perceives and understands, and is radiant with intelligence","l":"en","ob":"La República","an":"c. 375 a. C.","u":"Libro 6","te":["verdad","conciencia"]},{"i":"platon-017","a":"platon","t":"Quien tiene un carácter sereno y alegre apenas siente el peso de la vejez; para quien tiene el carácter opuesto, juventud y vejez son igualmente una carga.","o":"for he who is of a calm and happy nature will hardly feel the pressure of age, but to him who is of an opposite disposition youth and age are equally a burden.","l":"en","ob":"La República","an":"c. 375 a. C.","u":"","te":["desarrollo-humano","felicidad"]},{"i":"platon-018","a":"platon","t":"Mirá: seres humanos que viven en una caverna subterránea…","o":"Behold! human beings living in a underground den","l":"en","ob":"La República","an":"c. 375 a. C.","u":"Libro 7","te":["conocimiento","verdad"]},{"i":"platon-019","a":"platon","t":"Para ellos, la verdad no sería otra cosa que las sombras de las imágenes.","o":"To them, I said, the truth would be literally nothing but the shadows of the images.","l":"en","ob":"La República","an":"c. 375 a. C.","u":"Libro 7","te":["verdad","conocimiento"]},{"i":"platon-020","a":"platon","t":"El verdadero creador es la necesidad, que es la madre de nuestra invención.","o":"the true creator is necessity, who is the mother of our invention","l":"en","ob":"La República","an":"c. 375 a. C.","u":"Libro 2","te":["creatividad"]},{"i":"platon-021","a":"platon","t":"La formación musical es el instrumento más poderoso, porque el ritmo y la armonía penetran en lo más íntimo del alma.","o":"musical training is a more potent instrument than any other, because rhythm and harmony find their way into the inward places of the soul","l":"en","ob":"La República","an":"c. 375 a. C.","u":"Libro 3","te":["educacion","cultura"]},{"i":"platon-022","a":"platon","t":"La virtud es libre.","o":"Virtue is free","l":"en","ob":"La República","an":"c. 375 a. C.","u":"Libro 10","te":["libertad","responsabilidad"]},{"i":"platon-023","a":"platon","t":"Una fe inquebrantable en la verdad y en lo justo.","o":"adamantine faith in truth and right","l":"en","ob":"La República","an":"c. 375 a. C.","u":"Libro 10","te":["verdad","esperanza"]},{"i":"platon-024","a":"platon","t":"¿No es el amor por aprender amor por la sabiduría, es decir, filosofía?","o":"is not the love of learning the love of wisdom, which is philosophy?","l":"en","ob":"La República","an":"c. 375 a. C.","u":"Libro 2","te":["educacion","conocimiento"]},{"i":"platon-025","a":"platon","t":"En el cielo, respondí, hay un modelo de ella [la ciudad justa]: quien lo desee puede contemplarlo y, contemplándolo, poner en orden su propia casa.","o":"In heaven, I replied, there is laid up a pattern of it, methinks, which he who desires may behold, and beholding, may set his own house in order.","l":"en","ob":"La República","an":"c. 375 a. C.","u":"Libro 9","te":["transformacion-personal","sentido-de-vida"]},{"i":"platon-001","a":"platon","t":"Una vida sin examen no merece ser vivida.","o":"the unexamined life is not worth living","l":"en","ob":"Apología de Sócrates","an":"c. 399–390 a. C.","u":"","te":["autoconocimiento","sentido-de-vida"]},{"i":"platon-002","a":"platon","t":"Él no sabe nada y cree que sabe; yo ni sé ni creo saber.","o":"he knows nothing, and thinks that he knows; I neither know nor think that I know.","l":"en","ob":"Apología de Sócrates","an":"c. 399–390 a. C.","u":"","te":["conocimiento","autoconocimiento"]},{"i":"platon-003","a":"platon","t":"Llegó la hora de partir y seguimos nuestros caminos: yo, a morir; ustedes, a vivir. Cuál es mejor, solo lo sabe el dios.","o":"The hour of departure has arrived, and we go our ways-I to die, and you to live. Which is better God only knows.","l":"en","ob":"Apología de Sócrates","an":"c. 399–390 a. C.","u":"","te":["muerte","incertidumbre"]},{"i":"platon-004","a":"platon","t":"Temer a la muerte es aparentar una sabiduría que no se tiene: es creer saber lo que no se sabe.","o":"For the fear of death is indeed the pretence of wisdom, and not real wisdom, being a pretence of knowing the unknown","l":"en","ob":"Apología de Sócrates","an":"c. 399–390 a. C.","u":"","te":["muerte","miedo","conocimiento"]},{"i":"platon-005","a":"platon","t":"Sepan con certeza que a un hombre bueno no puede sucederle ningún mal, ni en vida ni después de muerto.","o":"know of a certainty, that no evil can happen to a good man, either in life or after death.","l":"en","ob":"Apología de Sócrates","an":"c. 399–390 a. C.","u":"","te":["muerte","esperanza"]},{"i":"platon-006","a":"platon","t":"[Soy] una especie de tábano que el dios le dio a la ciudad.","o":"am a sort of gadfly, given to the state by God","l":"en","ob":"Apología de Sócrates","an":"c. 399–390 a. C.","u":"","te":["sociedad","verdad"]},{"i":"platon-007","a":"platon","t":"Sé que no tengo sabiduría, ni pequeña ni grande.","o":"for I know that I have no wisdom, small or great.","l":"en","ob":"Apología de Sócrates","an":"c. 399–390 a. C.","u":"","te":["conocimiento","autenticidad"]},{"i":"platon-008","a":"platon","t":"Prefiero morir habiendo hablado a mi manera que vivir hablando a la de ustedes.","o":"I would rather die having spoken after my manner, than speak in your manner and live.","l":"en","ob":"Apología de Sócrates","an":"c. 399–390 a. C.","u":"","te":["autenticidad","libertad"]},{"i":"platon-009","a":"platon","t":"Lo difícil, amigos, no es escapar de la muerte, sino de la injusticia, que corre más rápido que la muerte.","o":"the difficulty, my friends, is not to avoid death, but to avoid unrighteousness; for that runs faster than death.","l":"en","ob":"Apología de Sócrates","an":"c. 399–390 a. C.","u":"","te":["responsabilidad","muerte"]},{"i":"platon-010","a":"platon","t":"Un hombre que valga algo no debe calcular las probabilidades de vivir o morir.","o":"a man who is good for anything ought not to calculate the chance of living or dying","l":"en","ob":"Apología de Sócrates","an":"c. 399–390 a. C.","u":"","te":["responsabilidad","miedo"]},{"i":"platon-011","a":"platon","t":"Quienes me escuchan siempre imaginan que yo tengo la sabiduría que encuentro que les falta a otros.","o":"my hearers always imagine that I myself possess the wisdom which I find wanting in others","l":"en","ob":"Apología de Sócrates","an":"c. 399–390 a. C.","u":"","te":["conocimiento","identidad"]},{"i":"platon-026","a":"platon","t":"La naturaleza humana era en su origen una y éramos un todo: el deseo y la búsqueda de ese todo se llama amor.","o":"human nature was originally one and we were a whole, and the desire and pursuit of the whole is called love.","l":"en","ob":"El banquete","an":"c. 385–370 a. C.","u":"","te":["amor","deseo"]},{"i":"platon-027","a":"platon","t":"Solo el amor hace que hombres, y también mujeres, se atrevan a morir por quien aman.","o":"Love will make men dare to die for their beloved--love alone; and women as well as men.","l":"en","ob":"El banquete","an":"c. 385–370 a. C.","u":"","te":["amor"]},{"i":"platon-028","a":"platon","t":"El amor es amor de poseer el bien para siempre.","o":"love is of the everlasting possession of the good","l":"en","ob":"El banquete","an":"c. 385–370 a. C.","u":"","te":["amor","deseo"]},{"i":"platon-029","a":"platon","t":"Esa es, más que ninguna otra, la vida que el ser humano debe vivir: la contemplación de la belleza en sí.","o":"is that life above all others which man should live, in the contemplation of beauty absolute","l":"en","ob":"El banquete","an":"c. 385–370 a. C.","u":"","te":["trascendencia","sentido-de-vida"]},{"i":"platon-030","a":"platon","t":"El Amor es el más antiguo, el más noble y el más poderoso de los dioses.","o":"Love is the eldest and noblest and mightiest of the gods","l":"en","ob":"El banquete","an":"c. 385–370 a. C.","u":"","te":["amor"]},{"i":"platon-031","a":"platon","t":"Empezar por las bellezas de la tierra y subir hacia aquella otra belleza, usando estas solo como peldaños.","o":"to begin from the beauties of earth and mount upwards for the sake of that other beauty, using these as steps only","l":"en","ob":"El banquete","an":"c. 385–370 a. C.","u":"","te":["trascendencia","amor"]},{"i":"platon-032","a":"platon","t":"La sabiduría es lo más bello, y el Amor es amor de lo bello: por eso el Amor es también filósofo, amante de la sabiduría.","o":"For wisdom is a most beautiful thing, and Love is of the beautiful; and therefore Love is also a philosopher or lover of wisdom","l":"en","ob":"El banquete","an":"c. 385–370 a. C.","u":"","te":["amor","conocimiento"]},{"i":"platon-033","a":"platon","t":"[El Amor] es un gran espíritu (daimon) y, como todos los espíritus, está a medio camino entre lo divino y lo mortal.","o":"He is a great spirit (daimon), and like all spirits he is intermediate between the divine and the mortal.","l":"en","ob":"El banquete","an":"c. 385–370 a. C.","u":"","te":["amor","trascendencia"]},{"i":"platon-049","a":"platon","t":"No advierten que [el verdadero filósofo] no hace otra cosa que ocuparse de morir y de estar muerto.","o":"they do not perceive that he is always pursuing death and dying","l":"en","ob":"Fedón","an":"c. 380 a. C.","u":"","te":["muerte"]},{"i":"platon-050","a":"platon","t":"Los verdaderos filósofos, Simmias, se ejercitan siempre en morir; por eso a ellos, más que a nadie, la muerte no les resulta terrible.","o":"And the true philosophers, Simmias, are always occupied in the practice of dying, wherefore also to them least of all men is death terrible.","l":"en","ob":"Fedón","an":"c. 380 a. C.","u":"","te":["muerte","miedo"]},{"i":"platon-051","a":"platon","t":"El cuerpo nos da infinitas molestias por la sola necesidad de alimentarse.","o":"For the body is a source of endless trouble to us by reason of the mere requirement of food","l":"en","ob":"Fedón","an":"c. 380 a. C.","u":"","te":["cuerpo"]},{"i":"platon-052","a":"platon","t":"Critón, le debo un gallo a Asclepio: ¿te acordarás de pagar la deuda?","o":"Crito, I owe a cock to Asclepius; will you remember to pay the debt?","l":"en","ob":"Fedón","an":"c. 380 a. C.","u":"","te":["muerte","gratitud"]},{"i":"platon-053","a":"platon","t":"[De todos los hombres de su tiempo que conocí,] fue el más sabio, el más justo y el mejor.","o":"he was the wisest and justest and best.","l":"en","ob":"Fedón","an":"c. 380 a. C.","u":"","te":["duelo","amistad"]},{"i":"platon-039","a":"platon","t":"Querido Pan, y ustedes, los demás dioses de este lugar: concédanme ser bello por dentro, y que lo de afuera y lo de adentro estén en armonía.","o":"Beloved Pan, and all ye other gods who haunt this place, give me beauty in the inward soul; and may the outward and inward man be at one.","l":"en","ob":"Fedro","an":"c. 370 a. C.","u":"","te":["autenticidad","trascendencia"]},{"i":"platon-040","a":"platon","t":"Que la imagen sea compuesta: un par de caballos alados y un auriga.","o":"let the figure be composite--a pair of winged horses and a charioteer.","l":"en","ob":"Fedro","an":"c. 370 a. C.","u":"","te":["identidad","regulacion-emocional"]},{"i":"platon-041","a":"platon","t":"Este invento tuyo [la escritura] producirá olvido en las almas de quienes aprendan, porque dejarán de ejercitar la memoria.","o":"this discovery of yours will create forgetfulness in the learners' souls, because they will not use their memories","l":"en","ob":"Fedro","an":"c. 370 a. C.","u":"","te":["memoria","tecnologia"]},{"i":"platon-042","a":"platon","t":"Parecerán saberlo todo y en general no sabrán nada.","o":"they will appear to be omniscient and will generally know nothing","l":"en","ob":"Fedro","an":"c. 370 a. C.","u":"","te":["conocimiento","tecnologia"]},{"i":"platon-043","a":"platon","t":"El alma, en todo su ser, es inmortal.","o":"The soul through all her being is immortal","l":"en","ob":"Fedro","an":"c. 370 a. C.","u":"","te":["trascendencia"]},{"i":"platon-044","a":"platon","t":"Hay también una locura que es un don divino y fuente de los mayores bienes concedidos a los seres humanos.","o":"there is also a madness which is a divine gift, and the source of the chiefest blessings granted to men","l":"en","ob":"Fedro","an":"c. 370 a. C.","u":"","te":["creatividad","amor"]},{"i":"platon-034","a":"platon","t":"Lo que más hay que valorar no es vivir, sino vivir bien.","o":"not life, but a good life, is to be chiefly valued","l":"en","ob":"Critón","an":"c. 399–390 a. C.","u":"","te":["sentido-de-vida"]},{"i":"platon-035","a":"platon","t":"No debemos responder con represalias ni devolver mal por mal a nadie, sea cual sea el mal que nos haya hecho.","o":"we ought not to retaliate or render evil for evil to any one, whatever evil we may have suffered from him.","l":"en","ob":"Critón","an":"c. 399–390 a. C.","u":"","te":["ira","compasion"]},{"i":"platon-036","a":"platon","t":"No debemos atender a lo que dice de nosotros la mayoría, sino a lo que dirá quien entiende de lo justo y lo injusto, y a lo que dirá la verdad.","o":"we must not regard what the many say of us: but what he, the one man who has understanding of just and unjust, will say, and what the truth will say.","l":"en","ob":"Critón","an":"c. 399–390 a. C.","u":"","te":["autenticidad","verdad"]},{"i":"platon-037","a":"platon","t":"Seremos mejores, más valientes y menos impotentes si creemos que hay que investigar, que si nos entregamos a la ociosa fantasía de que no se puede saber ni vale la pena buscar lo que no sabemos.","o":"we shall be better and braver and less helpless if we think that we ought to enquire, than we should have been if we indulged in the idle fancy that there was no knowing and no use in seeking to know what we do not know","l":"en","ob":"Menón","an":"c. 385 a. C.","u":"","te":["conocimiento","educacion"]},{"i":"platon-038","a":"platon","t":"Toda búsqueda y todo aprendizaje no son más que recuerdo.","o":"for all enquiry and all learning is but recollection","l":"en","ob":"Menón","an":"c. 385 a. C.","u":"","te":["conocimiento","memoria"]},{"i":"platon-045","a":"platon","t":"El asombro es el sentimiento propio del filósofo, y la filosofía empieza con el asombro.","o":"for wonder is the feeling of a philosopher, and philosophy begins in wonder","l":"en","ob":"Teeteto","an":"c. 369 a. C.","u":"","te":["conocimiento","creatividad"]},{"i":"platon-046","a":"platon","t":"El triunfo de mi arte está en examinar a fondo si el pensamiento que da a luz la mente del joven es un ídolo falso o un parto noble y verdadero.","o":"the triumph of my art is in thoroughly examining whether the thought which the mind of the young man brings forth is a false idol or a noble and true birth.","l":"en","ob":"Teeteto","an":"c. 369 a. C.","u":"","te":["educacion","terapia","verdad"]},{"i":"platon-047","a":"platon","t":"Y como las parteras, yo soy estéril [de sabiduría].","o":"And like the midwives, I am barren","l":"en","ob":"Teeteto","an":"c. 369 a. C.","u":"","te":["conocimiento","terapia"]},{"i":"platon-048","a":"platon","t":"Debemos huir de la tierra al cielo lo antes posible; y huir es asemejarse a Dios en la medida de lo posible.","o":"we ought to fly away from earth to heaven as quickly as we can; and to fly away is to become like God, as far as this is possible","l":"en","ob":"Teeteto","an":"c. 369 a. C.","u":"","te":["trascendencia"]},{"i":"aristoteles-001","a":"aristoteles","t":"Así como una golondrina o un día de sol no hacen primavera, tampoco un día o un breve tiempo hacen a alguien dichoso y feliz.","o":"for as it is not one swallow or one fine day that makes a spring, so it is not one day or a short time that makes a man blessed and happy.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"","te":["felicidad","tiempo","habitos"]},{"i":"aristoteles-002","a":"aristoteles","t":"Haciendo actos justos nos volvemos justos; haciendo actos de dominio de nosotros mismos nos volvemos dueños de nosotros; y haciendo actos valientes [nos volvemos valientes].","o":"by doing just actions we come to be just; by doing the actions of self-mastery we come to be perfected in self-mastery; and by doing brave actions","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 2","te":["habitos","transformacion-personal"]},{"i":"aristoteles-003","a":"aristoteles","t":"Las virtudes no nacen en nosotros por naturaleza ni contra la naturaleza: la naturaleza nos da la capacidad de recibirlas, y la costumbre las perfecciona.","o":"The Virtues then come to be in us neither by nature, nor in despite of nature, but we are furnished by nature with a capacity for receiving themu and are perfected in them through custom.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 2","te":["habitos","desarrollo-humano"]},{"i":"aristoteles-004","a":"aristoteles","t":"Tenemos razón al decir que estas virtudes se forman en una persona por hacer las acciones correspondientes.","o":"We are right then in saying, that these virtues are formed in a man by his doing the actions","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 2","te":["habitos"]},{"i":"aristoteles-005","a":"aristoteles","t":"A quien alega no saber que los hábitos se forman a partir de actos sucesivos, le respondemos que esa ignorancia es señal de una torpeza excesiva.","o":"As for the plea, that a man did not know that habits are produced from separate acts of working, we reply, such ignorance is a mark of excessive stupidity.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 3","te":["habitos","responsabilidad"]},{"i":"aristoteles-006","a":"aristoteles","t":"De ahí la necesidad de haber sido bien educado en hábitos para estudiar con algún provecho los principios de lo noble, de lo justo y de la ética en general.","o":"Hence the necessity that he should have been well trained in habits, who is to study, with any tolerable chance of profit, the principles of nobleness and justice and moral philosophy generally.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"","te":["educacion","habitos"]},{"i":"aristoteles-007","a":"aristoteles","t":"La felicidad es, pues, evidentemente algo final y suficiente en sí mismo: el fin de todo lo que se hace y se puede hacer.","o":"So then Happiness is manifestly something final and self-sufficient, being the end of all things which are and may be done.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"","te":["felicidad","sentido-de-vida"]},{"i":"aristoteles-008","a":"aristoteles","t":"Aun en la desgracia brilla la nobleza cuando alguien soporta con serenidad muchos y grandes infortunios, no por insensibilidad al dolor, sino porque es noble y magnánimo.","o":"But still, even in these, nobleness shines through when a man bears contentedly many and great mischances not from insensibility to pain but because he is noble and high-spirited.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"","te":["resiliencia","sufrimiento"]},{"i":"aristoteles-009","a":"aristoteles","t":"[El placer] crece con todos nosotros desde la infancia; por eso es difícil quitarnos ese sentimiento, tan arraigado en nuestra vida.","o":"Again, it grows up with us all from infancy, and so it is a hard matter to remove from ourselves this feeling, engrained as it is into our very life.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 2","te":["deseo","infancia"]},{"i":"aristoteles-010","a":"aristoteles","t":"La ira y el miedo los sentimos sin elegirlos, mientras que las virtudes son actos de elección.","o":"Again, both anger and fear we feel without moral choice, whereas the virtues are acts of moral choice","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 2","te":["emociones","ira","miedo","libertad"]},{"i":"aristoteles-011","a":"aristoteles","t":"La virtud ha de ser una disposición por la cual el ser humano llega a ser bueno y realiza bien su propia tarea.","o":"Virtue, must be a state whereby Man comes to be good and whereby he will perform well his proper work.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 2","te":["identidad","responsabilidad"]},{"i":"aristoteles-012","a":"aristoteles","t":"La virtud es, en cierto sentido, un término medio, ya que tiende a apuntar al justo medio.","o":"Virtue then is in a sense a mean state, since it certainly has an aptitude for aiming at the mean.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 2","te":["regulacion-emocional"]},{"i":"aristoteles-013","a":"aristoteles","t":"Por eso es difícil ser bueno: en cada caso es difícil encontrar el término medio, así como encontrar el centro de un círculo no es algo que cualquiera pueda hacer.","o":"And so it is hard to be good: for surely hard it is in each instance to find the mean, just as to find the mean point or centre of a circle is not what any man can do","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 2","te":["regulacion-emocional","responsabilidad"]},{"i":"aristoteles-014","a":"aristoteles","t":"Tenemos una inclinación natural hacia los placeres; por eso nos inclinamos mucho más a abandonar todo control de nosotros mismos que a la disciplina.","o":"Thus we have a natural bias towards pleasures, for which reason we are much more inclined to the rejection of all self-control, than to self-discipline.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 2","te":["deseo","habitos"]},{"i":"aristoteles-015","a":"aristoteles","t":"En todos los casos hay que cuidarse sobre todo de lo agradable y del placer mismo, porque no somos jueces imparciales de él.","o":"But in all cases we must guard most carefully against what is pleasant, and pleasure itself, because we are not impartial judges of it.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 2","te":["deseo","autoconocimiento"]},{"i":"aristoteles-016","a":"aristoteles","t":"Es realmente absurdo atribuir las propias acciones a las cosas exteriores en lugar de a la propia facilidad para dejarse atrapar por ellas.","o":"It is truly absurd for a man to attribute his actions to external things instead of to his own capacity for being easily caught by them","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 3","te":["responsabilidad","autoconocimiento"]},{"i":"aristoteles-017","a":"aristoteles","t":"Es posible temer estas cosas demasiado o demasiado poco, o temer lo que en realidad no es temible como si lo fuera.","o":"Now it is possible to fear these things too much, or too little, or again to fear what is not really fearful as if it were such.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 3","te":["miedo","angustia"]},{"i":"aristoteles-018","a":"aristoteles","t":"Los temerarios son precipitados: ansiosos antes del peligro, se derrumban cuando están en él; los valientes, en cambio, son rápidos y decididos en la acción, pero antes están tranquilos y serenos.","o":"The rash again are precipitate, and, being eager before danger, when actually in it fall away, while the Brave are quick and sharp in action, but before are quiet and composed.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 3","te":["miedo","resiliencia"]},{"i":"aristoteles-019","a":"aristoteles","t":"De ahí que el coraje implique dolor y sea justamente elogiado: es más difícil soportar lo doloroso que abstenerse de lo agradable.","o":"It follows that Courage involves pain and is justly praised, since it is a harder matter to withstand things that are painful than to abstain from such as are pleasant.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 3","te":["resiliencia","sufrimiento"]},{"i":"aristoteles-020","a":"aristoteles","t":"Si se encontrara a alguien que no disfrutara de nada y para quien todo diera igual, estaría lejos de ser humano.","o":"In fact, could a man be found who takes no pleasure in anything and to whom all things are alike, he would be far from being human at all","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 3","te":["alegria","salud-mental"]},{"i":"aristoteles-021","a":"aristoteles","t":"Además, el dolor perturba y estropea la disposición natural de quien lo padece.","o":"And again, pain deranges and spoils the natural disposition of its victim","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 3","te":["sufrimiento"]},{"i":"aristoteles-022","a":"aristoteles","t":"Es propio de él [el magnánimo] ser franco en lo que le gusta y en lo que le disgusta, porque el ocultamiento es consecuencia del miedo.","o":"It is a property of him also to be open, both in his dislikes and his likings, because concealment is a consequent of fear.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 4","te":["autenticidad","miedo","comunicacion"]},{"i":"aristoteles-023","a":"aristoteles","t":"Se elogia a quien se enoja por lo que corresponde y con quien corresponde, y además de la manera, en el momento y durante el tiempo adecuados.","o":"Now he who is angry at what and with whom he ought, and further, in right manner and time, and for proper length of time, is praised","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 4","te":["ira","regulacion-emocional"]},{"i":"aristoteles-024","a":"aristoteles","t":"Ser apacible es ser imperturbable, no dejarse arrastrar por la pasión, sino enojarse de la manera, por las cosas y durante el tiempo que la razón indique.","o":"For the notion represented by the term Meek man is the being imperturbable, and not being led away by passion, but being angry in that manner, and at those things, and for that length of time, which Reason may direct.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 4","te":["ira","regulacion-emocional"]},{"i":"aristoteles-025","a":"aristoteles","t":"Y digerir el enojo dentro de uno lleva tiempo.","o":"and digesting anger within one's self takes time","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 4","te":["ira","tiempo"]},{"i":"aristoteles-026","a":"aristoteles","t":"No es fácil definir cómo, con quién, por qué cosas y durante cuánto tiempo hay que enojarse, ni hasta qué punto se tiene razón o no.","o":"I mean, it is no easy matter to define how, and with what persons, and at what kind of things, and how long one ought to be angry, and up to what point a person is right or is wrong.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 4","te":["ira","regulacion-emocional"]},{"i":"aristoteles-027","a":"aristoteles","t":"Sin embargo, en general se considera que en la vida son indispensables cierto descanso y diversión.","o":"Yet some pause and amusement in life are generally judged to be indispensable.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 4","te":["alegria","humor","trabajo"]},{"i":"aristoteles-028","a":"aristoteles","t":"[La vergüenza] se define como “una especie de miedo al deshonor”, y sus efectos se parecen a los del miedo al peligro: quienes sienten vergüenza se ponen rojos, y quienes temen la muerte, pálidos.","o":"It is defined, we know, to be \"a kind of fear of disgrace,\" and its effects are similar to those of the fear of danger, for they who feel Shame grow red and they who fear death turn pale.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 4","te":["emociones","cuerpo","culpa"]},{"i":"aristoteles-029","a":"aristoteles","t":"En la pobreza y en todas las demás adversidades, se piensa que los amigos son el único refugio.","o":"in poverty moreover and all other adversities men think friends to be their only refuge.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 8","te":["amistad","resiliencia"]},{"i":"aristoteles-030","a":"aristoteles","t":"Además, la amistad parece ser el lazo de las comunidades, y los legisladores parecen preocuparse más por ella que por la justicia misma.","o":"Furthermore, Friendship seems to be the bond of Social Communities, and legislators seem to be more anxious to secure it than Justice even.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 8","te":["amistad","sociedad"]},{"i":"aristoteles-031","a":"aristoteles","t":"Al amigo, se dice, hay que desearle todo bien por él mismo.","o":"But to the friend they say one should wish all good for his sake.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 8","te":["amistad","amor"]},{"i":"aristoteles-032","a":"aristoteles","t":"Estas amistades son accidentales: no se quiere al otro por ser quien es, sino por la utilidad o el placer que brinda.","o":"These Friendships then are a matter of result: since the object is not beloved in that he is the man he is but in that he furnishes advantage or pleasure as the case may be.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 8","te":["amistad","vinculos"]},{"i":"aristoteles-033","a":"aristoteles","t":"Por eso [los jóvenes] hacen y deshacen amistades con rapidez: la amistad cambia con lo que les resulta agradable, y eso cambia pronto.","o":"This is the reason why they form and dissolve Friendships rapidly: since the Friendship changes with the pleasurable object and such pleasure changes quickly.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 8","te":["amistad","desarrollo-humano"]},{"i":"aristoteles-034","a":"aristoteles","t":"Es probable que estas amistades sean raras, porque las personas así son raras.","o":"Rare it is probable Friendships of this kind will be, because men of this kind are rare.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 8","te":["amistad"]},{"i":"aristoteles-035","a":"aristoteles","t":"Los sentimientos amistosos que mostramos hacia nuestros amigos parecen haber nacido de los que tenemos hacia nosotros mismos.","o":"Now the friendly feelings which are exhibited towards our friends, and by which Friendships are characterised, seem to have sprung out of those which we entertain toward ourselves.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 9","te":["amistad","autoestima"]},{"i":"aristoteles-036","a":"aristoteles","t":"[Hay que esforzarse por ser bueno,] porque así uno puede ser amigo de sí mismo y llegar a ser amigo de otro.","o":"because thus may he be friends with himself and may come to be a friend to another.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 9","te":["amistad","autoestima"]},{"i":"aristoteles-037","a":"aristoteles","t":"Y haber hecho posible que un amigo haga algo puede ser más noble que haberlo hecho uno mismo.","o":"and to have caused a friend's doing a thing may be more noble than having done it one's self.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 9","te":["amistad","compasion"]},{"i":"aristoteles-038","a":"aristoteles","t":"El amigo no es sino el nombre de otro yo.","o":"friend being but a name for a second Self","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 9","te":["amistad","identidad"]},{"i":"aristoteles-039","a":"aristoteles","t":"Quien vaya a ser feliz, según lo entendemos, necesitará buenos amigos.","o":"The man therefore who is to come up to our notion \"Happy\" will need good Friends.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 9","te":["amistad","felicidad"]},{"i":"aristoteles-040","a":"aristoteles","t":"La sola presencia de los amigos es agradable incluso en la adversidad: cuando las personas sufren, las consuela la compañía de sus amigos.","o":"For the very presence of friends is pleasant even in adversity: since men when grieved are comforted by the sympathy of their friends.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 9","te":["amistad","duelo","resiliencia"]},{"i":"aristoteles-041","a":"aristoteles","t":"Quizás haya que cuidarse de no parecer huraño al rechazar el consuelo o la ayuda de los amigos.","o":"One should perhaps be cautious not to present the appearance of sullenness in declining the sympathy or help of friends","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 9","te":["amistad","vinculos"]},{"i":"aristoteles-042","a":"aristoteles","t":"Y así se educa a los jóvenes, guiándolos con los timones del placer y del dolor.","o":"and so men train the young, guiding them on their course by the rudders of Pleasure and Pain.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 10","te":["educacion","emociones"]},{"i":"aristoteles-043","a":"aristoteles","t":"El placer perfecciona la actividad, y así también la vida, a la que todos aspiran.","o":"And Pleasure perfects the acts of Working, and so Life after which men grasp.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 10","te":["alegria","sentido-de-vida"]},{"i":"aristoteles-044","a":"aristoteles","t":"El placer completa la actividad no como algo que le es propio, sino como un acabado que se le suma, como la lozanía a quienes están en la flor de la edad.","o":"Furthermore, Pleasure perfects the act of Working not in the way of an inherent state but as a supervening finish, such as is bloom in people at their prime.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 10","te":["alegria","trabajo"]},{"i":"aristoteles-045","a":"aristoteles","t":"Si la felicidad es una actividad conforme a la excelencia, esa excelencia ha de ser la más alta: la de lo mejor que hay en nosotros.","o":"Now if Happiness is a Working in the way of Excellence of course that Excellence must be the highest, that is to say, the Excellence of the best Principle.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 10","te":["felicidad"]},{"i":"aristoteles-046","a":"aristoteles","t":"Las virtudes tienen que ver con acciones y sentimientos, y a todo sentimiento y a toda acción les siguen el placer o el dolor.","o":"Again: since Virtues have to do with actions and feelings, and on every feeling and every action pleasure and pain follow","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 2","te":["emociones"]},{"i":"aristoteles-047","a":"aristoteles","t":"El ser humano es por naturaleza un animal político.","o":"that man is naturally a political animal","l":"en","ob":"Política","an":"s. IV a. C.","u":"cap. 2","te":["sociedad","vinculos"]},{"i":"aristoteles-048","a":"aristoteles","t":"Quien es incapaz de vivir en sociedad, o tan suficiente que no la necesita, no forma parte de la ciudad: es una bestia o un dios.","o":"he that is incapable of society, or so complete in himself as not to want it, makes no part of a city, as a beast or a god.","l":"en","ob":"Política","an":"s. IV a. C.","u":"cap. 2","te":["sociedad","soledad"]},{"i":"aristoteles-049","a":"aristoteles","t":"Pensamos que la amistad es el mayor bien que puede tener una ciudad, porque nada previene tanto las discordias.","o":"we think that friendship is the greatest good which can happen to any city, as nothing so much prevents seditions","l":"en","ob":"Política","an":"s. IV a. C.","u":"Libro 2, cap. 4","te":["amistad","sociedad"]},{"i":"aristoteles-050","a":"aristoteles","t":"[La tragedia,] mediante la compasión y el miedo, lleva a cabo la purificación (catarsis) de esas emociones.","o":"through pity and fear effecting the proper purgation of these emotions","l":"en","ob":"Poética","an":"s. IV a. C.","u":"","te":["emociones","cultura","terapia"]},{"i":"aristoteles-051","a":"aristoteles","t":"El instinto de imitación está implantado en el ser humano desde la infancia.","o":"the instinct of imitation is implanted in man from childhood","l":"en","ob":"Poética","an":"s. IV a. C.","u":"","te":["infancia","educacion"]},{"i":"aristoteles-052","a":"aristoteles","t":"La poesía es, por eso, más filosófica y más elevada que la historia.","o":"Poetry, therefore, is a more philosophical and a higher thing than history","l":"en","ob":"Poética","an":"s. IV a. C.","u":"","te":["cultura","creatividad"]},{"i":"epicteto-029","a":"epicteto","t":"Son las dificultades las que muestran quiénes son las personas.","o":"It is circumstances (difficulties) which show what men are.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«How we should struggle with circumstances»","te":["resiliencia","identidad"]},{"i":"epicteto-030","a":"epicteto","t":"Nada grande, decía Epicteto, se produce de golpe: ni siquiera la uva o el higo.","o":"Nothing great, said Epictetus, is produced suddenly, since not even the grape or the fig is.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«What philosophy promises»","te":["cambio","habitos"]},{"i":"epicteto-031","a":"epicteto","t":"La materia del arte de vivir es la vida de cada uno.","o":"so the matter of the art of living is each man's life.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«What philosophy promises»","te":["sentido-de-vida","responsabilidad"]},{"i":"epicteto-032","a":"epicteto","t":"¿Dónde está el bien? En la voluntad. ¿Dónde está el mal? En la voluntad.","o":"Where is the good? In the will. Where is the evil? In the will.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«That we do not strive to use our opinions about good and evil»","te":["voluntad","responsabilidad"]},{"i":"epicteto-033","a":"epicteto","t":"Es imposible empezar a aprender lo que uno cree que ya sabe.","o":"For it is impossible for a man to begin to learn that which he thinks that he knows.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«How we must adapt preconceptions to particular cases»","te":["educacion","conocimiento"]},{"i":"epicteto-034","a":"epicteto","t":"Todo hábito y toda capacidad se mantienen y crecen con las acciones que les corresponden.","o":"Every habit and faculty is maintained and increased by the corresponding actions","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«How we should struggle against appearances»","te":["habitos"]},{"i":"epicteto-035","a":"epicteto","t":"Si querés ser un buen lector, leé; si querés ser escritor, escribí.","o":"If you would be a good reader, read; if a writer, write.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«How we should struggle against appearances»","te":["habitos","educacion"]},{"i":"epicteto-036","a":"epicteto","t":"En general, si querés que algo se vuelva hábito, hacelo; si no querés, no lo hagas.","o":"Generally then if you would make anything a habit, do it; if you would not make it a habit, do not do it","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«How we should struggle against appearances»","te":["habitos","cambio"]},{"i":"epicteto-037","a":"epicteto","t":"El comienzo de la filosofía, para quien entra en ella como corresponde, es la conciencia de la propia debilidad e incapacidad en las cosas necesarias.","o":"The beginning of philosophy, to him at least who enters on it in the right way and by the door is a consciousness of his own weakness and inability about necessary things","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«What the beginning of philosophy is»","te":["autoconocimiento","conocimiento"]},{"i":"epicteto-038","a":"epicteto","t":"Es libre quien vive como quiere vivir, sin estar sometido a la coacción, al impedimento ni a la fuerza.","o":"He is free who lives as he wishes to live; who is neither subject to compulsion nor to hindrance, nor to force","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«About freedom»","te":["libertad"]},{"i":"epicteto-039","a":"epicteto","t":"Tengo que morir. ¿Tengo entonces que morir lamentándome? Me van a encadenar. ¿Tengo también que lamentarme?","o":"I must die. Must I then die lamenting? I must be put in chains. Must I then also lament?","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«Of the things which are in our power and not in our power»","te":["muerte","aceptacion","libertad"]},{"i":"epicteto-040","a":"epicteto","t":"Quien entiende qué es el bien sabe también amar.","o":"Whoever then understands what is good can also know how to love","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«On friendship»","te":["amor","amistad"]},{"i":"epicteto-041","a":"epicteto","t":"La soledad es la condición de una persona desamparada. Porque alguien esté solo no por eso está en soledad.","o":"Solitude is a certain condition of a helpless man. For because a man is alone, he is not for that reason also solitary","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«What solitude is, and what kind of person a solitary man is»","te":["soledad","vinculos"]},{"i":"epicteto-042","a":"epicteto","t":"Si sos alguien, caminá solo, hablá con vos mismo y no te escondas en el coro.","o":"Man, if you are anything, both walk alone and talk to yourself, and do not hide yourself in the chorus.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«Certain miscellaneous matters»","te":["soledad","autenticidad","identidad"]},{"i":"epicteto-043","a":"epicteto","t":"Examinate un poco por fin, mirá a tu alrededor, sacudite, para saber quién sos.","o":"Examine a little at last, look around, stir yourself up, that you may know who you are.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«Certain miscellaneous matters»","te":["autoconocimiento","identidad"]},{"i":"epicteto-044","a":"epicteto","t":"Quien trata con frecuencia con otros, para conversar, beber juntos o por la vida social, termina pareciéndose a ellos o haciéndolos parecidos a él.","o":"If a man has frequent intercourse with others either for talk, or drinking together, or generally for social purposes, he must either become like them, or change them to his own fashion.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«That we ought with caution to enter into familiar intercourse with men»","te":["vinculos","amistad"]},{"i":"epicteto-045","a":"epicteto","t":"Las cosas en sí son indiferentes; el uso que hacemos de ellas, no.","o":"Things themselves (materials) are indifferent; but the use of them is not indifferent.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«How magnanimity is consistent with care»","te":["responsabilidad"]},{"i":"epicteto-046","a":"epicteto","t":"Lo exterior no depende de mí; la voluntad, sí.","o":"Externals are not in my power: will is in my power.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«How magnanimity is consistent with care»","te":["libertad","voluntad","aceptacion"]},{"i":"epicteto-047","a":"epicteto","t":"Para cada persona, la causa de sus actos es su opinión.","o":"For to every man the cause of his acting is opinion.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«To a certain rhetorician who was going up to rome on a suit»","te":["conciencia","responsabilidad"]},{"i":"epicteto-048","a":"epicteto","t":"[Para alabar la Providencia hacen falta dos cosas:] la capacidad de ver lo que pertenece y sucede a todas las personas y cosas, y una disposición agradecida.","o":"the faculty of seeing what belongs and happens to all persons and things, and a grateful disposition","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«Of providence»","te":["gratitud","atencion"]},{"i":"epicteto-049","a":"epicteto","t":"Considerá quién sos.","o":"Consider who you are.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«How we may discover the duties of life from names»","te":["identidad","autoconocimiento"]},{"i":"epicteto-050","a":"epicteto","t":"Además, sos ciudadano del mundo y parte de él.","o":"Further, you are a citizen of the world, and a part of it","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«How we may discover the duties of life from names»","te":["sociedad","conexion"]},{"i":"epicteto-051","a":"epicteto","t":"No debemos retroceder cuando estamos en el combate más grande: hasta hay que recibir golpes.","o":"For we must not shrink when we are engaged in the greatest combat, but we must even take blows.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«From their purpose»","te":["resiliencia"]},{"i":"epicteto-052","a":"epicteto","t":"Creo que nadie tuvo una dificultad más provechosa que la tuya, si querés aprovecharla como un atleta a un rival joven.","o":"In my opinion no man has had a more profitable difficulty than you have had, if you choose to make use of it as an athlete would deal with a young antagonist.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«How we should struggle with circumstances»","te":["resiliencia","sufrimiento"]},{"i":"epicteto-053","a":"epicteto","t":"La filosofía no promete conseguirle a nadie nada exterior.","o":"Philosophy does not propose to secure for a man any external thing.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«What philosophy promises»","te":["sentido-de-vida","libertad"]},{"i":"epicteto-001","a":"epicteto","t":"De las cosas, unas dependen de nosotros y otras no.","o":"Of things some are in our power, and others are not.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 1","te":["libertad","aceptacion","responsabilidad"]},{"i":"epicteto-002","a":"epicteto","t":"Si amás una vasija de barro, decite que amás una vasija de barro: cuando se rompa, no te perturbará.","o":"If you love an earthen vessel, say it is an earthen vessel which you love; for when it has been broken you will not be disturbed.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 3","te":["perdida","aceptacion"]},{"i":"epicteto-003","a":"epicteto","t":"A los seres humanos no los perturban las cosas que suceden, sino las opiniones sobre las cosas.","o":"Men are disturbed not by the things which happen, but by the opinions about the things","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 5","te":["sufrimiento","conciencia","regulacion-emocional"]},{"i":"epicteto-004","a":"epicteto","t":"Lo terrible es la opinión de que la muerte es terrible.","o":"for the opinion about death that it is terrible, is the terrible thing.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 5","te":["muerte","miedo"]},{"i":"epicteto-005","a":"epicteto","t":"No pretendas que las cosas sucedan como querés: querelas como suceden, y tu vida fluirá en calma.","o":"Seek not that the things which happen should happen as you wish; but wish the things which happen to be as they are, and you will have a tranquil flow of life.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 8","te":["aceptacion","felicidad"]},{"i":"epicteto-006","a":"epicteto","t":"La enfermedad es un impedimento para el cuerpo, pero no para la voluntad, a menos que ella misma lo elija.","o":"Disease is an impediment to the body, but not to the will, unless the will itself chooses.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 9","te":["cuerpo","libertad","resiliencia"]},{"i":"epicteto-007","a":"epicteto","t":"Ante cada cosa que te suceda, acordate de volver a vos y preguntarte qué capacidad tenés para aprovecharla.","o":"On the occasion of every accident (event) that befalls you, remember to turn to yourself and inquire what power you have for turning it to use.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 10","te":["resiliencia","responsabilidad"]},{"i":"epicteto-008","a":"epicteto","t":"Nunca digas de algo “lo perdí”, sino “lo devolví”.","o":"Never say about anything, I have lost it, but say I have restored it.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 11","te":["perdida","duelo","aceptacion"]},{"i":"epicteto-009","a":"epicteto","t":"Si querés progresar, aceptá que te consideren tonto e ignorante en las cosas exteriores.","o":"If you would improve, submit to be considered without sense and foolish with respect to externals.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 13","te":["autenticidad","transformacion-personal"]},{"i":"epicteto-010","a":"epicteto","t":"Recordá que en la vida tenés que comportarte como en un banquete.","o":"Remember that in life you ought to behave as at a banquet.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 15","te":["deseo","aceptacion"]},{"i":"epicteto-011","a":"epicteto","t":"Recordá que sos un actor en una obra, tal como el autor quiera que sea.","o":"Remember that thou art an actor in a play, of such a kind as the teacher (author) may choose","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 17","te":["identidad","aceptacion"]},{"i":"epicteto-012","a":"epicteto","t":"Podés ser invencible si no entrás en ninguna contienda en la que vencer no dependa de vos.","o":"You can be invincible, if you enter into no contest in which it is not in your power to conquer.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 19","te":["libertad","resiliencia"]},{"i":"epicteto-013","a":"epicteto","t":"Recordá que no te ofende quien te insulta o te golpea, sino tu opinión de que eso es ofensivo.","o":"Remember that it is not he who reviles you or strikes you, who insults you, but it is your opinion about these things as being insulting.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 20","te":["ira","conciencia"]},{"i":"epicteto-014","a":"epicteto","t":"Cuando alguien te irrita, sabé que lo que te irritó es tu propia opinión.","o":"When then a man irritates you, you must know that it is your own opinion which has irritated you.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 20","te":["ira","regulacion-emocional"]},{"i":"epicteto-015","a":"epicteto","t":"Tené cada día ante los ojos la muerte, el exilio y todo lo que parece terrible, sobre todo la muerte: nunca pensarás nada mezquino ni desearás nada en exceso.","o":"Let death and exile and every other thing which appears dreadful be daily before your eyes; but most of all death: and you will never think of anything mean nor will you desire anything extravagantly.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 21","te":["muerte","deseo"]},{"i":"epicteto-016","a":"epicteto","t":"Si alguna vez te volcás hacia lo exterior para agradar a alguien, sabé que perdiste el rumbo de tu vida.","o":"If it should ever happen to you to be turned to externals in order to please some person, you must know that you have lost your purpose in life.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 23","te":["autenticidad","sentido-de-vida"]},{"i":"epicteto-017","a":"epicteto","t":"[Te indignaría que alguien entregara tu cuerpo a un desconocido;] pero que pongas tu mente en manos de cualquiera, de modo que si te insulta quede turbada, ¿no te avergüenza?","o":"but that you put your understanding in the power of any man whom you meet, so that if he should revile you, it is disturbed and troubled, are you not ashamed at this?","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 28","te":["libertad","autoestima"]},{"i":"epicteto-018","a":"epicteto","t":"Que el silencio sea la regla general, o que se diga solo lo necesario y en pocas palabras.","o":"And let silence be the general rule, or let only what is necessary be said, and in few words.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 33","te":["silencio","comunicacion"]},{"i":"epicteto-019","a":"epicteto","t":"[Ante la impresión de un placer,] que la cosa te espere, y concedete cierta demora.","o":"but let the thing wait for you, and allow yourself a certain delay on your own part.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 34","te":["deseo","regulacion-emocional"]},{"i":"epicteto-020","a":"epicteto","t":"Cuando decidiste que algo debe hacerse y lo estás haciendo, no evites que te vean, aunque muchos opinen mal de ello.","o":"When you have decided that a thing ought to be done, and are doing it, never avoid being seen doing it, though the many shall form an unfavorable opinion about it.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 35","te":["autenticidad","responsabilidad"]},{"i":"epicteto-021","a":"epicteto","t":"Que todo tu cuidado se dirija a la mente.","o":"let all your care be directed to the mind.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 41","te":["autoconocimiento"]},{"i":"epicteto-022","a":"epicteto","t":"Cuando alguien te trata mal o habla mal de vos, recordá que lo hace o lo dice porque cree que es lo que corresponde.","o":"When any person treats you ill or speaks ill of you, remember that he does this or says this because he thinks that it is his duty.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 42","te":["vinculos","compasion","ira"]},{"i":"epicteto-023","a":"epicteto","t":"Todo tiene dos asas: una por la que se lo puede llevar y otra por la que no.","o":"Everything has two handles, the one by which it may be borne, the other by which it may not.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 43","te":["aceptacion","vinculos"]},{"i":"epicteto-024","a":"epicteto","t":"Antes de conocer su razón, ¿cómo sabés si obra mal?","o":"For before you shall have determined the opinion how do you know whether he is acting wrong?","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 45","te":["vinculos","comunicacion"]},{"i":"epicteto-025","a":"epicteto","t":"En un banquete no digas cómo hay que comer: comé como se debe.","o":"at a banquet do not say how a man ought to eat, but eat as you ought to eat.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 46","te":["autenticidad","habitos"]},{"i":"epicteto-026","a":"epicteto","t":"Lo propio del filósofo es esto: espera de sí mismo todo beneficio y todo daño.","o":"The condition and characteristic of a philosopher is this: he expects all advantage and all harm from himself.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 48","te":["responsabilidad","libertad"]},{"i":"epicteto-027","a":"epicteto","t":"Y lo que digan de vos, no le prestes atención: no es asunto tuyo.","o":"And whatever any man shall say about you, do not attend to it; for this is no affair of yours.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 50","te":["autoestima","libertad"]},{"i":"epicteto-028","a":"epicteto","t":"Si querés que tus hijos, tu pareja y tus amigos vivan para siempre, sos un ingenuo.","o":"If you would have your children and your wife and your friends to live for ever, you are silly","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 14","te":["muerte","aceptacion","vinculos"]},{"i":"baruch-spinoza-001","a":"baruch-spinoza","t":"Consideraré las acciones y los deseos humanos exactamente como si se tratara de líneas, planos y cuerpos.","o":"I shall consider human actions and desires in exactly the same manner, as though I were concerned with lines, planes, and solids.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["emociones","conocimiento"]},{"i":"baruch-spinoza-002","a":"baruch-spinoza","t":"Cada cosa, en cuanto está en sí, se esfuerza por perseverar en su ser.","o":"Everything, in so far as it is in itself, endeavours to persist in its own being.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["existencia","deseo"]},{"i":"baruch-spinoza-003","a":"baruch-spinoza","t":"Los seres humanos se creen libres porque son conscientes de sus voliciones y deseos, y en su ignorancia ni sueñan con las causas [que los determinan].","o":"men think themselves free inasmuch as they are conscious of their volitions and desires, and never even dream, in their ignorance, of the causes","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 1","te":["libertad","inconsciente","deseo"]},{"i":"baruch-spinoza-004","a":"baruch-spinoza","t":"Conscientes de sus acciones y apetitos, pero ignorantes de las causas que los determinan a desear algo en particular.","o":"conscious of their own actions and appetites, but ignorant of the causes whereby they are determined to any particular desire","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 4","te":["inconsciente","deseo"]},{"i":"baruch-spinoza-005","a":"baruch-spinoza","t":"El deseo es la esencia misma del ser humano.","o":"Desire is the actual essence of man","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["deseo","identidad"]},{"i":"baruch-spinoza-006","a":"baruch-spinoza","t":"La alegría es el paso de una perfección menor a una mayor.","o":"Pleasure is the transition of a man from a less to a greater perfection.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["alegria","emociones"]},{"i":"baruch-spinoza-007","a":"baruch-spinoza","t":"La tristeza es el paso de una perfección mayor a una menor.","o":"Pain is the transition of a man from a greater to a less perfection.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["tristeza","emociones"]},{"i":"baruch-spinoza-008","a":"baruch-spinoza","t":"El amor no es sino una alegría acompañada de la idea de una causa exterior.","o":"Love is nothing else but pleasure accompanied by the idea of an external cause","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["amor","emociones"]},{"i":"baruch-spinoza-009","a":"baruch-spinoza","t":"El odio es una tristeza acompañada de la idea de una causa exterior.","o":"Hatred is pain, accompanied by the idea of an external cause.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["ira","emociones"]},{"i":"baruch-spinoza-010","a":"baruch-spinoza","t":"La admiración es la imaginación de algo en que la mente se detiene, porque esa idea no tiene conexión con otras.","o":"Wonder is the conception (imaginatio) of anything, wherein the mind comes to a stand, because the particular concept in question has no connection with other concepts","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["emociones","atencion"]},{"i":"baruch-spinoza-011","a":"baruch-spinoza","t":"La esperanza es una alegría inconstante, surgida de la idea de algo pasado o futuro de cuyo desenlace dudamos en alguna medida.","o":"Hope is an inconstant pleasure, arising from the idea of something past or future, whereof we to a certain extent doubt the issue.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["esperanza","incertidumbre","emociones"]},{"i":"baruch-spinoza-012","a":"baruch-spinoza","t":"El miedo es una tristeza inconstante, surgida de la idea de algo pasado o futuro de cuyo desenlace dudamos en alguna medida.","o":"Fear is an inconstant pain arising from the idea of something past or future, whereof we to a certain extent doubt the issue","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["miedo","incertidumbre","emociones"]},{"i":"baruch-spinoza-013","a":"baruch-spinoza","t":"La seguridad es una alegría surgida de la idea de algo pasado o futuro del que se ha eliminado toda causa de duda.","o":"Confidence is pleasure arising from the idea of something past or future, wherefrom all cause of doubt has been removed.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["emociones","esperanza"]},{"i":"baruch-spinoza-014","a":"baruch-spinoza","t":"La desesperación es una tristeza surgida de la idea de algo pasado o futuro del que se ha eliminado toda causa de duda.","o":"Despair is pain arising from the idea of something past or future, wherefrom all cause of doubt has been removed.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["angustia","emociones"]},{"i":"baruch-spinoza-015","a":"baruch-spinoza","t":"La decepción es una tristeza acompañada de la idea de algo pasado que tuvo un desenlace contrario a nuestra esperanza.","o":"Disappointment is pain accompanied by the idea of something past, which has had an issue contrary to our hope.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["tristeza","emociones"]},{"i":"baruch-spinoza-016","a":"baruch-spinoza","t":"La conmiseración es una tristeza acompañada de la idea de un mal que le sucedió a otro que imaginamos semejante a nosotros.","o":"Pity is pain accompanied by the idea of evil, which has befallen someone else whom we conceive to be like ourselves","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["empatia","compasion","emociones"]},{"i":"baruch-spinoza-017","a":"baruch-spinoza","t":"La envidia es odio en cuanto lleva a entristecerse por la dicha ajena y alegrarse por la desgracia ajena.","o":"Envy is hatred, in so far as it induces a man to be pained by another's good fortune, and to rejoice in another's evil fortune.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["emociones","vinculos"]},{"i":"baruch-spinoza-018","a":"baruch-spinoza","t":"La humildad es una tristeza que surge de contemplar la propia debilidad del cuerpo o de la mente.","o":"Humility is pain arising from a man's contemplation of his own weakness of body or mind.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["autoestima","emociones"]},{"i":"baruch-spinoza-019","a":"baruch-spinoza","t":"La soberbia es estimarse más de lo justo por amor de sí.","o":"Pride is thinking too highly of one's self from self--love.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["autoestima","emociones"]},{"i":"baruch-spinoza-020","a":"baruch-spinoza","t":"La vergüenza es una tristeza acompañada de la idea de alguna acción propia que creemos censurada por los demás.","o":"Shame is pain accompanied by the idea of some action of our own, which we believe to be blamed by others.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["culpa","emociones"]},{"i":"baruch-spinoza-021","a":"baruch-spinoza","t":"La añoranza es el deseo de poseer algo, mantenido vivo por su recuerdo y a la vez frenado por el recuerdo de otras cosas que excluyen su existencia.","o":"Regret is the desire or appetite to possess something, kept alive by the remembrance of the said thing, and at the same time constrained by the remembrance of other things which exclude the existence of it.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["duelo","memoria","emociones"]},{"i":"baruch-spinoza-022","a":"baruch-spinoza","t":"La emulación es el deseo de algo, engendrado en nosotros porque imaginamos que otros tienen el mismo deseo.","o":"Emulation is the desire of something, engendered in us by our conception that others have the same desire.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["deseo","vinculos"]},{"i":"baruch-spinoza-023","a":"baruch-spinoza","t":"El agradecimiento o gratitud es el deseo, nacido del amor, de hacer el bien a quien, con un afecto semejante, nos hizo bien.","o":"Thankfulness or Gratitude is the desire or zeal springing from love, whereby we endeavour to benefit him, who with similar feelings of love has conferred a benefit on us.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["gratitud","vinculos"]},{"i":"baruch-spinoza-024","a":"baruch-spinoza","t":"La ira es el deseo que, por odio, nos impulsa a dañar a quien odiamos.","o":"Anger is the desire, whereby through hatred we are induced to injure one whom we hate","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["ira","emociones"]},{"i":"baruch-spinoza-025","a":"baruch-spinoza","t":"La venganza es el deseo que, por odio recíproco, nos impulsa a dañar a quien, con un afecto semejante, nos dañó.","o":"Revenge is the desire whereby we are induced, through mutual hatred, to injure one who, with similar feelings, has injured us.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["ira","vinculos"]},{"i":"baruch-spinoza-026","a":"baruch-spinoza","t":"La ambición es el deseo inmoderado de poder.","o":"Ambition is the immoderate desire of power.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["poder","deseo"]},{"i":"baruch-spinoza-027","a":"baruch-spinoza","t":"Un afecto que es una pasión deja de ser pasión en cuanto nos formamos de él una idea clara y distinta.","o":"An emotion, which is a passion, ceases to be a passion, as soon as we form a clear and distinct idea thereof.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 5","te":["regulacion-emocional","autoconocimiento","terapia"]},{"i":"baruch-spinoza-028","a":"baruch-spinoza","t":"Un afecto solo puede ser reprimido o suprimido por otro afecto contrario y más fuerte.","o":"An emotion can only be controlled or destroyed by another emotion contrary thereto, and with more power for controlling emotion.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 4","te":["regulacion-emocional","emociones"]},{"i":"baruch-spinoza-029","a":"baruch-spinoza","t":"Un afecto es tanto más fuerte cuantas más causas concurren a la vez para despertarlo.","o":"An emotion is stronger in proportion to the number of simultaneous concurrent causes whereby it is aroused.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 5","te":["emociones"]},{"i":"baruch-spinoza-030","a":"baruch-spinoza","t":"Llamo servidumbre a la impotencia humana para moderar y reprimir los afectos.","o":"Human infirmity in moderating and checking the emotions I name bondage","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 4","te":["libertad","regulacion-emocional"]},{"i":"baruch-spinoza-031","a":"baruch-spinoza","t":"El odio aumenta cuando es correspondido y, en cambio, puede ser destruido por el amor.","o":"Hatred is increased by being reciprocated, and can on the other hand be destroyed by love.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["ira","amor"]},{"i":"baruch-spinoza-032","a":"baruch-spinoza","t":"El odio nunca puede ser bueno.","o":"Hatred can never be good.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 4","te":["ira"]},{"i":"baruch-spinoza-033","a":"baruch-spinoza","t":"[Quien vive guiado por la razón] se esfuerza, en lo posible, por devolver amor o bondad al odio de los demás.","o":"endeavours, as far as possible, to render back love, or kindness, for other men's hatred","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 4","te":["compasion","ira"]},{"i":"baruch-spinoza-034","a":"baruch-spinoza","t":"Los afectos de esperanza y miedo no pueden ser buenos por sí mismos.","o":"Emotions of hope and fear cannot be in themselves good.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 4","te":["esperanza","miedo"]},{"i":"baruch-spinoza-035","a":"baruch-spinoza","t":"La humildad no es una virtud, o no nace de la razón.","o":"Humility is not a virtue, or does not arise from reason.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 4","te":["autoestima"]},{"i":"baruch-spinoza-036","a":"baruch-spinoza","t":"El contento de sí puede nacer de la razón, y el que nace de la razón es el más alto posible.","o":"Self--approval may arise from reason, and that which arises from reason is the highest possible.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 4","te":["autoestima","felicidad"]},{"i":"baruch-spinoza-037","a":"baruch-spinoza","t":"En quien vive guiado por la razón, la conmiseración es en sí misma mala e inútil.","o":"Pity, in a man who lives under the guidance of reason, is in itself bad and useless.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 4","te":["compasion"]},{"i":"baruch-spinoza-038","a":"baruch-spinoza","t":"Para el ser humano no hay nada más útil que otro ser humano.","o":"to man there is nothing more useful than man","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 4","te":["vinculos","sociedad"]},{"i":"baruch-spinoza-039","a":"baruch-spinoza","t":"El bien supremo de quienes siguen la virtud es común a todos, y por eso todos pueden gozarlo por igual.","o":"The highest good of those who follow virtue is common to all, and therefore all can equally rejoice therein.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 4","te":["felicidad","sociedad"]},{"i":"baruch-spinoza-040","a":"baruch-spinoza","t":"Sin embargo, las almas no se vencen con las armas, sino con el amor y la generosidad.","o":"Yet minds are not conquered by force, but by love and high--mindedness.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 4","te":["amor","poder"]},{"i":"baruch-spinoza-041","a":"baruch-spinoza","t":"El hombre libre en nada piensa menos que en la muerte, y su sabiduría es una meditación no de la muerte sino de la vida.","o":"A free man thinks of death least of all things; and his wisdom is a meditation not of death but of life.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 4","te":["muerte","libertad","sentido-de-vida"]},{"i":"baruch-spinoza-042","a":"baruch-spinoza","t":"Quien sabe bien que todo se sigue de la necesidad de la naturaleza divina [no hallará nada digno de odio, risa o desprecio].","o":"He who rightly realizes, that all things follow from the necessity of the divine nature","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 4","te":["aceptacion","trascendencia"]},{"i":"baruch-spinoza-043","a":"baruch-spinoza","t":"El bien supremo de la mente es el conocimiento de Dios.","o":"The mind's highest good is the knowledge of God","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 4","te":["trascendencia","conocimiento"]},{"i":"baruch-spinoza-044","a":"baruch-spinoza","t":"Sentimos y experimentamos que somos eternos.","o":"we feel and know that we are eternal","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 5","te":["trascendencia","existencia"]},{"i":"baruch-spinoza-045","a":"baruch-spinoza","t":"La felicidad no es el premio de la virtud, sino la virtud misma.","o":"Blessedness is not the reward of virtue, but virtue itself","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 5","te":["felicidad"]},{"i":"baruch-spinoza-046","a":"baruch-spinoza","t":"Pero todo lo excelso es tan difícil como raro.","o":"But all things excellent are as difficult as they are rare.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 5","te":["transformacion-personal","esperanza"]},{"i":"baruch-spinoza-047","a":"baruch-spinoza","t":"La devoción es amor hacia alguien a quien admiramos.","o":"Devotion is love towards one whom we admire.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["amor","emociones"]},{"i":"baruch-spinoza-048","a":"baruch-spinoza","t":"La indignación es odio hacia quien hizo mal a otro.","o":"Indignation is hatred towards one who has done evil to another.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["ira","sociedad"]},{"i":"baruch-spinoza-049","a":"baruch-spinoza","t":"La sobrestimación es estimar a alguien más de lo justo por el amor que le tenemos.","o":"Partiality is thinking too highly of anyone because of the love we bear him.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["amor","vinculos"]},{"i":"baruch-spinoza-050","a":"baruch-spinoza","t":"La benevolencia es el deseo de hacer bien a alguien que nos inspira conmiseración.","o":"Benevolence is the desire of benefiting one whom we pity.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["compasion"]},{"i":"baruch-spinoza-051","a":"baruch-spinoza","t":"La audacia es el deseo que impulsa a hacer algo peligroso que nuestros iguales temen intentar.","o":"Daring is the desire, whereby a man is set on to do something dangerous which his equals fear to attempt.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["miedo","voluntad"]},{"i":"immanuel-kant-001","a":"immanuel-kant","t":"La Ilustración es la salida del ser humano de su minoría de edad, de la que él mismo es culpable.","o":"Aufklärung ist der Ausgang des Menschen aus seiner selbst verschuldeten Unmündigkeit.","l":"de","ob":"Respuesta a la pregunta: ¿qué es la Ilustración?","an":"1784","u":"Capítulo 1","te":["libertad","transformacion-personal"]},{"i":"immanuel-kant-002","a":"immanuel-kant","t":"La minoría de edad es la incapacidad de servirse del propio entendimiento sin la guía de otro.","o":"Unmündigkeit ist das Unvermögen, sich seines Verstandes ohne Leitung eines anderen zu bedienen.","l":"de","ob":"Respuesta a la pregunta: ¿qué es la Ilustración?","an":"1784","u":"Capítulo 1","te":["libertad","desarrollo-humano"]},{"i":"immanuel-kant-003","a":"immanuel-kant","t":"Sapere aude: ¡tené el valor de servirte de tu propio entendimiento! Ese es el lema de la Ilustración.","o":"Sapere aude! Habe Mut dich deines eigenen Verstandes zu bedienen! ist also der Wahlspruch der Aufklärung.","l":"de","ob":"Respuesta a la pregunta: ¿qué es la Ilustración?","an":"1784","u":"Capítulo 1","te":["libertad","miedo","autenticidad"]},{"i":"immanuel-kant-004","a":"immanuel-kant","t":"La pereza y la cobardía son las causas por las que tantas personas [siguen gustosamente toda la vida en la minoría de edad].","o":"Faulheit und Feigheit sind die Ursachen, warum ein so großer Teil der Menschen","l":"de","ob":"Respuesta a la pregunta: ¿qué es la Ilustración?","an":"1784","u":"Capítulo 1","te":["libertad","miedo"]},{"i":"immanuel-kant-005","a":"immanuel-kant","t":"¡Es tan cómodo ser menor de edad!","o":"Es ist so bequem, unmündig zu sein.","l":"de","ob":"Respuesta a la pregunta: ¿qué es la Ilustración?","an":"1784","u":"Capítulo 1","te":["libertad","responsabilidad"]},{"i":"immanuel-kant-006","a":"immanuel-kant","t":"Si tengo un libro que piensa por mí, un director espiritual que tiene conciencia por mí, un médico que decide por mí la dieta… [no necesito esforzarme].","o":"Habe ich ein Buch, das für mich Verstand hat, einen Seelsorger, der für mich Gewissen hat, einen Arzt, der für mich die Diät beurteilt","l":"de","ob":"Respuesta a la pregunta: ¿qué es la Ilustración?","an":"1784","u":"Capítulo 1","te":["responsabilidad","libertad"]},{"i":"immanuel-kant-007","a":"immanuel-kant","t":"[Para la Ilustración solo hace falta la libertad] de hacer uso público de la propia razón en todos los asuntos.","o":"von seiner Vernunft in allen Stücken öffentlichen Gebrauch zu machen","l":"de","ob":"Respuesta a la pregunta: ¿qué es la Ilustración?","an":"1784","u":"Capítulo 1","te":["libertad","sociedad","comunicacion"]},{"i":"immanuel-kant-008","a":"immanuel-kant","t":"Que un público se ilustre a sí mismo es más bien posible; más aún, si se le deja libertad, es casi inevitable.","o":"Daß aber ein Publikum sich selbst aufkläre, ist eher möglich; ja es ist, wenn man ihm nur Freiheit läßt, beinahe unausbleiblich.","l":"de","ob":"Respuesta a la pregunta: ¿qué es la Ilustración?","an":"1784","u":"Capítulo 1","te":["libertad","sociedad"]},{"i":"immanuel-kant-009","a":"immanuel-kant","t":"No hay nada en el mundo, ni fuera de él, que pueda considerarse bueno sin restricción, salvo una buena voluntad.","o":"Es ist überall nichts in der Welt, ja überhaupt auch außer derselben zu denken möglich, was ohne Einschränkung für gut könnte gehalten werden, als allein ein guter Wille.","l":"de","ob":"Fundamentación de la metafísica de las costumbres","an":"1785","u":"Capítulo 3","te":["voluntad","responsabilidad"]},{"i":"immanuel-kant-010","a":"immanuel-kant","t":"Obrá solo según aquella máxima que puedas querer, al mismo tiempo, que se convierta en ley universal.","o":"Handle nur nach derjenigen Maxime, durch die du zugleich wollen kannst, dass sie ein allgemeines Gesetz werde.","l":"de","ob":"Fundamentación de la metafísica de las costumbres","an":"1785","u":"Capítulo 4","te":["responsabilidad"]},{"i":"immanuel-kant-011","a":"immanuel-kant","t":"¿Podés querer también que tu máxima se convierta en ley universal?","o":"Kannst du auch wollen, dass deine Maxime ein allgemeines Gesetz werde?","l":"de","ob":"Fundamentación de la metafísica de las costumbres","an":"1785","u":"Capítulo 3","te":["responsabilidad","autoconocimiento"]},{"i":"immanuel-kant-012","a":"immanuel-kant","t":"Obrá de tal modo que trates a la humanidad, tanto en tu persona como en la de cualquier otro, siempre a la vez como un fin y nunca solo como un medio.","o":"Handle so, dass du die Menschheit sowohl in deiner Person, als in der Person eines jeden andern jederzeit zugleich als Zweck, niemals bloß als Mittel brauchst.","l":"de","ob":"Fundamentación de la metafísica de las costumbres","an":"1785","u":"Capítulo 4","te":["vinculos","responsabilidad","sociedad"]},{"i":"immanuel-kant-013","a":"immanuel-kant","t":"En el reino de los fines, todo tiene un precio o una dignidad.","o":"Im Reiche der Zwecke hat alles entweder einen Preis, oder eine Würde.","l":"de","ob":"Fundamentación de la metafísica de las costumbres","an":"1785","u":"Capítulo 4","te":["identidad","sociedad"]},{"i":"immanuel-kant-014","a":"immanuel-kant","t":"Lo que tiene precio puede ser reemplazado por otra cosa equivalente; lo que está por encima de todo precio y no admite equivalente tiene dignidad.","o":"Was einen Preis hat, an dessen Stelle kann auch etwas anderes als Äquivalent gesetzt werden; was dagegen über allen Preis erhaben ist, mithin kein Äquivalent verstattet, das hat eine Würde.","l":"de","ob":"Fundamentación de la metafísica de las costumbres","an":"1785","u":"Capítulo 4","te":["identidad","autoestima"]},{"i":"immanuel-kant-015","a":"immanuel-kant","t":"La autonomía es, pues, el fundamento de la dignidad de la naturaleza humana y de toda naturaleza racional.","o":"Autonomie ist also der Grund der Würde der menschlichen und jeder vernünftigen Natur.","l":"de","ob":"Fundamentación de la metafísica de las costumbres","an":"1785","u":"Capítulo 4","te":["libertad","identidad"]},{"i":"immanuel-kant-016","a":"immanuel-kant","t":"Porque la felicidad no es un ideal de la razón, sino de la imaginación.","o":"weil Glückseligkeit nicht ein Ideal der Vernunft, sondern der Einbildungskraft ist","l":"de","ob":"Fundamentación de la metafísica de las costumbres","an":"1785","u":"Capítulo 4","te":["felicidad","deseo"]},{"i":"immanuel-kant-017","a":"immanuel-kant","t":"El deber es la necesidad de una acción por respeto a la ley.","o":"Pflicht ist die Notwendigkeit einer Handlung aus Achtung fürs Gesetz.","l":"de","ob":"Fundamentación de la metafísica de las costumbres","an":"1785","u":"Capítulo 3","te":["responsabilidad"]},{"i":"immanuel-kant-018","a":"immanuel-kant","t":"En rigor, el respeto es la representación de un valor que le pone freno a mi amor propio.","o":"Eigentlich ist Achtung die Vorstellung von einem Werte, der meiner Selbstliebe Abbruch tut.","l":"de","ob":"Fundamentación de la metafísica de las costumbres","an":"1785","u":"Capítulo 3","te":["vinculos","autoestima"]},{"i":"immanuel-kant-019","a":"immanuel-kant","t":"Conservan su vida conforme al deber, pero no por deber.","o":"Sie bewahren ihr Leben zwar pflichtmäßig aber nicht aus Pflicht.","l":"de","ob":"Fundamentación de la metafísica de las costumbres","an":"1785","u":"Capítulo 3","te":["responsabilidad"]},{"i":"immanuel-kant-020","a":"immanuel-kant","t":"[Ahí empieza el valor del carácter:] en hacer el bien no por inclinación, sino por deber.","o":"dass er wohltue, nicht aus Neigung, sondern aus Pflicht","l":"de","ob":"Fundamentación de la metafísica de las costumbres","an":"1785","u":"Capítulo 3","te":["responsabilidad","compasion"]},{"i":"immanuel-kant-021","a":"immanuel-kant","t":"Todos los seres humanos tienen por sí mismos la inclinación más poderosa e íntima hacia la felicidad.","o":"haben alle Menschen schon von selbst die mächtigste und innigste Neigung zur Glückseligkeit","l":"de","ob":"Fundamentación de la metafísica de las costumbres","an":"1785","u":"Capítulo 3","te":["felicidad","deseo"]},{"i":"immanuel-kant-022","a":"immanuel-kant","t":"La habilidad y la diligencia en el trabajo tienen un precio de mercado; el ingenio, la imaginación viva y el humor, un precio afectivo; en cambio, la fidelidad a lo prometido y la benevolencia por principios tienen un valor interior.","o":"Geschicklichkeit und Fleiß im Arbeiten haben einen Marktpreis; Witz, lebhafte Einbildungskraft und Launen einen Affektionspreis; dagegen Treue im Versprechen, Wohlwollen aus Grundsätzen (nicht aus Instinkt) haben einen innern Wert.","l":"de","ob":"Fundamentación de la metafísica de las costumbres","an":"1785","u":"Capítulo 4","te":["trabajo","vinculos","autenticidad"]},{"i":"immanuel-kant-023","a":"immanuel-kant","t":"Todo respeto por una persona es, en rigor, respeto por la ley [de la que nos da el ejemplo].","o":"Alle Achtung für eine Person ist eigentlich nur Achtung fürs Gesetz","l":"de","ob":"Fundamentación de la metafísica de las costumbres","an":"1785","u":"Capítulo 3","te":["vinculos"]},{"i":"immanuel-kant-024","a":"immanuel-kant","t":"Dos cosas llenan el ánimo de una admiración y un respeto siempre nuevos y crecientes, cuanto más a menudo y con más constancia se ocupa de ellas la reflexión: el cielo estrellado sobre mí y la ley moral en mí.","o":"Zwei Dinge erfüllen das Gemüt mit immer neuer und zunehmender Bewunderung und Ehrfurcht, je öfter und anhaltender sich das Nachdenken damit beschäftigt: Der bestirnte Himmel über mir, und das moralische Gesetz in mir.","l":"de","ob":"Crítica de la razón práctica","an":"1788","u":"Capítulo 34","te":["trascendencia","conciencia","naturaleza"]},{"i":"immanuel-kant-025","a":"immanuel-kant","t":"¡Deber! Nombre sublime y grande…","o":"Pflicht! du erhabener großer Name","l":"de","ob":"Crítica de la razón práctica","an":"1788","u":"Capítulo 17","te":["responsabilidad"]},{"i":"immanuel-kant-026","a":"immanuel-kant","t":"Pensar por uno mismo significa buscar en sí mismo, es decir, en la propia razón, la piedra de toque suprema de la verdad; y la máxima de pensar siempre por uno mismo es la Ilustración.","o":"Selbstdenken heißt den obersten Probierstein der Wahrheit in sich selbst (d. i. in seiner eigenen Vernunft) suchen; und die Maxime, jederzeit selbst zu denken, ist die Aufklärung.","l":"de","ob":"¿Qué significa orientarse en el pensamiento?","an":"1786","u":"Capítulo 2","te":["autenticidad","verdad","libertad"]},{"i":"immanuel-kant-027","a":"immanuel-kant","t":"Pero ¡cuánto y con qué acierto pensaríamos si no pensáramos, por así decir, en comunidad con otros a quienes comunicamos nuestros pensamientos y que nos comunican los suyos!","o":"Allein wie viel und mit welcher Richtigkeit würden wir wohl denken, wenn wir nicht gleichsam in Gemeinschaft mit andern, denen wir unsere und die uns ihre Gedanken mitteilen, dächten!","l":"de","ob":"¿Qué significa orientarse en el pensamiento?","an":"1786","u":"Capítulo 2","te":["comunicacion","encuentro","conocimiento"]},{"i":"immanuel-kant-028","a":"immanuel-kant","t":"La razón no siente: advierte su carencia y, mediante el impulso de conocer, produce el sentimiento de necesidad.","o":"Die Vernunft fühlt nicht; sie sieht ihren Mangel ein, und wirkt durch den Erkenntnistrieb das Gefühl des Bedürfnisses.","l":"de","ob":"¿Qué significa orientarse en el pensamiento?","an":"1786","u":"Capítulo 2","te":["emociones","conocimiento"]},{"i":"immanuel-kant-029","a":"immanuel-kant","t":"Y así, la libertad de pensamiento, si quiere proceder con total independencia de las leyes de la razón, termina destruyéndose a sí misma.","o":"Und so zerstört Freiheit im Denken, wenn sie so gar unabhängig von Gesetzen der Vernunft verfahren will, endlich sich selbst.","l":"de","ob":"¿Qué significa orientarse en el pensamiento?","an":"1786","u":"Capítulo 2","te":["libertad"]},{"i":"immanuel-kant-030","a":"immanuel-kant","t":"Se dice que un poder superior puede quitarnos la libertad de hablar o de escribir, pero de ningún modo la libertad de pensar.","o":"Zwar sagt man: die Freiheit zu sprechen oder zu schreiben, könne uns zwar durch obere Gewalt, aber die Freiheit zu denken durch sie gar nicht genommen werden.","l":"de","ob":"¿Qué significa orientarse en el pensamiento?","an":"1786","u":"Capítulo 2","te":["libertad","poder"]},{"i":"immanuel-kant-051","a":"immanuel-kant","t":"A la libertad de pensar se opone, en primer lugar, la coacción civil.","o":"Der Freiheit zu denken ist erstlich der bürgerliche Zwang entgegengesetzt.","l":"de","ob":"¿Qué significa orientarse en el pensamiento?","an":"1786","u":"Capítulo 2","te":["libertad","poder"]},{"i":"immanuel-kant-038","a":"immanuel-kant","t":"El estado de paz entre seres humanos que viven juntos no es un estado natural [hay que instaurarlo].","o":"Der Friedenszustand unter Menschen, die neben einander leben, ist kein Naturstand","l":"de","ob":"Sobre la paz perpetua","an":"1795","u":"Capítulo 4","te":["sociedad","vinculos"]},{"i":"immanuel-kant-039","a":"immanuel-kant","t":"El mundo no se va a hundir porque haya menos personas malas.","o":"Die Welt wird keinesweges dadurch untergehen, daß der bösen Menschen weniger wird.","l":"de","ob":"Sobre la paz perpetua","an":"1795","u":"Capítulo 9","te":["sociedad","humor"]},{"i":"immanuel-kant-040","a":"immanuel-kant","t":"Es el espíritu comercial el que no puede coexistir con la guerra.","o":"Es ist der Handelsgeist, der mit dem Kriege nicht zusammen bestehen kann","l":"de","ob":"Sobre la paz perpetua","an":"1795","u":"Capítulo 8","te":["sociedad"]},{"i":"immanuel-kant-031","a":"immanuel-kant","t":"Lo sublime conmueve; lo bello encanta.","o":"Das Erhabene rührt, das Schöne reizt.","l":"de","ob":"Observaciones sobre el sentimiento de lo bello y lo sublime","an":"1764","u":"Capítulo 2","te":["emociones","cultura"]},{"i":"immanuel-kant-032","a":"immanuel-kant","t":"La noche es sublime; el día es bello.","o":"Die Nacht ist erhaben, der Tag ist schön.","l":"de","ob":"Observaciones sobre el sentimiento de lo bello y lo sublime","an":"1764","u":"Capítulo 2","te":["naturaleza","emociones"]},{"i":"immanuel-kant-033","a":"immanuel-kant","t":"Las cualidades sublimes inspiran respeto; las bellas, amor.","o":"Erhabene Eigenschaften flößen Hochachtung, schöne aber Liebe ein.","l":"de","ob":"Observaciones sobre el sentimiento de lo bello y lo sublime","an":"1764","u":"Capítulo 3","te":["amor","vinculos"]},{"i":"immanuel-kant-034","a":"immanuel-kant","t":"La amistad tiene sobre todo el rasgo de lo sublime.","o":"Freundschaft hat hauptsächlich den Zug des Erhabenen.","l":"de","ob":"Observaciones sobre el sentimiento de lo bello y lo sublime","an":"1764","u":"Capítulo 3","te":["amistad"]},{"i":"immanuel-kant-035","a":"immanuel-kant","t":"Entre las cualidades morales, solo la verdadera virtud es sublime.","o":"In moralischen Eigenschaften ist wahre Tugend allein erhaben.","l":"de","ob":"Observaciones sobre el sentimiento de lo bello y lo sublime","an":"1764","u":"Capítulo 3","te":["autenticidad"]},{"i":"immanuel-kant-036","a":"immanuel-kant","t":"La veracidad y la honradez son sencillas y nobles; la broma y la lisonja amable son finas y bellas.","o":"Wahrhaftigkeit und Redlichkeit ist einfältig und edel, Scherz und gefällige Schmeichelei ist fein und schön.","l":"de","ob":"Observaciones sobre el sentimiento de lo bello y lo sublime","an":"1764","u":"Capítulo 3","te":["verdad","comunicacion"]},{"i":"immanuel-kant-037","a":"immanuel-kant","t":"Las bromas y la alegría pertenecen al sentimiento de lo bello.","o":"Scherze und Munterkeit schlagen in das Gefühl des Schönen ein.","l":"de","ob":"Observaciones sobre el sentimiento de lo bello y lo sublime","an":"1764","u":"Capítulo 3","te":["humor","alegria"]},{"i":"immanuel-kant-041","a":"immanuel-kant","t":"De una madera tan torcida como aquella de la que está hecho el ser humano no puede tallarse nada del todo recto.","o":"aus so krummem Holze, als woraus der Mensch gemacht ist, kann nichts ganz Gerades gezimmert werden.","l":"de","ob":"Idea de una historia universal en sentido cosmopolita","an":"1784","u":"Capítulo 1","te":["aceptacion","existencia"]},{"i":"immanuel-kant-042","a":"immanuel-kant","t":"Entiendo aquí por antagonismo la insociable sociabilidad del ser humano.","o":"Ich verstehe hier unter dem Antagonism die ungesellige Geselligkeit des Menschen","l":"de","ob":"Idea de una historia universal en sentido cosmopolita","an":"1784","u":"Capítulo 1","te":["vinculos","sociedad"]},{"i":"immanuel-kant-043","a":"immanuel-kant","t":"Del poder del ánimo para dominar sus sentimientos morbosos por la sola resolución.","o":"Von der Macht des Gemüths durch den bloßen Vorsatz seiner krankhaften Gefühle Meister zu sein.","l":"de","ob":"El conflicto de las facultades","an":"1798","u":"Capítulo 1","te":["regulacion-emocional","salud-mental"]},{"i":"immanuel-kant-044","a":"immanuel-kant","t":"Cuando lo asaltan angustias que amenazan convertirse en cavilaciones, es decir, en males imaginados, una persona razonable se pregunta si existe un objeto que las justifique.","o":"Ein vernünftiger Mensch statuirt keine solche Hypochondrie: sondern wenn ihm Beängstigungen anwandeln, die in Grillen, d.i. selbst ausgedachte Übel, ausschlagen wollen, so fragt er sich, ob ein Object derselben da sei.","l":"de","ob":"El conflicto de las facultades","an":"1798","u":"Capítulo 1","te":["angustia","regulacion-emocional","terapia"]},{"i":"immanuel-kant-045","a":"immanuel-kant","t":"[Por mi pecho estrecho tengo] una disposición natural a la hipocondría.","o":"eine natürliche Anlage zur Hypochondrie","l":"de","ob":"El conflicto de las facultades","an":"1798","u":"Capítulo 1","te":["salud-mental","cuerpo"]},{"i":"immanuel-kant-046","a":"immanuel-kant","t":"Pero llegué a dominar su influencia sobre mis pensamientos y acciones apartando la atención de ese sentimiento, como si no tuviera que ver conmigo.","o":"Aber über ihren Einfluß auf meine Gedanken und Handlungen bin ich Meister geworden durch Abkehrung der Aufmerksamkeit von diesem Gefühle, als ob es mich gar nicht anginge.","l":"de","ob":"El conflicto de las facultades","an":"1798","u":"Capítulo 1","te":["atencion","regulacion-emocional","salud-mental"]},{"i":"immanuel-kant-047","a":"immanuel-kant","t":"Uno se alegra más de la vida por lo que hace en el uso libre de ella que por lo que disfruta.","o":"da man des Lebens mehr froh wird durch das, was man im freien Gebrauch desselben thut, als was man genießt","l":"de","ob":"El conflicto de las facultades","an":"1798","u":"Capítulo 1","te":["sentido-de-vida","alegria","trabajo"]},{"i":"immanuel-kant-048","a":"immanuel-kant","t":"Para quien estudia, pensar es un alimento sin el cual, cuando está despierto y solo, no puede vivir.","o":"Einem Gelehrten ist das Denken ein Nahrungsmittel, ohne welches, wenn er wach und allein ist, er nicht leben kann","l":"de","ob":"El conflicto de las facultades","an":"1798","u":"Capítulo 1","te":["conocimiento","soledad"]},{"i":"immanuel-kant-049","a":"immanuel-kant","t":"Pensar con esfuerzo mientras se camina cansa enseguida; en cambio, si uno se entrega al libre juego de la imaginación, el movimiento repara.","o":"daß das angestrengte Denken im Gehen geschwinde matt macht; dagegen, wenn man sich dem freien Spiel der Einbildungskraft überläßt, die Motion restaurirend ist.","l":"de","ob":"El conflicto de las facultades","an":"1798","u":"Capítulo 1","te":["cuerpo","creatividad","habitos"]},{"i":"immanuel-kant-050","a":"immanuel-kant","t":"[El arte de cuidar la salud] es filosófico cuando el modo de vida lo determina solo el poder de la razón para dominar los sentimientos sensibles mediante un principio que uno mismo se da.","o":"Diese ist alsdann philosophisch, wenn bloß die Macht der Vernunft im Menschen, über seine sinnliche Gefühle durch einen sich selbst gegebenen Grundsatz Meister zu sein, die Lebensweise bestimmt.","l":"de","ob":"El conflicto de las facultades","an":"1798","u":"Capítulo 1","te":["habitos","regulacion-emocional","cuerpo"]},{"i":"hegel-001","a":"hegel","t":"Lo verdadero es el todo.","o":"Das Wahre ist das Ganze.","l":"de","ob":"Fenomenología del espíritu","an":"1807","u":"Capítulo 3","te":["verdad","conocimiento"]},{"i":"hegel-002","a":"hegel","t":"Lo conocido en general, precisamente por ser conocido, no es reconocido.","o":"Das Bekannte überhaupt ist darum, weil es bekannt ist, nicht erkannt.","l":"de","ob":"Fenomenología del espíritu","an":"1807","u":"Capítulo 4","te":["conocimiento","autoconocimiento"]},{"i":"hegel-003","a":"hegel","t":"El comienzo de un espíritu nuevo es el producto de una larga transformación de múltiples formas de cultura, el precio de un camino muy enrevesado y de mucho esfuerzo.","o":"Der Anfang des neuen Geistes ist das Produkt einer weitläufigen Umwälzung von mannigfaltigen Bildungsformen, der Preis eines vielfach verschlungnen Weges und ebenso vielfacher Anstrengung und Bemühung.","l":"de","ob":"Fenomenología del espíritu","an":"1807","u":"Capítulo 3","te":["cambio","transformacion-personal"]},{"i":"hegel-004","a":"hegel","t":"Del absoluto hay que decir que es esencialmente resultado: que solo al final es lo que es en verdad.","o":"Es ist von dem Absoluten zu sagen, daß es wesentlich Resultat , daß es erst am Ende das ist, was es in Wahrheit ist","l":"de","ob":"Fenomenología del espíritu","an":"1807","u":"Capítulo 3","te":["verdad","desarrollo-humano"]},{"i":"hegel-005","a":"hegel","t":"La meta es que el espíritu comprenda qué es el saber.","o":"Das Ziel ist die Einsicht des Geistes in das, was das Wissen ist.","l":"de","ob":"Fenomenología del espíritu","an":"1807","u":"Capítulo 4","te":["conocimiento"]},{"i":"hegel-006","a":"hegel","t":"La muerte, si queremos llamar así a esa irrealidad, es lo más terrible, y sostener lo muerto es lo que exige la mayor fuerza.","o":"Der Tod, wenn wir jene Unwirklichkeit so nennen wollen, ist das Furchtbarste, und das Tote festzuhalten das, was die größte Kraft erfodert.","l":"de","ob":"Fenomenología del espíritu","an":"1807","u":"Capítulo 4","te":["muerte","resiliencia"]},{"i":"hegel-007","a":"hegel","t":"No es la vida que se espanta ante la muerte y se preserva pura de la devastación, sino la que la soporta y se mantiene en ella, la vida del espíritu.","o":"Aber nicht das Leben, das sich vor dem Tode scheut und von der Verwüstung rein bewahrt, sondern das ihn erträgt und in ihm sich erhält, ist das Leben des Geistes.","l":"de","ob":"Fenomenología del espíritu","an":"1807","u":"Capítulo 4","te":["muerte","resiliencia","sufrimiento"]},{"i":"hegel-008","a":"hegel","t":"[El espíritu] solo conquista su verdad cuando se encuentra a sí mismo en el desgarramiento absoluto.","o":"Er gewinnt seine Wahrheit nur, indem er in der absoluten Zerrissenheit sich selbst findet.","l":"de","ob":"Fenomenología del espíritu","an":"1807","u":"Capítulo 4","te":["sufrimiento","identidad","transformacion-personal"]},{"i":"hegel-009","a":"hegel","t":"Lo que importa en el estudio de la ciencia es asumir el esfuerzo del concepto.","o":"Worauf es deswegen bei dem Studium der Wissenschaft ankommt, ist die Anstrengung des Begriffs auf sich zu nehmen.","l":"de","ob":"Fenomenología del espíritu","an":"1807","u":"Capítulo 7","te":["educacion","conocimiento"]},{"i":"hegel-010","a":"hegel","t":"De todas las ciencias, artes, habilidades y oficios se sabe que, para dominarlos, hace falta mucho esfuerzo de aprendizaje y práctica.","o":"Von allen Wissenschaften, Künsten, Geschicklichkeiten, Handwerken gilt die Überzeugung, daß, um sie zu besitzen, eine vielfache Bemühung des Erlernens und Übens derselben nötig ist.","l":"de","ob":"Fenomenología del espíritu","an":"1807","u":"Capítulo 8","te":["educacion","habitos","trabajo"]},{"i":"hegel-011","a":"hegel","t":"Los pensamientos verdaderos y la comprensión científica solo se ganan con el trabajo del concepto.","o":"Wahre Gedanken und wissenschaftliche Einsicht ist nur in der Arbeit des Begriffes zu gewinnen.","l":"de","ob":"Fenomenología del espíritu","an":"1807","u":"Capítulo 8","te":["conocimiento","trabajo"]},{"i":"hegel-012","a":"hegel","t":"La serie de figuras que la conciencia recorre en este camino es la historia detallada de la formación de la conciencia misma.","o":"Die Reihe seiner Gestaltungen, welche das Bewußtsein auf diesem Wege durchläuft, ist vielmehr die ausführliche Geschichte der Bildung des Bewußtseins selbst zur Wissenschaft.","l":"de","ob":"Fenomenología del espíritu","an":"1807","u":"Capítulo 9","te":["conciencia","desarrollo-humano"]},{"i":"hegel-013","a":"hegel","t":"El individuo particular es el espíritu incompleto.","o":"Das besondre Individuum aber ist der unvollständige Geist","l":"de","ob":"Fenomenología del espíritu","an":"1807","u":"Capítulo 4","te":["identidad"]},{"i":"hegel-014","a":"hegel","t":"La autoconciencia solo alcanza su satisfacción en otra autoconciencia.","o":"das Selbstbewußtsein erreicht seine Befriedigung nur in einem andern Selbstbewußtsein.","l":"de","ob":"Fenomenología del espíritu","an":"1807","u":"Capítulo 20","te":["vinculos","identidad","encuentro"]},{"i":"hegel-015","a":"hegel","t":"Un yo que es un nosotros, y un nosotros que es un yo.","o":"Ich, das Wir, und Wir, das Ich ist","l":"de","ob":"Fenomenología del espíritu","an":"1807","u":"Capítulo 20","te":["vinculos","identidad","sociedad"]},{"i":"hegel-016","a":"hegel","t":"La autoconciencia es en sí y para sí en cuanto y porque es en sí y para sí para otra; es decir, solo existe en cuanto reconocida.","o":"Das Selbstbewußtsein ist an und für sich , indem, und dadurch, daß es für ein Anderes an und für sich ist; d.h. es ist nur als ein Anerkanntes.","l":"de","ob":"Fenomenología del espíritu","an":"1807","u":"Capítulo 21","te":["vinculos","identidad","autoestima"]},{"i":"hegel-017","a":"hegel","t":"El trabajo, en cambio, es deseo refrenado, desaparición contenida: forma.","o":"Die Arbeit hingegen ist gehemmte Begierde, aufgehaltenes Verschwinden, oder sie bildet .","l":"de","ob":"Fenomenología del espíritu","an":"1807","u":"Capítulo 22","te":["trabajo","deseo","transformacion-personal"]},{"i":"hegel-018","a":"hegel","t":"Aunque el temor al amo sea el comienzo de la sabiduría…","o":"obzwar die Furcht des Herrn der Anfang der Weisheit ist","l":"de","ob":"Fenomenología del espíritu","an":"1807","u":"Capítulo 22","te":["miedo","poder"]},{"i":"hegel-019","a":"hegel","t":"Pero a través del trabajo [la conciencia] llega a sí misma.","o":"Durch die Arbeit kömmt es aber zu sich selbst.","l":"de","ob":"Fenomenología del espíritu","an":"1807","u":"Capítulo 22","te":["trabajo","identidad","libertad"]},{"i":"hegel-020","a":"hegel","t":"La conciencia desdichada es la conciencia de sí como un ser desdoblado, solo contradictorio.","o":"das unglückliche Bewußtsein ist das Bewußtsein seiner als des gedoppelten nur widersprechenden Wesens.","l":"de","ob":"Fenomenología del espíritu","an":"1807","u":"Capítulo 24","te":["sufrimiento","identidad","conciencia"]},{"i":"hegel-021","a":"hegel","t":"Las heridas del espíritu se curan sin dejar cicatrices.","o":"Die Wunden des Geistes heilen, ohne daß Narben bleiben","l":"de","ob":"Fenomenología del espíritu","an":"1807","u":"Capítulo 77","te":["resiliencia","esperanza","trauma"]},{"i":"hegel-022","a":"hegel","t":"No hay héroe para su ayuda de cámara; pero no porque aquel no sea un héroe, sino porque este es un ayuda de cámara.","o":"Es gibt keinen Helden für den Kammerdiener; nicht aber weil jener nicht ein Held, sondern weil dieser - der Kammerdiener ist","l":"de","ob":"Fenomenología del espíritu","an":"1807","u":"Capítulo 77","te":["identidad","vinculos"]},{"i":"hegel-023","a":"hegel","t":"La ciencia debe liberarse de esta apariencia, y solo puede hacerlo volviéndose contra ella.","o":"Die Wissenschaft muß sich aber von diesem Scheine befreien; und sie kann dies nur dadurch, daß sie sich gegen ihn wendet.","l":"de","ob":"Fenomenología del espíritu","an":"1807","u":"Capítulo 9","te":["verdad","conocimiento"]},{"i":"hegel-024","a":"hegel","t":"Porque es propio de la naturaleza humana buscar el acuerdo con otros y existir solo en la comunidad lograda de las conciencias.","o":"Denn die Natur dieser ist, auf die Übereinkunft mit andern zu dringen, und ihre Existenz nur in der zustande gebrachten Gemeinsamkeit der Bewußtsein.","l":"de","ob":"Fenomenología del espíritu","an":"1807","u":"Capítulo 8","te":["vinculos","comunicacion","sociedad"]},{"i":"hegel-025","a":"hegel","t":"La actividad de separar es la fuerza y el trabajo del entendimiento, el más asombroso y grande de los poderes, o más bien el poder absoluto.","o":"Die Tätigkeit des Scheidens ist die Kraft und Arbeit des Verstandes , der verwundersamsten und größten, oder vielmehr der absoluten Macht.","l":"de","ob":"Fenomenología del espíritu","an":"1807","u":"Capítulo 4","te":["conocimiento"]},{"i":"hegel-049","a":"hegel","t":"La Fenomenología del espíritu debe reemplazar a las explicaciones psicológicas y a las discusiones abstractas sobre el fundamento del saber.","o":"Die Phänomenologie des Geistes soll an die Stelle der psychologischen Erklärungen oder auch der abstraktem Erörterungen über die Begründung des Wissens treten.","l":"de","ob":"Fenomenología del espíritu","an":"1807","u":"Capítulo 1","te":["conocimiento","conciencia"]},{"i":"hegel-050","a":"hegel","t":"[La Fenomenología] comprende las distintas figuras del espíritu como estaciones de un camino.","o":"Sie faßt die verschiedenen Gestalten des Geistes als Stationen des Weges in sich","l":"de","ob":"Fenomenología del espíritu","an":"1807","u":"Capítulo 1","te":["desarrollo-humano","conciencia"]},{"i":"hegel-051","a":"hegel","t":"El saber tal como es al principio, el espíritu inmediato, es lo carente de espíritu: la conciencia sensible.","o":"Das Wissen, wie es zuerst ist, oder der unmittelbare Geist ist das Geistlose, oder ist das sinnliche Bewußtsein .","l":"de","ob":"Fenomenología del espíritu","an":"1807","u":"Capítulo 4","te":["conocimiento","cuerpo"]},{"i":"hegel-052","a":"hegel","t":"Esto [la palabra “Dios”] tomado por sí solo es un sonido sin sentido, un mero nombre.","o":"Dies für sich ist ein sinnloser Laut, ein bloßer Name","l":"de","ob":"Fenomenología del espíritu","an":"1807","u":"Capítulo 3","te":["comunicacion","trascendencia"]},{"i":"hegel-026","a":"hegel","t":"Nada grande se ha hecho en el mundo sin pasión.","o":"daß nichts Großes in der Welt ohne Leidenschaft vollbracht worden ist","l":"de","ob":"Lecciones sobre la filosofía de la historia","an":"1822–1831 (publ. 1837)","u":"Capítulo 1","te":["deseo","emociones","creatividad"]},{"i":"hegel-027","a":"hegel","t":"La historia universal es el progreso en la conciencia de la libertad.","o":"Die Weltgeschichte ist der Fortschritt im Bewußtsein der Freiheit","l":"de","ob":"Lecciones sobre la filosofía de la historia","an":"1822–1831 (publ. 1837)","u":"Capítulo 1","te":["libertad","sociedad"]},{"i":"hegel-028","a":"hegel","t":"Lo que enseñan la experiencia y la historia es que los pueblos y los gobiernos nunca aprendieron nada de la historia ni actuaron según las lecciones que podrían haber sacado de ella.","o":"Was die Erfahrung aber und die Geschichte lehren, ist dieses, daß Völker und Regierungen niemals etwas aus der Geschichte gelernt und nach Lehren, die aus derselben zu ziehen gewesen wären, gehandelt haben.","l":"de","ob":"Lecciones sobre la filosofía de la historia","an":"1822–1831 (publ. 1837)","u":"Capítulo 1","te":["sociedad","repeticion"]},{"i":"hegel-029","a":"hegel","t":"Cada época tiene circunstancias tan propias, es una situación tan singular…","o":"Jede Zeit hat so eigentümliche Umstände, ist ein so individueller Zustand","l":"de","ob":"Lecciones sobre la filosofía de la historia","an":"1822–1831 (publ. 1837)","u":"Capítulo 1","te":["cambio","tiempo"]},{"i":"hegel-030","a":"hegel","t":"La historia universal no es el terreno de la felicidad. Los períodos de felicidad son en ella hojas en blanco.","o":"Die Weltgeschichte ist nicht der Boden des Glücks. Die Perioden des Glücks sind leere Blätter in ihr","l":"de","ob":"Lecciones sobre la filosofía de la historia","an":"1822–1831 (publ. 1837)","u":"Capítulo 1","te":["felicidad","sociedad"]},{"i":"hegel-031","a":"hegel","t":"Feliz es quien adecuó su existencia a su carácter, a su querer y a su albedrío, y así se disfruta a sí mismo en su existencia.","o":"Glücklich ist derjenige, welcher sein Dasein seinem besonderen Charakter, Wollen und Willkür angemessen hat und so in seinem Dasein sich selbst genießt.","l":"de","ob":"Lecciones sobre la filosofía de la historia","an":"1822–1831 (publ. 1837)","u":"Capítulo 1","te":["felicidad","autenticidad"]},{"i":"hegel-032","a":"hegel","t":"A quien mira el mundo con razón, el mundo también lo mira con razón: ambas cosas se determinan mutuamente.","o":"wer die Welt vernünftig ansieht, den sieht sie auch vernünftig an, beides ist in Wechselbestimmung.","l":"de","ob":"Lecciones sobre la filosofía de la historia","an":"1822–1831 (publ. 1837)","u":"Capítulo 1","te":["conciencia","conocimiento"]},{"i":"hegel-033","a":"hegel","t":"Los discursos son acciones entre seres humanos, y acciones muy eficaces.","o":"Reden aber sind Handlungen unter Menschen und zwar sehr wesentlich wirksame Handlungen.","l":"de","ob":"Lecciones sobre la filosofía de la historia","an":"1822–1831 (publ. 1837)","u":"Capítulo 1","te":["comunicacion","vinculos"]},{"i":"hegel-034","a":"hegel","t":"Es cierto que la gente suele decir que “fueron solo palabras”, y quiere así mostrar su inocencia.","o":"Freilich sagen die Menschen oft, es seien nur Reden gewesen, und wollen insofern die Unschuld derselben dartun.","l":"de","ob":"Lecciones sobre la filosofía de la historia","an":"1822–1831 (publ. 1837)","u":"Capítulo 1","te":["comunicacion","responsabilidad"]},{"i":"hegel-035","a":"hegel","t":"Lo general es que la filosofía de la historia no significa otra cosa que su consideración pensante.","o":"Das Allgemeine ist jedoch, daß die Philosophie der Geschichte nichts andres als die denkende Betrachtung derselben bedeutet.","l":"de","ob":"Lecciones sobre la filosofía de la historia","an":"1822–1831 (publ. 1837)","u":"Capítulo 1","te":["conocimiento"]},{"i":"hegel-036","a":"hegel","t":"Explicar la historia significa revelar las pasiones de los seres humanos, su genio, sus fuerzas activas.","o":"Die Geschichte erklären aber heißt, die Leidenschaften des Menschen, ihr Genie, ihre wirkenden Kräfte enthüllen","l":"de","ob":"Lecciones sobre la filosofía de la historia","an":"1822–1831 (publ. 1837)","u":"Capítulo 1","te":["emociones","sociedad"]},{"i":"hegel-037","a":"hegel","t":"Así como la sustancia de la materia es la gravedad, debemos decir que la sustancia, la esencia del espíritu, es la libertad.","o":"Wie die Substanz der Materie die Schwere ist, so, müssen wir sagen, ist die Substanz, das Wesen des Geistes die Freiheit.","l":"de","ob":"Lecciones sobre la filosofía de la historia","an":"1822–1831 (publ. 1837)","u":"Capítulo 1","te":["libertad","identidad"]},{"i":"hegel-038","a":"hegel","t":"El espíritu, en cambio, es precisamente tener el centro en sí mismo.","o":"Der Geist im Gegenteil ist eben das, in sich den Mittelpunkt zu haben","l":"de","ob":"Lecciones sobre la filosofía de la historia","an":"1822–1831 (publ. 1837)","u":"Capítulo 1","te":["identidad","autenticidad"]},{"i":"hegel-039","a":"hegel","t":"Esto es la libertad: si dependo, me refiero a otro que no soy yo y no puedo ser sin algo exterior; soy libre cuando estoy en mí mismo.","o":"Dies eben ist die Freiheit, denn wenn ich abhängig bin, so beziehe ich mich auf ein andres, das ich nicht bin; ich kann nicht sein ohne ein Äußeres; frei bin ich, wenn ich bei mir selbst bin.","l":"de","ob":"Lecciones sobre la filosofía de la historia","an":"1822–1831 (publ. 1837)","u":"Capítulo 1","te":["libertad","autenticidad","vinculos"]},{"i":"hegel-040","a":"hegel","t":"Este estar en sí mismo del espíritu es autoconciencia, conciencia de sí.","o":"Dieses Beisichselbstsein des Geistes ist Selbstbewußtsein, das Bewußtsein von sich selbst.","l":"de","ob":"Lecciones sobre la filosofía de la historia","an":"1822–1831 (publ. 1837)","u":"Capítulo 1","te":["conciencia","autoconocimiento"]},{"i":"hegel-041","a":"hegel","t":"La actividad que realiza [las ideas] y les da existencia son las necesidades, los impulsos, las inclinaciones y las pasiones del ser humano.","o":"Die Tätigkeit, welche sie ins Werk und Dasein setzt, ist des Menschen Bedürfnis, Trieb, Neigung und Leidenschaft.","l":"de","ob":"Lecciones sobre la filosofía de la historia","an":"1822–1831 (publ. 1837)","u":"Capítulo 1","te":["deseo","emociones"]},{"i":"hegel-042","a":"hegel","t":"Para que las personas se interesen por algo, tienen que encontrarse a sí mismas en ello y ver satisfecho su propio sentimiento de sí.","o":"Wenn die Menschen sich für etwas interessieren sollen, so müssen sie sich selbst darin haben und ihr eignes Selbstgefühl darin befriedigt finden.","l":"de","ob":"Lecciones sobre la filosofía de la historia","an":"1822–1831 (publ. 1837)","u":"Capítulo 1","te":["sentido-de-vida","autoestima","deseo"]},{"i":"hegel-043","a":"hegel","t":"El único pensamiento que trae la filosofía es el simple pensamiento de que la razón gobierna el mundo.","o":"Der einzige Gedanke, den die Philosophie mitbringt, ist aber der einfache Gedanke der Vernunft, daß die Vernunft die Welt beherrsche","l":"de","ob":"Lecciones sobre la filosofía de la historia","an":"1822–1831 (publ. 1837)","u":"Capítulo 1","te":["conocimiento","verdad"]},{"i":"hegel-044","a":"hegel","t":"“No hay héroe para su ayuda de cámara” es un dicho conocido; yo le agregué [que no es porque aquel no sea un héroe, sino porque este es un ayuda de cámara].","o":"Für einen Kammerdiener gibt es keinen Helden, ist ein bekanntes Sprichwort; ich habe hinzugesetzt","l":"de","ob":"Lecciones sobre la filosofía de la historia","an":"1822–1831 (publ. 1837)","u":"Capítulo 1","te":["identidad"]},{"i":"hegel-045","a":"hegel","t":"El ser humano tiene que comer y beber, está en relación con amigos y conocidos, tiene sentimientos y arrebatos del momento.","o":"Der Mensch muß essen und trinken, steht in Beziehung zu Freunden und Bekannten, hat Empfindungen und Aufwallungen des Augenblicks.","l":"de","ob":"Lecciones sobre la filosofía de la historia","an":"1822–1831 (publ. 1837)","u":"Capítulo 1","te":["existencia","cuerpo","vinculos"]},{"i":"hegel-046","a":"hegel","t":"La materia tiene su sustancia fuera de sí; el espíritu es el estar en sí mismo.","o":"Die Materie hat ihre Substanz außer ihr; der Geist ist das Bei-sich-selbst-sein .","l":"de","ob":"Lecciones sobre la filosofía de la historia","an":"1822–1831 (publ. 1837)","u":"Capítulo 1","te":["identidad","conciencia"]},{"i":"hegel-047","a":"hegel","t":"Para la realidad hace falta un segundo momento: la puesta en práctica, la realización, cuyo principio es la voluntad, la actividad humana en general.","o":"Es muß ein zweites Moment für die Wirklichkeit hinzukommen, und dies ist die Betätigung, Verwirklichung, und deren Prinzip ist der Wille, die Tätigkeit des Menschen überhaupt.","l":"de","ob":"Lecciones sobre la filosofía de la historia","an":"1822–1831 (publ. 1837)","u":"Capítulo 1","te":["voluntad","responsabilidad"]},{"i":"hegel-048","a":"hegel","t":"En los griegos surgió por primera vez la conciencia de la libertad.","o":"In den Griechen ist erst das Bewußtsein der Freiheit aufgegangen","l":"de","ob":"Lecciones sobre la filosofía de la historia","an":"1822–1831 (publ. 1837)","u":"Capítulo 1","te":["libertad","cultura"]},{"i":"arthur-schopenhauer-001","a":"arthur-schopenhauer","t":"Para el bienestar de una persona, y para toda su manera de existir, lo principal es evidentemente lo que hay o sucede dentro de ella misma.","o":"Allerdings ist für das Wohlsein des Menschen, ja für die ganze Weise seines Daseins die Hauptsache offenbar das, was in ihm selbst besteht, oder vergeht.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 3","te":["felicidad","identidad"]},{"i":"arthur-schopenhauer-002","a":"arthur-schopenhauer","t":"Por eso la vida de cada persona, a pesar de todos los cambios exteriores, conserva siempre el mismo carácter: se parece a una serie de variaciones sobre un mismo tema.","o":"Demgemäß trägt das Leben jedes Menschen, trotz aller Abwechslung von außen, durchgängig denselben Charakter und ist einer Reihe Variationen auf ein Thema zu vergleichen.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 3","te":["identidad","repeticion"]},{"i":"arthur-schopenhauer-003","a":"arthur-schopenhauer","t":"La salud supera tanto a todos los bienes exteriores que, en verdad, un mendigo sano es más feliz que un rey enfermo.","o":"Besonders überwiegt die Gesundheit alle äußeren Güter so sehr, daß wahrlich ein gesunder Bettler glücklicher ist, als ein kranker König.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 3","te":["cuerpo","felicidad"]},{"i":"arthur-schopenhauer-004","a":"arthur-schopenhauer","t":"Un carácter bueno, moderado y apacible puede estar contento en circunstancias humildes, mientras que uno codicioso, envidioso y malo no lo está con toda su riqueza.","o":"Ein guter, gemäßigter, sanfter Charakter kann unter dürftigen Umständen zufrieden sein; während ein begehrlicher, neidischer und böser es bei allem Reichtum nicht ist.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 3","te":["felicidad","deseo"]},{"i":"arthur-schopenhauer-005","a":"arthur-schopenhauer","t":"De aquí se sigue que desde afuera se puede influir en una persona mucho menos de lo que se cree.","o":"Hieraus nun folgt, daß dem Menschen von außen viel weniger beizukommen ist, als man wohl meint.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 3","te":["identidad","resiliencia"]},{"i":"arthur-schopenhauer-006","a":"arthur-schopenhauer","t":"Lo que uno es para sí mismo, lo que lo acompaña en la soledad y nadie puede darle ni quitarle, es evidentemente más esencial que todo lo que pueda poseer o lo que pueda ser a los ojos de los demás.","o":"Denn was einer für sich selbst ist, was ihn in die Einsamkeit begleitet und was keiner ihm geben, oder nehmen kann, ist offenbar für ihn wesentlicher, als alles, was er besitzen, oder auch, was er in den Augen anderer sein mag.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 3","te":["identidad","soledad","autoestima"]},{"i":"arthur-schopenhauer-007","a":"arthur-schopenhauer","t":"Una persona de espíritu encuentra, en completa soledad, una compañía excelente en sus propios pensamientos y fantasías.","o":"Ein geistreicher Mensch hat in gänzlicher Einsamkeit, an seinen eigenen Gedanken und Phantasien vortreffliche Unterhaltung","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 3","te":["soledad","creatividad"]},{"i":"arthur-schopenhauer-008","a":"arthur-schopenhauer","t":"El mundo en que vive cada uno depende ante todo de la manera en que lo concibe.","o":"Die Welt, in der jeder lebt, hängt zunächst ab von seiner Auffassung derselben","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 3","te":["conciencia","identidad"]},{"i":"arthur-schopenhauer-009","a":"arthur-schopenhauer","t":"Así, lo que uno tiene en sí mismo es lo más esencial para la felicidad de su vida.","o":"Also, was einer an sich selber hat, ist zu seinem Lebensglücke das Wesentlichste.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 3","te":["felicidad","autoconocimiento"]},{"i":"arthur-schopenhauer-010","a":"arthur-schopenhauer","t":"El vacío interior, la insipidez de la conciencia y la pobreza de espíritu empujan a muchos a buscar compañía.","o":"Die Leere ihres Innern, das Fade ihres Bewußtseins, die Armut ihres Geistes treibt sie zur Gesellschaft","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 3","te":["soledad","vinculos"]},{"i":"arthur-schopenhauer-011","a":"arthur-schopenhauer","t":"Además, uno sigue siendo esclavo de la opinión y del parecer ajenos.","o":"Außerdem bleibt man der Sklave fremder Meinung und fremden Bedünkens.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 6","te":["autoestima","libertad"]},{"i":"arthur-schopenhauer-012","a":"arthur-schopenhauer","t":"Por eso, valorar con justeza lo que uno es en sí y para sí, frente a lo que es solo a los ojos de los demás, contribuirá mucho a nuestra felicidad.","o":"Demnach wird eine richtige Abschätzung des Wertes dessen, was man in und für sich selbst ist, gegen das, was man bloß in den Augen anderer ist, zu unserm Glücke viel beitragen.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 6","te":["autoestima","felicidad"]},{"i":"arthur-schopenhauer-013","a":"arthur-schopenhauer","t":"Comprenderemos entonces que quien le da mucho valor a la opinión de la gente le hace demasiado honor.","o":"Wir werden dann einsehen, daß wer auf die Meinung der Menschen einen großen Wert legt, ihnen zuviel Ehre erzeigt.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 6","te":["autoestima","libertad"]},{"i":"arthur-schopenhauer-014","a":"arthur-schopenhauer","t":"Todas nuestras preocupaciones, disgustos, rencillas, enojos, angustias y esfuerzos se refieren, quizás en la mayoría de los casos, a la opinión ajena.","o":"Unser aller Sorgen, Kümmern, Wurmen, Ärgern, Ängstigen, Anstrengen, usw. betrifft, in vielleicht den meisten Fällen, eigentlich die fremde Meinung","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 6","te":["angustia","autoestima"]},{"i":"arthur-schopenhauer-015","a":"arthur-schopenhauer","t":"No menos brotan de esa misma raíz [la opinión ajena] nuestra envidia y nuestro odio.","o":"Nicht weniger entspringt unser Neid und Haß größtenteils aus besagter Wurzel.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 6","te":["ira","autoestima"]},{"i":"arthur-schopenhauer-016","a":"arthur-schopenhauer","t":"El honor es, objetivamente, la opinión de los demás sobre nuestro valor y, subjetivamente, nuestro miedo a esa opinión.","o":"die Ehre ist, objektiv, die Meinung anderer von unserm Wert, und subjektiv, unsere Furcht vor dieser Meinung.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 6","te":["autoestima","miedo"]},{"i":"arthur-schopenhauer-017","a":"arthur-schopenhauer","t":"El ser humano solo puede muy poco y es un Robinson abandonado: únicamente en comunidad con los demás es y puede mucho.","o":"Der Mensch für sich allein vermag gar wenig und ist ein verlassener Robinson: nur in der Gemeinschaft mit den andern ist und vermag er viel.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 6","te":["vinculos","sociedad"]},{"i":"arthur-schopenhauer-018","a":"arthur-schopenhauer","t":"Debe tener una opinión muy débil de su propio valor quien se apura a sofocar cualquier comentario que lo ponga en duda.","o":"Der aber muß selbst eine schwache Meinung von seinem eigenen Werte haben, der sich beeilt, jeder denselben anfechtenden Äußerung den Daumen aufs Auge zu drücken","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 6","te":["autoestima","ira"]},{"i":"arthur-schopenhauer-019","a":"arthur-schopenhauer","t":"Nuestra vida es tan pobre que hay que administrar sus bienes con más economía.","o":"Unser Leben ist so arm, daß seine Güter haushälterischer verteilt werden müssen.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 6","te":["existencia"]},{"i":"arthur-schopenhauer-020","a":"arthur-schopenhauer","t":"Los dolores, en cambio, se sienten de manera positiva: por eso su ausencia es la medida de la felicidad de una vida.","o":"Die Schmerzen hingegen werden positiv empfunden: daher ist ihre Abwesenheit der Maßstab des Lebensglückes.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["sufrimiento","felicidad"]},{"i":"arthur-schopenhauer-021","a":"arthur-schopenhauer","t":"Si a un estado sin dolor se suma la ausencia de aburrimiento, la felicidad terrenal está, en lo esencial, alcanzada.","o":"Kommt zu einem schmerzlosen Zustand noch die Abwesenheit der Langenweile; so ist das irdische Glück im wesentlichen erreicht","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["felicidad","sufrimiento"]},{"i":"arthur-schopenhauer-022","a":"arthur-schopenhauer","t":"El necio corre tras los placeres de la vida y se ve engañado; el sabio evita los males.","o":"Der Tor läuft den Genüssen des Lebens nach und sieht sich betrogen: der Weise vermeidet die Übel.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["felicidad","deseo"]},{"i":"arthur-schopenhauer-023","a":"arthur-schopenhauer","t":"Llegamos al mundo llenos de pretensiones de felicidad y placer, y alimentamos la esperanza tonta de conseguirlos.","o":"wir treten in die Welt voll Ansprüche auf Glück und Genuß und hegen die törichte Hoffnung, solche durchzusetzen.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["felicidad","esperanza","deseo"]},{"i":"arthur-schopenhauer-024","a":"arthur-schopenhauer","t":"La compañía verdaderamente buena es, en todas partes y necesariamente, muy reducida.","o":"Die wirklich gute Gesellschaft nämlich ist, überall und notwendig, sehr klein.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["amistad","vinculos"]},{"i":"arthur-schopenhauer-025","a":"arthur-schopenhauer","t":"En general, una de las mayores y más frecuentes tonterías es hacer grandes preparativos para vivir.","o":"Überhaupt ist es eine der größten und häufigsten Torheiten, daß man weitläufige Anstalten zum Leben macht","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["tiempo","presencia"]},{"i":"arthur-schopenhauer-026","a":"arthur-schopenhauer","t":"Muchos viven demasiado en el presente: los imprudentes.","o":"Viele leben zu sehr in der Gegenwart; die Leichtsinnigen.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["presencia","tiempo"]},{"i":"arthur-schopenhauer-027","a":"arthur-schopenhauer","t":"Otros, demasiado en el futuro: los ansiosos y preocupados.","o":"Andere zu sehr in der Zukunft: die Ängstlichen und Besorglichen.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["angustia","tiempo"]},{"i":"arthur-schopenhauer-028","a":"arthur-schopenhauer","t":"Solo el presente es verdadero y real: es el tiempo efectivamente lleno, y únicamente en él está nuestra existencia.","o":"Die Gegenwart allein ist wahr und wirklich: sie ist die real erfüllte Zeit, und ausschließlich in ihr liegt unser Dasein.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["presencia","tiempo"]},{"i":"arthur-schopenhauer-029","a":"arthur-schopenhauer","t":"Cada uno huirá de la soledad, la soportará o la amará en proporción exacta al valor de su propio yo.","o":"Demgemäß wird jeder in genauer Proportion zum Werte seines eigenen Selbst die Einsamkeit fliehen, ertragen, oder lieben.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["soledad","identidad"]},{"i":"arthur-schopenhauer-030","a":"arthur-schopenhauer","t":"Cada uno puede ser enteramente él mismo solo mientras está solo: quien no ama la soledad tampoco ama la libertad, porque solo cuando uno está solo es libre.","o":"Ganz er selbst sein darf jeder nur so lange er allein ist: wer also nicht die Einsamkeit liebt, der liebt auch nicht die Freiheit: denn nur wenn man allein ist, ist man frei","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["soledad","libertad","autenticidad"]},{"i":"arthur-schopenhauer-031","a":"arthur-schopenhauer","t":"En esa clase de compañía tenemos que renunciar, con penosa negación de nosotros mismos, a tres cuartas partes de lo que somos para parecernos a los demás.","o":"In solcher Gesellschaft müssen wir daher mit schwerer Selbstverleugnung dreiviertel unserer selbst aufgeben, um uns den andern zu verähnlichen.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["autenticidad","vinculos"]},{"i":"arthur-schopenhauer-032","a":"arthur-schopenhauer","t":"El vacío interior y el hastío son los que empujan a muchos a la vida social, al extranjero y a los viajes.","o":"Innere Leere und Überdruß sind es, von denen sie sowohl in die Gesellschaft, wie in die Fremde und auf Reisen getrieben werden.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["soledad","deseo"]},{"i":"arthur-schopenhauer-033","a":"arthur-schopenhauer","t":"Quien se hace amigo de la soledad a tiempo, y hasta llega a quererla, ha conseguido una mina de oro.","o":"Sonach hat, wer sich zeitig mit der Einsamkeit befreundet, ja, sie lieb gewinnt, eine Goldmine erworben.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["soledad","felicidad"]},{"i":"arthur-schopenhauer-034","a":"arthur-schopenhauer","t":"Así como al principio la necesidad, una vez resuelta esta es el aburrimiento lo que junta a las personas.","o":"Denn wie ursprünglich die Not, so treibt, nach Beseitigung dieser, die Langeweile die Menschen zusammen.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["vinculos","soledad"]},{"i":"arthur-schopenhauer-035","a":"arthur-schopenhauer","t":"La envidia es natural en el ser humano; sin embargo, es a la vez un vicio y una desdicha.","o":"Neid ist dem Menschen natürlich: dennoch ist er ein Laster und Unglück zugleich.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["emociones","sufrimiento"]},{"i":"arthur-schopenhauer-036","a":"arthur-schopenhauer","t":"La envidia de las personas muestra cuán desdichadas se sienten; su atención constante a lo que hacen los demás, cuánto se aburren.","o":"Der Neid der Menschen zeigt an, wie unglücklich sie sich fühlen; ihre beständige Aufmerksamkeit auf fremdes Tun und Lassen, wie sehr sie sich langweilen.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["emociones","felicidad"]},{"i":"arthur-schopenhauer-037","a":"arthur-schopenhauer","t":"En general, la salud, el sueño, la alimentación, la temperatura, el clima, el entorno y muchas otras cosas exteriores influyen poderosamente en nuestro ánimo, y este en nuestros pensamientos.","o":"Überhaupt aber hat Gesundheitszustand, Schlaf, Nahrung, Temperatur, Wetter, Umgebung und noch viel anderes Äußerliches auf unsere Stimmung, und diese auf unsere Gedanken einen mächtigen Einfluß.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["cuerpo","emociones","habitos"]},{"i":"arthur-schopenhauer-038","a":"arthur-schopenhauer","t":"Cada día es una pequeña vida: cada despertar y levantarse, un pequeño nacimiento; cada mañana fresca, una pequeña juventud; y cada acostarse y dormirse, una pequeña muerte.","o":"Jeder Tag ist ein kleines Leben - jedes Erwachen und Aufstehen eine kleine Geburt, jeder frische Morgen eine kleine Jugend, und jedes Zubettgehen und Einschlafen ein kleiner Tod.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["tiempo","presencia","habitos"]},{"i":"arthur-schopenhauer-039","a":"arthur-schopenhauer","t":"Nuestra existencia es esencialmente inquieta: por eso la inactividad total se nos vuelve pronto insoportable.","o":"Unser Dasein nämlich ist ein wesentlich restloses: daher wird die gänzliche Untätigkeit uns bald unerträglich","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["trabajo","existencia"]},{"i":"arthur-schopenhauer-040","a":"arthur-schopenhauer","t":"Esforzarse y luchar contra la resistencia es para el ser humano una necesidad, como cavar lo es para el topo.","o":"Sich zu mühen und mit dem Widerstände zu kämpfen ist dem Menschen Bedürfnis, wie dem Maulwurf das Graben.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["trabajo","resiliencia"]},{"i":"arthur-schopenhauer-041","a":"arthur-schopenhauer","t":"La riqueza se parece al agua de mar: cuanto más se bebe, más sed da. Lo mismo vale para la fama.","o":"Der Reichtum gleicht dem Seewasser: je mehr man davon trinkt, desto durstiger wird man. - Dasselbe gilt vom Ruhm.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 5","te":["deseo","felicidad"]},{"i":"arthur-schopenhauer-042","a":"arthur-schopenhauer","t":"Lo que la gente suele llamar destino no son, en su mayoría, más que sus propias tonterías.","o":"Was aber die Leute gemeiniglich das Schicksal nennen sind meistens nur ihre eigenen dummen Streiche.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["responsabilidad"]},{"i":"arthur-schopenhauer-043","a":"arthur-schopenhauer","t":"Salvo raras excepciones, en el mundo solo se puede elegir entre la soledad y la vulgaridad.","o":"daß es, seltene Ausnahmen abgerechnet, in der Welt nur die Wahl gibt zwischen Einsamkeit und Gemeinheit.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["soledad"]},{"i":"arthur-schopenhauer-044","a":"arthur-schopenhauer","t":"Claro que eso implica infligirse el gran dolor del descontento con uno mismo; pero nadie se educa sin pasar por algún castigo.","o":"Freilich hat man sich dabei den großen Schmerz der Unzufriedenheit mit sich selbst anzutun: aber der Mensch wird nicht erzogen, ohne daß er gestraft wird.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["educacion","culpa"]},{"i":"arthur-schopenhauer-045","a":"arthur-schopenhauer","t":"La mitad objetiva del presente y de la realidad está en manos del destino y es, por tanto, variable; la mitad subjetiva somos nosotros mismos.","o":"Die objektive Hälfte der Gegenwart und Wirklichkeit steht in der Hand des Schicksals und ist demnach veränderlich: die subjektive sind wir selbst","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 3","te":["responsabilidad","identidad"]},{"i":"arthur-schopenhauer-046","a":"arthur-schopenhauer","t":"Para no perder la tranquilidad de la vida por males inciertos o indeterminados [conviene mirarlos como si nunca fueran a llegar].","o":"Um also nicht der Ruhe unseres Lebens durch ungewisse, oder unbestimmte Übel verlustig zu werden","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["angustia","incertidumbre"]},{"i":"arthur-schopenhauer-047","a":"arthur-schopenhauer","t":"Toda compañía exige necesariamente una adaptación mutua y una moderación; por eso, cuanto más grande, más insípida.","o":"Zunächst erfordert jede Gesellschaft notwendig eine gegenseitige Accommodation und Temperatur; daher wird sie, je größer, desto fader.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["vinculos","sociedad"]},{"i":"arthur-schopenhauer-048","a":"arthur-schopenhauer","t":"A menudo, donde buscábamos placer, dicha y alegría, recibimos en cambio enseñanza, comprensión y conocimiento.","o":"Zumal wird uns oft da, wo wir, Genuß, Glück, Freude suchten, statt ihrer Belehrung, Einsicht, Erkenntnis","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["conocimiento","transformacion-personal"]},{"i":"arthur-schopenhauer-049","a":"arthur-schopenhauer","t":"Es un consuelo de la vejez tener ya detrás el trabajo de la vida.","o":"Ja es ist ein Trost im Alter, daß man die Arbeit des Lebens hinter sich hat.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["desarrollo-humano","trabajo"]},{"i":"arthur-schopenhauer-050","a":"arthur-schopenhauer","t":"Es curioso que el ser humano tenga un cierto respeto innato, realmente instintivo, por las canas.","o":"Merkwürdig aber ist es, daß dem Menschen ein gewisser Respekt vor weißen Haaren angeboren und daher wirklich instinktiv ist.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 6","te":["desarrollo-humano"]},{"i":"arthur-schopenhauer-051","a":"arthur-schopenhauer","t":"Para alcanzar la dicha de la paz del espíritu, los cínicos renunciaban a toda posesión; quien con el mismo fin renuncia a la vida social eligió el medio más sabio.","o":"Um des Glückes der Geistesruhe teilhaftig zu werden, entsagen die Zyniker jedem Besitze: wer in gleicher Absicht der Gesellschaft entsagt, hat das weiseste Mittel erwählt.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["soledad","silencio"]},{"i":"soren-kierkegaard-001","a":"soren-kierkegaard","t":"El ser humano es espíritu. Pero ¿qué es el espíritu? El espíritu es el yo. Pero ¿qué es el yo? El yo es una relación que se relaciona consigo misma.","o":"Mennesket er Aand. Men hvad er Aand? Aand er Selvet. Men hvad er Selvet? Selvet er et Forhold, der forholder sig til sig selv","l":"da","ob":"La enfermedad mortal","an":"1849","u":"","te":["identidad","autoconocimiento"]},{"i":"soren-kierkegaard-002","a":"soren-kierkegaard","t":"El ser humano es una síntesis de infinitud y finitud, de lo temporal y lo eterno, de libertad y necesidad; en suma, una síntesis.","o":"Mennesket er en Synthese af Uendelighed og Endelighed, af det Timelige og det Evige, af Frihed og Nødvendighed, kort en Synthese.","l":"da","ob":"La enfermedad mortal","an":"1849","u":"","te":["identidad","existencia","libertad"]},{"i":"soren-kierkegaard-003","a":"soren-kierkegaard","t":"La desesperación es una enfermedad del espíritu, del yo, y puede ser triple: desesperar sin tener conciencia de tener un yo; desesperar no queriendo ser uno mismo; desesperar queriendo ser uno mismo.","o":"Fortvivlelse er en Sygdom i Aanden, i Selvet, og kan saaledes være et Tredobbelt: fortvivlet ikke at være sig bevidst at have et Selv; fortvivlet ikke at ville være sig selv; fortvivlet at ville være sig selv","l":"da","ob":"La enfermedad mortal","an":"1849","u":"","te":["sufrimiento","identidad","autenticidad"]},{"i":"soren-kierkegaard-004","a":"soren-kierkegaard","t":"Atreverse por completo a ser uno mismo, un individuo, este individuo determinado.","o":"at vove ganske at blive sig selv, et enkelt Menneske, dette bestemte enkelte Menneske","l":"da","ob":"La enfermedad mortal","an":"1849","u":"","te":["autenticidad","identidad","libertad"]},{"i":"soren-kierkegaard-005","a":"soren-kierkegaard","t":"Así es como una persona siempre encuentra valor: cuando teme un peligro mayor, siempre tiene valor para afrontar uno menor.","o":"Paa den Maade faaer et Menneske altid Mod; naar man frygter en større Fare, har et Menneske altid Mod til at gaae i en mindre","l":"da","ob":"La enfermedad mortal","an":"1849","u":"","te":["miedo","resiliencia"]},{"i":"soren-kierkegaard-006","a":"soren-kierkegaard","t":"La posibilidad de esta enfermedad [la desesperación] es la ventaja del ser humano sobre el animal.","o":"Muligheden af denne Sygdom er Menneskets Fortrin for Dyret","l":"da","ob":"La enfermedad mortal","an":"1849","u":"","te":["existencia","conciencia"]},{"i":"soren-kierkegaard-007","a":"soren-kierkegaard","t":"La desesperación es el desequilibrio en la relación de una síntesis que se relaciona consigo misma.","o":"Fortvivlelse er Misforholdet i en Syntheses Forhold, som forholder sig til sig selv.","l":"da","ob":"La enfermedad mortal","an":"1849","u":"","te":["sufrimiento","identidad"]},{"i":"soren-kierkegaard-008","a":"soren-kierkegaard","t":"Y nadie puede deshacerse de la relación consigo mismo, como tampoco de su propio yo.","o":"Og Forholdet til sig selv kan et Menneske ikke blive af med, saa lidet som med sit Selv","l":"da","ob":"La enfermedad mortal","an":"1849","u":"","te":["identidad","autoconocimiento"]},{"i":"soren-kierkegaard-009","a":"soren-kierkegaard","t":"La desesperación es justamente un consumirse a sí mismo, pero un consumirse impotente, que no logra lo que quiere.","o":"Dog er Fortvivlelse just en Selvfortærelse, men en afmægtig Selvfortærelse, der ikke formaaer hvad den selv vil.","l":"da","ob":"La enfermedad mortal","an":"1849","u":"","te":["sufrimiento","angustia"]},{"i":"soren-kierkegaard-010","a":"soren-kierkegaard","t":"Pero en la posibilidad todo es posible.","o":"Dog i Muligheden er Alt muligt.","l":"da","ob":"La enfermedad mortal","an":"1849","u":"","te":["incertidumbre","esperanza"]},{"i":"soren-kierkegaard-011","a":"soren-kierkegaard","t":"En lugar de traer la posibilidad de vuelta a la necesidad, corre tras la posibilidad, y al final no puede encontrar el camino de regreso a sí mismo.","o":"Istedetfor at tage Muligheden tilbage i Nødvendigheden, løber han efter Muligheden - og tilsidst kan han ikke finde tilbage til sig selv.","l":"da","ob":"La enfermedad mortal","an":"1849","u":"","te":["deseo","identidad","angustia"]},{"i":"soren-kierkegaard-012","a":"soren-kierkegaard","t":"La angustia puede compararse con el vértigo. Quien mira hacia abajo, a un abismo que se abre, siente vértigo.","o":"Angest kan man sammenligne med Svimmelhed. Den, hvis Øie kommer til at skue ned i et svælgende Dyb, han bliver svimmel.","l":"da","ob":"El concepto de la angustia","an":"1844","u":"","te":["angustia","libertad"]},{"i":"soren-kierkegaard-013","a":"soren-kierkegaard","t":"La angustia es una antipatía simpática y una simpatía antipática.","o":"Angest er en sympathetisk Antipathie og en antipathetisk Sympathie.","l":"da","ob":"El concepto de la angustia","an":"1844","u":"","te":["angustia","deseo"]},{"i":"soren-kierkegaard-014","a":"soren-kierkegaard","t":"Este es el profundo secreto de la inocencia: que al mismo tiempo es angustia.","o":"Dette er Uskyldighedens dybe Hemmelighed, at den paa samme Tid er Angest.","l":"da","ob":"El concepto de la angustia","an":"1844","u":"","te":["angustia","infancia"]},{"i":"soren-kierkegaard-015","a":"soren-kierkegaard","t":"La angustia es una determinación del espíritu que sueña, y como tal pertenece a la psicología.","o":"Angest er en Bestemmelse af den drømmende Aand, og hører som saadan hjemme i Psychologien.","l":"da","ob":"El concepto de la angustia","an":"1844","u":"","te":["angustia","conciencia"]},{"i":"soren-kierkegaard-016","a":"soren-kierkegaard","t":"Por eso no se encontrará angustia en el animal: justamente porque, en su naturalidad, no está determinado como espíritu.","o":"Man vil derfor ikke finde Angest hos Dyret , netop fordi det i sin Naturlighed ikke er bestemmet som Aand.","l":"da","ob":"El concepto de la angustia","an":"1844","u":"","te":["angustia","existencia"]},{"i":"soren-kierkegaard-017","a":"soren-kierkegaard","t":"Cuanto menos espíritu, menos angustia.","o":"jo mindre Aand jo mindre Angest","l":"da","ob":"El concepto de la angustia","an":"1844","u":"","te":["angustia","conciencia"]},{"i":"soren-kierkegaard-018","a":"soren-kierkegaard","t":"Si se observa a los niños, se encontrará esta angustia indicada con más claridad como búsqueda de lo aventurero, lo monstruoso, lo enigmático.","o":"Naar man vil iagttage Børn, vil man finde denne Angest bestemtere antydet som en Søgen efter det Eventyrlige, det Uhyre, det Gaadefulde.","l":"da","ob":"El concepto de la angustia","an":"1844","u":"","te":["infancia","angustia","creatividad"]},{"i":"soren-kierkegaard-019","a":"soren-kierkegaard","t":"Esta angustia pertenece tan esencialmente al niño que no quiere prescindir de ella: aunque lo angustie, lo cautiva con su dulce zozobra.","o":"Denne Angest hører Barnet saa væsentligen til, at han ikke vil undvære den; om den end ængster ham, fængsler den ham dog i sin søde Beængstelse.","l":"da","ob":"El concepto de la angustia","an":"1844","u":"","te":["infancia","angustia"]},{"i":"soren-kierkegaard-020","a":"soren-kierkegaard","t":"La prohibición lo angustia porque despierta en él la posibilidad de la libertad.","o":"Forbudet ængster ham, fordi Forbudet vækker Frihedens Mulighed i ham.","l":"da","ob":"El concepto de la angustia","an":"1844","u":"","te":["angustia","libertad"]},{"i":"soren-kierkegaard-021","a":"soren-kierkegaard","t":"La angustiante posibilidad de poder.","o":"den ængstende Mulighed af at kunne","l":"da","ob":"El concepto de la angustia","an":"1844","u":"","te":["angustia","libertad"]},{"i":"soren-kierkegaard-022","a":"soren-kierkegaard","t":"¿Qué es un poeta? Una persona desdichada que oculta en su corazón tormentos profundos, pero cuyos labios están hechos de tal modo que, cuando el suspiro y el grito pasan por ellos, suenan como una música hermosa.","o":"Hvad er en Digter? Et ulykkeligt Menneske, der gjemmer dybe Qvaler i sit Hjerte, men hvis Læber ere dannede saaledes, at idet Sukket og Skriget strømme ud over dem, lyde de som en skjøn Musik.","l":"da","ob":"O lo uno o lo otro, primera parte","an":"1843","u":"","te":["creatividad","sufrimiento"]},{"i":"soren-kierkegaard-023","a":"soren-kierkegaard","t":"Casate y te arrepentirás; no te cases y también te arrepentirás.","o":"Gift Dig, Du vil fortryde det; gift Dig ikke, Du vil ogsaa fortryde det","l":"da","ob":"O lo uno o lo otro, primera parte","an":"1843","u":"","te":["incertidumbre","humor","libertad"]},{"i":"soren-kierkegaard-024","a":"soren-kierkegaard","t":"Además de mi numeroso círculo de amistades, tengo todavía un confidente íntimo: mi melancolía.","o":"Foruden min øvrige talrige Omgangskreds har jeg endnu een intim Fortrolig - mit Tungsind","l":"da","ob":"O lo uno o lo otro, primera parte","an":"1843","u":"","te":["tristeza","soledad"]},{"i":"soren-kierkegaard-025","a":"soren-kierkegaard","t":"Mi melancolía es la amante más fiel que he conocido; ¿qué tiene de extraño que yo la ame también?","o":"Mit Tungsind er den trofasteste Elskerinde, jeg har kjendt, hvad Under da, at jeg elsker igjen.","l":"da","ob":"O lo uno o lo otro, primera parte","an":"1843","u":"","te":["tristeza"]},{"i":"soren-kierkegaard-026","a":"soren-kierkegaard","t":"¡Qué espantoso es el aburrimiento, espantosamente aburrido!","o":"Hvor er dog Kjedsommelighed rædsom - rædsom kjedsommelig","l":"da","ob":"O lo uno o lo otro, primera parte","an":"1843","u":"","te":["existencia","humor"]},{"i":"soren-kierkegaard-027","a":"soren-kierkegaard","t":"El aburrimiento descansa sobre la nada que serpentea a través de la existencia.","o":"Kjedsommelighed hviler paa det Intet, der slynger sig gjennem Tilværelsen","l":"da","ob":"O lo uno o lo otro, primera parte","an":"1843","u":"","te":["existencia","angustia"]},{"i":"soren-kierkegaard-028","a":"soren-kierkegaard","t":"Quizás vos mismo guardaste un secreto que, en su alegría o en su dolor, sentías demasiado querido como para compartirlo con otros.","o":"Du har maaskee selv gjemt en Hemmelighed, om hvilken Du følte, at den, i sin Glæde eller i sin Smerte, var Dig for kjær til, at Du kunde indvie Andre i den.","l":"da","ob":"O lo uno o lo otro, primera parte","an":"1843","u":"","te":["silencio","vinculos","identidad"]},{"i":"soren-kierkegaard-029","a":"soren-kierkegaard","t":"[Mi duda acerca de] que lo exterior sea lo interior.","o":"at det Udvortes ikke er det Indvortes","l":"da","ob":"O lo uno o lo otro, primera parte","an":"1843","u":"","te":["identidad","autenticidad"]},{"i":"soren-kierkegaard-030","a":"soren-kierkegaard","t":"¡Ay, el deseo es muy elocuente, y los buenos propósitos siempre están a mano!","o":"Ak, Lysten er meget veltalende, og de gode Forsætter ere altid ved Haanden.","l":"da","ob":"O lo uno o lo otro, primera parte","an":"1843","u":"","te":["deseo","humor"]},{"i":"soren-kierkegaard-031","a":"soren-kierkegaard","t":"Y el yo se elige a sí mismo, o mejor dicho, se recibe a sí mismo.","o":"og Jeget vælger sig selv, eller rettere, det modtager sig selv.","l":"da","ob":"O lo uno o lo otro, segunda parte","an":"1843","u":"","te":["identidad","libertad"]},{"i":"soren-kierkegaard-032","a":"soren-kierkegaard","t":"Pero como se elige a sí mismo, al elegirse no se vuelve otro ser: se vuelve sí mismo.","o":"men da han dog vælger sig selv, og ikke ved at vælge sig selv bliver et andet Væsen, men bliver sig selv","l":"da","ob":"O lo uno o lo otro, segunda parte","an":"1843","u":"","te":["identidad","autenticidad","transformacion-personal"]},{"i":"soren-kierkegaard-033","a":"soren-kierkegaard","t":"¿O no es la melancolía el mal de nuestro tiempo?","o":"Eller er Tungsind ikke Tidens Brøst","l":"da","ob":"O lo uno o lo otro, segunda parte","an":"1843","u":"","te":["tristeza","sociedad"]},{"i":"soren-kierkegaard-052","a":"soren-kierkegaard","t":"Si supiera dónde vive un caballero de la fe así, iría a pie a buscarlo.","o":"Vidste jeg derimod, hvor der levede en saadan Troens Ridder, da vilde jeg paa min Fod vandre til ham","l":"da","ob":"Temor y temblor","an":"1843","u":"","te":["trascendencia","esperanza"]},{"i":"soren-kierkegaard-034","a":"soren-kierkegaard","t":"La repetición y el recuerdo son el mismo movimiento, solo que en sentido opuesto: lo que se recuerda ha sido, se repite hacia atrás; la verdadera repetición, en cambio, se recuerda hacia adelante.","o":"Gjentagelse og Erindring er den samme Bevægelse, kun i modsat Retning; thi hvad der erindres, har været, gjentages baglænds; hvorimod den egentlige Gjentagelse erindres forlænds.","l":"da","ob":"La repetición","an":"1843","u":"","te":["repeticion","memoria","tiempo"]},{"i":"soren-kierkegaard-035","a":"soren-kierkegaard","t":"La esperanza es un traje nuevo, rígido, ajustado y reluciente, pero nunca se lo ha usado, y por eso no se sabe cómo le quedará a uno ni cómo calza.","o":"Haabet er en ny Klædning, stiv og stram og glimrende, dog har man aldrig havt den paa, og veed derfor ikke, hvorledes den vil klæde En, eller hvorledes den sidder.","l":"da","ob":"La repetición","an":"1843","u":"","te":["esperanza","tiempo"]},{"i":"soren-kierkegaard-036","a":"soren-kierkegaard","t":"El recuerdo es un traje desechado que, por hermoso que sea, ya no queda bien, porque uno lo dejó atrás al crecer.","o":"Erindringen er en aflagt Klædning, som, hvor skjøn den end er, dog ikke passer, da man er voxet fra den.","l":"da","ob":"La repetición","an":"1843","u":"","te":["memoria","cambio"]},{"i":"soren-kierkegaard-037","a":"soren-kierkegaard","t":"La repetición es un traje que no se gasta, que se ajusta firme y tierno, sin apretar ni flamear.","o":"Gjentagelsen er en uopslidelig Klædning, der slutter fast og ømt, hverken trykker eller flagrer.","l":"da","ob":"La repetición","an":"1843","u":"","te":["repeticion","habitos","presencia"]},{"i":"soren-kierkegaard-038","a":"soren-kierkegaard","t":"Hace falta juventud para esperar, juventud para recordar, pero hace falta valor para querer la repetición.","o":"Der hører Ungdom til at haabe, Ungdom til at erindre, men der hører Mod til at ville Gjentagelsen.","l":"da","ob":"La repetición","an":"1843","u":"","te":["repeticion","esperanza","resiliencia"]},{"i":"soren-kierkegaard-039","a":"soren-kierkegaard","t":"Quien solo quiere esperar es cobarde; quien solo quiere recordar es voluptuoso; pero quien quiere la repetición es un hombre.","o":"Den, der blot vil haabe, han er feig; den, der blot vil erindre, han er vellystig; men den, der vil Gjentagelsen, han er en Mand","l":"da","ob":"La repetición","an":"1843","u":"","te":["repeticion","esperanza","memoria"]},{"i":"soren-kierkegaard-040","a":"soren-kierkegaard","t":"Quien eligió la repetición, ese vive.","o":"den, der valgte Gjentagelsen, han lever.","l":"da","ob":"La repetición","an":"1843","u":"","te":["repeticion","sentido-de-vida"]},{"i":"soren-kierkegaard-041","a":"soren-kierkegaard","t":"Si no hubiera repetición, ¿qué sería la vida?","o":"Ja hvis der ingen Gjentagelse var, hvad var ogsaa Livet?","l":"da","ob":"La repetición","an":"1843","u":"","te":["repeticion","existencia"]},{"i":"soren-kierkegaard-042","a":"soren-kierkegaard","t":"Así como los griegos enseñaban que todo conocer es recordar, la nueva filosofía enseñará que toda la vida es una repetición.","o":"Som da disse lærte, at al Erkjenden er en Erindren, saaledes vil den nye Philosophi lære, at hele Livet er en Gjentagelse.","l":"da","ob":"La repetición","an":"1843","u":"","te":["repeticion","conocimiento"]},{"i":"soren-kierkegaard-043","a":"soren-kierkegaard","t":"Engañarse a uno mismo privándose del amor es lo más terrible: una pérdida eterna para la que no hay compensación ni en el tiempo ni en la eternidad.","o":"At bedrage sig selv for Kjerlighed er det forfærdeligste, er et evigt Tab, for hvilket der ingen Erstatning er hverken i Tid eller i Evighed.","l":"da","ob":"Las obras del amor","an":"1847","u":"","te":["amor","perdida"]},{"i":"soren-kierkegaard-044","a":"soren-kierkegaard","t":"¿Qué une lo temporal y la eternidad sino el amor, que por eso mismo está antes de todo y permanece cuando todo ha pasado?","o":"Hvad er det nemlig, der forbinder det Timelige og Evigheden, hvad er det Andet end Kjerlighed, som just derfor er før Alt, og bliver naar Alt er forbi.","l":"da","ob":"Las obras del amor","an":"1847","u":"","te":["amor","trascendencia"]},{"i":"soren-kierkegaard-045","a":"soren-kierkegaard","t":"Toda la vida de uno debe ser tiempo de esperanza.","o":"hele Ens Liv skal være Haabets Tid","l":"da","ob":"Las obras del amor","an":"1847","u":"","te":["esperanza","sentido-de-vida"]},{"i":"soren-kierkegaard-046","a":"soren-kierkegaard","t":"[El mandamiento] no quiere enseñarle a nadie que no debe amarse a sí mismo, sino, al contrario, enseñarle el verdadero amor propio.","o":"der dog ikke vil lære et Menneske, at han ikke skal elske sig selv, men tvertimod netop lære ham den rette Selvkjerlighed.","l":"da","ob":"Las obras del amor","an":"1847","u":"","te":["autoestima","amor"]},{"i":"soren-kierkegaard-047","a":"soren-kierkegaard","t":"El amor todo lo espera, y sin embargo nunca queda en ridículo.","o":"Kjerlighed haaber Alt - og bliver dog aldrig til Skamme","l":"da","ob":"Las obras del amor","an":"1847","u":"","te":["amor","esperanza"]},{"i":"soren-kierkegaard-048","a":"soren-kierkegaard","t":"Nuestro deber de amar a las personas que vemos.","o":"Vor Pligt at elske de Mennesker, vi see","l":"da","ob":"Las obras del amor","an":"1847","u":"","te":["amor","vinculos"]},{"i":"soren-kierkegaard-049","a":"soren-kierkegaard","t":"La obra de amor de recordar a un difunto.","o":"Den Kjerlighedens Gjerning at erindre en Afdød","l":"da","ob":"Las obras del amor","an":"1847","u":"","te":["duelo","memoria","amor"]},{"i":"soren-kierkegaard-051","a":"soren-kierkegaard","t":"Es muy cierto lo que dice la filosofía: que la vida debe comprenderse hacia atrás. Pero se olvida la otra frase: que debe vivirse hacia adelante.","o":"Det er ganske sandt, hvad Philosophien siger, at Livet maa forstaaes baglænds. Men derover glemmer man den anden Sætning, at det maa leves forlænds.","l":"da","ob":"Diario JJ","an":"1842","u":"","te":["tiempo","sentido-de-vida","memoria"]},{"i":"soren-kierkegaard-050","a":"soren-kierkegaard","t":"Se trata de encontrar una verdad que sea verdad para mí, de encontrar la idea por la cual quiero vivir y morir.","o":"det gjælder om at finde en Sandhed, som er Sandhed for mig, at finde den Idee, for hvilken jeg vil leve og døe.","l":"da","ob":"Diario AA","an":"1835","u":"","te":["sentido-de-vida","autenticidad","verdad"]},{"i":"friedrich-nietzsche-026","a":"friedrich-nietzsche","t":"Hay que tener todavía caos dentro de sí para poder dar a luz una estrella danzante.","o":"man muss noch Chaos in sich haben, um einen tanzenden Stern gebären zu können","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["creatividad","transformacion-personal"]},{"i":"friedrich-nietzsche-027","a":"friedrich-nietzsche","t":"El ser humano es una cuerda tendida entre el animal y el superhombre.","o":"Der Mensch ist ein Seil, geknüpft zwischen Thier und Übermensch","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["existencia","transformacion-personal"]},{"i":"friedrich-nietzsche-028","a":"friedrich-nietzsche","t":"Lo grande del ser humano es que es un puente y no una meta.","o":"Was gross ist am Menschen, das ist, dass er eine Brücke und kein Zweck ist","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["transformacion-personal","cambio"]},{"i":"friedrich-nietzsche-029","a":"friedrich-nietzsche","t":"Solo creería en un dios que supiera bailar.","o":"Ich würde nur an einen Gott glauben, der zu tanzen verstünde.","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["trascendencia","alegria"]},{"i":"friedrich-nietzsche-030","a":"friedrich-nietzsche","t":"Siempre hay algo de locura en el amor. Pero siempre hay también algo de razón en la locura.","o":"Es ist immer etwas Wahnsinn in der Liebe. Es ist aber immer auch etwas Vernunft im Wahnsinn.","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["amor","deseo"]},{"i":"friedrich-nietzsche-031","a":"friedrich-nietzsche","t":"Detrás de tus pensamientos y sentimientos, hermano, hay un soberano poderoso, un sabio desconocido: se llama “sí mismo”. Habita en tu cuerpo; es tu cuerpo.","o":"Hinter deinen Gedanken und Gefühlen, mein Bruder, steht ein mächtiger Gebieter, ein unbekannter Weiser-der heisst Selbst. In deinem Leibe wohnt er, dein Leib ist er.","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["cuerpo","inconsciente","identidad"]},{"i":"friedrich-nietzsche-032","a":"friedrich-nietzsche","t":"Hay más razón en tu cuerpo que en tu mejor sabiduría.","o":"Es ist mehr Vernunft in deinem Leibe, als in deiner besten Weisheit.","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["cuerpo","conocimiento"]},{"i":"friedrich-nietzsche-033","a":"friedrich-nietzsche","t":"También tu pequeña razón es una herramienta de tu cuerpo.","o":"Werkzeug deines Leibes ist auch deine kleine Vernunft","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["cuerpo","conciencia"]},{"i":"friedrich-nietzsche-034","a":"friedrich-nietzsche","t":"Tenés que querer quemarte en tu propia llama: ¿cómo querrías renovarte si antes no te hiciste ceniza?","o":"Verbrennen musst du dich wollen in deiner eignen Flamme: wie wolltest du neu werden, wenn du nicht erst Asche geworden bist!","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["transformacion-personal","cambio"]},{"i":"friedrich-nietzsche-035","a":"friedrich-nietzsche","t":"Solitario, recorrés el camino hacia vos mismo.","o":"Einsamer, du gehst den Weg zu dir selber!","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["soledad","autoconocimiento"]},{"i":"friedrich-nietzsche-036","a":"friedrich-nietzsche","t":"Pero el peor enemigo que podés encontrar siempre serás vos mismo.","o":"Aber der schlimmste Feind, dem du begegnen kannst, wirst du immer dir selber sein","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["autoconocimiento","sufrimiento"]},{"i":"friedrich-nietzsche-037","a":"friedrich-nietzsche","t":"En verdad, el ser humano es un río sucio. Hay que ser un mar para poder recibir un río sucio sin volverse impuro.","o":"Wahrlich, ein schmutziger Strom ist der Mensch. Man muss schon ein Meer sein, um einen schmutzigen Strom aufnehmen zu können, ohne unrein zu werden.","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["aceptacion","existencia"]},{"i":"friedrich-nietzsche-038","a":"friedrich-nietzsche","t":"El valor es el mejor matador, el valor que ataca: hasta a la muerte mata.","o":"Muth aber ist der beste Todtschläger, Muth, der angreift: der schlägt noch den Tod todt","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Dritter Theil","te":["miedo","muerte","resiliencia"]},{"i":"friedrich-nietzsche-039","a":"friedrich-nietzsche","t":"¿Eso era la vida? ¡Bien! ¡Otra vez!","o":"War _das_ das Leben? Wohlan! Noch Ein Mal!","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Dritter Theil","te":["sentido-de-vida","aceptacion"]},{"i":"friedrich-nietzsche-040","a":"friedrich-nietzsche","t":"Se le paga mal a un maestro si se sigue siendo siempre solo su alumno.","o":"Man vergilt einem Lehrer schlecht, wenn man immer nur der Schüler bleibt.","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["educacion","autenticidad"]},{"i":"friedrich-nietzsche-041","a":"friedrich-nietzsche","t":"El ser humano es algo que debe ser superado.","o":"Der Mensch ist Etwas, das überwunden werden soll.","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["transformacion-personal"]},{"i":"friedrich-nietzsche-042","a":"friedrich-nietzsche","t":"Permanezcan fieles a la tierra.","o":"bleibt der Erde treu","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["naturaleza","cuerpo"]},{"i":"friedrich-nietzsche-043","a":"friedrich-nietzsche","t":"Toda la vida es una disputa sobre gustos y sabores.","o":"alles Leben ist Streit um Geschmack und Schmecken","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Zweiter Theil","te":["existencia","deseo"]},{"i":"friedrich-nietzsche-044","a":"friedrich-nietzsche","t":"De todo lo escrito, solo amo lo que alguien escribe con su sangre.","o":"Von allem Geschriebenen liebe ich nur Das, was Einer mit seinem Blute schreibt.","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["autenticidad","creatividad"]},{"i":"friedrich-nietzsche-011","a":"friedrich-nietzsche","t":"Quien lucha con monstruos debe cuidar de no convertirse en monstruo. Y si mirás largo tiempo a un abismo, el abismo también mira dentro de vos.","o":"Wer mit Ungeheuern kämpft, mag zusehn, dass er nicht dabei zum Ungeheuer wird. Und wenn du lange in einen Abgrund blickst, blickt der Abgrund auch in dich hinein.","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 146","te":["identidad","inconsciente"]},{"i":"friedrich-nietzsche-012","a":"friedrich-nietzsche","t":"“Esto lo hice yo”, dice mi memoria. “Esto no puedo haberlo hecho”, dice mi orgullo, y se mantiene inflexible. Al final, cede la memoria.","o":"\"Das habe ich gethan\" sagt mein Gedächtniss. Das kann ich nicht gethan haben - sagt mein Stolz und bleibt unerbittlich. Endlich - giebt das Gedächtniss nach.","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 68","te":["memoria","autoestima","inconsciente"]},{"i":"friedrich-nietzsche-013","a":"friedrich-nietzsche","t":"Lo que se hace por amor sucede siempre más allá del bien y del mal.","o":"Was aus Liebe gethan wird, geschieht immer jenseits von Gut und Böse.","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 153","te":["amor"]},{"i":"friedrich-nietzsche-014","a":"friedrich-nietzsche","t":"La locura es algo raro en los individuos; pero en los grupos, los partidos, los pueblos y las épocas, es la regla.","o":"Der Irrsinn ist bei Einzelnen etwas Seltenes, - aber bei Gruppen, Parteien, Völkern, Zeiten die Regel.","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 156","te":["sociedad","salud-mental"]},{"i":"friedrich-nietzsche-015","a":"friedrich-nietzsche","t":"Quien se desprecia a sí mismo se respeta todavía, en eso, como despreciador.","o":"Wer sich selbst verachtet, achtet sich doch immer noch dabei als Verächter.","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 78","te":["autoestima","identidad"]},{"i":"friedrich-nietzsche-016","a":"friedrich-nietzsche","t":"Al final, uno ama su deseo y no lo deseado.","o":"Man liebt zuletzt seine Begierde, und nicht das Begehrte.","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 175","te":["deseo","amor"]},{"i":"friedrich-nietzsche-017","a":"friedrich-nietzsche","t":"Todo lo profundo ama la máscara.","o":"Alles, was tief ist, liebt die Maske","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 40","te":["identidad","autenticidad"]},{"i":"friedrich-nietzsche-018","a":"friedrich-nietzsche","t":"No me conmovió que me mintieras, sino que ya no pueda creerte.","o":"Nicht dass du mich belogst, sondern dass ich dir nicht mehr glaube, hat mich erschüttert.","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 183","te":["vinculos","verdad","perdida"]},{"i":"friedrich-nietzsche-019","a":"friedrich-nietzsche","t":"No hay fenómenos morales, sino solo una interpretación moral de los fenómenos.","o":"Es giebt gar keine moralischen Phänomene, sondern nur eine moralische Ausdeutung von Phänomenen","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 108","te":["verdad","cultura"]},{"i":"friedrich-nietzsche-020","a":"friedrich-nietzsche","t":"Uno ya no ama lo suficiente su conocimiento en cuanto lo comunica.","o":"Man liebt seine Erkenntniss nicht genug mehr, sobald man sie mittheilt.","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 160","te":["conocimiento","comunicacion"]},{"i":"friedrich-nietzsche-021","a":"friedrich-nietzsche","t":"Un pensamiento viene cuando “él” quiere, y no cuando “yo” quiero.","o":"ein Gedanke kommt, wenn \"er\" will, und nicht wenn \"ich\" will","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 17","te":["inconsciente","conciencia"]},{"i":"friedrich-nietzsche-022","a":"friedrich-nietzsche","t":"Madurez del hombre: haber reencontrado la seriedad que se tenía de niño al jugar.","o":"Reife des Mannes: das heisst den Ernst wiedergefunden haben, den man als Kind hatte, beim Spiel.","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 94","te":["infancia","desarrollo-humano"]},{"i":"friedrich-nietzsche-023","a":"friedrich-nietzsche","t":"Que un juicio sea falso no es todavía, para nosotros, una objeción contra ese juicio.","o":"Die Falschheit eines Urtheils ist uns noch kein Einwand gegen ein Urtheil","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 4","te":["verdad","conocimiento"]},{"i":"friedrich-nietzsche-024","a":"friedrich-nietzsche","t":"El amor saca a la luz las cualidades elevadas y ocultas de quien ama.","o":"Die Liebe bringt die hohen und verborgenen Eigenschaften eines Liebenden an's Licht","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 163","te":["amor","identidad"]},{"i":"friedrich-nietzsche-025","a":"friedrich-nietzsche","t":"[¿Un gran hombre?] Siempre veo solo al actor de su propio ideal.","o":"Ich sehe immer nur den Schauspieler seines eignen Ideals","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 97","te":["identidad","autenticidad"]},{"i":"friedrich-nietzsche-001","a":"friedrich-nietzsche","t":"Lo que no me mata me hace más fuerte.","o":"Was mich nicht umbringt, macht mich stärker.","l":"de","ob":"El ocaso de los ídolos","an":"1889","u":"«Sprüche und Pfeile», § 8","te":["resiliencia","sufrimiento"]},{"i":"friedrich-nietzsche-002","a":"friedrich-nietzsche","t":"Si se tiene un “por qué” para vivir, se soporta casi cualquier “cómo”.","o":"Hat man sein warum? des Lebens, so verträgt man sich fast mit jedem wie?","l":"de","ob":"El ocaso de los ídolos","an":"1889","u":"«Sprüche und Pfeile», § 12","te":["sentido-de-vida","resiliencia"]},{"i":"friedrich-nietzsche-003","a":"friedrich-nietzsche","t":"Sin música, la vida sería un error.","o":"Ohne Musik wäre das Leben ein Irrthum.","l":"de","ob":"El ocaso de los ídolos","an":"1889","u":"«Sprüche und Pfeile», § 33","te":["alegria","cultura"]},{"i":"friedrich-nietzsche-004","a":"friedrich-nietzsche","t":"El ocio es el comienzo de toda psicología.","o":"Müssiggang ist aller Psychologie Anfang.","l":"de","ob":"El ocaso de los ídolos","an":"1889","u":"«Sprüche und Pfeile», § 1","te":["autoconocimiento","humor"]},{"i":"friedrich-nietzsche-005","a":"friedrich-nietzsche","t":"Hasta el más valiente de nosotros rara vez tiene el valor de lo que en verdad sabe.","o":"Auch der Muthigste von uns hat nur selten den Muth zu dem, was er eigentlich weiss","l":"de","ob":"El ocaso de los ídolos","an":"1889","u":"«Sprüche und Pfeile», § 2","te":["miedo","verdad"]},{"i":"friedrich-nietzsche-006","a":"friedrich-nietzsche","t":"La sabiduría también le pone límites al conocimiento.","o":"Die Weisheit zieht auch der Erkenntniss Grenzen.","l":"de","ob":"El ocaso de los ídolos","an":"1889","u":"«Sprüche und Pfeile», § 5","te":["conocimiento"]},{"i":"friedrich-nietzsche-007","a":"friedrich-nietzsche","t":"Desconfío de todos los sistemáticos y los evito. La voluntad de sistema es una falta de honestidad.","o":"Ich misstraue allen Systematikern und gehe ihnen aus dem Weg. Der Wille zum System ist ein Mangel an Rechtschaffenheit.","l":"de","ob":"El ocaso de los ídolos","an":"1889","u":"«Sprüche und Pfeile», § 26","te":["verdad","autenticidad"]},{"i":"friedrich-nietzsche-008","a":"friedrich-nietzsche","t":"Solo valen los pensamientos que nacen caminando.","o":"Nur die ergangenen Gedanken haben Werth.","l":"de","ob":"El ocaso de los ídolos","an":"1889","u":"«Sprüche und Pfeile», § 34","te":["cuerpo","creatividad"]},{"i":"friedrich-nietzsche-009","a":"friedrich-nietzsche","t":"¿Es el ser humano solo un error de Dios? ¿O Dios solo un error del ser humano?","o":"ist der Mensch nur ein Fehlgriff Gottes? Oder Gott nur ein Fehlgriff des Menschen?","l":"de","ob":"El ocaso de los ídolos","an":"1889","u":"«Sprüche und Pfeile», § 7","te":["trascendencia","existencia"]},{"i":"friedrich-nietzsche-010","a":"friedrich-nietzsche","t":"El gusano pisado se enrosca. Así es prudente.","o":"Der getretene Wurm krümmt sich. So ist es klug.","l":"de","ob":"El ocaso de los ídolos","an":"1889","u":"«Sprüche und Pfeile», § 31","te":["poder","humor"]},{"i":"friedrich-nietzsche-045","a":"friedrich-nietzsche","t":"Mi fórmula para la grandeza del ser humano es amor fati: no querer que nada sea distinto, ni hacia adelante, ni hacia atrás, ni por toda la eternidad.","o":"Meine Formel für die Grösse am Menschen ist amor fati: dass man Nichts anders haben will, vorwärts nicht, rückwärts nicht, in alle Ewigkeit nicht.","l":"de","ob":"Ecce homo","an":"1888 (publ. 1908)","u":"«Warum ich so klug bin», § 10","te":["aceptacion","sentido-de-vida"]},{"i":"friedrich-nietzsche-046","a":"friedrich-nietzsche","t":"No darle crédito a ningún pensamiento que no haya nacido al aire libre.","o":"keinem Gedanken Glauben schenken, der nicht im Freien geboren ist","l":"de","ob":"Ecce homo","an":"1888 (publ. 1908)","u":"«Warum ich so klug bin»","te":["cuerpo","naturaleza","creatividad"]},{"i":"friedrich-nietzsche-047","a":"friedrich-nietzsche","t":"Llegar a ser lo que uno es supone no sospechar ni remotamente lo que uno es.","o":"Dass man wird, was man ist, setzt voraus, dass man nicht im Entferntesten ahnt, was man ist.","l":"de","ob":"Ecce homo","an":"1888 (publ. 1908)","u":"«Warum ich so klug bin», § 9","te":["identidad","desarrollo-humano","autoconocimiento"]},{"i":"friedrich-nietzsche-048","a":"friedrich-nietzsche","t":"No soy un hombre, soy dinamita.","o":"Ich bin kein Mensch, ich bin Dynamit.","l":"de","ob":"Ecce homo","an":"1888 (publ. 1908)","u":"«Warum ich ein Schicksal bin», § 1","te":["identidad"]},{"i":"friedrich-nietzsche-049","a":"friedrich-nietzsche","t":"Las convicciones son enemigas de la verdad más peligrosas que las mentiras.","o":"Ueberzeugungen sind gefährlichere Feinde der Wahrheit, als Lügen.","l":"de","ob":"Humano, demasiado humano","an":"1878","u":"§ 483","te":["verdad"]},{"i":"friedrich-nietzsche-050","a":"friedrich-nietzsche","t":"[La esperanza] es, en verdad, el peor de los males, porque prolonga el tormento de los seres humanos.","o":"sie ist in Wahrheit das übelste der Uebel, weil sie die Qual der Menschen verlängert","l":"de","ob":"Humano, demasiado humano","an":"1878","u":"§ 71","te":["esperanza","sufrimiento"]},{"i":"friedrich-nietzsche-051","a":"friedrich-nietzsche","t":"Lo que hace al amigo es compartir la alegría, no compartir el sufrimiento.","o":"Mitfreude, nicht Mitleiden, macht den Freund.","l":"de","ob":"Humano, demasiado humano","an":"1878","u":"§ 499","te":["amistad","alegria"]},{"i":"friedrich-nietzsche-052","a":"friedrich-nietzsche","t":"Quien haya llegado aunque sea un poco a la libertad de la razón no puede sentirse en la tierra sino como un caminante.","o":"Wer nur einigermaassen zur Freiheit der Vernunft gekommen ist, kann sich auf Erden nicht anders fühlen, denn als Wanderer","l":"de","ob":"Humano, demasiado humano","an":"1878","u":"§ 638","te":["libertad","existencia"]},{"i":"rene-descartes-011","a":"rene-descartes","t":"En nada se ve mejor cuán defectuosas son las ciencias que heredamos de los antiguos que en lo que escribieron sobre las pasiones.","o":"Il n'y a rien en quoi paraisse mieux combien les sciences que nous avons des anciens sont défectueuses qu'en ce qu'ils ont écrit des passions.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 1","te":["emociones","conocimiento"]},{"i":"rene-descartes-012","a":"rene-descartes","t":"Tales son los sentimientos de alegría, de ira y otros semejantes, que a veces despiertan en nosotros los objetos que mueven nuestros nervios, y a veces otras causas.","o":"Tels sont les sentiments de joie, de colère, et autres semblables, qui sont quelquefois excités en nous par les objets qui meuvent nos nerfs, et quelquefois aussi par d'autres causes.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 25","te":["emociones","cuerpo"]},{"i":"rene-descartes-013","a":"rene-descartes","t":"Cómo una misma causa puede despertar pasiones distintas en personas distintas.","o":"Comment une même cause peut exciter diverses passions en divers hommes.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 39","te":["emociones","identidad"]},{"i":"rene-descartes-014","a":"rene-descartes","t":"Por ejemplo, si la ira hace levantar la mano para golpear, la voluntad puede de ordinario retenerla; si el miedo empuja las piernas a huir, la voluntad puede detenerlas; y así con las demás.","o":"Par exemple, si la colère fait lever la main pour frapper, la volonté peut ordinairement la retenir ; si la peur incite les jambes à fuir, la volonté les peut arrêter, et ainsi des autres.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 46","te":["regulacion-emocional","ira","miedo"]},{"i":"rene-descartes-015","a":"rene-descartes","t":"Pero hay quienes no pueden probar su fuerza porque nunca hacen combatir a su voluntad con sus propias armas, sino solo con las que le dan algunas pasiones para resistir a otras.","o":"Mais il y en a qui ne peuvent éprouver leur force, parce qu'ils ne font jamais combattre leur volonté avec ses propres armes, mais seulement avec celles que lui fournissent quelques passions pour résister à quelques autres.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 48","te":["voluntad","regulacion-emocional"]},{"i":"rene-descartes-016","a":"rene-descartes","t":"Que no hay alma tan débil que, bien guiada, no pueda adquirir un poder absoluto sobre sus pasiones.","o":"Qu'il n'y a point d'âme si faible qu'elle ne puisse, étant bien conduite, acquérir un pouvoir absolu sur ses passions.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 50","te":["regulacion-emocional","esperanza"]},{"i":"rene-descartes-017","a":"rene-descartes","t":"Es útil saber estas cosas para darle a cada uno el ánimo de aprender a regular sus pasiones.","o":"Or ces choses sont utiles à savoir pour donner le courage à un chacun d'étudier à régler ses passions.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 50","te":["regulacion-emocional","educacion"]},{"i":"rene-descartes-018","a":"rene-descartes","t":"Me parece que la admiración [el asombro] es la primera de todas las pasiones.","o":"il me semble que l'admiration est la première de toutes les passions.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 53","te":["emociones","atencion"]},{"i":"rene-descartes-019","a":"rene-descartes","t":"La admiración es una sorpresa súbita del alma que la lleva a considerar con atención los objetos que le parecen raros y extraordinarios.","o":"L'admiration est une subite surprise de l'âme, qui fait qu'elle se porte à considérer avec attention les objets qui lui semblent rares et extraordinaires.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 70","te":["emociones","atencion","conocimiento"]},{"i":"rene-descartes-020","a":"rene-descartes","t":"De la admiración puede decirse en particular que es útil porque hace que aprendamos y retengamos en la memoria lo que antes ignorábamos.","o":"Et on peut dire en particulier de l'admiration qu'elle est utile en ce qu'elle fait que nous apprenons et retenons en notre mémoire les choses que nous avons auparavant ignorées.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 75","te":["educacion","memoria"]},{"i":"rene-descartes-021","a":"rene-descartes","t":"Eso es lo que comúnmente se llama quedarse atónito; y el pasmo es un exceso de admiración que no puede ser sino malo.","o":"C'est cela qu'on appelle communément être étonné ; et l'étonnement est un excès d'admiration qui ne peut jamais être que mauvais.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 73","te":["emociones"]},{"i":"rene-descartes-022","a":"rene-descartes","t":"El amor es una emoción del alma que la incita a unirse por voluntad a los objetos que le parecen convenientes.","o":"L'amour est une émotion de l'âme causée par le mouvement des esprits, qui l'incite à se joindre de volonté aux objets qui paraissent lui être convenables.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 79","te":["amor","emociones"]},{"i":"rene-descartes-023","a":"rene-descartes","t":"Y el odio es una emoción que incita al alma a querer separarse de los objetos que se le presentan como dañinos.","o":"Et la haine est une émotion causée par les esprits, qui incite l'âme à vouloir être séparée des objets qui se présentent à elle comme nuisibles.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 79","te":["ira","emociones"]},{"i":"rene-descartes-024","a":"rene-descartes","t":"Cuando se estima lo que se ama menos que a uno mismo, se siente por ello un simple afecto; cuando se lo estima igual que a uno mismo, se llama amistad; y cuando se lo estima más, esa pasión puede llamarse devoción.","o":"Car lorsqu'on estime l'objet de son amour moins que soi, on n'a pour lui qu'une simple affection ; lorsqu'on l'estime à l'égal de soi, cela se nomme amitié ; et lorsqu'on l'estime davantage, la passion qu'on a peut être nommée dévotion.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 83","te":["amor","amistad","vinculos"]},{"i":"rene-descartes-025","a":"rene-descartes","t":"El deseo es una agitación del alma que la dispone a querer para el futuro las cosas que se representa como convenientes.","o":"La passion du désir est une agitation de l'âme causée par les esprits qui la dispose à vouloir pour l'avenir les choses qu'elle se représente être convenables.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 86","te":["deseo","emociones"]},{"i":"rene-descartes-026","a":"rene-descartes","t":"La alegría es una emoción agradable del alma en la que consiste el disfrute del bien que las impresiones del cerebro le presentan como propio.","o":"La joie est une agréable émotion de l'âme, en laquelle consiste la jouissance qu'elle a du bien que les impressions du cerveau lui représentent comme sien.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 91","te":["alegria","emociones"]},{"i":"rene-descartes-027","a":"rene-descartes","t":"La tristeza es una languidez desagradable en la que consiste el malestar que el alma recibe del mal o de la carencia que las impresiones del cerebro le presentan como propios.","o":"La tristesse est une langueur désagréable en laquelle consiste l'incommodité que l'âme reçoit du mal, ou du défaut que les impressions du cerveau lui représentent comme lui appartenant.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 92","te":["tristeza","emociones"]},{"i":"rene-descartes-028","a":"rene-descartes","t":"Sin embargo, son tan distintos que a veces se pueden sufrir dolores con alegría y recibir cosquillas que desagradan.","o":"Toutefois, ils diffèrent si fort qu'on peut quelquefois souffrir des douleurs avec joie, et recevoir des chatouillements qui déplaisent.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 94","te":["emociones","cuerpo"]},{"i":"rene-descartes-029","a":"rene-descartes","t":"El bien que hicimos nos da una satisfacción interior, la más dulce de todas las pasiones; el mal, en cambio, despierta el arrepentimiento, la más amarga.","o":"Et le bien qui a été fait par nous-mêmes nous donne une satisfaction intérieure, qui est la plus douce de toutes les passions, au lieu que le mal excite le repentir, qui est la plus amère.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 63","te":["culpa","felicidad"]},{"i":"rene-descartes-030","a":"rene-descartes","t":"A veces la duración del bien causa aburrimiento o hastío, mientras que la duración del mal disminuye la tristeza.","o":"Et quelquefois la durée du bien cause l'ennui ou le dégoût, au lieu que celle du mal diminue la tristesse.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 67","te":["emociones","tiempo"]},{"i":"rene-descartes-031","a":"rene-descartes","t":"Del bien pasado viene la añoranza, que es una especie de tristeza; y del mal pasado, el alivio alegre, que es una especie de alegría.","o":"Enfin, du bien passé vient le regret, qui est une espèce de tristesse, et du mal passé vient l'allégresse, qui est une espèce de joie.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 67","te":["duelo","alegria","memoria"]},{"i":"rene-descartes-032","a":"rene-descartes","t":"Y como una de las partes principales de la sabiduría es saber de qué manera y por qué causa cada uno debe estimarse o despreciarse, intentaré dar aquí mi opinión.","o":"Et parce que l'une des principales parties de la sagesse est de savoir en quelle façon et pour quelle cause chacun se doit estimer ou mépriser, je tâcherai ici d'en dire mon opinion.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 152","te":["autoestima","autoconocimiento"]},{"i":"rene-descartes-033","a":"rene-descartes","t":"Cuáles son las propiedades de la generosidad y cómo sirve de remedio contra todos los desarreglos de las pasiones.","o":"Quelles sont les propriétés de la générosité, et comment elle sert de remède contre tous les dérèglements des passions.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 156","te":["regulacion-emocional","autoestima"]},{"i":"rene-descartes-034","a":"rene-descartes","t":"Quienes son generosos de esta manera tienden naturalmente a hacer grandes cosas, y sin embargo a no emprender nada de lo que no se sientan capaces.","o":"Ceux qui sont généreux en cette façon sont naturellement portés à faire de grandes choses, et toutefois à ne rien entreprendre dont ils ne se sentent capables.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 156","te":["autoestima","responsabilidad"]},{"i":"rene-descartes-035","a":"rene-descartes","t":"Y sucede a menudo que quienes tienen el espíritu más bajo son los más arrogantes y soberbios, así como los más generosos son los más modestos y humildes.","o":"et il arrive souvent que ceux qui ont l'esprit le plus bas sont les plus arrogants et superbes, en même façon que les plus généreux sont les plus modestes et les plus humbles.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 159","te":["autoestima"]},{"i":"rene-descartes-036","a":"rene-descartes","t":"Hay que notar que lo que comúnmente llamamos virtudes son hábitos del alma que la disponen a ciertos pensamientos.","o":"Et il faut remarquer que ce qu'on nomme communément des vertus sont des habitudes en l'âme qui la disposent à certaines pensées","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 161","te":["habitos"]},{"i":"rene-descartes-037","a":"rene-descartes","t":"La esperanza es una disposición del alma a persuadirse de que lo que desea sucederá.","o":"L'espérance est une disposition de l'âme à se persuader que ce qu'elle désire adviendra","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 165","te":["esperanza","emociones"]},{"i":"rene-descartes-038","a":"rene-descartes","t":"Y el temor es otra disposición del alma que la persuade de que no sucederá.","o":"Et la crainte est une autre disposition de l'âme qui lui persuade qu'il n'adviendra pas.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 165","te":["miedo","emociones"]},{"i":"rene-descartes-039","a":"rene-descartes","t":"La irresolución es también una especie de temor que, reteniendo al alma como en una balanza entre varias acciones posibles, hace que no realice ninguna.","o":"L'irrésolution est aussi une espèce de crainte qui, retenant l'âme comme en balance entre plusieurs actions qu'elle peut faire, est cause qu'elle n'en exécute aucune","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 170","te":["miedo","voluntad","incertidumbre"]},{"i":"rene-descartes-040","a":"rene-descartes","t":"Como la principal causa del miedo es la sorpresa, nada mejor para librarse de él que anticiparse y prepararse para todos los sucesos que podrían causarlo.","o":"Et parce que la principale cause de la peur est la surprise, il n'y a rien de meilleur pour s'en exempter que d'user de préméditation et de se préparer à tous les événements, la crainte desquels la peut causer.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 176","te":["miedo","regulacion-emocional"]},{"i":"rene-descartes-041","a":"rene-descartes","t":"La envidia, en cuanto pasión, es una especie de tristeza mezclada con odio que surge al ver que les llega un bien a quienes creemos que no lo merecen.","o":"L'envie donc, en tant qu'elle est une passion, est une espèce de tristesse mêlée de haine qui vient de ce qu'on voit arriver du bien à ceux qu'on pense en être indignes.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 182","te":["emociones","vinculos"]},{"i":"rene-descartes-042","a":"rene-descartes","t":"Por lo demás, no hay vicio que dañe tanto la felicidad de las personas como la envidia.","o":"Au reste, il n'y a aucun vice qui nuise tant à la félicité des hommes que celui de l'envie.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 184","te":["felicidad","emociones"]},{"i":"rene-descartes-043","a":"rene-descartes","t":"La compasión es una especie de tristeza mezclada con amor o buena voluntad hacia quienes vemos sufrir un mal que no merecen.","o":"La pitié est une espèce de tristesse mêlée d'amour ou de bonne volonté envers ceux à qui nous voyons souffrir quelque mal duquel nous les estimons indignes.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 185","te":["compasion","empatia"]},{"i":"rene-descartes-044","a":"rene-descartes","t":"Tener buena voluntad hacia cada uno es parte de la generosidad.","o":"Car c'est une partie de la générosité que d'avoir de la bonne volonté pour un chacun.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 187","te":["compasion","vinculos"]},{"i":"rene-descartes-045","a":"rene-descartes","t":"La satisfacción que tienen siempre quienes siguen con constancia la virtud es un hábito del alma que se llama tranquilidad y paz de conciencia.","o":"La satisfaction qu'ont toujours ceux qui suivent constamment la vertu est une habitude en leur âme qui se nomme tranquillité et repos de conscience.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 190","te":["felicidad","habitos","silencio"]},{"i":"rene-descartes-046","a":"rene-descartes","t":"El arrepentimiento es lo contrario de la satisfacción de uno mismo: una especie de tristeza que surge de creer que hicimos algo malo; y es muy amarga, porque su causa está solo en nosotros.","o":"Le repentir est directement contraire à la satisfaction de soi-même, et c'est une espèce de tristesse qui vient de ce qu'on croit avoir fait quelque mauvaise action ; et elle est très amère, parce que sa cause ne vient que de nous.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 191","te":["culpa","tristeza"]},{"i":"rene-descartes-047","a":"rene-descartes","t":"La gratitud es también una especie de amor que despierta en nosotros alguna acción de aquel por quien [la sentimos].","o":"La reconnaissance est aussi une espèce d'amour excitée en nous par quelque action de celui pour qui","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 193","te":["gratitud","amor"]},{"i":"rene-descartes-048","a":"rene-descartes","t":"Por lo demás, la indignación se nota mucho más en quienes quieren parecer virtuosos que en quienes lo son de verdad.","o":"Au reste, l'indignation se remarque bien plus en ceux qui veulent paraître vertueux qu'en ceux qui le sont véritablement.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 198","te":["autenticidad","ira"]},{"i":"rene-descartes-049","a":"rene-descartes","t":"La vergüenza, en cambio, es una especie de tristeza fundada también en el amor de sí, que nace de la opinión o del temor de ser censurado.","o":"La honte, au contraire, est une espèce de tristesse fondée aussi sur l'amour de soi-même, et qui vient de l'opinion ou de la crainte qu'on a d'être blâmé.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 205","te":["culpa","autoestima"]},{"i":"rene-descartes-050","a":"rene-descartes","t":"Solo hace falta educar el juicio sobre lo que de verdad merece censura o elogio, para no avergonzarse de obrar bien ni envanecerse de los propios vicios.","o":"Il est seulement besoin d'instruire son jugement touchant ce qui est véritablement digne de blâme ou de louange, afin de n'être pas honteux de bien faire, et ne tirer point de vanité de ses vices","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 206","te":["autoestima","educacion"]},{"i":"rene-descartes-051","a":"rene-descartes","t":"Vemos que [las pasiones] son todas buenas por naturaleza, y que solo tenemos que evitar sus malos usos o sus excesos.","o":"Car nous voyons qu'elles sont toutes bonnes de leur nature, et que nous n'avons","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 211","te":["emociones","aceptacion"]},{"i":"rene-descartes-052","a":"rene-descartes","t":"Pero la sabiduría es útil sobre todo en esto: enseña a dominar las pasiones y a manejarlas con tanta destreza que los males que causan resultan muy soportables, y que hasta se saca alegría de todos ellos.","o":"Mais la sagesse est principalement utile en ce point, qu'elle enseigne à s'en rendre tellement maître et à les ménager avec tant d'adresse, que les maux qu'elles causent sont fort supportables, et même qu'on tire de la joie de tous.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 212","te":["regulacion-emocional","alegria","resiliencia"]},{"i":"rene-descartes-001","a":"rene-descartes","t":"El buen sentido es la cosa mejor repartida del mundo.","o":"Le bon sens est la chose du monde la mieux partagée","l":"fr","ob":"Discurso del método","an":"1637","u":"","te":["conocimiento","humor"]},{"i":"rene-descartes-002","a":"rene-descartes","t":"No basta con tener buen ingenio: lo principal es aplicarlo bien.","o":"car ce n'est pas assez d'avoir l'esprit bon, mais le principal est de l'appliquer bien.","l":"fr","ob":"Discurso del método","an":"1637","u":"","te":["conocimiento","responsabilidad"]},{"i":"rene-descartes-003","a":"rene-descartes","t":"Las almas más grandes son capaces de los mayores vicios tanto como de las mayores virtudes.","o":"Les plus grandes âmes sont capables des plus grands vices aussi bien que des plus grandes vertus","l":"fr","ob":"Discurso del método","an":"1637","u":"","te":["identidad"]},{"i":"rene-descartes-004","a":"rene-descartes","t":"La lectura de todos los buenos libros es como una conversación con las personas más valiosas de los siglos pasados.","o":"la lecture de tous les bons livres est comme une conversation avec les plus honnêtes gens des siècles passés","l":"fr","ob":"Discurso del método","an":"1637","u":"","te":["educacion","cultura","encuentro"]},{"i":"rene-descartes-005","a":"rene-descartes","t":"Pienso, luego existo.","o":"je pense, donc je suis","l":"fr","ob":"Discurso del método","an":"1637","u":"","te":["conciencia","existencia","identidad"]},{"i":"rene-descartes-006","a":"rene-descartes","t":"Procurar siempre vencerme a mí mismo antes que a la fortuna, y cambiar mis deseos antes que el orden del mundo.","o":"tâcher toujours plutôt à me vaincre que la fortune, et à changer mes désirs que l'ordre du monde","l":"fr","ob":"Discurso del método","an":"1637","u":"","te":["aceptacion","deseo","regulacion-emocional"]},{"i":"rene-descartes-007","a":"rene-descartes","t":"No hay nada que esté enteramente en nuestro poder salvo nuestros pensamientos.","o":"il n'y a rien qui soit entièrement en notre pouvoir que nos pensées","l":"fr","ob":"Discurso del método","an":"1637","u":"","te":["libertad","conciencia"]},{"i":"rene-descartes-008","a":"rene-descartes","t":"No aceptar nunca nada como verdadero sin conocer con evidencia que lo es.","o":"ne recevoir jamais aucune chose pour vraie que je ne la connusse évidemment être telle","l":"fr","ob":"Discurso del método","an":"1637","u":"","te":["verdad","conocimiento"]},{"i":"rene-descartes-009","a":"rene-descartes","t":"[Esta proposición:] yo soy, yo existo, es necesariamente verdadera cada vez que la pronuncio o la concibo en mi mente.","o":"je suis, j'existe, est nécessairement vraie, toutes les fois que je la prononce ou que je la conçois en mon esprit.","l":"fr","ob":"Meditaciones metafísicas","an":"1641 (trad. francesa de 1647)","u":"Meditación 2","te":["existencia","conciencia"]},{"i":"rene-descartes-010","a":"rene-descartes","t":"No soy, entonces, hablando con precisión, más que una cosa que piensa.","o":"je ne suis donc, précisément parlant, qu'une chose qui pense","l":"fr","ob":"Meditaciones metafísicas","an":"1641 (trad. francesa de 1647)","u":"Meditación 2","te":["identidad","conciencia"]},{"i":"john-locke-001","a":"john-locke","t":"Supongamos que la mente es, como se dice, un papel en blanco, sin ningún carácter escrito, sin ideas: ¿cómo llega a llenarse?","o":"Let us then suppose the mind to be, as we say, white paper, void of all characters, without any ideas:-How comes it to be furnished?","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 1","te":["conocimiento","desarrollo-humano"]},{"i":"john-locke-002","a":"john-locke","t":"El conocimiento de nadie puede ir, en esto, más allá de su experiencia.","o":"No man's knowledge here can go beyond his experience.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 1","te":["conocimiento"]},{"i":"john-locke-003","a":"john-locke","t":"La conciencia es la percepción de lo que pasa en la propia mente.","o":"Consciousness is the perception of what passes in a man's own mind.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 1","te":["conciencia","autoconocimiento"]},{"i":"john-locke-004","a":"john-locke","t":"Las opiniones nuevas son siempre sospechadas y casi siempre combatidas, sin otra razón que la de no ser todavía comunes.","o":"new opinions are always suspected, and usually opposed, without any other reason but because they are not already common.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 33","te":["cambio","sociedad"]},{"i":"john-locke-005","a":"john-locke","t":"La verdad casi nunca ganó por votación cuando apareció por primera vez.","o":"Truth scarce ever yet carried it by vote anywhere at its first appearance","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 33","te":["verdad","sociedad"]},{"i":"john-locke-006","a":"john-locke","t":"Es ambición suficiente trabajar como peón despejando un poco el terreno y quitando algunos escombros del camino hacia el conocimiento.","o":"it is ambition enough to be employed as an under-labourer in clearing the ground a little, and removing some of the rubbish that lies in the way to knowledge","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 33","te":["conocimiento","trabajo"]},{"i":"john-locke-007","a":"john-locke","t":"Los hábitos, sobre todo los que empiezan muy temprano, terminan produciendo en nosotros acciones que a menudo escapan a nuestra observación.","o":"Habits, especially such as are begun very early, come at last to produce actions in us, which often escape our observation.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 9","te":["habitos","inconsciente","infancia"]},{"i":"john-locke-008","a":"john-locke","t":"Cómo la facilidad que adquirimos por la costumbre de hacer algo hace que muchas veces pase en nosotros sin que lo notemos.","o":"how the facility which we get of doing things, by a custom of doing, makes them often pass in us without our notice.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 9","te":["habitos","atencion"]},{"i":"john-locke-009","a":"john-locke","t":"Quienes por costumbre adquirieron una muletilla la pronuncian casi en cada frase: los demás la notan, pero ellos mismos ni la oyen ni la advierten.","o":"Men that, by custom, have got the use of a by-word, do almost in every sentence pronounce sounds which, though taken notice of by others, they themselves neither hear nor observe.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 9","te":["habitos","comunicacion","autoconocimiento"]},{"i":"john-locke-010","a":"john-locke","t":"En una criatura inteligente, la memoria es lo más necesario después de la percepción.","o":"Memory, in an intellectual creature, is necessary in the next degree to perception.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 10","te":["memoria"]},{"i":"john-locke-011","a":"john-locke","t":"No es fácil para la mente desprenderse de las nociones confusas y los prejuicios que absorbió de la costumbre, la distracción y la conversación corriente.","o":"It is not easy for the mind to put off those confused notions and prejudices it has imbibed from custom, inadvertency, and common conversation.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 13","te":["cambio","conocimiento"]},{"i":"john-locke-012","a":"john-locke","t":"El placer y el dolor, y lo que los causa —el bien y el mal—, son los goznes sobre los que giran nuestras pasiones.","o":"Pleasure and pain and that which causes them,-good and evil, are the hinges on which our passions turn.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 20","te":["emociones"]},{"i":"john-locke-013","a":"john-locke","t":"La inquietud que una persona siente ante la ausencia de algo cuyo disfrute le traería deleite es lo que llamamos deseo.","o":"The uneasiness a man finds in himself upon the absence of anything whose present enjoyment carries the idea of delight with it, is that we call DESIRE","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 20","te":["deseo","emociones"]},{"i":"john-locke-014","a":"john-locke","t":"El deseo también se detiene o se apaga ante la opinión de que el bien buscado es imposible o inalcanzable.","o":"Desire also is stopped or abated by the opinion of the impossibility or unattainableness of the good proposed","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 20","te":["deseo","esperanza"]},{"i":"john-locke-015","a":"john-locke","t":"La alegría es un deleite de la mente al considerar la posesión presente, o segura y próxima, de un bien.","o":"JOY is a delight of the mind, from the consideration of the present or assured approaching possession of a good","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 20","te":["alegria","emociones"]},{"i":"john-locke-016","a":"john-locke","t":"La tristeza es una inquietud de la mente al pensar en un bien perdido del que se podría haber disfrutado más tiempo, o al sentir un mal presente.","o":"SORROW is uneasiness in the mind, upon the thought of a good lost, which might have been enjoyed longer; or the sense of a present evil.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 20","te":["tristeza","duelo","emociones"]},{"i":"john-locke-017","a":"john-locke","t":"La esperanza es ese placer de la mente que cada uno encuentra en sí al pensar en el disfrute futuro y probable de algo que puede deleitarlo.","o":"HOPE is that pleasure in the mind, which every one finds in himself, upon the thought of a probable future enjoyment of a thing which is apt to delight him.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 20","te":["esperanza","emociones"]},{"i":"john-locke-018","a":"john-locke","t":"El miedo es una inquietud de la mente al pensar en un mal futuro que probablemente nos alcance.","o":"FEAR is an uneasiness of the mind, upon the thought of future evil likely to befall us.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 20","te":["miedo","angustia","emociones"]},{"i":"john-locke-019","a":"john-locke","t":"La desesperación es pensar que un bien es inalcanzable; obra de modo distinto en cada mente: a veces produce inquietud o dolor, a veces quietud e indolencia.","o":"DESPAIR is the thought of the unattainableness of any good, which works differently in men's minds, sometimes producing uneasiness or pain, sometimes rest and indolency.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 20","te":["angustia","emociones"]},{"i":"john-locke-020","a":"john-locke","t":"La ira es la inquietud o la turbación de la mente al recibir una ofensa, con el propósito presente de vengarse.","o":"ANGER is uneasiness or discomposure of the mind, upon the receipt of any injury, with a present purpose of revenge.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 20","te":["ira","emociones"]},{"i":"john-locke-021","a":"john-locke","t":"La envidia es una inquietud de la mente causada por ver un bien que deseamos en manos de alguien que, creemos, no debería haberlo tenido antes que nosotros.","o":"ENVY is an uneasiness of the mind, caused by the consideration of a good we desire obtained by one we think should not have had it before us.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 20","te":["emociones","vinculos"]},{"i":"john-locke-022","a":"john-locke","t":"La vergüenza, que es una inquietud de la mente al pensar que hicimos algo indecoroso o que disminuirá la estima que otros nos tienen, no siempre va acompañada de rubor.","o":"For SHAME, which is an uneasiness of the mind upon the thought of having done something which is indecent, or will lessen the valued esteem which others have for us, has not always blushing accompanying it.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 20","te":["culpa","emociones","autoestima"]},{"i":"john-locke-023","a":"john-locke","t":"Todo dolor del cuerpo, de cualquier tipo, y toda intranquilidad de la mente son inquietud; y a ella siempre se une un deseo igual al dolor o a la inquietud que se siente.","o":"All pain of the body, of what sort soever, and disquiet of the mind, is uneasiness: and with this is always joined desire, equal to the pain or uneasiness felt","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 21","te":["sufrimiento","deseo","cuerpo"]},{"i":"john-locke-024","a":"john-locke","t":"Que el deseo es un estado de inquietud lo descubrirá enseguida cualquiera que reflexione sobre sí mismo.","o":"That desire is a state of uneasiness, every one who reflects on himself will quickly find.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 21","te":["deseo","autoconocimiento"]},{"i":"john-locke-025","a":"john-locke","t":"Cuando alguien está perfectamente contento con su estado, es decir, sin ninguna inquietud, ¿qué esfuerzo, qué acción, qué voluntad le queda, salvo seguir en él?","o":"When a man is perfectly content with the state he is in-which is when he is perfectly without any uneasiness-what industry, what action, what will is there left, but to continue in it?","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 21","te":["deseo","felicidad","cambio"]},{"i":"john-locke-026","a":"john-locke","t":"Estoy seguro de que donde hay inquietud, hay deseo.","o":"I am sure wherever there is uneasiness, there is desire.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 21","te":["deseo"]},{"i":"john-locke-027","a":"john-locke","t":"Deseamos constantemente la felicidad, y cuanto sentimos de inquietud, tanto nos falta, sin duda, de felicidad.","o":"For we constantly desire happiness; and whatever we feel of uneasiness, so much it is certain we want of happiness","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 21","te":["felicidad","deseo"]},{"i":"john-locke-028","a":"john-locke","t":"La mayor inquietud presente es el aguijón de la acción: es la que más se siente y la que, casi siempre, determina la voluntad al elegir la acción siguiente.","o":"The greatest present uneasiness is the spur to action, that is constantly most felt, and for the most part determines the will in its choice of the next action.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 21","te":["voluntad","deseo"]},{"i":"john-locke-029","a":"john-locke","t":"Una vez quitada toda inquietud, una porción moderada de bien basta para contentar a las personas.","o":"All uneasiness therefore being removed, a moderate portion of good serve at present to content men","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 21","te":["felicidad","aceptacion"]},{"i":"john-locke-030","a":"john-locke","t":"Pero en cuanto llega una nueva inquietud, esa felicidad se altera y volvemos a ponernos en marcha tras ella.","o":"But as soon as any new uneasiness comes in, this happiness is disturbed, and we are set afresh on work in the pursuit of happiness.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 21","te":["felicidad","deseo"]},{"i":"john-locke-031","a":"john-locke","t":"Nada, pensamos apasionadamente, puede superar ni casi igualar la inquietud que pesa tanto sobre nosotros.","o":"Nothing, as we passionately think, can exceed, or almost equal, the uneasiness that sits so heavy upon us.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 21","te":["sufrimiento","angustia"]},{"i":"john-locke-032","a":"john-locke","t":"Además, el bien ausente, es decir, el placer futuro, sobre todo si es de una clase que no conocemos, rara vez logra contrapesar una inquietud presente de dolor o de deseo.","o":"Add to this, that absent good, or, which is the same thing, future pleasure,-especially if of a sort we are unacquainted with,-seldom is able to counterbalance any uneasiness, either of pain or desire, which is present.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 21","te":["deseo","tiempo","habitos"]},{"i":"john-locke-033","a":"john-locke","t":"En algunos casos bastará una reflexión adecuada; en la mayoría, la práctica, la dedicación y la costumbre.","o":"A due consideration will do it in some cases; and practice, application, and custom in most.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 21","te":["habitos","cambio"]},{"i":"john-locke-034","a":"john-locke","t":"Cuando la moda y la opinión común instalaron ideas equivocadas, y la educación y la costumbre malos hábitos, el justo valor de las cosas se desplaza y el gusto de las personas se corrompe.","o":"Fashion and the common opinion having settled wrong notions, and education and custom ill habits, the just values of things are misplaced, and the palates of men corrupted.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 21","te":["habitos","sociedad","educacion"]},{"i":"john-locke-035","a":"john-locke","t":"Hay que esforzarse por corregirlo: los hábitos contrarios cambian nuestros placeres y le dan gusto a lo que es necesario o conduce a nuestra felicidad.","o":"Pains should be taken to rectify these; and contrary habits change our pleasures, and give a relish to that which is necessary or conducive to our happiness.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 21","te":["habitos","cambio","felicidad"]},{"i":"john-locke-036","a":"john-locke","t":"Las ideas de duendes y espíritus no tienen en realidad más que ver con la oscuridad que con la luz; pero basta que alguien se las inculque a menudo a un niño y las asocie [para que ya no pueda separarlas].","o":"The ideas of goblins and sprites have really no more to do with darkness than light: yet let but a foolish maid inculcate these often on the mind of a child, and raise them there together","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 33","te":["miedo","infancia","inconsciente"]},{"i":"john-locke-037","a":"john-locke","t":"Ideas que en sí mismas no tienen nada que ver llegan a unirse tanto en la mente de algunas personas que es muy difícil separarlas: siempre van juntas.","o":"Ideas that in themselves are not all of kin, come to be so united in some men's minds, that it is very hard to separate them; they always keep in company","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 33","te":["inconsciente","memoria","conciencia"]},{"i":"john-locke-038","a":"john-locke","t":"Si la costumbre, desde la infancia, unió una figura a la idea de Dios, ¿en qué absurdos podrá caer esa mente acerca de la divinidad?","o":"Let custom from the very childhood have joined figure and shape to the idea of God, and what absurdities will that mind be liable to about the Deity?","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 33","te":["infancia","trascendencia"]},{"i":"john-locke-039","a":"john-locke","t":"El odio o el amor hacia seres capaces de dicha o desdicha suelen ser la inquietud o el deleite que encontramos en nosotros por su sola existencia o su felicidad.","o":"But hatred or love, to beings capable of happiness or misery, is often the uneasiness of delight which we find in ourselves, arising from their very being or happiness.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 20","te":["amor","ira","vinculos"]},{"i":"john-locke-040","a":"john-locke","t":"La aversión, el miedo, la ira, la envidia, la vergüenza, etcétera, tienen cada uno su propia inquietud, y por eso influyen en la voluntad.","o":"Aversion, fear, anger, envy, shame, &c. have each their uneasinesses too, and thereby influence the will.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 21","te":["emociones","voluntad"]},{"i":"john-locke-041","a":"john-locke","t":"El bien que reconocemos como infinitamente mayor suele quedar descuidado para satisfacer la inquietud sucesiva de deseos que persiguen nimiedades.","o":"the infinitely greatest confessed good being often neglected, to satisfy the successive uneasiness of our desires pursuing trifles.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 21","te":["deseo","sentido-de-vida"]},{"i":"john-locke-042","a":"john-locke","t":"Solo la inquietud determina la voluntad.","o":"it is uneasiness alone determines the will","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 21","te":["voluntad","deseo"]},{"i":"john-locke-043","a":"john-locke","t":"Las necesidades corrientes de la vida la llenan en gran parte con las inquietudes del hambre, la sed, el calor, el frío, el cansancio, el trabajo y el sueño, que vuelven una y otra vez.","o":"The ordinary necessities of our lives fill a great part of them with the uneasinesses of hunger, thirst, heat, cold, weariness, with labour, and sleepiness, in their constant returns","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 21","te":["cuerpo","existencia"]},{"i":"john-locke-050","a":"john-locke","t":"Los niños, aunque puedan tener ideas en el vientre materno, no tienen ninguna innata.","o":"Children, though they may have Ideas in the Womb, have none innate.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 9","te":["infancia","desarrollo-humano"]},{"i":"john-locke-044","a":"john-locke","t":"Por eso algunos, no solo niños sino también adultos, dicen muchas palabras como loros, solo porque las aprendieron y se acostumbraron a esos sonidos.","o":"therefore some, not only children but men, speak several words no otherwise than parrots do, only because they have learned them, and have been accustomed to those sounds.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 2","an":"1690","u":"Libro 3, cap. 2","te":["comunicacion","habitos"]},{"i":"john-locke-045","a":"john-locke","t":"Es evidente cuánto les gusta a las personas engañar y ser engañadas.","o":"It is evident how much men love to deceive and be deceived","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 2","an":"1690","u":"Libro 3, cap. 10","te":["verdad","comunicacion"]},{"i":"john-locke-046","a":"john-locke","t":"Las ideas de la nodriza y de la madre están bien formadas en su mente [de los niños] y, como retratos, representan solo a esas personas.","o":"The ideas of the nurse and the mother are well framed in their minds; and, like pictures of them there, represent only those individuals.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 2","an":"1690","u":"Libro 3, cap. 3","te":["infancia","familia","desarrollo-humano"]},{"i":"john-locke-047","a":"john-locke","t":"La experiencia nos convence de que tenemos un conocimiento intuitivo de nuestra propia existencia, una percepción interna e infalible de que somos.","o":"Experience then convinces us, that we have an INTUITIVE KNOWLEDGE of our own existence, and an internal infallible perception that we are.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 2","an":"1690","u":"Libro 4, cap. 9","te":["conciencia","existencia"]},{"i":"john-locke-048","a":"john-locke","t":"En esta parte debemos apoyarnos en la experiencia.","o":"Experience is that which in this part we must depend on.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 2","an":"1690","u":"Libro 4, cap. 3","te":["conocimiento"]},{"i":"john-locke-049","a":"john-locke","t":"Porque muchas palabras se aprenden antes de conocer las ideas que representan.","o":"because words are many of them learned before the ideas are known for which they stand","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 2","an":"1690","u":"Libro 3, cap. 2","te":["comunicacion","infancia"]},{"i":"buda-001","a":"buda","t":"Todo lo que somos es el resultado de lo que hemos pensado: está fundado en nuestros pensamientos, está hecho de nuestros pensamientos.","o":"All that we are is the result of what we have thought: it is founded on our thoughts, it is made up of our thoughts.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 1","te":["conciencia","identidad"]},{"i":"buda-002","a":"buda","t":"El odio nunca cesa con el odio: el odio cesa con el amor. Esta es una ley antigua.","o":"For hatred does not cease by hatred at any time: hatred ceases by love, this is an old rule.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 1, verso 5","te":["ira","amor","compasion"]},{"i":"buda-003","a":"buda","t":"El mundo no sabe que todos hemos de terminar aquí; pero quienes lo saben, dejan enseguida de pelear.","o":"The world does not know that we must all come to an end here;--but those who know it, their quarrels cease at once.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 1, verso 6","te":["muerte","vinculos"]},{"i":"buda-004","a":"buda","t":"Quienes imaginan verdad en lo falso y ven falsedad en lo verdadero nunca llegan a la verdad: siguen deseos vanos.","o":"They who imagine truth in untruth, and see untruth in truth, never arrive at truth, but follow vain desires.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 1, verso 11","te":["verdad","deseo"]},{"i":"buda-005","a":"buda","t":"Así como la lluvia no atraviesa una casa bien techada, la pasión no atraviesa una mente que reflexiona.","o":"As rain does not break through a well-thatched house, passion will not break through a well-reflecting mind.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 1, verso 14","te":["regulacion-emocional","conciencia"]},{"i":"buda-006","a":"buda","t":"Despertándose, con empeño, con mesura y dominio de sí, el sabio puede hacerse una isla que ninguna inundación logre cubrir.","o":"By rousing himself, by earnestness, by restraint and control, the wise man may make for himself an island which no flood can overwhelm.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 2, verso 25","te":["resiliencia","autoconocimiento"]},{"i":"buda-007","a":"buda","t":"Atento entre los distraídos, despierto entre los dormidos, el sabio avanza como un caballo de carrera que deja atrás al rocín.","o":"Earnest among the thoughtless, awake among the sleepers, the wise man advances like a racer, leaving behind the hack.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 2, verso 29","te":["atencion","presencia"]},{"i":"buda-008","a":"buda","t":"Es bueno domar la mente, difícil de sujetar y voluble, que corre adonde se le antoja: una mente domada trae felicidad.","o":"It is good to tame the mind, which is difficult to hold in and flighty, rushing wherever it listeth; a tamed mind brings happiness.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 3, verso 35","te":["atencion","felicidad","regulacion-emocional"]},{"i":"buda-009","a":"buda","t":"Que el sabio cuide sus pensamientos, porque son difíciles de percibir, muy astutos, y corren adonde quieren: los pensamientos bien cuidados traen felicidad.","o":"Let the wise man guard his thoughts, for they are difficult to perceive, very artful, and they rush wherever they list: thoughts well guarded bring happiness.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 3, verso 36","te":["conciencia","atencion"]},{"i":"buda-010","a":"buda","t":"Lo que un enemigo pueda hacerle a otro enemigo, más daño nos hará una mente mal dirigida.","o":"Whatever a hater may do to a hater, or an enemy to an enemy, a wrongly-directed mind will do us greater mischief.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 3, verso 42","te":["conciencia","sufrimiento"]},{"i":"buda-011","a":"buda","t":"Ni una madre, ni un padre, ni ningún otro pariente harán tanto por nosotros como una mente bien dirigida.","o":"Not a mother, not a father will do so much, nor any other relative; a well-directed mind will do us greater service.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 3, verso 43","te":["conciencia","familia"]},{"i":"buda-012","a":"buda","t":"No las faltas de los otros, ni lo que hicieron o dejaron de hacer: el sabio debe fijarse en sus propios errores y descuidos.","o":"Not the perversities of others, not their sins of commission or omission, but his own misdeeds and negligences should a sage take notice of.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 4, verso 50","te":["autoconocimiento","responsabilidad"]},{"i":"buda-013","a":"buda","t":"Como una flor hermosa, llena de color pero sin perfume, son las palabras bellas y estériles de quien no actúa en consecuencia.","o":"Like a beautiful flower, full of colour, but without scent, are the fine but fruitless words of him who does not act accordingly.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 4, verso 51","te":["autenticidad","comunicacion"]},{"i":"buda-014","a":"buda","t":"Si un caminante no encuentra a alguien mejor o igual que él, que siga con firmeza su camino solitario: no hay compañía posible con un necio.","o":"If a traveller does not meet with one who is his better, or his equal, let him firmly keep to his solitary journey; there is no companionship with a fool.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 5, verso 61","te":["soledad","vinculos"]},{"i":"buda-015","a":"buda","t":"El necio que conoce su necedad es, al menos en eso, sabio. Pero el necio que se cree sabio es un necio de verdad.","o":"The fool who knows his foolishness, is wise at least so far. But a fool who thinks himself wise, he is called a fool indeed.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 5, verso 63","te":["autoconocimiento","conocimiento"]},{"i":"buda-016","a":"buda","t":"Como una roca firme no se mueve con el viento, los sabios no vacilan entre la crítica y el elogio.","o":"As a solid rock is not shaken by the wind, wise people falter not amidst blame and praise.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 6, verso 81","te":["resiliencia","autoestima"]},{"i":"buda-017","a":"buda","t":"Los sabios, después de escuchar la enseñanza, se vuelven serenos como un lago profundo, liso y quieto.","o":"Wise people, after they have listened to the laws, become serene, like a deep, smooth, and still lake.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 6, verso 82","te":["silencio","presencia"]},{"i":"buda-018","a":"buda","t":"Si uno vence en batalla mil veces a mil hombres, y otro se vence a sí mismo, este es el mayor de los vencedores.","o":"If one man conquer in battle a thousand times thousand men, and if another conquer himself, he is the greatest of conquerors.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 8, verso 103","te":["autoconocimiento","regulacion-emocional"]},{"i":"buda-019","a":"buda","t":"Si alguien obra mal, que no lo repita ni se complazca en ello: el dolor es el fruto del mal.","o":"If a man commits a sin, let him not do it again; let him not delight in sin: pain is the outcome of evil.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 9, verso 117","te":["responsabilidad","habitos"]},{"i":"buda-020","a":"buda","t":"Si alguien obra bien, que lo repita y se alegre en ello: la felicidad es el fruto del bien.","o":"If a man does what is good, let him do it again; let him delight in it: happiness is the outcome of good.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 9, verso 118","te":["habitos","felicidad"]},{"i":"buda-021","a":"buda","t":"Gota a gota se llena un cántaro.","o":"Even by the falling of water-drops a water-pot is filled","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 9, verso 121","te":["habitos","cambio"]},{"i":"buda-022","a":"buda","t":"Quien aprendió poco envejece como un buey: crece su carne, pero no su conocimiento.","o":"A man who has learnt little, grows old like an ox; his flesh grows, but his knowledge does not grow.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 11, verso 152","te":["educacion","desarrollo-humano"]},{"i":"buda-023","a":"buda","t":"Que cada uno se encamine primero hacia lo correcto y después enseñe a otros: así el sabio no sufrirá.","o":"Let each man direct himself first to what is proper, then let him teach others; thus a wise man will not suffer.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 12, verso 158","te":["autenticidad","educacion"]},{"i":"buda-024","a":"buda","t":"Uno mismo es dueño de sí: ¿quién más podría serlo? Con uno mismo bien dominado, se encuentra un señor como pocos encuentran.","o":"Self is the lord of self, who else could be the lord? With self well subdued, a man finds a lord such as few can find.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 12, verso 160","te":["autoconocimiento","libertad"]},{"i":"buda-025","a":"buda","t":"Lo malo y lo que nos daña es fácil de hacer; lo beneficioso y bueno es muy difícil.","o":"Bad deeds, and deeds hurtful to ourselves, are easy to do; what is beneficial and good, that is very difficult to do.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 12, verso 163","te":["habitos","voluntad"]},{"i":"buda-026","a":"buda","t":"Por uno mismo se hace el mal, por uno mismo se sufre; por uno mismo se deja de hacerlo, por uno mismo uno se purifica.","o":"By oneself the evil is done, by oneself one suffers; by oneself evil is left undone, by oneself one is purified.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 12, verso 165","te":["responsabilidad","transformacion-personal"]},{"i":"buda-027","a":"buda","t":"Mirá el mundo como una burbuja, miralo como un espejismo.","o":"Look upon the world as a bubble, look upon it as a mirage","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 13, verso 170","te":["existencia","cambio"]},{"i":"buda-028","a":"buda","t":"No hacer ningún mal, hacer el bien y purificar la propia mente: esa es la enseñanza de todos los Despiertos.","o":"Not to commit any sin, to do good, and to purify one's mind, that is the teaching of (all) the Awakened.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 14, verso 183","te":["trascendencia","conciencia"]},{"i":"buda-029","a":"buda","t":"No hay manera de saciar los deseos, ni siquiera con una lluvia de monedas de oro.","o":"There is no satisfying lusts, even by a shower of gold pieces","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 14, verso 186","te":["deseo","felicidad"]},{"i":"buda-030","a":"buda","t":"La victoria engendra odio, porque el vencido es desdichado. Quien renunció a la victoria y a la derrota, ese, el contento, es feliz.","o":"Victory breeds hatred, for the conquered is unhappy. He who has given up both victory and defeat, he, the contented, is happy.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 15, verso 201","te":["felicidad","ira","vinculos"]},{"i":"buda-031","a":"buda","t":"La salud es el mayor de los dones; el contento, la mejor riqueza; la confianza, el mejor de los vínculos; el nirvana, la felicidad suprema.","o":"Health is the greatest of gifts, contentedness the best riches; trust is the best of relationships, Nirvana the highest happiness.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 15, verso 204","te":["felicidad","vinculos","cuerpo"]},{"i":"buda-032","a":"buda","t":"Quien probó la dulzura de la soledad y la calma queda libre del miedo y del mal.","o":"He who has tasted the sweetness of solitude and tranquillity, is free from fear and free from sin","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 15, verso 205","te":["soledad","silencio","miedo"]},{"i":"buda-033","a":"buda","t":"Del apego nace la pena, del apego nace el miedo; quien está libre del apego no conoce la pena ni el miedo.","o":"From love comes grief, from love comes fear; he who is free from love knows neither grief nor fear.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 16, verso 215","te":["amor","duelo","miedo"]},{"i":"buda-034","a":"buda","t":"A quien frena la ira que surge como a un carro desbocado, a ese llamo verdadero conductor; los demás solo sostienen las riendas.","o":"He who holds back rising anger like a rolling chariot, him I call a real driver; other people are but holding the reins.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 17, verso 222","te":["ira","regulacion-emocional"]},{"i":"buda-035","a":"buda","t":"Que se venza la ira con amor, el mal con el bien, la avaricia con generosidad y la mentira con la verdad.","o":"Let a man overcome anger by love, let him overcome evil by good; let him overcome the greedy by liberality, the liar by truth!","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 17, verso 223","te":["ira","compasion","verdad"]},{"i":"buda-036","a":"buda","t":"Decí la verdad, no cedas a la ira; da, aunque te pidan poco.","o":"Speak the truth, do not yield to anger; give, if thou art asked for little","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 17, verso 224","te":["verdad","ira"]},{"i":"buda-037","a":"buda","t":"No hubo, no habrá ni hay ahora nadie que sea siempre criticado, ni nadie que sea siempre elogiado.","o":"There never was, there never will be, nor is there now, a man who is always blamed, or a man who is always praised.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 17, verso 228","te":["autoestima","aceptacion"]},{"i":"buda-038","a":"buda","t":"Hacete una isla, trabajá con empeño, sé sabio.","o":"Make thyself an island, work hard, be wise!","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 18, verso 236","te":["resiliencia","autoconocimiento"]},{"i":"buda-039","a":"buda","t":"La falta ajena se ve con facilidad; la propia, con dificultad.","o":"The fault of others is easily perceived, but that of oneself is difficult to perceive","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 18, verso 252","te":["autoconocimiento","vinculos"]},{"i":"buda-040","a":"buda","t":"Si alguien vive pendiente de las faltas de los demás y siempre dispuesto a ofenderse, sus propias pasiones crecerán.","o":"If a man looks after the faults of others, and is always inclined to be offended, his own passions will grow","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 18, verso 253","te":["ira","autoconocimiento"]},{"i":"buda-041","a":"buda","t":"Nadie es sabio por hablar mucho; sabio es quien es paciente y está libre de odio y de miedo.","o":"A man is not learned because he talks much; he who is patient, free from hatred and fear, he is called learned.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 19, verso 258","te":["conocimiento","miedo"]},{"i":"buda-042","a":"buda","t":"Vos mismo tenés que hacer el esfuerzo. Los Budas solo enseñan el camino.","o":"You yourself must make an effort. The Tathagatas (Buddhas) are only preachers.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 20, verso 276","te":["responsabilidad","transformacion-personal"]},{"i":"buda-043","a":"buda","t":"“Todo lo creado perece”: quien sabe y ve esto se vuelve sereno ante el dolor.","o":"'All created things perish,' he who knows and sees this becomes passive in pain","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 20, verso 277","te":["cambio","aceptacion","sufrimiento"]},{"i":"buda-044","a":"buda","t":"Con dedicación se gana el conocimiento; sin ella, se pierde.","o":"Through zeal knowledge is gotten, through lack of zeal knowledge is lost","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 20, verso 282","te":["educacion","habitos"]},{"i":"buda-045","a":"buda","t":"Si algo debe hacerse, que se haga, y con decisión.","o":"If anything is to be done, let a man do it, let him attack it vigorously!","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 22, verso 313","te":["voluntad","responsabilidad"]},{"i":"buda-046","a":"buda","t":"Esta mente mía andaba antes errante por donde quería, como se le antojaba, como le placía.","o":"This mind of mine went formerly wandering about as it liked, as it listed, as it pleased","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 23, verso 326","te":["atencion","conciencia"]},{"i":"buda-047","a":"buda","t":"No seas descuidado, vigilá tus pensamientos. Salí del mal camino como un elefante hundido en el barro.","o":"Be not thoughtless, watch your thoughts! Draw yourself out of the evil way, like an elephant sunk in mud.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 23, verso 327","te":["atencion","cambio"]},{"i":"buda-048","a":"buda","t":"Soltá lo que está adelante, soltá lo que está atrás, soltá lo que está en el medio.","o":"Give up what is before, give up what is behind, give up what is in the middle","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 24, verso 348","te":["aceptacion","presencia"]},{"i":"buda-049","a":"buda","t":"Sin conocimiento no hay meditación; sin meditación no hay conocimiento.","o":"Without knowledge there is no meditation, without meditation there is no knowledge","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 25, verso 372","te":["conocimiento","silencio"]},{"i":"buda-050","a":"buda","t":"Despertate por vos mismo, examinate por vos mismo: así, protegido por vos mismo y atento, vivirás feliz.","o":"Rouse thyself by thyself, examine thyself by thyself, thus self-protected and attentive wilt thou live happily","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 25, verso 379","te":["autoconocimiento","atencion","felicidad"]},{"i":"buda-051","a":"buda","t":"Que nadie menosprecie el bien diciéndose: “No llegará a mí”.","o":"Let no man think lightly of good, saying in his heart, It will not come nigh unto me.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 9, verso 122","te":["esperanza","habitos"]},{"i":"buda-052","a":"buda","t":"Como un pez sacado del agua y arrojado a tierra seca, nuestro pensamiento tiembla por entero.","o":"As a fish taken from his watery home and thrown on dry ground, our thought trembles all over","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 3, verso 34","te":["angustia","conciencia"]},{"i":"lao-tse-001","a":"lao-tse","t":"El Tao que puede recorrerse no es el Tao permanente e inmutable. El nombre que puede nombrarse no es el nombre permanente e inmutable.","o":"The Tao that can be trodden is not the enduring and unchanging Tao. The name that can be named is not the enduring and unchanging name.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 1","te":["trascendencia","conocimiento"]},{"i":"lao-tse-002","a":"lao-tse","t":"Todos en el mundo conocen la belleza de lo bello, y al hacerlo ya tienen la idea de lo feo.","o":"All in the world know the beauty of the beautiful, and in doing this they have (the idea of) what ugliness is","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 2","te":["conocimiento","existencia"]},{"i":"lao-tse-003","a":"lao-tse","t":"Deberíamos limar nuestras aristas y desenredar las complicaciones de las cosas.","o":"We should blunt our sharp points, and unravel the complications of things","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 4","te":["aceptacion","vinculos"]},{"i":"lao-tse-004","a":"lao-tse","t":"Por eso el sabio se pone en último lugar, y sin embargo se encuentra en el primero.","o":"Therefore the sage puts his own person last, and yet it is found in the foremost place","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 7","te":["poder","autenticidad"]},{"i":"lao-tse-005","a":"lao-tse","t":"La excelencia más alta es como la del agua.","o":"The highest excellence is like (that of) water.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 8","te":["naturaleza","aceptacion"]},{"i":"lao-tse-006","a":"lao-tse","t":"La excelencia del agua está en que beneficia a todas las cosas y ocupa, sin disputar, el lugar bajo que todos desprecian.","o":"The excellence of water appears in its benefiting all things, and in its occupying, without striving (to the contrary), the low place which all men dislike.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 8","te":["naturaleza","compasion"]},{"i":"lao-tse-007","a":"lao-tse","t":"La excelencia de la mente está en su quietud profunda.","o":"that of the mind is in abysmal stillness","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 8","te":["silencio","conciencia"]},{"i":"lao-tse-008","a":"lao-tse","t":"Es mejor dejar una vasija sin llenar que intentar llevarla cuando está colmada.","o":"It is better to leave a vessel unfilled, than to attempt to carry it when it is full.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 9","te":["deseo","aceptacion"]},{"i":"lao-tse-009","a":"lao-tse","t":"Cuando la obra está hecha y el nombre empieza a destacarse, retirarse a la sombra es el camino del cielo.","o":"When the work is done, and one's name is becoming distinguished, to withdraw into obscurity is the way of Heaven.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 9","te":["trabajo","poder"]},{"i":"lao-tse-010","a":"lao-tse","t":"Los treinta rayos se unen en un solo cubo; pero del espacio vacío depende la utilidad de la rueda.","o":"The thirty spokes unite in the one nave; but it is on the empty space (for the axle), that the use of the wheel depends.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 10","te":["silencio","existencia"]},{"i":"lao-tse-011","a":"lao-tse","t":"Cuando las plantas despliegan su crecimiento exuberante, vemos a cada una volver a su raíz.","o":"When things (in the vegetable world) have displayed their luxuriant growth, we see each of them return to its root.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 16","te":["naturaleza","cambio"]},{"i":"lao-tse-012","a":"lao-tse","t":"Este volver a la raíz es lo que llamamos quietud.","o":"This returning to their root is what we call the state of stillness","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 16","te":["silencio","presencia"]},{"i":"lao-tse-013","a":"lao-tse","t":"Lo parcial se vuelve completo; lo torcido, recto; lo vacío, lleno; lo gastado, nuevo.","o":"The partial becomes complete; the crooked, straight; the empty, full; the worn out, new.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 22","te":["cambio","esperanza"]},{"i":"lao-tse-014","a":"lao-tse","t":"No se exhibe, y por eso brilla.","o":"He is free from self-display, and therefore he shines","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 22","te":["autenticidad","autoestima"]},{"i":"lao-tse-015","a":"lao-tse","t":"Un viento violento no dura toda la mañana; un aguacero repentino no dura todo el día.","o":"A violent wind does not last for a whole morning; a sudden rain does not last for the whole day.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 23","te":["cambio","regulacion-emocional","naturaleza"]},{"i":"lao-tse-016","a":"lao-tse","t":"Quien se pone en puntas de pie no está firme; quien estira las piernas no camina con soltura.","o":"He who stands on his tiptoes does not stand firm; he who stretches his legs does not walk (easily).","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 23","te":["autenticidad","aceptacion"]},{"i":"lao-tse-017","a":"lao-tse","t":"La gravedad es la raíz de la ligereza; la quietud, la que gobierna el movimiento.","o":"Gravity is the root of lightness; stillness, the ruler of movement.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 26","te":["silencio","presencia"]},{"i":"lao-tse-018","a":"lao-tse","t":"El buen viajero no deja huellas de sus ruedas ni de sus pasos.","o":"The skilful traveller leaves no traces of his wheels or footsteps","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 27","te":["presencia","naturaleza"]},{"i":"lao-tse-019","a":"lao-tse","t":"Quien conoce a los demás es perspicaz; quien se conoce a sí mismo es sabio. Quien vence a otros es fuerte; quien se vence a sí mismo es poderoso.","o":"He who knows other men is discerning; he who knows himself is intelligent. He who overcomes others is strong; he who overcomes himself is mighty.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 33","te":["autoconocimiento","poder"]},{"i":"lao-tse-020","a":"lao-tse","t":"Quien está conforme con lo que tiene es rico.","o":"He who is satisfied with his lot is rich","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 33","te":["felicidad","deseo","aceptacion"]},{"i":"lao-tse-021","a":"lao-tse","t":"Lo blando vence a lo duro; lo débil, a lo fuerte.","o":"The soft overcomes the hard; and the weak the strong.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 36","te":["resiliencia","naturaleza"]},{"i":"lao-tse-022","a":"lao-tse","t":"El movimiento del Tao procede por contrarios.","o":"The movement of the Tao By contraries proceeds","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 40","te":["cambio","trascendencia"]},{"i":"lao-tse-023","a":"lao-tse","t":"Lo más blando del mundo choca contra lo más duro y lo vence.","o":"The softest thing in the world dashes against and overcomes the hardest","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 43","te":["resiliencia"]},{"i":"lao-tse-024","a":"lao-tse","t":"Quien está contento no teme la vergüenza. Quien sabe detenerse no incurre en culpa.","o":"Who is content Needs fear no shame. Who knows to stop Incurs no blame.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 44","te":["aceptacion","deseo"]},{"i":"lao-tse-025","a":"lao-tse","t":"No hay culpa mayor que consentir la ambición, ni calamidad mayor que no estar conforme con lo que uno tiene, ni falta mayor que el deseo de obtener.","o":"There is no guilt greater than to sanction ambition; no calamity greater than to be discontented with one's lot; no fault greater than the wish to be getting.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 46","te":["deseo","felicidad"]},{"i":"lao-tse-026","a":"lao-tse","t":"Por eso la suficiencia del contento es una suficiencia duradera e inmutable.","o":"Therefore the sufficiency of contentment is an enduring and unchanging sufficiency.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 46","te":["felicidad","aceptacion"]},{"i":"lao-tse-027","a":"lao-tse","t":"Cuanto más lejos va uno, fuera de sí, menos sabe.","o":"The farther that one goes out (from himself), the less he knows.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 47","te":["autoconocimiento","conocimiento"]},{"i":"lao-tse-028","a":"lao-tse","t":"Quien se dedica al estudio busca aumentar cada día su saber; quien se dedica al Tao busca disminuir cada día su hacer.","o":"He who devotes himself to learning (seeks) from day to day to increase (his knowledge); he who devotes himself to the Tao (seeks) from day to day to diminish (his doing).","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 48","te":["conocimiento","trascendencia"]},{"i":"lao-tse-029","a":"lao-tse","t":"Con quienes son buenos conmigo soy bueno; con quienes no lo son, también soy bueno: y así todos llegan a ser buenos.","o":"To those who are good (to me), I am good; and to those who are not good (to me), I am also good;--and thus (all) get to be good.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 49","te":["compasion","vinculos"]},{"i":"lao-tse-030","a":"lao-tse","t":"Quien conoce el Tao no se preocupa por hablar de él; quien siempre está dispuesto a hablar de él no lo conoce.","o":"He who knows (the Tao) does not (care to) speak (about it); he who is (ever ready to) speak about it does not know it.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 56","te":["silencio","conocimiento"]},{"i":"lao-tse-031","a":"lao-tse","t":"¡La desdicha! A su lado se encuentra la dicha. ¡La dicha! Debajo acecha la desdicha. ¿Quién sabe en qué terminará cada una?","o":"Misery!--happiness is to be found by its side! Happiness!--misery lurks beneath it! Who knows what either will come to in the end?","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 58","te":["felicidad","sufrimiento","incertidumbre"]},{"i":"lao-tse-032","a":"lao-tse","t":"No hay nada como la moderación.","o":"there is nothing like moderation","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 59","te":["habitos"]},{"i":"lao-tse-033","a":"lao-tse","t":"Gobernar un gran Estado es como cocinar pescados pequeños.","o":"Governing a great state is like cooking small fish.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 60","te":["poder","sociedad"]},{"i":"lao-tse-034","a":"lao-tse","t":"Y responder a la ofensa con bondad.","o":"and to recompense injury with kindness","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 63","te":["compasion","ira"]},{"i":"lao-tse-035","a":"lao-tse","t":"El árbol que llena los brazos nació de un brote diminuto; la torre de nueve pisos se levantó de un montón de tierra; el viaje de mil li empezó con un solo paso.","o":"The tree which fills the arms grew from the tiniest sprout; the tower of nine storeys rose from a (small) heap of earth; the journey of a thousand li commenced with a single step.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 64","te":["cambio","habitos","esperanza"]},{"i":"lao-tse-036","a":"lao-tse","t":"Hay que actuar antes de que algo aparezca; hay que poner orden antes de que empiece el desorden.","o":"Action should be taken before a thing has made its appearance; order should be secured before disorder has begun.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 64","te":["responsabilidad"]},{"i":"lao-tse-037","a":"lao-tse","t":"Los ríos y los mares reciben el tributo de todos los arroyos del valle porque saben estar más abajo que ellos.","o":"That whereby the rivers and seas are able to receive the homage and tribute of all the valley streams, is their skill in being lower than they","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 66","te":["poder","naturaleza"]},{"i":"lao-tse-038","a":"lao-tse","t":"Tengo tres tesoros que aprecio y conservo: el primero es la bondad; el segundo, la sobriedad; el tercero, no querer ponerme por delante de los demás.","o":"But I have three precious things which I prize and hold fast. The first is gentleness; the second is economy; and the third is shrinking from taking precedence of others.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 67","te":["compasion","autenticidad"]},{"i":"lao-tse-039","a":"lao-tse","t":"Con esa bondad puedo ser valiente.","o":"With that gentleness I can be bold","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 67","te":["compasion","miedo"]},{"i":"lao-tse-040","a":"lao-tse","t":"Saber y pensar que no sabemos es lo más alto; no saber y creer que sabemos es una enfermedad.","o":"To know and yet (think) we do not know is the highest (attainment); not to know (and yet think) we do know is a disease.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 71","te":["conocimiento","autoconocimiento"]},{"i":"lao-tse-041","a":"lao-tse","t":"Al nacer, el ser humano es flexible y débil; al morir, rígido y duro.","o":"Man at his birth is supple and weak; at his death, firm and strong.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 76","te":["muerte","cuerpo"]},{"i":"lao-tse-042","a":"lao-tse","t":"Así, la rigidez y la dureza acompañan a la muerte; la flexibilidad y la suavidad acompañan a la vida.","o":"Thus it is that firmness and strength are the concomitants of death; softness and weakness, the concomitants of life.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 76","te":["resiliencia","muerte"]},{"i":"lao-tse-043","a":"lao-tse","t":"No hay nada en el mundo más blando y débil que el agua, y sin embargo, para vencer lo firme y lo fuerte, nada la supera.","o":"There is nothing in the world more soft and weak than water, and yet for attacking things that are firm and strong there is nothing that can take precedence of it","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 78","te":["resiliencia","naturaleza"]},{"i":"lao-tse-044","a":"lao-tse","t":"Todos en el mundo saben que lo blando vence a lo duro y lo débil a lo fuerte, pero nadie es capaz de llevarlo a la práctica.","o":"Every one in the world knows that the soft overcomes the hard, and the weak the strong, but no one is able to carry it out in practice.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 78","te":["conocimiento","habitos"]},{"i":"lao-tse-045","a":"lao-tse","t":"Cuando dos partes se reconcilian después de una gran enemistad, siempre queda algún rencor.","o":"When a reconciliation is effected (between two parties) after a great animosity, there is sure to be a grudge remaining","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 79","te":["vinculos","ira"]},{"i":"lao-tse-046","a":"lao-tse","t":"Las palabras sinceras no son bellas; las palabras bellas no son sinceras.","o":"Sincere words are not fine; fine words are not sincere.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 81","te":["autenticidad","comunicacion"]},{"i":"lao-tse-047","a":"lao-tse","t":"Cuanto más da a los demás, más posee.","o":"The more that he expends for others, the more does he possess of his own","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 81","te":["compasion","vinculos"]},{"i":"lao-tse-048","a":"lao-tse","t":"Mis palabras son muy fáciles de entender y muy fáciles de practicar; pero nadie en el mundo es capaz de entenderlas y practicarlas.","o":"My words are very easy to know, and very easy to practise; but there is no one in the world who is able to know and able to practise them.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 70","te":["conocimiento","habitos"]},{"i":"lao-tse-049","a":"lao-tse","t":"La pureza y la quietud dan la norma justa a todo lo que existe bajo el cielo.","o":"Purity and stillness give the correct law to all under heaven.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 45","te":["silencio"]},{"i":"lao-tse-050","a":"lao-tse","t":"Quien presta atención indivisa a la respiración y la vuelve flexible al máximo puede ser como un niño pequeño.","o":"When one gives undivided attention to the (vital) breath, and brings it to the utmost degree of pliancy, he can become as a (tender) babe.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 10","te":["cuerpo","atencion","presencia"]},{"i":"lao-tse-051","a":"lao-tse","t":"Quien tiene en abundancia las virtudes del Tao es como un niño recién nacido.","o":"He who has in himself abundantly the attributes (of the Tao) is like an infant.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 55","te":["infancia","trascendencia"]},{"i":"lao-tse-052","a":"lao-tse","t":"El favor y la desgracia parecen igualmente temibles.","o":"Favour and disgrace would seem equally to be feared","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 13","te":["miedo","autoestima"]},{"i":"patanjali-001","a":"patanjali","t":"La unión, la conciencia espiritual, se alcanza mediante el dominio de la naturaleza psíquica cambiante.","o":"Union, spiritual consciousness, is gained through control of the versatile psychic nature.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 1, sutra 2","te":["conciencia","regulacion-emocional"]},{"i":"patanjali-002","a":"patanjali","t":"Entonces el que ve toma conciencia de su verdadera naturaleza.","o":"Then the Seer comes to consciousness in his proper nature.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 1, sutra 3","te":["conciencia","autoconocimiento"]},{"i":"patanjali-003","a":"patanjali","t":"El conocimiento erróneo es una comprensión falsa, que no se apoya en la percepción de la verdadera naturaleza de las cosas.","o":"Unsound intellection is false understanding, not resting on a perception of the true nature of things.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 1, sutra 8","te":["verdad","conocimiento"]},{"i":"patanjali-004","a":"patanjali","t":"La memoria es retener las imágenes mentales de lo percibido, sin modificarlas.","o":"Memory is holding to mind-images of things perceived, without modifying them.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 1, sutra 11","te":["memoria"]},{"i":"patanjali-005","a":"patanjali","t":"El dominio de estas actividades psíquicas llega con el buen uso de la voluntad y el abandono de la complacencia.","o":"The control of these psychic activities comes through the right use of the will, and through ceasing from self-indulgence.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 1, sutra 12","te":["voluntad","regulacion-emocional"]},{"i":"patanjali-006","a":"patanjali","t":"El buen uso de la voluntad es el esfuerzo sostenido por permanecer en el ser espiritual.","o":"The right use of the will is the steady, effort to stand in spiritual being.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 1, sutra 13","te":["voluntad","presencia"]},{"i":"patanjali-007","a":"patanjali","t":"Esto se vuelve un lugar firme de descanso cuando se lo sigue mucho tiempo, con constancia y con seriedad.","o":"This becomes a firm resting-place, when followed long, persistently, with earnestness.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 1, sutra 14","te":["habitos","presencia"]},{"i":"patanjali-008","a":"patanjali","t":"Abandonar la complacencia es el dominio consciente de la sed de placeres de los sentidos, aquí o en el más allá.","o":"Ceasing from self-indulgence is conscious mastery over the thirst for sensuous pleasure here or hereafter.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 1, sutra 15","te":["deseo","regulacion-emocional"]},{"i":"patanjali-009","a":"patanjali","t":"Para los demás, la conciencia espiritual llega a través de la fe, el valor, la atención correcta, la concentración y la percepción.","o":"For the others, there is spiritual consciousness, led up to by faith, valour, right mindfulness, one-pointedness, perception.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 1, sutra 20","te":["atencion","trascendencia"]},{"i":"patanjali-010","a":"patanjali","t":"La conciencia espiritual está más cerca de quienes tienen una voluntad viva e intensa.","o":"Spiritual consciousness is nearest to those of keen, intense will.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 1, sutra 21","te":["voluntad"]},{"i":"patanjali-011","a":"patanjali","t":"De ahí vienen el despertar de la conciencia interior y la remoción de los obstáculos.","o":"Thence come the awakening of interior consciousness, and the removal of barriers.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 1, sutra 29","te":["conciencia"]},{"i":"patanjali-012","a":"patanjali","t":"La pena, el desánimo, la inquietud del cuerpo y la respiración agitada también contribuyen a zarandear la naturaleza psíquica.","o":"Grieving, despondency, bodily restlessness, the drawing in and sending forth of the life-breath also contribute to drive the psychic nature to and fro.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 1, sutra 31","te":["tristeza","cuerpo","angustia"]},{"i":"patanjali-013","a":"patanjali","t":"La dedicación constante a un principio es la manera de detener estas perturbaciones.","o":"Steady application to a principle is the way to put a stop to these.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 1, sutra 32","te":["habitos","atencion"]},{"i":"patanjali-014","a":"patanjali","t":"Con simpatía hacia quien es feliz, compasión hacia quien sufre, alegría ante lo bueno e indiferencia ante lo malo, la naturaleza psíquica se encamina hacia una paz serena.","o":"By sympathy with the happy, compassion for the sorrowful, delight in the holy, disregard of the unholy, the psychic nature moves to gracious peace.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 1, sutra 33","te":["compasion","alegria","regulacion-emocional"]},{"i":"patanjali-015","a":"patanjali","t":"O la paz puede alcanzarse mediante la exhalación pareja y el dominio de la respiración.","o":"Or peace may be reached by the even sending forth and control of the life-breath.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 1, sutra 34","te":["cuerpo","presencia","regulacion-emocional"]},{"i":"patanjali-016","a":"patanjali","t":"La dedicación fiel y persistente a cualquier objeto, si se logra plenamente, fija la mente en la estabilidad.","o":"Faithful, persistent application to any object, if completely attained, will bind the mind to steadiness.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 1, sutra 35","te":["atencion","habitos"]},{"i":"patanjali-017","a":"patanjali","t":"Como también lo hace un espíritu alegre y luminoso.","o":"As also will a joyful, radiant spirit.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 1, sutra 36","te":["alegria"]},{"i":"patanjali-018","a":"patanjali","t":"O la meditación sobre lo que es más querido para el corazón.","o":"Or meditative brooding on what is dearest to the heart.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 1, sutra 39","te":["amor","atencion"]},{"i":"patanjali-019","a":"patanjali","t":"Cuando todas las perturbaciones de la naturaleza psíquica se aquietaron, la conciencia, como un cristal puro, toma el color de aquello sobre lo que se posa.","o":"When the perturbations of the psychic nature have all been stilled, then the consciousness, like a pure crystal, takes the colour of what it rests on","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 1, sutra 41","te":["conciencia","silencio"]},{"i":"patanjali-020","a":"patanjali","t":"Cuando se alcanza una percepción pura, sin el juicio de la mente, llega la paz serena del yo interior.","o":"When pure perception without judicial action of the mind is reached, there follows the gracious peace of the inner self.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 1, sutra 47","te":["presencia","aceptacion"]},{"i":"patanjali-021","a":"patanjali","t":"En esa paz, la percepción es infaliblemente verdadera.","o":"In that peace, perception is unfailingly true.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 1, sutra 48","te":["verdad","silencio"]},{"i":"patanjali-022","a":"patanjali","t":"Su fin es traer la visión del alma y desgastar los obstáculos.","o":"Their aim is, to bring soul-vision, and to wear away hindrances.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 2, sutra 2","te":["transformacion-personal"]},{"i":"patanjali-023","a":"patanjali","t":"La oscuridad de la ignorancia es el terreno de los demás obstáculos.","o":"The darkness of unwisdom is the field of the others.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 2, sutra 4","te":["conocimiento","sufrimiento"]},{"i":"patanjali-024","a":"patanjali","t":"La afirmación del ego proviene de pensar que el que ve y el instrumento con que ve forman un solo yo.","o":"Self-assertion comes from thinking of the Seer and the instrument of vision as forming one self.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 2, sutra 6","te":["identidad","conciencia"]},{"i":"patanjali-025","a":"patanjali","t":"El apego es detenerse en la sensación de placer.","o":"Lust is the resting in the sense of enjoyment.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 2, sutra 7","te":["deseo"]},{"i":"patanjali-026","a":"patanjali","t":"La aversión es detenerse en la sensación de dolor.","o":"Hate is the resting in the sense of pain.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 2, sutra 8","te":["ira","sufrimiento"]},{"i":"patanjali-027","a":"patanjali","t":"El aferrarse es el deseo de vivir, presente aun en los sabios, impulsado por su propia energía.","o":"Attachment is the desire toward life, even in the wise, carried forward by its own energy.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 2, sutra 9","te":["deseo","muerte"]},{"i":"patanjali-028","a":"patanjali","t":"Estos obstáculos, cuando se han vuelto sutiles, deben quitarse con una contracorriente.","o":"These hindrances, when they have become subtle, are to be removed by a countercurrent.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 2, sutra 10","te":["transformacion-personal"]},{"i":"patanjali-029","a":"patanjali","t":"Sus movimientos activos deben quitarse con la meditación.","o":"Their active turnings are to be removed by meditation.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 2, sutra 11","te":["silencio","regulacion-emocional"]},{"i":"patanjali-030","a":"patanjali","t":"La carga de estar atado al sufrimiento tiene su raíz en estos obstáculos.","o":"The burden of bondage to sorrow has its root in these hindrances.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 2, sutra 12","te":["sufrimiento"]},{"i":"patanjali-031","a":"patanjali","t":"Hay que evitar este dolor antes de que llegue.","o":"This pain is to be warded off, before it has come.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 2, sutra 16","te":["sufrimiento","responsabilidad"]},{"i":"patanjali-032","a":"patanjali","t":"La causa de lo que hay que evitar es que el que ve quede absorbido en lo visto.","o":"The cause of what is to be warded off, is the absorption of the Seer in things seen.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 2, sutra 17","te":["conciencia","identidad"]},{"i":"patanjali-033","a":"patanjali","t":"El que ve es visión pura.","o":"The Seer is pure vision.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 2, sutra 20","te":["conciencia"]},{"i":"patanjali-034","a":"patanjali","t":"Un discernimiento sostenido sin vacilar es el medio de la liberación.","o":"A discerning which is carried on without wavering is the means of liberation.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 2, sutra 26","te":["libertad","conocimiento"]},{"i":"patanjali-035","a":"patanjali","t":"Cuando las faltas estorban, hay que poner el peso de la imaginación del lado opuesto.","o":"When transgressions hinder, the weight of the imagination should be thrown' on the opposite side.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 2, sutra 33","te":["regulacion-emocional","habitos"]},{"i":"patanjali-036","a":"patanjali","t":"Donde la no violencia está perfeccionada, toda enemistad cesa en presencia de quien la posee.","o":"Where non-injury is perfected, all enmity ceases in the presence of him who possesses it.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 2, sutra 35","te":["compasion","vinculos"]},{"i":"patanjali-037","a":"patanjali","t":"Quien ha vencido con firmeza la codicia despierta al cómo y al porqué de la vida.","o":"Where there is firm conquest of covetousness, he who has conquered it awakes to the how and why of life.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 2, sutra 39","te":["deseo","sentido-de-vida"]},{"i":"patanjali-038","a":"patanjali","t":"A los puros de corazón les llegan también un espíritu sereno, un pensamiento concentrado y la aptitud para contemplar el alma.","o":"To the pure of heart come also a quiet spirit, one-pointed thought, the victory over sensuality, and fitness to behold the Soul.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 2, sutra 41","te":["silencio","atencion"]},{"i":"patanjali-039","a":"patanjali","t":"De la aceptación, el discípulo obtiene la felicidad suprema.","o":"From acceptance, the disciple gains happiness supreme.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 2, sutra 42","te":["aceptacion","felicidad"]},{"i":"patanjali-040","a":"patanjali","t":"La postura correcta debe ser firme y sin tensión.","o":"Right poise must be firm and without strain.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 2, sutra 46","te":["cuerpo","presencia"]},{"i":"patanjali-041","a":"patanjali","t":"La postura correcta se logra con un esfuerzo constante y moderado, y poniendo el corazón en lo eterno.","o":"Right poise is to be gained by steady and temperate effort, and by setting the heart upon the everlasting.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 2, sutra 47","te":["cuerpo","habitos"]},{"i":"patanjali-042","a":"patanjali","t":"El fruto de la postura correcta es la fuerza para resistir los golpes del enamoramiento o de la pena.","o":"The fruit of right poise is the strength to resist the shocks of infatuation or sorrow.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 2, sutra 48","te":["resiliencia","regulacion-emocional"]},{"i":"patanjali-043","a":"patanjali","t":"Cuando se logra esto, sigue la buena conducción de las corrientes vitales: el dominio de la inspiración y la espiración.","o":"When this is gained, there follows the right guidance of the life-currents, the control of the incoming and outgoing breath.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 2, sutra 49","te":["cuerpo","regulacion-emocional"]},{"i":"patanjali-044","a":"patanjali","t":"De ahí viene el poder de la mente para sostenerse en la luz.","o":"Thence comes the mind's power to hold itself in the light.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 2, sutra 53","te":["atencion","conciencia"]},{"i":"patanjali-045","a":"patanjali","t":"El recogimiento correcto es desprender las capacidades de su enredo en las cosas exteriores.","o":"The right Withdrawal is the disengaging of the powers from entanglement in outer things","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 2, sutra 54","te":["silencio","atencion"]},{"i":"patanjali-046","a":"patanjali","t":"Sostener de manera prolongada la conciencia que percibe en ese punto es la meditación (dhyana).","o":"A prolonged holding of the perceiving consciousness in that region is meditation (dhyana).","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 3, sutra 2","te":["silencio","atencion"]},{"i":"patanjali-047","a":"patanjali","t":"Con la repetición frecuente de este proceso, la mente se habitúa y surge un flujo sereno de conciencia.","o":"Through frequent repetition of this process, the mind becomes habituated to it, and there arises an equable flow of perceiving consciousness.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 3, sutra 10","te":["habitos","atencion"]},{"i":"patanjali-048","a":"patanjali","t":"La conquista gradual de la tendencia de la mente a saltar de un objeto a otro, y la capacidad de concentrarse en uno, constituyen el desarrollo de la contemplación.","o":"The gradual conquest of the mind's tendency to flit from one object to another, and the power of one-pointedness, make the development of Contemplation.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 3, sutra 11","te":["atencion","presencia"]},{"i":"patanjali-049","a":"patanjali","t":"Con la meditación perfectamente concentrada en la simpatía, la compasión y la bondad se obtiene la capacidad de unirse interiormente con los demás.","o":"By perfectly concentrated Meditation on sympathy, compassion and kindness, is gained the power of interior union with others.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 3, sutra 23","te":["compasion","vinculos","empatia"]},{"i":"patanjali-050","a":"patanjali","t":"La serie de imágenes mentales dinámicas no tiene comienzo, porque el deseo es perpetuo.","o":"The series of dynamic mind-images is beginningless, because Desire is everlasting.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 4, sutra 10","te":["deseo","inconsciente"]},{"i":"patanjali-051","a":"patanjali","t":"Un objeto se percibe o no según que la mente esté o no teñida del color de ese objeto.","o":"An object is perceived, or not perceived, according as the mind is, or is not, tinged with the colour of the object.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 4, sutra 17","te":["atencion","conciencia"]},{"i":"patanjali-052","a":"patanjali","t":"Entonces llega el cese del sufrimiento y de la carga del esfuerzo.","o":"Thereon comes surcease from sorrow and the burden of toil.","l":"en","ob":"Yoga Sutras","an":"c. s. II a. C. – s. V","u":"Libro 4, sutra 30","te":["sufrimiento","esperanza"]},{"i":"sandor-ferenczi-001","a":"sandor-ferenczi","t":"El punto de partida de mis reflexiones sobre este tema fueron ciertas observaciones hechas en el psicoanálisis de la impotencia masculina.","o":"Den Ausgangspunkt meiner Überlegungen über diesen Gegenstand bildeten gewisse Beobachtungen bei der Psychoanalyse der Impotenz des Mannes.","l":"de","ob":"Ensayo de una teoría de la genitalidad","an":"1924","u":"","te":["sexualidad","terapia"]},{"i":"sandor-ferenczi-002","a":"sandor-ferenczi","t":"No haber observado esta regla en mis especulaciones fue una de las causas que me impidieron publicar la teoría de la genitalidad.","o":"Die Nichtbeobachtung dieser Regel in meiner Spekulation war eine der Ursachen, die mich abhielten, die Genitaltheorie zu veröffentlichen.","l":"de","ob":"Ensayo de una teoría de la genitalidad","an":"1924","u":"","te":["sexualidad","conocimiento"]},{"i":"sandor-ferenczi-003","a":"sandor-ferenczi","t":"El resultado es una supuesta sobrepotencia, que solo es satisfactoria para la mujer.","o":"Die Folge ist eine scheinbare Überpotenz, die aber nur für die Frau befriedigend ist.","l":"de","ob":"Ensayo de una teoría de la genitalidad","an":"1924","u":"","te":["sexualidad","vinculos"]},{"i":"sandor-ferenczi-004","a":"sandor-ferenczi","t":"¿De dónde saca, sin embargo, la fuerza para acatar las indicaciones de la madre y de la nodriza, y para vencer el derroche con la orina y la avaricia con las heces?","o":"Woher nimmt es aber die Kraft, den Weisungen der Mutter und Amme nachzukommen und die Verschwendung mit dem Harn, den Geiz mit dem Kote zu überwinden?","l":"de","ob":"Ensayo de una teoría de la genitalidad","an":"1924","u":"","te":["infancia","habitos","familia"]},{"i":"sandor-ferenczi-005","a":"sandor-ferenczi","t":"La observación de niños, por sí sola, aporta innumerables pruebas de su existencia.","o":"Die Kinderbeobachtung allein liefert zahllose Beweise für ihr Vorhandensein.","l":"de","ob":"Ensayo de una teoría de la genitalidad","an":"1924","u":"","te":["infancia","sexualidad"]},{"i":"sandor-ferenczi-006","a":"sandor-ferenczi","t":"Al niño y al adulto neurótico les resulta posible, exagerando, llevar las medidas educativas al absurdo.","o":"Es gelingt dem Kinde und dem neurotischen Erwachsenen, mittels Übertreibung die Erziehungsmaßnahmen ad absurdum zu führen.","l":"de","ob":"Ensayo de una teoría de la genitalidad","an":"1924","u":"","te":["infancia","educacion","salud-mental"]},{"i":"sandor-ferenczi-007","a":"sandor-ferenczi","t":"Este caso nos muestra que la conocida asociación entre erotismo anal y oral, el comer excrementos, pretende compensar el dolor de la pérdida anal con el placer de la incorporación oral.","o":"Dieser Fall zeigt uns, daß die beliebte Verknüpfung der Anal- mit der Oralerotik, das Kotessen, den Schmerz des analen Verlustes durch die Lust der Oral-Einverleibung wettmachen möchte.","l":"de","ob":"Ensayo de una teoría de la genitalidad","an":"1924","u":"","te":["sexualidad","perdida","infancia"]},{"i":"sandor-ferenczi-008","a":"sandor-ferenczi","t":"Pero esta analogía tampoco es casual, ya que el síntoma histérico, como lo prueban innumerables observaciones psicoanalíticas, siempre imita de algún modo la función genital.","o":"Aber auch diese Analogie ist keine zufällige, da doch das hysterische Symptom, wie es uns unzählige psychoanalytische Beobachtungen beweisen, irgendwie immer der Genitalfunktion nachgebildet ist.","l":"de","ob":"Ensayo de una teoría de la genitalidad","an":"1924","u":"","te":["sexualidad","salud-mental"]},{"i":"sandor-ferenczi-009","a":"sandor-ferenczi","t":"Las funciones de excreción están, por ahora, totalmente sin control, y la actividad del recién nacido se limita sobre todo a succionar el pecho materno.","o":"Die Ausscheidungsfunktionen sind einstweilen vollständig unbeherrscht, und die aktive Tätigkeit des Neugeborenen beschränkt sich wesentlich auf das Saugen an der Mutterbrust.","l":"de","ob":"Ensayo de una teoría de la genitalidad","an":"1924","u":"","te":["infancia","cuerpo"]},{"i":"sandor-ferenczi-010","a":"sandor-ferenczi","t":"Pero incluso este primer objeto de amor se le impone al niño, al principio, por parte de la madre.","o":"Doch selbst dieses erste Liebesobjekt wird dem Kinde ursprünglich zunächst von der Mutter aufgedrängt","l":"de","ob":"Ensayo de una teoría de la genitalidad","an":"1924","u":"","te":["infancia","amor","familia"]},{"i":"sandor-ferenczi-011","a":"sandor-ferenczi","t":"¿Qué impulsa al niño a seguir succionando después de saciarse? ¿Qué le proporciona placer en esa actividad?","o":"Was drängt das Kind dazu, die Betätigung des Saugens auch nach erfolgter Sättigung fortzusetzen; was verschafft ihm bei dieser Betätigung die Lust?","l":"de","ob":"Ensayo de una teoría de la genitalidad","an":"1924","u":"","te":["infancia","deseo","cuerpo"]},{"i":"sandor-ferenczi-012","a":"sandor-ferenczi","t":"El niño de pecho es, en líneas generales, un parásito externo de la madre, como antes, en la vida fetal, había sido un parásito interno que se nutría de ella.","o":"Das Brustkind ist im Ganzen und Großen ein Ektoparasit der Mutter, gleichwie es in der Fötalperiode endoparasitisch an ihr zehrte.","l":"de","ob":"Ensayo de una teoría de la genitalidad","an":"1924","u":"","te":["infancia","familia","cuerpo"]},{"i":"sandor-ferenczi-013","a":"sandor-ferenczi","t":"El motivo de este desplazamiento es la reacción de displacer que, en el niño, produce la obligación de cumplir ciertas normas de excreción exigidas por quienes lo cuidan.","o":"Das Motiv zu dieser Verschiebung ist die Unlustreaktion, die beim Kinde der Zwang zur Einhaltung gewisser von den Pflegepersonen geforderter Ausscheidungsregeln hervorruft.","l":"de","ob":"Ensayo de una teoría de la genitalidad","an":"1924","u":"","te":["infancia","educacion","emociones"]},{"i":"sandor-ferenczi-014","a":"sandor-ferenczi","t":"Tampoco en este período se abandona la regresión a la madre intentada antes por vía oral; aquí vuelve como identificación de la materia fecal con un niño, es decir, con el propio sí mismo.","o":"Auch die früher oralerotisch versuchte Mutterregression wird in dieser Periode nicht aufgegeben; sie kehrt hier als Identifizierung des Kotes mit einem Kinde, d. h. mit dem eigenen Selbst wieder.","l":"de","ob":"Ensayo de una teoría de la genitalidad","an":"1924","u":"","te":["infancia","identidad","repeticion"]},{"i":"sandor-ferenczi-015","a":"sandor-ferenczi","t":"Llama la atención que el niño, en las dos últimas fases, desempeña de manera constante un papel doble, que sin duda se relaciona con el hecho de la bisexualidad infantil.","o":"Es fällt uns auf, daß das Kind in den letzten beiden Phasen durchgängig eine Doppelrolle agiert, die sicherlich mit der Tatsache der infantilen Bisexualität zusammenhängt.","l":"de","ob":"Ensayo de una teoría de la genitalidad","an":"1924","u":"","te":["infancia","identidad","sexualidad"]},{"i":"sandor-ferenczi-016","a":"sandor-ferenczi","t":"El desarrollo de la sexualidad genital en el varón, que acabamos de esbozar, sufre en la mujer una interrupción por lo general bastante abrupta.","o":"Die soeben kursorisch geschilderte Ausbildung der Genitalsexualität beim Manne erfährt beim weiblichen Wesen eine meist ziemlich unvermittelte Unterbrechung.","l":"de","ob":"Ensayo de una teoría de la genitalidad","an":"1924","u":"","te":["sexualidad","identidad"]},{"i":"sandor-ferenczi-017","a":"sandor-ferenczi","t":"Si se observa el desarrollo genital de la mujer, se tiene la impresión de que, en la primera relación sexual, suele estar todavía por completo inmaduro.","o":"Beobachtet man die Genitalentwicklung der Frau, so gewinnt man den Eindruck, daß diese beim ersten Geschlechtsverkehr meist noch ganz unfertig ist.","l":"de","ob":"Ensayo de una teoría de la genitalidad","an":"1924","u":"","te":["sexualidad","desarrollo-humano"]},{"i":"sandor-ferenczi-018","a":"sandor-ferenczi","t":"Solo más tarde aprende la mujer a soportar pasivamente el acto sexual; más tarde aún, a sentir placer en él o a participar activamente.","o":"Erst später lernt die Frau den Geschlechtsakt passiv zu ertragen, noch später lustvoll zu empfinden oder gar daran aktiv teilzunehmen.","l":"de","ob":"Ensayo de una teoría de la genitalidad","an":"1924","u":"","te":["sexualidad","desarrollo-humano"]},{"i":"sandor-ferenczi-019","a":"sandor-ferenczi","t":"A la luz de estas consideraciones, las formas de satisfacción de los perversos y los síntomas de los psiconeuróticos aparecen bajo una nueva luz.","o":"Im Lichte dieser Betrachtungen erscheinen die Befriedigungsarten der Perversen und die Symptome der Psychoneurotiker in einem neuen Lichte.","l":"de","ob":"Ensayo de una teoría de la genitalidad","an":"1924","u":"","te":["sexualidad","salud-mental"]},{"i":"sandor-ferenczi-020","a":"sandor-ferenczi","t":"La variedad de conductas sexuales de los animales permite observar, en ejemplos extremos, los distintos desenlaces de esta lucha.","o":"Die Mannigfaltigkeit in der Geschlechtsgebarung der Tiere gestattet es, die verschiedenen Ausgänge dieses Kampfes an extremen Beispielen zu beobachten.","l":"de","ob":"Ensayo de una teoría de la genitalidad","an":"1924","u":"","te":["sexualidad","naturaleza"]},{"i":"sandor-ferenczi-021","a":"sandor-ferenczi","t":"Está, sobre todo, el proceso de la erección, para el que la teoría de la genitalidad como vuelta al seno materno ofrece una explicación, por cierto al principio extraña.","o":"Da ist vor allem der Vorgang der Erektion, für den sich aus der Mutterleibstheorie der Genitalität eine allerdings zunächst befremdende Erklärung darbietet.","l":"de","ob":"Ensayo de una teoría de la genitalidad","an":"1924","u":"","te":["sexualidad","cuerpo"]},{"i":"sandor-ferenczi-022","a":"sandor-ferenczi","t":"Supongo que la invaginación permanente del glande en un pliegue de la mucosa (el prepucio) no es sino una imitación, en pequeño, de la existencia en el seno materno.","o":"Ich nehme an, daß die Dauer-Invaginierung der Eichel in einer Schleimhautfalte (in der Vorhaut), selbst nichts anderes ist als eine Nachahmung der Mutterleibsexistenz im Kleinen.","l":"de","ob":"Ensayo de una teoría de la genitalidad","an":"1924","u":"","te":["sexualidad","cuerpo","infancia"]},{"i":"sandor-ferenczi-023","a":"sandor-ferenczi","t":"Las llamamos hipnosis paterna y materna","o":"Wir nannten sie Vater- und Mutterhypnose","l":"de","ob":"Ensayo de una teoría de la genitalidad","an":"1924","u":"","te":["vinculos","familia","poder"]},{"i":"sandor-ferenczi-024","a":"sandor-ferenczi","t":"Uno estaría inclinado, en principio, a considerar estos estados como molestas perturbaciones del trabajo analítico, y a tratarlos en consecuencia.","o":"Man wäre zunächst geneigt, diese Zustände für unliebsame Störungen der Analysenarbeit anzusehen und sie danach zu behandeln.","l":"de","ob":"Materiales para el psicoanálisis","an":"1927","u":"","te":["terapia"]},{"i":"sandor-ferenczi-025","a":"sandor-ferenczi","t":"Un síntoma surgido de este modo no representa solo una cierta cantidad de excitación, sino que se revela también como determinado cualitativamente.","o":"Ein auf diese Art zustande gekommenes Symptom stellt aber nicht nur eine gewisse Erregungsmenge vor, sondern erweist sich auch als qualitativ determiniert.","l":"de","ob":"Materiales para el psicoanálisis","an":"1927","u":"","te":["salud-mental","inconsciente"]},{"i":"sandor-ferenczi-026","a":"sandor-ferenczi","t":"La observación del paciente muestra de manera inequívoca que el síntoma solo cesa cuando el paciente no solo ha entendido nuestra explicación, sino que la ha reconocido como correcta.","o":"Die Beobachtung des Patienten zeigt in nicht mißverständlicher Weise, daß das Symptom nur aufhört, wenn der Patient unsere Erklärung nicht nur verstanden, sondern als richtig erkannt hat.","l":"de","ob":"Materiales para el psicoanálisis","an":"1927","u":"","te":["terapia","autoconocimiento"]},{"i":"sandor-ferenczi-027","a":"sandor-ferenczi","t":"La indagación posterior de la paciente reveló que se esforzaba por negarse a sí misma la situación incómoda de la mujer casada por debajo de su rango.","o":"Die nachträgliche Befragung der Patientin stellte fest, daß sie das Bestreben hatte, sich selbst gegenüber die mißliche Lage der unter ihrem Stand verheirateten Frau abzuleugnen.","l":"de","ob":"Materiales para el psicoanálisis","an":"1927","u":"","te":["autoconocimiento","identidad","vinculos"]},{"i":"sandor-ferenczi-028","a":"sandor-ferenczi","t":"Traducido al lenguaje del psicoanálisis, esto significa: todo síntoma está sobredeterminado.","o":"In die Sprache der Psychoanalyse übersetzt, heißt das: jedes Symptom ist überdeterminiert.","l":"de","ob":"Materiales para el psicoanálisis","an":"1927","u":"","te":["inconsciente","salud-mental"]},{"i":"sandor-ferenczi-029","a":"sandor-ferenczi","t":"El análisis llevó a vivencias infantiles en las que, a una altura considerable, se sintió tan indefenso que le dio vértigo.","o":"Die Analyse führte zu infantilen Erlebnissen, bei denen er in ziemlich bedeutender Höhe sich so hilflos vorkam, daß er schwindlig wurde.","l":"de","ob":"Materiales para el psicoanálisis","an":"1927","u":"","te":["infancia","angustia","trauma"]},{"i":"sandor-ferenczi-030","a":"sandor-ferenczi","t":"Una \"terrible somnolencia\" se apoderaba de una paciente cada vez que quería escapar por un atajo del análisis, que se le volvía desagradable.","o":"Eine \"fürchterliche Schläfrigkeit\" überkam eine Patientin jedesmal, wenn sie der ihr unangenehm werdenden Analyse auf kurzem Wege entkommen wollte.","l":"de","ob":"Materiales para el psicoanálisis","an":"1927","u":"","te":["terapia","cuerpo"]},{"i":"sandor-ferenczi-031","a":"sandor-ferenczi","t":"El paciente descubrió por sí mismo la identificación simbólica \"pierna = pene, calambre = erección\".","o":"Die symbolische Identifizierung \"Bein = Penis, Krampf - Erektion\" fand der Patient selbst heraus.","l":"de","ob":"Materiales para el psicoanálisis","an":"1927","u":"","te":["inconsciente","autoconocimiento"]},{"i":"sandor-ferenczi-032","a":"sandor-ferenczi","t":"Según el resultado del análisis, el calambre era una medida de protección contra el castigo temido","o":"Der Krampf war nach dem Ergebnisse der Analyse eine Schutzmaßregel gegen die befürchtete Strafe","l":"de","ob":"Materiales para el psicoanálisis","an":"1927","u":"","te":["miedo","culpa","inconsciente"]},{"i":"sandor-ferenczi-033","a":"sandor-ferenczi","t":"Las molestias intestinales pasajeras (diarreas, estreñimientos) se revelaban a menudo en el análisis como regresiones del carácter anal","o":"Vorübergehende Stuhlbeschwerden (Diarrhöen, Verstopfungen) entpuppten sich in der Analyse oft als Regressionen des Analcharakters","l":"de","ob":"Materiales para el psicoanálisis","an":"1927","u":"","te":["cuerpo","repeticion","infancia"]},{"i":"sandor-ferenczi-034","a":"sandor-ferenczi","t":"Pero pronto veo que al paciente no le importa la explicación: la idea sigue adherida, obsesiva.","o":"Doch bald sehe ich ein, daß dem Patienten nichts an der Erklärung gelegen ist, die Vorstellung bleibt weiter zwanghaft haften.","l":"de","ob":"Materiales para el psicoanálisis","an":"1927","u":"","te":["terapia","salud-mental"]},{"i":"sandor-ferenczi-035","a":"sandor-ferenczi","t":"No es raro que aparezcan engaños ilusorios pasajeros durante la hora de análisis","o":"Nicht selten treten vorübergehende illusionäre Täuschungen in der Analysenstunde auf","l":"de","ob":"Materiales para el psicoanálisis","an":"1927","u":"","te":["terapia","cuerpo"]},{"i":"sandor-ferenczi-036","a":"sandor-ferenczi","t":"Si un paciente se siente tratado sin afecto por el médico, recurre, si hay una fijación autoerótica correspondiente, a la masturbación.","o":"Fühlt sich ein Patient vom Arzte lieblos behandelt, so greift er - bei entsprechender autoerotischer Fixierung - zur Onanie.","l":"de","ob":"Materiales para el psicoanálisis","an":"1927","u":"","te":["terapia","sexualidad","vinculos"]},{"i":"sandor-ferenczi-037","a":"sandor-ferenczi","t":"En su día, de niño, renunció a la autosatisfacción solo porque a cambio recibía la compensación del amor de objeto","o":"Seinerzeit, als Kind, verzichtete er auf die Selbstbefriedigung nur, indem er dafür durch die Objektliebe entschädigt wurde","l":"de","ob":"Materiales para el psicoanálisis","an":"1927","u":"","te":["infancia","amor","vinculos"]},{"i":"sandor-ferenczi-038","a":"sandor-ferenczi","t":"Si se siente decepcionado en este tipo de amor, vuelve a recaer.","o":"Fühlt er sich in dieser Art Liebe enttäuscht, so wird er rückfällig.","l":"de","ob":"Materiales para el psicoanálisis","an":"1927","u":"","te":["amor","perdida","repeticion"]},{"i":"sandor-ferenczi-039","a":"sandor-ferenczi","t":"Los niños no están del todo equivocados en esto.","o":"Die Kinder haben damit nicht so ganz unrecht.","l":"de","ob":"Materiales para el psicoanálisis","an":"1927","u":"","te":["infancia"]},{"i":"sandor-ferenczi-040","a":"sandor-ferenczi","t":"Una paciente que entró a tratamiento poco después me trajo, creo, la clave de este fenómeno extraño.","o":"Eine Patientin, die bald nachher in meine Behandlung trat, brachte mir dann, wie ich glaube, die Lösung dieser sonderbaren Erscheinung.","l":"de","ob":"Materiales para el psicoanálisis","an":"1927","u":"","te":["terapia","conocimiento"]},{"i":"sandor-ferenczi-041","a":"sandor-ferenczi","t":"Nos ofrecen puntos de ataque contra las resistencias más fuertes de los pacientes, disfrazadas de transferencia, y así adquieren un valor técnico práctico para el análisis.","o":"Sie bieten uns Angriffspunkte zur Bekämpfung der stärksten, als Übertragung verkleideten Widerstände der Patienten und erlangen dadurch praktisch-technischen Wert für die Analyse.","l":"de","ob":"Materiales para el psicoanálisis","an":"1927","u":"","te":["terapia","vinculos"]},{"i":"sandor-ferenczi-042","a":"sandor-ferenczi","t":"Algunos pacientes producen un gorgoteo en el estómago cuando han callado algo.","o":"Manche Patienten produzieren ein Gurren im Magen, wenn sie etwas verschwiegen haben.","l":"de","ob":"Materiales para el psicoanálisis","an":"1927","u":"","te":["cuerpo","comunicacion","terapia"]},{"i":"sandor-ferenczi-043","a":"sandor-ferenczi","t":"Pero si uno toma realmente en serio la tesis de que todo lo que ocurre está estrictamente determinado, también deberá buscar explicaciones para estos fenómenos.","o":"Macht man aber mit dem Satz von der strengen Determiniertheit alles Geschehens wirklich Ernst, so wird man auch für diese Erscheinungen Erklärungen suchen müssen.","l":"de","ob":"Materiales para el psicoanálisis","an":"1927","u":"","te":["inconsciente","conocimiento"]},{"i":"sandor-ferenczi-044","a":"sandor-ferenczi","t":"Entonces se me ocurre que eso podría ser un trozo de resistencia, y pienso qué pudo haberlo provocado.","o":"Da fällt es mir ein, daß das ein Stück Widerstand sein könnte, und ich sinne nach, wodurch es wohl ausgelöst worden sein mag.","l":"de","ob":"Materiales para el psicoanálisis","an":"1927","u":"","te":["terapia","autoconocimiento"]},{"i":"sandor-ferenczi-045","a":"sandor-ferenczi","t":"No cabe duda de que esos éxitos son analíticos solo en una pequeña parte; en su mayor parte son sugestivos, es decir, éxitos de la transferencia.","o":"Es unterliegt keinem Zweifel, daß diese Erfolge nur zum kleineren Teil analytisch, zum größeren aber rein suggestiv, das heißt Übertragungserfolge sind.","l":"de","ob":"Materiales para el psicoanálisis","an":"1927","u":"","te":["terapia","vinculos"]},{"i":"sandor-ferenczi-046","a":"sandor-ferenczi","t":"Se entiende que el médico, incluso ante este tipo de sucesos, no debe perder la paciencia benevolente.","o":"Es versteht sich von selbst, daß den Arzt auch derartigen Vorkommnissen gegenüber die wohlwollende Geduld nicht verlassen darf.","l":"de","ob":"Materiales para el psicoanálisis","an":"1927","u":"","te":["terapia","compasion"]},{"i":"sandor-ferenczi-047","a":"sandor-ferenczi","t":"Aunque el paciente se esfuerce por recordar algo que el médico sabe, no hay que ayudarlo sin más, porque de lo contrario se pierden las ocurrencias sustitutas, que pueden ser valiosas.","o":"Auch wenn der Patient sich anstrengt, etwas zu erinnern, was der Arzt wohl weiß, darf ihm nicht ohne weiteres geholfen werden, sonst kommt man um die eventuell wertvollen Ersatzeinfälle.","l":"de","ob":"Materiales para el psicoanálisis","an":"1927","u":"","te":["terapia","memoria"]},{"i":"sandor-ferenczi-048","a":"sandor-ferenczi","t":"Hubo que explicarle que la regla fundamental no exige pensar hasta el final una ocurrencia, sino decir hasta el final lo que se pensó alguna vez.","o":"Es mußte ihm erklärt werden, daß die Grundregel zwar nicht das Zuendedenken eines Einfalles, wohl aber das Zuendesagen des einmal Gedachten fordert.","l":"de","ob":"Materiales para el psicoanálisis","an":"1927","u":"","te":["terapia","comunicacion"]},{"i":"sandor-ferenczi-049","a":"sandor-ferenczi","t":"Puede ocurrir que la mayor parte de la hora transcurra sin que ni el médico ni el paciente pronuncien una sola palabra.","o":"Es kann vorkommen, daß der größte Teil der Stunde vergeht, ohne daß Arzt oder Patient auch nur ein Wort gesprochen hätten.","l":"de","ob":"Materiales para el psicoanálisis","an":"1927","u":"","te":["silencio","terapia"]},{"i":"sandor-ferenczi-050","a":"sandor-ferenczi","t":"Si se quiere dar una idea de ello, lo mejor es recurrir a ejemplos tomados de la experiencia.","o":"Will man einen Begriff davon geben, so tut man wohl am besten, wenn man Beispiele aus der Erfahrung heranzieht.","l":"de","ob":"Materiales para el psicoanálisis","an":"1927","u":"","te":["conocimiento","terapia"]},{"i":"ivan-pavlov-001","a":"ivan-pavlov","t":"Los hemisferios cerebrales se destacan como el logro culminante del desarrollo nervioso del reino animal.","o":"The cerebral hemispheres stand out as the crowning achievement in the nervous development of the animal kingdom.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento","cuerpo"]},{"i":"ivan-pavlov-002","a":"ivan-pavlov","t":"Tal complejidad de estructura sugiere naturalmente una complejidad semejante de funciones, que de hecho es evidente en los animales superiores y en el ser humano.","o":"Such complexity of structure naturally suggests a like complexity of function, which in fact is obvious in the higher animal and in man.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento"]},{"i":"ivan-pavlov-003","a":"ivan-pavlov","t":"Sabemos que esta conducta compleja del animal, que sin duda implica la actividad nerviosa más elevada, está asociada principalmente con los hemisferios cerebrales.","o":"We know that this complex behaviour of the animal, undoubtedly involving the highest nervous activity, is mainly associated with the cerebral hemispheres.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conciencia","cuerpo"]},{"i":"ivan-pavlov-004","a":"ivan-pavlov","t":"También en el ser humano la actividad nerviosa más elevada depende de la integridad estructural y funcional de los hemisferios cerebrales.","o":"In man also the highest nervous activity is dependent upon the structural and functional integrity of the cerebral hemispheres.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["cuerpo","conciencia"]},{"i":"ivan-pavlov-005","a":"ivan-pavlov","t":"En cuanto esas estructuras se dañan y sus funciones se alteran de algún modo, el ser humano también se vuelve un inválido.","o":"As soon as these structures become damaged and their functions impaired in any way, so man also becomes an invalid.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["cuerpo","salud-mental"]},{"i":"ivan-pavlov-006","a":"ivan-pavlov","t":"Ya no puede cumplir con sus tareas habituales y debe quedar apartado del mundo laboral de sus semejantes.","o":"He can no longer proceed with his normal duties, but has to be kept out of the working world of his fellow men.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["cuerpo","existencia"]},{"i":"ivan-pavlov-007","a":"ivan-pavlov","t":"En sorprendente contraste con la actividad sin límites de los hemisferios cerebrales, se encuentra el escaso contenido del conocimiento fisiológico actual sobre ellos.","o":"In astounding contrast with the unbounded activity of the cerebral hemispheres stands the meagre content of present-day physiological knowledge concerning them.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento"]},{"i":"ivan-pavlov-008","a":"ivan-pavlov","t":"Numerosos investigadores han realizado, y siguen realizando, búsquedas minuciosas sobre la localización de funciones en la corteza.","o":"Searching investigations have been made, and still are being made, by numerous workers on this question of localization of function in the cortex.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento"]},{"i":"ivan-pavlov-009","a":"ivan-pavlov","t":"Nuestro conocimiento ha ganado precisión y se ha completado en detalle, sobre todo en lo que respecta al área motora, y incluso ha encontrado aplicaciones útiles en la medicina.","o":"Our knowledge has been increased in precision and filled out in detail, especially as regards the motor area, and has even found useful application in medicine.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento"]},{"i":"ivan-pavlov-010","a":"ivan-pavlov","t":"Estas investigaciones, sin embargo, no avanzaron fundamentalmente más allá de la posición establecida por Fritsch y Hitzig.","o":"These investigations, however, did not proceed fundamentally beyond the position established by Fritsch and Hitzig.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento"]},{"i":"ivan-pavlov-011","a":"ivan-pavlov","t":"Por eso, cuando nos preguntamos: ¿qué explican de la conducta de los animales superiores los hechos que hasta ahora tuvo a su disposición el fisiólogo?","o":"When therefore we ask the questions: What do those facts which have up to the present been at the disposal of the physiologist explain with regard to the behaviour of the higher animals?","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento","conciencia"]},{"i":"ivan-pavlov-012","a":"ivan-pavlov","t":"¿O qué reglas generales que rijan esa actividad nos ayudan a formular? El fisiólogo moderno se encuentra desorientado y no puede dar una respuesta satisfactoria.","o":"Or what general rules governing this activity can they help us to formulate? -- the modern physiologist finds himself at a loss and can give no satisfactory reply.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento"]},{"i":"ivan-pavlov-013","a":"ivan-pavlov","t":"Estas actividades nerviosas nunca se consideraron desde el mismo punto de vista que las de otros órganos, ni siquiera que las de otras partes del sistema nervioso central.","o":"These nervous activities have never been regarded from the same point of view as those of other organs, or even other parts of the central nervous system.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento"]},{"i":"ivan-pavlov-014","a":"ivan-pavlov","t":"Se ha hablado de la actividad de los hemisferios como una suerte de actividad psíquica especial, cuyo funcionamiento sentimos y captamos en nosotros mismos, y que por analogía suponemos que existe en los animales.","o":"The activities of the hemispheres have been talked about as some kind of special psychical activity, whose working we feel and apprehend in ourselves, and by analogy suppose to exist in animals.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conciencia"]},{"i":"ivan-pavlov-015","a":"ivan-pavlov","t":"¿Quizá debería estudiar primero los métodos de esta ciencia de la psicología, y solo después esperar estudiar el mecanismo fisiológico de los hemisferios?","o":"Perhaps he should first of all study the methods of this science of psychology, and only afterwards hope to study the physiological mechanism of the hemispheres?","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento","conciencia"]},{"i":"ivan-pavlov-016","a":"ivan-pavlov","t":"Es lógico que la fisiología, al analizar las distintas actividades de la materia viva, se apoye en las ciencias más avanzadas y más exactas: la física y la química.","o":"It is logical that in its analysis of the various activities of living matter physiology should base itself on the more advanced and more exact sciences -- physics and chemistry.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento"]},{"i":"ivan-pavlov-017","a":"ivan-pavlov","t":"De hecho, sigue abierta la discusión sobre si la psicología es una ciencia natural o si puede considerarse siquiera una ciencia.","o":"In fact it is still open to discussion whether psychology is a natural science, or whether it can be regarded as a science at all.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento"]},{"i":"ivan-pavlov-018","a":"ivan-pavlov","t":"El eminente psicólogo estadounidense William James se refirió en los últimos años a la psicología no como una ciencia, sino como una esperanza de ciencia.","o":"The eminent American psychologist, William James, has in recent years referred to psychology not as a science but as a hope of science.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento"]},{"i":"ivan-pavlov-019","a":"ivan-pavlov","t":"Otra ilustración llamativa la ofrece Wundt, el célebre filósofo y psicólogo, fundador del llamado método experimental en psicología y antiguo fisiólogo.","o":"Another striking illustration is provided by Wundt, the celebrated philosopher and psychologist, founder of the so-called experimental method in psychology and himself formerly a physiologist.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento"]},{"i":"ivan-pavlov-020","a":"ivan-pavlov","t":"Así, el fisiólogo debe seguir su propio camino, allí donde ya se ha abierto una senda para él.","o":"The physiologist must thus take his own path, where a trail has already been blazed for him.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento","cambio"]},{"i":"ivan-pavlov-021","a":"ivan-pavlov","t":"En los siglos XVIII, XIX y XX, los fisiólogos utilizaron por completo la concepción del reflejo.","o":"In the eighteenth, nineteenth and twentieth centuries the conception of the reflex was used to the full by physiologists.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento","cuerpo"]},{"i":"ivan-pavlov-022","a":"ivan-pavlov","t":"La concepción del reflejo de Descartes se aplicó constante y fructíferamente en esos estudios, pero su aplicación se detuvo antes de llegar a la corteza cerebral.","o":"Descartes' conception of the reflex was constantly and fruitfully applied in these studies, but its application has stopped short of the cerebral cortex.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento","cuerpo"]},{"i":"ivan-pavlov-023","a":"ivan-pavlov","t":"Había llegado el momento de pasar al análisis experimental del tema, un análisis que debía ser tan objetivo como el de cualquier otra rama de la ciencia natural.","o":"The time was ripe for a transition to the experimental analysis of the subject -- an analysis which must be as objective as the analysis in any other branch of natural science.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento","cambio"]},{"i":"ivan-pavlov-024","a":"ivan-pavlov","t":"Esa transición recibió un impulso de la fisiología comparada, una ciencia que se desarrollaba rápidamente y que había surgido como resultado directo de la teoría de la evolución.","o":"An impetus was given to this transition by the rapidly developing science of comparative physiology, which itself sprang up as a direct result of the Theory of Evolution.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento","cambio"]},{"i":"ivan-pavlov-025","a":"ivan-pavlov","t":"En estas investigaciones el animal se mantenía dentro de una caja, y la comida se colocaba afuera, de modo que el animal pudiera verla.","o":"In these investigations the animal was kept in a box, and food was placed outside the box so that it was visible to the animal.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento"]},{"i":"ivan-pavlov-026","a":"ivan-pavlov","t":"Para obtener la comida, el animal debía abrir una puerta, que en los distintos experimentos se aseguraba con diversos mecanismos apropiados.","o":"In order to get the food the animal had to open a door, which was fastened by various suitable contrivances in the different experiments.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento","habitos"]},{"i":"ivan-pavlov-027","a":"ivan-pavlov","t":"Se elaboraron tablas y gráficos que mostraban con qué rapidez y de qué manera el animal resolvía los problemas que se le planteaban.","o":"Tables and charts were made showing how quickly and in what manner the animal solved the problems set it.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento"]},{"i":"ivan-pavlov-028","a":"ivan-pavlov","t":"Todo el proceso se entendía como la formación de una asociación entre los estímulos visuales y táctiles, por un lado, y el aparato locomotor, por el otro.","o":"The whole process was understood as being the formation of an association between the visual and tactile stimuli on the one hand and the locomotor apparatus on the other.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["habitos","conocimiento"]},{"i":"ivan-pavlov-029","a":"ivan-pavlov","t":"Este método, con sus modificaciones, fue aplicado después por numerosos autores al estudio de la capacidad asociativa de distintos animales.","o":"This method, with its modifications, was subsequently applied by numerous authors to the study of questions relating to the associative ability of various animals.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento"]},{"i":"ivan-pavlov-030","a":"ivan-pavlov","t":"Como resultado de esta investigación, quedó firmemente grabada en mi mente la convicción absoluta de la inutilidad de los métodos subjetivos de indagación.","o":"As a result of this investigation an unqualified conviction of the futility of subjective methods of inquiry was firmly stamped upon my mind.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento","conciencia"]},{"i":"ivan-pavlov-031","a":"ivan-pavlov","t":"Quedó claro que la única solución satisfactoria del problema estaba en una investigación experimental con métodos estrictamente objetivos.","o":"It became clear that the only satisfactory solution of the problem lay in an experimental investigation by strictly objective methods.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento"]},{"i":"ivan-pavlov-032","a":"ivan-pavlov","t":"Por supuesto, hemos atravesado muchas etapas, y solo gradualmente el tema se fue abriendo y las dificultades se fueron superando.","o":"We have of course passed through many stages, and only gradually has the subject been opened up and the difficulties overcome.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento","cambio"]},{"i":"ivan-pavlov-033","a":"ivan-pavlov","t":"Al principio solo había unos pocos hechos dispersos, pero hoy se ha reunido material suficiente para justificar el intento de presentarlo de una forma más o menos sistemática.","o":"At first only a few scattered facts were available, but to-day sufficient material has been gathered together to warrant an attempt to present it in a more or less systematized form.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento"]},{"i":"ivan-pavlov-034","a":"ivan-pavlov","t":"Hasta ahora, sin embargo, ha habido una diferencia esencial entre la escuela norteamericana y nosotros.","o":"Up to the present, however, there has been one essential point of difference between the American School and ourselves.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento"]},{"i":"ivan-pavlov-035","a":"ivan-pavlov","t":"Nosotros, que partimos de la fisiología, seguimos atenidos estrictamente al punto de vista fisiológico, investigando y sistematizando todo el tema solo con métodos fisiológicos.","o":"We, having started from physiology, continue to adhere strictly to the physiological point of view, investigating and systematizing the whole subject by physiological methods alone.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento"]},{"i":"ivan-pavlov-036","a":"ivan-pavlov","t":"Así, un estímulo parece estar ligado necesariamente a una respuesta definida, como la causa con el efecto.","o":"Thus a stimulus appears to be connected of necessity with a definite response, as cause with effect.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento"]},{"i":"ivan-pavlov-037","a":"ivan-pavlov","t":"El animal debe responder a los cambios del entorno de tal modo que su actividad de respuesta esté orientada a la preservación de su existencia.","o":"The animal must respond to changes in the environment in such a manner that its responsive activity is directed towards the preservation of its existence.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["existencia","cuerpo"]},{"i":"ivan-pavlov-038","a":"ivan-pavlov","t":"Esta conclusión también vale si consideramos el organismo vivo desde el punto de vista de la física y la química.","o":"This conclusion holds also if we consider the living organism in terms of physical and chemical science.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento","cuerpo"]},{"i":"ivan-pavlov-039","a":"ivan-pavlov","t":"Todo sistema material puede existir como unidad solo mientras sus fuerzas internas, la atracción, la cohesión, etc., equilibren las fuerzas externas que actúan sobre él.","o":"Every material system can exist as an entity only so long as its internal forces, attraction, cohesion, etc., balance the external forces acting upon it.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["existencia"]},{"i":"ivan-pavlov-040","a":"ivan-pavlov","t":"Esto vale tanto para una piedra común como para las sustancias químicas más complejas, y debería reconocerse también para el organismo animal.","o":"This is true for an ordinary stone just as much as for the most complex chemical substances; and its truth should be recognized also for the animal organism.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["cuerpo"]},{"i":"ivan-pavlov-041","a":"ivan-pavlov","t":"Los reflejos, como las correas de transmisión de las máquinas diseñadas por el ser humano, pueden ser de dos clases: positivos y negativos, excitatorios e inhibitorios.","o":"Reflexes, like the driving-belts of machines of human design, may be of two kinds-positive and negative, excitatory and inhibitory.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["cuerpo","habitos"]},{"i":"ivan-pavlov-042","a":"ivan-pavlov","t":"Aunque los fisiólogos llevan mucho tiempo investigando estos reflejos, todavía no están ni cerca de terminar.","o":"Although the investigation of these reflexes by physiologists has been going on now for a long time, it is as yet not nearly finished.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento"]},{"i":"ivan-pavlov-043","a":"ivan-pavlov","t":"Ignoramos las propiedades de aquellos órganos receptores cuyo estímulo eficaz surge dentro del organismo, y los propios reflejos internos siguen siendo un campo inexplorado.","o":"We are ignorant of the properties of those receptor organs for which the effective stimulus arises inside the organism, and the internal reflexes themselves remain a field unexplored.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["cuerpo","inconsciente"]},{"i":"ivan-pavlov-044","a":"ivan-pavlov","t":"Además, la combinación y la interacción de distintos reflejos todavía se comprenden de manera insuficiente.","o":"Furthermore, the combination and interaction of different reflexes are as yet insufficiently understood.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento"]},{"i":"ivan-pavlov-045","a":"ivan-pavlov","t":"Estos también ocurren en el sistema nervioso, y son reacciones inevitables ante estímulos perfectamente definidos.","o":"These also take place in the nervous system, and they are the inevitable reactions to perfectly definite stimuli.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["cuerpo","habitos"]},{"i":"ivan-pavlov-046","a":"ivan-pavlov","t":"Le debemos al filósofo inglés Herbert Spencer la sugerencia de que las reacciones instintivas son reflejos.","o":"We owe to the English philosopher, Herbert Spencer, the suggestion that instinctive reactions are reflexes.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento","habitos"]},{"i":"ivan-pavlov-047","a":"ivan-pavlov","t":"Entre el reflejo más simple y el instinto encontramos numerosas etapas de transición, y entre ellas nos resulta desconcertante hallar alguna línea de demarcación.","o":"Between the simplest reflex and the instinct we can find numerous stages of transition, and among these we are puzzled to find any line of demarcation.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["habitos","conocimiento"]},{"i":"ivan-pavlov-048","a":"ivan-pavlov","t":"A modo de ejemplo podemos tomar la construcción de un nido, o de refugios en general, por parte de los animales.","o":"By way of example we may take the building of a nest, or of dwellings in general, by animals.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["habitos"]},{"i":"ivan-pavlov-049","a":"ivan-pavlov","t":"Un gato, incluso privado de sus hemisferios cerebrales, en la mayoría de los casos caerá de pie si se lo arroja desde una altura.","o":"A cat, even when deprived of its cerebral hemispheres, will in most cases land on its feet when thrown from a height.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["cuerpo"]},{"i":"ivan-pavlov-050","a":"ivan-pavlov","t":"Cuando cambia la posición del órgano otolítico en el espacio, se evoca un reflejo definido que contrae los músculos del cuello y devuelve la cabeza del animal a su posición normal.","o":"When the position of the otolithic organ in space is altered a definite reflex is evoked which brings about a contraction of the muscles in the neck, restoring the animal's head to the normal position.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["cuerpo"]},{"i":"ivan-pavlov-051","a":"ivan-pavlov","t":"Al enderezarse la cabeza se evoca un nuevo reflejo, y entran en juego ciertos músculos del tronco y de las extremidades, que devuelven al animal a la postura erguida.","o":"With the righting of the head a fresh reflex is evoked, and certain muscles of the trunk and limbs are brought into play, restoring the animal to the standing posture.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["cuerpo"]},{"i":"ivan-pavlov-052","a":"ivan-pavlov","t":"Algunos, a su vez, objetan la identificación de instintos con reflejos por esta razón: dicen que los instintos dependen con frecuencia del estado interno del organismo.","o":"Some, again, object to the identification of instincts with reflexes on this ground: instincts, they say, frequently depend upon the internal state of an organism.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["cuerpo","deseo"]},{"i":"ivan-pavlov-053","a":"ivan-pavlov","t":"O, para tomar un caso más simple: cuando un animal está saciado de comer, la comida ya no le resulta atractiva y deja de comer.","o":"Or, to take a simpler case, when an animal is satiated with eating, then food has no longer any attraction and the animal leaves off eating.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["deseo","cuerpo"]},{"i":"ivan-pavlov-054","a":"ivan-pavlov","t":"Por último, a veces se sostiene que, mientras los reflejos determinan solo la actividad de órganos y tejidos aislados, los instintos implican la actividad del organismo en su totalidad.","o":"Last of all, it is sometimes held that whereas reflexes determine only the activities of single organs and tissues, instincts involve the activity of the organism as a whole.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["cuerpo","conocimiento"]},{"i":"ivan-pavlov-055","a":"ivan-pavlov","t":"De los dos términos, reflejo tiene mejores títulos, porque se usó desde el comienzo con una connotación estrictamente científica.","o":"Reflex has the better claim of the two, in that it has been used from the very beginning with a strictly scientific connotation.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["conocimiento"]},{"i":"ivan-pavlov-056","a":"ivan-pavlov","t":"El conjunto de los reflejos constituye la base de la actividad nerviosa tanto de los seres humanos como de los animales.","o":"The aggregate of reflexes constitutes the foundation of the nervous activities both of men and of animals.","l":"en","ob":"Reflejos condicionados: investigación de la actividad fisiológica de la corteza cerebral","an":"1927","u":"Conferencia 1","te":["cuerpo","conciencia"]},{"i":"lev-vygotsky-001","a":"lev-vygotsky","t":"El primer modo de análisis psicológico podría llamarse descomposición de los todos psicológicos complejos en elementos.","o":"Первый способ психологического анализа можно было бы назвать разложением сложных психологических целых на элементы.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 1","te":["conocimiento"]},{"i":"lev-vygotsky-002","a":"lev-vygotsky","t":"Del mismo modo, la célula viva, que conserva todas las propiedades fundamentales de la vida inherentes al organismo vivo, es la verdadera unidad del análisis biológico.","o":"Так же точно живая клетка, сохраняющая все основные свойства жизни, присущие живому организму, является настоящей единицей биологического анализа.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 1","te":["cuerpo","conocimiento"]},{"i":"lev-vygotsky-003","a":"lev-vygotsky","t":"Este lado interior de la palabra apenas ha sido objeto de investigaciones especiales hasta ahora.","o":"Эта внутренняя сторона слова до сих пор почти не подвергалась специальным исследованиям.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 1","te":["conciencia","conocimiento"]},{"i":"lev-vygotsky-004","a":"lev-vygotsky","t":"Que la comunicación directa de las almas es imposible: esto es, por supuesto, un axioma para la psicología científica.","o":"Что непосредственное общение душ невозможно—это является конечно аксиомой для научной психологии.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 1","te":["vinculos","conocimiento"]},{"i":"lev-vygotsky-005","a":"lev-vygotsky","t":"Por eso, para los niños que aún no tienen cierta generalización, una cosa entera resulta incomunicable.","o":"Вот почему целая вещь является несообщаемой для детей, которые не имеют еще известного обобщения.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 1","te":["infancia","conocimiento"]},{"i":"lev-vygotsky-006","a":"lev-vygotsky","t":"El estado histórico de nuestra ciencia es tal que, para decirlo en el lenguaje de Brentano, “existe mucha psicología, pero no existe una psicología única”.","o":"Историческое состояние нашей науки таково, что, говоря языком Брентано, “существует много психологии, но не существует единой психологии”.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 2","te":["conocimiento"]},{"i":"lev-vygotsky-007","a":"lev-vygotsky","t":"Este es el nervio central de todo su sistema, es la piedra angular de toda su construcción.","o":"Это—основной нерв всей его системы, это—краеугольный камень всего его построения.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 2","te":["conocimiento"]},{"i":"lev-vygotsky-008","a":"lev-vygotsky","t":"Este pensamiento no se dirige tanto a la realidad como a la satisfacción del deseo.","o":"Это мышление не столько направлено на действительность, сколько на удовлетворение желания.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 2","te":["deseo","conciencia"]},{"i":"lev-vygotsky-009","a":"lev-vygotsky","t":"El salvaje que invoca la lluvia con un rito mágico explica su fracaso por la influencia de un espíritu maligno.","o":"Дикарь, призывающий дождь магическим обрядом, объясняет свой неуспех влиянием злого духа.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 2","te":["cultura"]},{"i":"lev-vygotsky-010","a":"lev-vygotsky","t":"Bajo el nombre de habla egocéntrica, Piaget entiende un habla que se distingue, ante todo, por su función.","o":"Под именем эгоцентрической речи Пиаже разумеет речь, отличающуюся прежде всего своей функцией.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 2","te":["conocimiento","vinculos"]},{"i":"lev-vygotsky-011","a":"lev-vygotsky","t":"Las investigaciones fácticas de Piaget muestran, en efecto, que el coeficiente del habla egocéntrica disminuye a medida que el niño crece.","o":"Фактические исследования Пиаже действительно показывают, что коэфициент эгоцентрической речи падает по мере роста ребенка.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 2","te":["infancia","conocimiento"]},{"i":"lev-vygotsky-012","a":"lev-vygotsky","t":"Aquí la investigación experimental directa de la esencia misma de la cuestión resulta extremadamente difícil.","o":"Здесь прямое экспериментальное исследование самой сути вопроса чрезвычайно затруднено.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 2","te":["conocimiento"]},{"i":"lev-vygotsky-013","a":"lev-vygotsky","t":"Así, el habla se vuelve psicológicamente interior antes de volverse realmente interior.","o":"Речь таким образом становится психологически внутренней раньше, чем она становится действительно внутренней.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 2","te":["conciencia","cambio"]},{"i":"lev-vygotsky-014","a":"lev-vygotsky","t":"El fenómeno A puede considerarse función del fenómeno B, pero también, a la inversa: el fenómeno B puede considerarse función de A.","o":"Явление А может рассматриваться как функция явления Б, но и, наоборот: явление Б может рассматриваться как функция А.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 2","te":["conocimiento"]},{"i":"lev-vygotsky-015","a":"lev-vygotsky","t":"Este es el plano de la objetividad, del habla, de los conceptos lógicos; en una palabra, la realidad.","o":"Это—плоскость объективности, речи, логических концепций, одним словом—реальность.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 2","te":["conocimiento"]},{"i":"lev-vygotsky-016","a":"lev-vygotsky","t":"Pues el pensamiento autista, según Piaget, crea por sí mismo una realidad imaginaria, la realidad del sueño.","o":"Ведь аутистическая мысль—по Пиаже—создает сама себе воображаемую действительность или действительность сновидения.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 2","te":["inconsciente","deseo"]},{"i":"lev-vygotsky-017","a":"lev-vygotsky","t":"En la vida real existen tantas clases de causalidad como clases o grados de conciencia.","o":"В действительной жизни существует столько видов причинности, сколько видов или ступеней сознания.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 2","te":["conciencia","conocimiento"]},{"i":"lev-vygotsky-018","a":"lev-vygotsky","t":"Es evidente que a todas las afirmaciones fácticas de Piaget hay que hacerles dos correcciones esenciales.","o":"Очевидно во все фактические положения Пиаже нужно внести две существенных поправки.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 2","te":["conocimiento"]},{"i":"lev-vygotsky-019","a":"lev-vygotsky","t":"Para Piaget, sin embargo, el dogma fundamental sigue siendo que el niño es impermeable a la experiencia.","o":"Для Пиаже все же основной догмой остается положение, что ребенок непроницаем для опыта.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 2","te":["infancia","conocimiento"]},{"i":"lev-vygotsky-020","a":"lev-vygotsky","t":"Las regularidades que Piaget estableció y los hechos que encontró tienen un valor no general, sino limitado.","o":"Те закономерности, которые Пиаже установил, те факты, которые он нашел, имеют не всеобщее, но ограниченное значение.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 2","te":["conocimiento"]},{"i":"lev-vygotsky-021","a":"lev-vygotsky","t":"Así se desarrolla no el pensamiento del niño en general, sino el pensamiento del niño que estudió Piaget.","o":"Так развивается не мышление ребенка вообще, но мышление того ребенка, которого изучал Пиаже.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 2","te":["infancia","conocimiento"]},{"i":"lev-vygotsky-022","a":"lev-vygotsky","t":"Este error se basa en que Piaget no tiene suficientemente en cuenta el significado de la situación social.","o":"Эта ошибка основана на том, что Пиаже недостаточно принимает во внимание значение социальной ситуации.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 2","te":["vinculos","cultura"]},{"i":"lev-vygotsky-023","a":"lev-vygotsky","t":"Estas regularidades, como ya se dijo, valen para el medio social que estudió Piaget.","o":"Эти закономерности, как уже сказано, действительны для той социальной среды, которую изучал Пиаже.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 2","te":["cultura"]},{"i":"lev-vygotsky-024","a":"lev-vygotsky","t":"Pero para ello, la psicología infantil necesita cambiar de raíz su orientación metodológica fundamental.","o":"Но для этого детской психологии необходимо коренным образом изменить свое основное методологическое направление.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 2","te":["infancia","cambio"]},{"i":"lev-vygotsky-025","a":"lev-vygotsky","t":"La idea básica de Stern es la del personalismo: la persona como unidad psicofísicamente neutra.","o":"Основная идея Штерна—идея персонализма: личность—как психофизически нейтральное единство.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 3","te":["identidad","conocimiento"]},{"i":"lev-vygotsky-026","a":"lev-vygotsky","t":"No queremos decir con esto que la presencia de la “ideación” sea una condición necesaria para la aparición del habla.","o":"Мы не хотим вовсе сказать этим, что наличие “идеации” является необходимым условием для возникновения речи.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 4","te":["conocimiento"]},{"i":"lev-vygotsky-027","a":"lev-vygotsky","t":"No hace falta ningún análisis especial para dar a esta pregunta una respuesta negativa.","o":"Не надо никакого специального анализа для того, чтобы дать на этот вопрос отрицательный ответ.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 4","te":["conocimiento"]},{"i":"lev-vygotsky-028","a":"lev-vygotsky","t":"Por el contrario, es más bien un rasgo extremadamente general de los animales que poseen un aparato vocal.","o":"Напротив, это скорее чрезвычайно общая черта для животных, обладающих голосовым аппаратом.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 4","te":["cuerpo"]},{"i":"lev-vygotsky-029","a":"lev-vygotsky","t":"Lo que menos puede recordar esta reacción es una comunicación intencional y con sentido de algo, o una acción de igual tipo.","o":"Менее всего эта реакция может напомнить намеренное, осмысленное сообщение чего-нибудь или такое же воздействие.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 4","te":["conciencia"]},{"i":"lev-vygotsky-030","a":"lev-vygotsky","t":"La opinión generalmente aceptada consideraba el habla infantil, en esta etapa de su desarrollo, sobre todo como una forma emocional de conducta.","o":"Общепринятый взгляд рассматривал детскую речь на этой ступени ее развития как эмоциональную форму поведения по преимуществу.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 4","te":["infancia","emociones"]},{"i":"lev-vygotsky-031","a":"lev-vygotsky","t":"Desde su punto de vista, el pensamiento no es otra cosa que habla inhibida, retenida, sin sonido.","o":"С их точки зрения, мышление есть не что иное, как заторможенная, задержанная, беззвучная речь.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 4","te":["conciencia"]},{"i":"lev-vygotsky-032","a":"lev-vygotsky","t":"Veríamos que el habla se vuelve psicológicamente interior antes de volverse fisiológicamente interior.","o":"Мы увидели бы, что речь становится психологически внутренней раньше, чем она становится физиологически внутренней.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 4","te":["conciencia","cuerpo"]},{"i":"lev-vygotsky-033","a":"lev-vygotsky","t":"Todo lo que sabemos al respecto nos obliga a dar una respuesta negativa a esta pregunta.","o":"Все, что мы знаем по этому поводу, заставляет нас дать отрицательный ответ на этот вопрос.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 4","te":["conocimiento"]},{"i":"lev-vygotsky-034","a":"lev-vygotsky","t":"Wallon sostiene que, durante cierto tiempo, para el niño el nombre es más un atributo que un sustituto del objeto.","o":"Валлон полагает, что для ребенка имя является некоторое время скорее атрибутом, чем субститутом предмета.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 4","te":["infancia","conocimiento"]},{"i":"lev-vygotsky-035","a":"lev-vygotsky","t":"La existencia de un fin, la existencia de una tarea, es un momento necesario pero insuficiente para la aparición de una actividad racional.","o":"Наличие цели, наличие задачи является необходимым, но недостаточным моментом для возникновения целесообразной деятельности.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 5","te":["habitos","conocimiento"]},{"i":"lev-vygotsky-036","a":"lev-vygotsky","t":"Desde este punto de vista resulta incomprensible, en general, el hecho de que las formas del pensamiento se desarrollen.","o":"С этой точки зрения вообще является непонятным тот факт, что формы мышления развиваются.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 5","te":["cambio","conocimiento"]},{"i":"lev-vygotsky-037","a":"lev-vygotsky","t":"El pensamiento del niño, guiado por los significados estables y constantes de las palabras, no cambia las leyes básicas de su actividad.","o":"Мышление ребенка, направляемое устойчивыми постоянными значениями слов, не изменяет основных законов своей деятельности.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 5","te":["conocimiento","habitos"]},{"i":"lev-vygotsky-038","a":"lev-vygotsky","t":"Ella ata la actividad propia del niño, encauzándola por un cauce determinado y estrictamente delimitado.","o":"Она связывает собственную активность ребенка, направляя ее по определенному, строго очерченному руслу.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 5","te":["habitos","infancia"]},{"i":"lev-vygotsky-039","a":"lev-vygotsky","t":"El niño, antes de que llegue este período, también incorpora palabras aisladas que son para él estímulos condicionados o sustitutos de objetos, personas, acciones, estados y deseos.","o":"Ребенок до наступления этого периода также усваивает отдельные слова, которые являются для него условными стимулами или заместителями отдельных предметов, людей, действий, состояний, желаний.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 4","te":["infancia","deseo"]},{"i":"lev-vygotsky-040","a":"lev-vygotsky","t":"En lugar de tres etapas —habla en voz alta, susurro, habla sin sonido— obtendríamos otros tres tipos de etapa: habla externa, habla egocéntrica, habla interna.","o":"Вместо трех этапов—громкая речь, шопот, беззвучная речь—мы получили бы другие три типа этапа: внешняя речь, эгоцентрическая речь, внутренняя речь.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 4","te":["conciencia","cambio"]},{"i":"lev-vygotsky-041","a":"lev-vygotsky","t":"El niño domina la sintaxis del habla antes de dominar la sintaxis del pensamiento.","o":"Ребенок овладевает синтаксисом речи раньше, чем он овладевает синтаксисом мысли.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 4","te":["infancia","conocimiento"]},{"i":"lev-vygotsky-042","a":"lev-vygotsky","t":"Así, los métodos tradicionales de investigación de los conceptos se caracterizan por igual por separar la palabra del material objetivo: operan o bien con palabras sin material objetivo, o bien con material objetivo sin palabras.","o":"Таким образом традиционные методы исследований понятий одинаково характеризуются отрывом слова от объективного материала; они оперируют либо словами без объективного материала, либо объективным материалом без слов.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 5","te":["conocimiento"]},{"i":"lev-vygotsky-043","a":"lev-vygotsky","t":"Pero este pensamiento verbal no agota ni todas las formas del pensamiento ni todas las formas del habla.","o":"Но это речевое мышление не исчерпывает ни всех форм мысли, ни всех форм речи.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 4","te":["conocimiento"]},{"i":"lev-vygotsky-044","a":"lev-vygotsky","t":"Esta cuestión se resuelve por la pertenencia de hecho o por el parentesco efectivo entre las personas.","o":"Этот вопрос решается на основании фактической принадлежности или фактического родства между людьми.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 5","te":["vinculos","cultura"]},{"i":"lev-vygotsky-045","a":"lev-vygotsky","t":"En lugar de la asociación por semejanza, aquí actúan más bien asociaciones por contraste.","o":"Вместо ассоциации по сходству, здесь действуют скорее ассоциации по контрасту.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 5","te":["conocimiento"]},{"i":"lev-vygotsky-046","a":"lev-vygotsky","t":"El significado de la palabra se desplaza así por los eslabones de la cadena compleja.","o":"Значение слова тем самым передвигается по звеньям комплексной цепи.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 5","te":["conocimiento"]},{"i":"lev-vygotsky-047","a":"lev-vygotsky","t":"En el complejo en cadena, el centro estructural puede faltar por completo.","o":"В цепном комплексе структурный центр может отсутствовать вовсе.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 5","te":["conocimiento"]},{"i":"lev-vygotsky-048","a":"lev-vygotsky","t":"Con frecuencia basta una semejanza lejana, un mero roce superficial de rasgos, para formar una conexión de hecho.","o":"Часто отдаленного сходства, самого поверхностного касания признаков оказывается достаточным для образования фактической связи.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 5","te":["conocimiento"]},{"i":"lev-vygotsky-049","a":"lev-vygotsky","t":"Podrían objetarnos que este modo condicional que empleamos habla más contra el experimento que a favor de él.","o":"Нам могли бы возразить, что это употребленное нами сослагательное наклонение говорит скорее против эксперимента, чем за него.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 5","te":["conocimiento"]},{"i":"lev-vygotsky-050","a":"lev-vygotsky","t":"Para el propio niño existen complejos equivalentes a los conceptos de los adultos, es decir, seudoconceptos.","o":"Для самого ребенка существуют комплексы, эквивалентные понятиям взрослых, т. е. псевдопонятия.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 5","te":["infancia","conocimiento"]},{"i":"lev-vygotsky-051","a":"lev-vygotsky","t":"Si se juzga por la semejanza externa, el seudoconcepto se parece al concepto verdadero como la ballena al pez.","o":"Если судить по внешнему сходству, то псевдопонятие так же похоже на истинное понятие, как кит—на рыбу.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 5","te":["conocimiento"]},{"i":"lev-vygotsky-052","a":"lev-vygotsky","t":"Dicho más sencillamente, el niño no crea su habla, sino que incorpora el habla ya hecha de los adultos que lo rodean.","o":"Проще говоря, ребенок не создает своей речи, но усваивает готовую речь окружающих его взрослых.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 5","te":["infancia","vinculos"]},{"i":"lev-vygotsky-053","a":"lev-vygotsky","t":"Precisamente por eso surge la enorme importancia funcional del seudoconcepto como forma particular, dual e internamente contradictoria, del pensamiento infantil.","o":"Именно благодаря этому возникает огромное функциональное значение псевдопонятия как особой двойственной внутренне противоречивой формы детского мышления.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 5","te":["infancia","conocimiento"]},{"i":"lev-vygotsky-054","a":"lev-vygotsky","t":"La comunicación verbal con los adultos se convierte así en un motor poderoso, en un factor potente del desarrollo de los conceptos infantiles.","o":"Речевое общение со взрослыми становится таким образом мощным двигателем, могучим фактором развития детских понятий.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 5","te":["vinculos","infancia"]},{"i":"lev-vygotsky-055","a":"lev-vygotsky","t":"Así se crea una situación genética peculiar, que representa más una regla general que una excepción en todo el desarrollo intelectual del niño.","o":"Таким образом создается своеобразное генетическое положение, представляющее скорее общее правило, нежели исключение, во всем интеллектуальном развитии ребенка.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 5","te":["infancia","cambio"]},{"i":"lev-vygotsky-056","a":"lev-vygotsky","t":"El desarrollo no es una función simple, determinada por completo por x unidades de herencia más y unidades de medio.","o":"Развитие не есть простая функция, полностью определяемая икс единицами наследственности плюс игрек единиц среды.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 5","te":["cambio","cultura"]},{"i":"lev-vygotsky-057","a":"lev-vygotsky","t":"A esta característica del pensamiento primitivo, que es evidentemente una propiedad del pensamiento en sus etapas genéticas tempranas, suele llamársela participación.","o":"Эту особенность примитивного мышления, составляющую очевидно свойство мышления на его ранних генетических ступенях, называют обычно партиципацией.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 5","te":["conocimiento","cultura"]},{"i":"lev-vygotsky-058","a":"lev-vygotsky","t":"No es un nombre que se atribuyen, no es un parentesco sobre el que insisten.","o":"Это не имя, которое они себе присваивают, это не родство, на котором они настаивают.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 5","te":["identidad","vinculos"]},{"i":"lev-vygotsky-059","a":"lev-vygotsky","t":"En la base de este pensamiento se halla un grupo concreto y visible de objetos.","o":"В основе этого мышления лежит наглядная группа конкретных предметов.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 5","te":["conocimiento"]},{"i":"lev-vygotsky-060","a":"lev-vygotsky","t":"Originalmente significaba la costura, el lugar de unión de dos trozos de tela, algo tejido junto.","o":"Первоначально оно означало шов, место соединения двух кусков ткани, нечто сотканное вместе.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 5","te":["cultura","conocimiento"]},{"i":"lev-vygotsky-061","a":"lev-vygotsky","t":"Se destaca algún rasgo concreto según el cual el objeto recibe su nombre.","o":"Выделяется какой-нибудь конкретный признак, по которому предмет получает свое название.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 5","te":["conocimiento","cultura"]},{"i":"lev-vygotsky-062","a":"lev-vygotsky","t":"En palabras de Potebnia, el lenguaje es el medio para comprenderse a sí mismo.","o":"По выражению Потебни, язык есть средство понимать самого себя.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 5","te":["conocimiento","cultura"]},{"i":"lev-vygotsky-063","a":"lev-vygotsky","t":"Los seudoconceptos no son un patrimonio exclusivo del niño.","o":"Псевдопонятия составляют не только исключительное достояние ребенка.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 5","te":["infancia","conocimiento"]},{"i":"lev-vygotsky-064","a":"lev-vygotsky","t":"En este sentido, el pensamiento en complejos resulta impotente.","o":"В этом отношении комплексное мышление оказывается беспомощным.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 5","te":["conocimiento"]},{"i":"lev-vygotsky-065","a":"lev-vygotsky","t":"Es más pobre que el seudoconcepto porque las conexiones sobre las que se sostiene esa construcción son extremadamente pobres: se agotan en la vaga impresión de comunidad o de máxima semejanza.","o":"Оно беднее псевдопонятия потому, что связи, на которых держится это построение, чрезвычайно бедны, они исчерпываются только смутным впечатлением общности или максимального сходства.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 5","te":["conocimiento"]},{"i":"lev-vygotsky-066","a":"lev-vygotsky","t":"No es un concepto, pero es algo que puede llegar a serlo.","o":"Это не понятие, но это нечто такое, что может стать таковым.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 5","te":["conocimiento","cambio"]},{"i":"lev-vygotsky-067","a":"lev-vygotsky","t":"Y un fenómeno así merece en verdad el nombre de concepto potencial.","o":"И такое явление действительно заслуживает названия потенциального понятия.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 5","te":["conocimiento"]},{"i":"lev-vygotsky-068","a":"lev-vygotsky","t":"Las representaciones de estos tres árboles pueden descomponerse en sus partes componentes, cada una de las cuales designa la forma, el color o el tamaño de los árboles individuales.","o":"Представления этих трех деревьев могут быть разложены на свои составные части, из которых каждая обозначает форму, цвет или величину отдельных деревьев.","l":"ru","ob":"Pensamiento y lenguaje","an":"1934","u":"Capítulo 5","te":["conocimiento"]},{"i":"wilhelm-wundt-001","a":"wilhelm-wundt","t":"Hay que considerar ante todo la psicología como una ciencia de la experiencia.","o":"Wir haben die Seelenlehre vor allem zu betrachten als eine Wissenschaft der Erfahrung.","l":"de","ob":"Lecciones sobre el alma humana y animal","an":"1892","u":"","te":["conocimiento","conciencia"]},{"i":"wilhelm-wundt-002","a":"wilhelm-wundt","t":"¿Cómo es posible, sin embargo, ampliar nuestra experiencia sobre sensaciones, sentimientos y pensamientos?","o":"Wie ist es aber möglich, über Empfindungen, Gefühle, Gedanken seine Erfahrungen zu erweitern?","l":"de","ob":"Lecciones sobre el alma humana y animal","an":"1892","u":"","te":["conciencia","emociones","conocimiento"]},{"i":"wilhelm-wundt-003","a":"wilhelm-wundt","t":"Somos nosotros quienes, por los elementos de representación que están listos para asociarse en nosotros, cambiamos los fenómenos, sin quererlo y sin saberlo.","o":"Wir sind es, die in Folge der in uns zur Association bereit liegenden Vorstellungselemente die Erscheinungen verändern, ohne es zu wollen und ohne es zu wissen.","l":"de","ob":"Lecciones sobre el alma humana y animal","an":"1892","u":"","te":["inconsciente","conciencia"]},{"i":"wilhelm-wundt-004","a":"wilhelm-wundt","t":"Esta experiencia actúa sobre mi percepción y modifica la representación que, de otro modo, me habría formado de la distancia de los objetos vistos.","o":"Diese Erfahrung wirkt auf meine Anschauung ein und verändert die Vorstellung, die ich mir sonst nach der Entfernung der gesehenen Gegenstände gebildet hätte.","l":"de","ob":"Lecciones sobre el alma humana y animal","an":"1892","u":"","te":["conciencia","cuerpo"]},{"i":"wilhelm-wundt-005","a":"wilhelm-wundt","t":"Una trama muy variada de representaciones puede dar lugar, aquí, a un sentimiento que, en general, es el mismo.","o":"Ein sehr mannigfacher Vorstellungszusammenhang kann hier zu einem im allgemeinen übereinstimmenden Gefühl Veranlassung bieten.","l":"de","ob":"Lecciones sobre el alma humana y animal","an":"1892","u":"","te":["emociones","conciencia"]},{"i":"wilhelm-wundt-022","a":"wilhelm-wundt","t":"A veces se ha intentado restringir el término sentimiento, porque bajo ese nombre parecían reunirse procesos demasiado distintos.","o":"Man hat die Bezeichnung Gefühl zuweilen einzuschränken gesucht, weil man unter diesem Titel allzu verschiedene Vorgänge vereinigt zu finden meinte.","l":"de","ob":"Lecciones sobre el alma humana y animal","an":"1892","u":"","te":["emociones","conocimiento"]},{"i":"wilhelm-wundt-023","a":"wilhelm-wundt","t":"Por eso, en este caso, se suele poner en lugar de esos procesos su resultado subjetivo, el sentimiento, que resume la multiplicidad de lo que sirve de fondo objetivo.","o":"Man substituirt daher in diesem Fall mit Vorliebe das subjektive Resultat, das Gefühl, der Mannigfaltigkeit jener Vorgänge, die demselben zum objektiven Hintergrund dienen.","l":"de","ob":"Lecciones sobre el alma humana y animal","an":"1892","u":"","te":["emociones","conciencia"]},{"i":"wilhelm-wundt-046","a":"wilhelm-wundt","t":"El alma es aire o fuego o éter; pero siempre sigue siendo una materia, aunque se intente cada vez más volatilizar esa materia y así volverla espiritual.","o":"Die Seele ist Luft oder Feuer oder ein Aether, immer aber bleibt sie ein Stoff, mag man auch mehr und mehr diesen Stoff zu verflüchtigen suchen und ihn dadurch zu vergeistigen meinen.","l":"de","ob":"Lecciones sobre el alma humana y animal","an":"1892","u":"","te":["conciencia","identidad"]},{"i":"wilhelm-wundt-047","a":"wilhelm-wundt","t":"Lo que del cuadro de la retina actúa sobre nuestra alma es solamente una serie de sensaciones coloreadas localmente.","o":"Was vom Netzhautbild auf unsere Seele einwirkt, ist lediglich eine Reihe lokal gefärbter Empfindungen.","l":"de","ob":"Lecciones sobre el alma humana y animal","an":"1892","u":"","te":["conciencia","cuerpo"]},{"i":"wilhelm-wundt-006","a":"wilhelm-wundt","t":"Me he esforzado seriamente por cumplir ese deber, en particular en lo que digo sobre el problema religioso y el social.","o":"Ich bin namentlich auch in den Ausführungen über das religiöse und das soziale Problem ernstlich bemüht gewesen, diese Pflicht zu erfüllen.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["responsabilidad","sociedad"]},{"i":"wilhelm-wundt-007","a":"wilhelm-wundt","t":"El pensamiento y la acción humanos están en un flujo continuo de desarrollo.","o":"Menschliches Denken und menschliches Handeln sind in einem fortwährenden Fluß der Entwicklung.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["desarrollo-humano","cambio"]},{"i":"wilhelm-wundt-008","a":"wilhelm-wundt","t":"Así, lo moral es la última fuente del concepto de norma, y la ética es la ciencia originaria de las normas.","o":"So ist das Sittliche die letzte Quelle des Normbegriffs, und die Ethik ist die ursprüngliche Normwissenschaft.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["responsabilidad","sociedad"]},{"i":"wilhelm-wundt-009","a":"wilhelm-wundt","t":"Pero, es cierto, alcanza ese objetivo solo mediante un autoengaño, cuyas consecuencias se sienten en todas partes donde pasa a aplicar sus principios.","o":"Aber freilich, sie erreicht dieses Ziel doch nur durch eine Selbsttäuschung, deren Folgen überall fühlbar werden, wo sie zur Anwendung ihrer Prinzipien übergeht.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["autoconocimiento","responsabilidad"]},{"i":"wilhelm-wundt-010","a":"wilhelm-wundt","t":"Así, el lenguaje forma de la culpa la inocencia, del pecado la ausencia de pecado, de la envidia la ausencia de envidia, del egoísmo la abnegación.","o":"So bildet die Sprache aus der Schuld die Unschuld, aus der Sünde die Sündlosigkeit, aus dem Neid die Neidlosigkeit, aus der Selbstsucht die Selbstlosigkeit.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["culpa","lenguaje","vinculos"]},{"i":"wilhelm-wundt-011","a":"wilhelm-wundt","t":"El carácter general de los conceptos se conserva, pero cambian sus relaciones más profundas y su valor afectivo.","o":"Der Gesamtcharakter der Begriffe bleibt erhalten, aber die tieferen Beziehungen derselben und ihr Gefühlswert verändern sich.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["emociones","cambio"]},{"i":"wilhelm-wundt-012","a":"wilhelm-wundt","t":"Un concepto general de lo moral solo será posible cuando el proceso de separación se haya cumplido en cada caso particular.","o":"Ein Gesamtbegriff des Sittlichen wird ja dann erst möglich sein, wenn sich dieser Prozeß der Trennung im einzelnen bereits vollzogen hat.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["responsabilidad","conocimiento"]},{"i":"wilhelm-wundt-013","a":"wilhelm-wundt","t":"El niño tiene algunas cualidades en común con el ser humano primitivo, pero no es él mismo, ni vive bajo las mismas influencias externas que él.","o":"Das Kind hat einige Eigenschaften mit dem primitiven Menschen gemein, aber es ist weder selbst ein solcher, noch lebt es unter den nämlichen äußeren Einwirkungen wie er.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["infancia","desarrollo-humano"]},{"i":"wilhelm-wundt-014","a":"wilhelm-wundt","t":"Pero no hay que olvidar que, en todas partes, solo los motivos que despiertan la esperanza o el temor de las personas producen un efecto duradero.","o":"Aber dabei ist doch nicht zu vergessen, daß überall erst solche Motive, welche die Hoffnung oder Furcht des Menschen erregen, eine nachhaltigere Wirkung äußern.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["esperanza","miedo"]},{"i":"wilhelm-wundt-015","a":"wilhelm-wundt","t":"También aquí el material mítico adquiere su valor ético por relaciones afectivas originarias que existen entre la acción humana y la naturaleza exterior.","o":"So gewinnt auch hier der mythische Stoff seinen ethischen Wert durch ursprüngliche Gefühlsbeziehungen, die zwischen dem menschlichen Tun und der äußeren Natur bestehen.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["emociones","naturaleza","cultura"]},{"i":"wilhelm-wundt-016","a":"wilhelm-wundt","t":"Por un lado, hay en ella la idea de que demasiada felicidad vuelve fácilmente soberbio al ser humano y así altera el equilibrio de sus fuerzas morales.","o":"Auf der einen Seite liegt in ihr der Gedanke, daß allzuviel Glück leicht den Menschen übermütig mache und so das Gleichgewicht seiner sittlichen Kräfte störe.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["felicidad","autoestima"]},{"i":"wilhelm-wundt-017","a":"wilhelm-wundt","t":"Religión y moral ya no se distinguen en lo esencial por su contenido, sino por el punto de vista desde el que se consideran ese contenido.","o":"Religion und Sittlichkeit scheiden sich nun im wesentlichen nicht mehr nach ihrem Inhalt, sondern nach dem Standpunkt der Betrachtung, den sie gegenüber diesem Inhalte einnehmen.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["espiritualidad","responsabilidad"]},{"i":"wilhelm-wundt-018","a":"wilhelm-wundt","t":"El lugar natural de origen de las representaciones y los sentimientos religiosos, sin embargo, es la conciencia de los pueblos.","o":"Der natürliche Entstehungsort der religiösen Vorstellungen und Gefühle ist jedoch das Völkerbewußtsein.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["espiritualidad","cultura","sociedad"]},{"i":"wilhelm-wundt-019","a":"wilhelm-wundt","t":"La relación de lo moral con lo religioso, en cuanto a la extensión de sus ámbitos, se parece a la de lo religioso con lo mítico.","o":"Das Verhältnis des Sittlichen zu dem Religiösen gestaltet sich so in Bezug auf den Umfang der Gebiete wiederum ähnlich wie das des Religiösen zum Mythischen.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["espiritualidad","cultura"]},{"i":"wilhelm-wundt-020","a":"wilhelm-wundt","t":"Nace de una percepción personificadora, cuya esencia consiste en que el ser humano objetiva su propia conciencia.","o":"Sie entspringt aus einer personifizierenden Apperzeption, deren Wesen darin besteht, daß der Mensch sein eigenes Bewußtsein objektiviert.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["conciencia","identidad","espiritualidad"]},{"i":"wilhelm-wundt-021","a":"wilhelm-wundt","t":"Ciertamente, es completamente antipsicológico suponer que el ser humano llegó al mundo con la necesidad de explicar la naturaleza, o con esa necesidad como lo único.","o":"Gewiß, es ist völlig unpsychologisch, vorauszusetzen, der Mensch sei mit dem Bedürfnis nach Naturerklärung oder gar allein mit diesem in die Welt getreten.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["conocimiento","naturaleza"]},{"i":"wilhelm-wundt-029","a":"wilhelm-wundt","t":"Como condición necesaria de tales juicios de valor se muestra siempre la existencia de la voluntad humana libre.","o":"Als eine notwendige Bedingung solcher Werturteile erweist sich stets das Dasein des freien menschlichen Willens.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["libertad","responsabilidad"]},{"i":"wilhelm-wundt-030","a":"wilhelm-wundt","t":"Las leyes éticas, en cambio, nos introducen en el centro de las complicadas cadenas de nuestros actos de voluntad.","o":"Die ethischen Gesetze dagegen führen mitten hinein in die verwickelten Verkettungen unserer Willenshandlungen.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["voluntad","responsabilidad"]},{"i":"wilhelm-wundt-031","a":"wilhelm-wundt","t":"Una reflexión sobre uno mismo como esa necesita, sin embargo, supuestos y procedimientos determinados.","o":"Eine solche Selbstbesinnung bedarf aber notwendig bestimmter Voraussetzungen und Verfahrungsweisen.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["autoconocimiento","conocimiento"]},{"i":"wilhelm-wundt-032","a":"wilhelm-wundt","t":"[La costumbre] contiene ciencia y religión, y rige tanto las costumbres del hogar como la vida pública.","o":"Sie enthält Wissenschaft und Religion, sie beherrscht die häusliche Sitte ebenso wie das öffentliche Leben.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["cultura","sociedad","familia"]},{"i":"wilhelm-wundt-033","a":"wilhelm-wundt","t":"[Las costumbres] han fundado el orden moral del mundo, y lo sostienen mediante premio y castigo.","o":"Sie haben die sittliche Weltordnung gegründet, und sie erhalten sie durch Belohnung und Strafe.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["sociedad","responsabilidad"]},{"i":"wilhelm-wundt-034","a":"wilhelm-wundt","t":"Pues la disposición moral no es algo que pueda producirse a voluntad pensando en las recompensas o los castigos que la acompañan.","o":"Denn die sittliche Gesinnung ist nichts, was mit Rücksicht auf Belohnungen oder Strafen, die ihr zu teil werden, willkürlich hervorgebracht werden könnte.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["responsabilidad","libertad"]},{"i":"wilhelm-wundt-035","a":"wilhelm-wundt","t":"La costumbre puede vigilar con todo rigor los actos de cada individuo, pero siempre le deja la posibilidad de eludir sus prescripciones.","o":"Die Sitte mag noch so strenge die Handlungen des Einzelnen überwachen, sie läßt diesem doch immer die Wahl frei, sich ihren Vorschriften zu entziehen.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["libertad","sociedad"]},{"i":"wilhelm-wundt-036","a":"wilhelm-wundt","t":"Por eso, el ser humano comparte con el animal la costumbre, pero la costumbre moral es un privilegio humano.","o":"Darum hat der Mensch zwar die Gewohnheit mit dem Tiere gemein, aber die Sitte ist menschliches Vorrecht.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["habitos","identidad"]},{"i":"wilhelm-wundt-037","a":"wilhelm-wundt","t":"La ley, en cambio, se separa de la costumbre: impone el deber que enuncia mediante castigos determinados contra su transgresión.","o":"Das Gesetz aber scheidet sich von der Sitte, indem es die Pflicht, die es ausspricht, durch bestimmte Strafgebote, die es gegen ihre Übertretung richtet, erzwingt.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["responsabilidad","miedo"]},{"i":"wilhelm-wundt-038","a":"wilhelm-wundt","t":"El derecho en todas sus formas, como derecho consuetudinario o como derecho legislado, debe su vigencia a los medios de coacción física de que dispone.","o":"Das Recht in allen seinen Formen, als Gewohnheitsrecht wie als Gesetzesrecht, verdankt seine Aufrechterhaltung den physischen Zwangsmitteln, die ihm zu Gebote stehen.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["poder","sociedad"]},{"i":"wilhelm-wundt-039","a":"wilhelm-wundt","t":"La costumbre de los tiempos primitivos da origen a ambos ámbitos, mientras que al mismo tiempo se separa un tercero, en forma de costumbre moralmente indiferente.","o":"Die Sitte der Urzeit entläßt aus sich beide Gebiete, während zugleich ein drittes in der Form sittlich indifferenter Sitte sich abzweigt.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["cultura","sociedad"]},{"i":"wilhelm-wundt-040","a":"wilhelm-wundt","t":"La propina es, por eso, un ejemplo curioso de una costumbre cuyo sentido original se ha vuelto por completo su contrario.","o":"Das Trinkgeld ist daher ein merkwürdiges Beispiel einer Sitte, deren ursprünglicher Sinn sich vollständig in sein Gegenteil verkehrt hat.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["cultura","cambio"]},{"i":"wilhelm-wundt-041","a":"wilhelm-wundt","t":"Su castigo recae a veces solo sobre el criminal y a veces también sobre sus compañeros de clan y sus descendientes.","o":"Ihre Strafe trifft den Verbrecher bald allein, bald zusammen mit seinen Stammesgenossen und Nachkommen.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["culpa","sociedad","familia"]},{"i":"wilhelm-wundt-042","a":"wilhelm-wundt","t":"No solo la desgracia, sino también la culpa de los hijos y nietos se considera una expiación por la culpa de los antepasados.","o":"Nicht bloß das Unglück, sondern auch die Schuld ihrer Söhne und Enkel wird als eine Sühne für die Schuld der Vorfahren betrachtet.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["culpa","familia"]},{"i":"wilhelm-wundt-043","a":"wilhelm-wundt","t":"También la “mala costumbre” sigue siendo costumbre mientras conserve el carácter de norma que liga a las personas.","o":"Auch die „schlechte Sitte“ bleibt eine Sitte, so lange ihr überhaupt der Charakter der verbindenden Norm zukommt.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["habitos","sociedad"]},{"i":"wilhelm-wundt-044","a":"wilhelm-wundt","t":"Ofender al huésped, a quien el pacto sellado casi a la vista de los dioses ha consagrado, era considerado una grave culpa contra los propios dioses.","o":"Den Gastfreund zu verletzen, den der gleichsam im Angesicht der Götter geschlossene Opferbund geheiligt, galt als eine schwere Schuld gegen die Götter selbst.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["culpa","vinculos","espiritualidad"]},{"i":"wilhelm-wundt-045","a":"wilhelm-wundt","t":"Si la costumbre es una medida del estado moral, lo es tanto por sus elementos morales como por los inmorales.","o":"Ist die Sitte ein Wertmesser des sittlichen Zustandes, so wird sie dazu ebensowohl durch ihre sittlichen wie durch ihre unsittlichen Bestandteile.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["responsabilidad","cultura"]},{"i":"wilhelm-wundt-048","a":"wilhelm-wundt","t":"En nuestra cultura actual, la costumbre se ha alejado tanto de su origen religioso que religión y costumbre nos parecen dos ámbitos totalmente distintos.","o":"In unserer heutigen Kultur ist die Sitte ihrem religiösen Ursprung so sehr entfremdet, daß uns Religion und Sitte als zwei völlig verschiedene Gebiete gelten.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["cultura","espiritualidad"]},{"i":"wilhelm-wundt-049","a":"wilhelm-wundt","t":"Ya en los instintos sociales de los animales, los fenómenos y sus condiciones suelen ser de un tipo más complicado.","o":"Schon bei den sozialen Trieben der Tiere sind die Erscheinungen wie ihre Bedingungen in der Regel von verwickelterer Art.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["naturaleza","vinculos"]},{"i":"wilhelm-wundt-050","a":"wilhelm-wundt","t":"Les siguen aquellos mandatos morales del deber que, como el respeto a los mayores o la piedad hacia los padres, todavía durante bastante tiempo ocupan una posición incierta entre costumbre y derecho.","o":"Ihnen folgen jene sittlichen Pflichtgebote, die, wie die Achtung des Alters, die Pietät gegen die Eltern, noch längere Zeit eine ungewisse Stellung zwischen Sitte und Recht behaupten.","l":"de","ob":"Ética. Una investigación de los hechos y leyes de la vida moral","an":"1903","u":"","te":["responsabilidad","familia","sociedad"]},{"i":"wilhelm-wundt-024","a":"wilhelm-wundt","t":"Estímulos más intensos despiertan inevitablemente sentimientos más intensos, que siempre pasan a ser afectos.","o":"Stärkere Reize erwecken unvermeidlich auch stärkere Gefühle, und diese gehen stets in Affekte über.","l":"de","ob":"Psicología de los pueblos (texto de Wundt)","an":"1904","u":"","te":["emociones","regulacion-emocional"]},{"i":"wilhelm-wundt-025","a":"wilhelm-wundt","t":"Por eso, el análisis de los sentimientos es una de las tareas más difíciles y más discutidas de la psicología.","o":"Die Analyse der Gefühle gehört deshalb zu den mißlichsten und meistumstrittenen Aufgaben der Psychologie.","l":"de","ob":"Psicología de los pueblos (texto de Wundt)","an":"1904","u":"","te":["emociones","conocimiento"]},{"i":"wilhelm-wundt-026","a":"wilhelm-wundt","t":"El lenguaje, como ya enseña su relación con el mito, depende en todas partes de motivos afectivos, y según su carácter más propio es una función de la voluntad.","o":"Die Sprache ist, wie schon ihr Verhältnis zum Mythus lehrt, überall von Gefühlsmotiven abhängig, und nach ihrem eigensten Charakter ist sie eine Willensfunktion.","l":"de","ob":"Psicología de los pueblos (texto de Wundt)","an":"1904","u":"","te":["lenguaje","emociones","voluntad"]},{"i":"wilhelm-wundt-027","a":"wilhelm-wundt","t":"Del mismo modo, los movimientos expresivos de la ira, de la alegría desbordada, de la pena profunda y de otros afectos pertenecen en su mayoría a las acciones instintivas.","o":"Ebenso gehören die Ausdrucksbewegungen des Zorns, der ausgelassenen Freude, des tiefen Kummers und anderer Affekte zumeist zu den Triebhandlungen.","l":"de","ob":"Psicología de los pueblos (texto de Wundt)","an":"1904","u":"","te":["emociones","cuerpo","ira"]},{"i":"wilhelm-wundt-028","a":"wilhelm-wundt","t":"En estas relaciones se fundan las dificultades que encuentra el estudio de los sentimientos puros.","o":"In diesen Verhältnissen liegen die Schwierigkeiten begründet, denen die Untersuchung der reinen Gefühle begegnet.","l":"de","ob":"Psicología de los pueblos (texto de Wundt)","an":"1904","u":"","te":["emociones","conocimiento"]},{"i":"edmund-husserl-001","a":"edmund-husserl","t":"Me inquietó entonces la duda de principio sobre cómo puede conciliarse la objetividad de la matemática y de toda ciencia con una fundamentación psicológica de lo lógico.","o":"Umsomehr beunruhigte mich daher auch der principielle Zweifel, wie sich die Objectivität der Mathematik und aller Wissenschaft überhaupt mit einer psychologischen Begründung des Logischen vertrage.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento","verdad"]},{"i":"edmund-husserl-002","a":"edmund-husserl","t":"El ámbito de una ciencia es una unidad objetivamente cerrada: no depende de nuestro arbitrio dónde y cómo delimitamos los campos de la verdad.","o":"Das Gebiet einer Wissenschaft ist eine objectiv geschlossene Einheit, es liegt nicht in unserer Willkür, wo und wie wir Wahrheitsgebiete abgrenzen.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["verdad","conocimiento"]},{"i":"edmund-husserl-003","a":"edmund-husserl","t":"De ahí se sigue naturalmente la pregunta por los fundamentos teóricos de esta disciplina y, en particular, por su relación con la psicología.","o":"Daran schließt sich naturgemäß die Frage nach den theoretischen Grundlagen dieser Disciplin und im Besonderen nach ihrem Verhältnis zur Psychologie.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento","conciencia"]},{"i":"edmund-husserl-004","a":"edmund-husserl","t":"El signo más perfecto de la corrección es la evidencia: vale para nosotros como percepción inmediata de la verdad misma.","o":"Das vollkommenste Kennzeichen der Richtigkeit ist die Evidenz, es gilt uns als unmittelbares Innewerden der Wahrheit selbst.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["verdad","conocimiento"]},{"i":"edmund-husserl-005","a":"edmund-husserl","t":"En última instancia, todo conocimiento genuino, y en especial todo conocimiento científico, descansa sobre la evidencia; y el concepto de saber alcanza hasta donde llega la evidencia.","o":"Im letzten Grunde beruht also jede echte und speciell jede wissenschaftliche Erkenntnis auf Evidenz, und so weit die Evidenz reicht, so weit reicht auch der Begriff des Wissens.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["verdad","conocimiento"]},{"i":"edmund-husserl-006","a":"edmund-husserl","t":"Si vivimos percepciones internas, una por una o en grupos, y las reconocemos como existentes, tenemos saber, pero todavía no ciencia.","o":"Wenn wir innere Wahrnehmungen, einzeln oder gruppenweise erleben und als daseiend anerkennen, so haben wir Wissen aber noch lange nicht Wissenschaft.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conciencia","conocimiento"]},{"i":"edmund-husserl-007","a":"edmund-husserl","t":"Y lo mismo ocurre con los grupos sin conexión de actos de saber en general.","o":"Und nicht anders verhält es sich mit zusammenhangslosen Gruppen von Wissensacten überhaupt.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento"]},{"i":"edmund-husserl-008","a":"edmund-husserl","t":"La ciencia quiere darnos una variedad del saber, pero no una mera variedad.","o":"Zwar Mannigfaltigkeit des Wissens aber nicht bloße Mannigfaltigkeit will die Wissenschaft uns geben.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento"]},{"i":"edmund-husserl-009","a":"edmund-husserl","t":"Pero se requiere algo más: una conexión sistemática en sentido teórico, en la que se fundamenta el saber y se ordena la sucesión de los fundamentos.","o":"Offenbar ist mehr erfordert, nämlich systematischer Zusammenhang im theoretischen Sinne, und darin liegt Begründung des Wissens und gehörige Verknüpfung und Ordnung in der Folge der Begründungen.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento"]},{"i":"edmund-husserl-010","a":"edmund-husserl","t":"La sistemática que corresponde a la ciencia verdadera y auténtica no la inventamos: está en las cosas mismas, donde simplemente la encontramos y descubrimos.","o":"Die Systematik, die der Wissenschaft eignet, natürlich der echten und rechten Wissenschaft, erfinden wir nicht, sondern sie liegt in den Sachen, wo wir sie einfach vorfinden, entdecken.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento","verdad"]},{"i":"edmund-husserl-011","a":"edmund-husserl","t":"¿Para qué investigar las relaciones de fundamentación y construir pruebas, si se llega a participar de la verdad por intuición inmediata?","o":"Wozu die Begründungsverhältnisse erforschen und Beweise construiren, wenn man der Wahrheit in unmittelbarem Innewerden theilhaftig wird?","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento","verdad"]},{"i":"edmund-husserl-012","a":"edmund-husserl","t":"Porque los tipos de prueba se le han grabado cada vez más hondo por la experiencia múltiple, y por eso le resultan mucho más eficaces y determinan la dirección de su pensamiento.","o":"Weil sich ihm die Typen der Beweise durch mannigfache Erfahrung immer tiefer eingegraben haben und darum für ihn viel leichter wirksam und die Gedankenrichtung bestimmend sein müssen.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento","habitos"]},{"i":"edmund-husserl-013","a":"edmund-husserl","t":"Por maravillosos que sean los logros de estos métodos, solo obtienen sentido y justificación de la esencia del pensar fundamentador.","o":"Wie Wunderbares diese Methoden auch leisten, sie gewinnen Sinn und Rechtfertigung nur aus dem Wesen des begründenden Denkens.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento"]},{"i":"edmund-husserl-014","a":"edmund-husserl","t":"Distinguir las fundamentaciones válidas de las inválidas, y también las teorías y ciencias válidas de las inválidas, le corresponde a ella.","o":"Nicht allein giltige und ungiltige Begründungen, sondern auch giltige und ungiltige Theorien und Wissenschaften zu scheiden, fällt ihr zu.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento","verdad"]},{"i":"edmund-husserl-015","a":"edmund-husserl","t":"Que una ciencia sea en verdad ciencia, y un método en verdad método, depende de si se ajusta al fin que persigue.","o":"Ob eine Wissenschaft in Wahrheit Wissenschaft, eine Methode in Wahrheit Methode ist, das hängt davon ab, ob sie dem Ziele gemäß ist, dem sie zustrebt.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento","verdad"]},{"i":"edmund-husserl-016","a":"edmund-husserl","t":"Lo que nos da en particular la doctrina de la ciencia, y lo único que puede darnos, son criterios especiales.","o":"Was uns im Besonderen die Wissenschaftslehre giebt und allein geben kann, sind Specialkriterien.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento"]},{"i":"edmund-husserl-017","a":"edmund-husserl","t":"Que esa definición es demasiado estrecha se deduce de que de ella no puede derivarse el fin del conocimiento científico.","o":"Daß diese Definition aber zu enge ist, geht nun daraus hervor, daß aus ihr der Zweck der wissenschaftlichen Erkenntnis nicht ableitbar ist.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento"]},{"i":"edmund-husserl-018","a":"edmund-husserl","t":"Excelentes ideas para delimitar nuestra disciplina se encuentran en la “Doctrina de la ciencia” de Bolzano, pero más en sus investigaciones críticas preliminares que en la definición que él mismo prefiere.","o":"Vortreffliche Gedanken zur Umgrenzung unserer Disciplin findet man in Bolzano's \"Wissenschaftslehre\", aber mehr in den kritischen Voruntersuchungen als in der Definition, die er selbst bevorzugt.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento"]},{"i":"edmund-husserl-019","a":"edmund-husserl","t":"Si reunimos a Erdmann y Drobisch, Wundt y Bergmann, Schuppe y Brentano, Sigwart y Ueberweg, ¿es todo esto una sola ciencia y no solo un nombre?","o":"Stellen wir Erdmann und Drobisch, Wundt und Bergmann, Schuppe und Brentano, Sigwart und Ueberweg zusammen - ist das alles Eine Wissenschaft und nicht bloß Ein Name?","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento","conciencia"]},{"i":"edmund-husserl-020","a":"edmund-husserl","t":"Hay, por tanto, leyes naturales del pensar y, además, leyes normales para él: prescripciones (normas) según las cuales debe regirse para llegar a resultados verdaderos.","o":"Es giebt daher sowol Naturgesetze des Denkens als Normalgesetze für dasselbe, Vorschriften (Normen), nach denen es sich zu richten hat, um zu wahren Ergebnissen zu führen.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento","verdad","conciencia"]},{"i":"edmund-husserl-021","a":"edmund-husserl","t":"Los juicios de forma normativa que acabamos de exponer no son, evidentemente, los únicos que se aceptarán como tales, aunque en la expresión no aparezca la palabra “deber”.","o":"Die soeben klargelegten Urtheile normativer Form sind offenbar nicht die einzigen, die man als solche wird gelten lassen, mag auch im Ausdruck das Wörtchen Sollen keine Verwendung finden.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["responsabilidad","conocimiento"]},{"i":"edmund-husserl-022","a":"edmund-husserl","t":"Pero, además de esta idea común de medirse por la norma fundamental, estas proposiciones tienen un contenido teórico propio, que distingue unas de otras.","o":"Aber neben diesem gemeinsamen Gedanken der Abmessung an der Grundnorm besitzen diese Sätze einen eigenen, den einen vom anderen unterscheidenden theoretischen Gehalt.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento","responsabilidad"]},{"i":"edmund-husserl-023","a":"edmund-husserl","t":"A ello se suman los conocimientos teóricos que deben ofrecer la base para una realización fecunda de fines y medios.","o":"Es treten die theoretischen Erkenntnisse hinzu, welche die Grundlage für eine fruchtbare Realisirung der Zwecke und Mittel bieten müssen.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento","trabajo"]},{"i":"edmund-husserl-024","a":"edmund-husserl","t":"La cuestión disputada es si los fundamentos teóricos esenciales de la lógica normativa residen en la psicología.","o":"Die Streitfrage, ob die wesentlichen theoretischen Fundamente der normativen Logik in der Psychologie liegen.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento","conciencia"]},{"i":"edmund-husserl-025","a":"edmund-husserl","t":"Para delimitar una nueva ciencia teórica, sobre todo una que merezca en un sentido más estricto y preciso el nombre de lógica, no hay motivo alguno en esta corriente.","o":"Zur Abgrenzung einer neuen theoretischen Wissenschaft, zumal einer solchen, die in einem engeren und prägnanteren Sinne den Namen Logik verdienen sollte, besteht für diese Richtung kein Anlaß.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento"]},{"i":"edmund-husserl-026","a":"edmund-husserl","t":"No pocas veces se habla como si la psicología diera el único y suficiente fundamento teórico para el arte lógico.","o":"Ja nicht selten spricht man so, als gäbe die Psychologie das alleinige und ausreichende theoretische Fundament für die logische Kunstlehre.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento","conciencia"]},{"i":"edmund-husserl-027","a":"edmund-husserl","t":"Por estrechos que se tracen los límites de la lógica pura, no se podrá mantener alejado lo psicológico.","o":"Man möge der reinen Logik noch so enge Grenzen ziehen, das Psychologische wird man nicht fernhalten können.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento","conciencia"]},{"i":"edmund-husserl-028","a":"edmund-husserl","t":"La primera tiene que ver con las leyes naturales; la segunda, con las leyes normales del pensar.","o":"Die erstere hat es mit den Naturgesetzen, die letztere mit den Normalgesetzen des Denkens zu thun.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento","conciencia"]},{"i":"edmund-husserl-029","a":"edmund-husserl","t":"Las reglas de la lógica deben tomarse, por tanto, no de un uso casual, sino del uso necesario de la razón, que se encuentra en uno mismo sin ninguna psicología.","o":"Die Regeln der Logik müssen daher nicht vom zufälligen, sondern vom nothwendigen Vernunftgebrauche hergenommen sein, den man ohne alle Psychologie bei sich findet.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento","conciencia"]},{"i":"edmund-husserl-030","a":"edmund-husserl","t":"En lógica no queremos saber cómo es y piensa el entendimiento, ni cómo ha procedido hasta ahora en su pensar, sino cómo debería proceder al pensar.","o":"Wir wollen in der Logik nicht wissen: wie der Verstand ist und denkt, und wie er bisher im Denken verfahren ist, sondern: wie er im Denken verfahren sollte.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento","responsabilidad"]},{"i":"edmund-husserl-031","a":"edmund-husserl","t":"Ellos responden: el uso necesario del entendimiento es también un uso del entendimiento, y pertenece con el entendimiento mismo a la psicología.","o":"Sie antworten: der notwendige Verstandesgebrauch ist eben auch ein Verstandesgebrauch und gehört mit dem Verstände selbst in die Psychologie.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento","conciencia"]},{"i":"edmund-husserl-032","a":"edmund-husserl","t":"¿Se quiere negar que las leyes normales del pensar tienen el carácter de tales leyes psicológicas especiales?","o":"Will man leugnen, daß die Normalgesetze des Denkens den Charakter solcher psychologischen Specialgesetze haben?","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento","conciencia"]},{"i":"edmund-husserl-033","a":"edmund-husserl","t":"Ciertamente, la lógica tiene una tarea muy distinta de la psicología: ¿quién lo negará?","o":"Gewiß hat die Logik eine ganz andere Aufgabe als die Psychologie, wer wird dies auch leugnen?","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento","conciencia"]},{"i":"edmund-husserl-034","a":"edmund-husserl","t":"Queda abierta la posibilidad de que otra ciencia, y quizás de modo mucho más significativo, contribuya a su fundamentación.","o":"Die Möglichkeit bleibt offen, daß eine andere Wissenschaft und vielleicht in ungleich bedeutsamerer Weise zu ihrer Fundirung beitrüge.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento"]},{"i":"edmund-husserl-035","a":"edmund-husserl","t":"Coloquémonos por un momento en el terreno de la lógica psicologista: supongamos que los fundamentos teóricos esenciales de las prescripciones lógicas residen en la psicología.","o":"Stellen wir uns für den Augenblick auf den Boden der psychologistischen Logik, nehmen wir also an, es lägen die wesentlichen theoretischen Fundamente der logischen Vorschriften in der Psychologie.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento","conciencia"]},{"i":"edmund-husserl-036","a":"edmund-husserl","t":"No se pretende con esto menospreciar en absoluto a la psicología, cuya crítica me es completamente ajena.","o":"Keineswegs soll durch ihn irgend welche Geringschätzung der Psychologie ausgedrückt sein, der etwas am Zeuge flicken zu wollen, mir gänzlich fern liegt.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento","conciencia"]},{"i":"edmund-husserl-037","a":"edmund-husserl","t":"No por inducción, sino por evidencia apodíctica, encuentran fundamento y justificación.","o":"Nicht durch Induction, sondern durch apodictische Evidenz finden sie Begründung und Rechtfertigung.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["verdad","conocimiento"]},{"i":"edmund-husserl-038","a":"edmund-husserl","t":"Lo que se justifica con evidencia no son meras probabilidades de su validez, sino su validez o verdad misma.","o":"Einsichtig gerechtfertigt sind nicht bloße Wahrscheinlichkeiten ihrer Geltung, sondern ihre Geltung oder Wahrheit selbst.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["verdad","conocimiento"]},{"i":"edmund-husserl-039","a":"edmund-husserl","t":"Porque no tenemos conocimiento de la mera probabilidad, sino de la verdad de las leyes lógicas.","o":"Wir haben ja Einsicht nicht in die bloße Wahrscheinlichkeit, sondern in die Wahrheit der logischen Gesetze.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["verdad","conocimiento"]},{"i":"edmund-husserl-040","a":"edmund-husserl","t":"La sola mirada a cualquiera de las leyes lógicas, a su sentido propio y a la evidencia con que se la capta como verdad en sí, debería poner fin al engaño.","o":"Der bloße Hinblick auf irgend Eines der logischen Gesetze, auf seine eigentliche Meinung und die Einsichtigkeit, mit der es als Wahrheit an sich erfaßt wird, müßte der Täuschung ein Ende machen.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["verdad","conocimiento"]},{"i":"edmund-husserl-041","a":"edmund-husserl","t":"También la afirmación de que todo saber es meramente probable sería solo probablemente válida; y esta nueva afirmación, a su vez, de nuevo, y así sin fin.","o":"Auch die Behauptung, daß alles Wissen ein bloß wahrscheinliches ist, wäre nur wahrscheinlich giltig; diese neue Behauptung abermals und so in infinitum.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["verdad","incertidumbre"]},{"i":"edmund-husserl-042","a":"edmund-husserl","t":"Como cada grado siguiente imprime en algo el grado de probabilidad del anterior, deberíamos preocuparnos seriamente por el valor de todo conocimiento.","o":"Da jede folgende Stufe den Wahrscheinlichkeitsgrad der nächstvorhergehenden in Etwas her abdrückt, so müssten wir um den Werth aller Erkenntnis ernstlich besorgt sein.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["verdad","incertidumbre"]},{"i":"edmund-husserl-043","a":"edmund-husserl","t":"¿Equivale medir un pensar según las leyes lógicas a demostrar su origen causal según esas mismas leyes, como leyes naturales?","o":"Ist die Bemessung eines Denkens durch die logischen Gesetze etwa gleichbedeutend mit dem Nachweis seiner causalen Entstehung nach eben diesen Gesetzen als Naturgesetzen?","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento","conciencia"]},{"i":"edmund-husserl-044","a":"edmund-husserl","t":"Primero se confunden las leyes lógicas con los juicios (actos de juzgar) en los que pueden llegar a conocerse; es decir, los contenidos de la ley con los juicios mismos.","o":"Zunächst verwechselt man die logischen Gesetze mit den Urtheilen (Urtheilsacten) , in denen sie möglicher Weise erkannt werden, also die Gesetze als \"Urtheilsinhalte\" mit den Urtheilen selbst.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento","conciencia"]},{"i":"edmund-husserl-045","a":"edmund-husserl","t":"Los juicios de contenido legal actúan con frecuencia como motivos del pensar, que dirigen el curso de nuestras vivencias de pensamiento tal como lo prescriben esos contenidos.","o":"Insbesondere wirken die Urtheile gesetzlichen Inhalts des Oefteren als Denkmotive, welche den Gang unserer Denkerlebnisse so bestimmen, wie es eben jene Inhalte, die Denkgesetze, vorschreiben.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conciencia","conocimiento"]},{"i":"edmund-husserl-046","a":"edmund-husserl","t":"Si se confunde la ley con el juzgar, el conocer la ley, lo ideal con lo real, la ley aparece como una fuerza que determina el curso de nuestro pensar.","o":"Verwechselt man aber das Gesetz mit dem Urtheilen, Erkennen des Gesetzes, das Ideale mit dem Realen, so erscheint das Gesetz als eine bestimmende Macht unseres Denkverlaufs.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conciencia","conocimiento"]},{"i":"edmund-husserl-047","a":"edmund-husserl","t":"Fingimos un hombre ideal en el que todo pensar transcurre como lo exigen las leyes lógicas.","o":"Wir fingiren einen Idealmenschen, in dem alles Denken so von Statten geht, wie es die logischen Gesetze fordern.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conciencia","conocimiento"]},{"i":"edmund-husserl-048","a":"edmund-husserl","t":"Leyes causales según las cuales el pensar debe discurrir tal como podría justificarse según las normas ideales de la lógica, y esas normas mismas: eso no es, ciertamente, lo mismo.","o":"Causalgesetze, nach welchen das Denken so ablaufen muß, wie es nach den idealen Normen der Logik gerechtfertigt werden könnte, und diese Normen selbst - das ist doch keineswegs dasselbe.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conciencia","conocimiento"]},{"i":"edmund-husserl-049","a":"edmund-husserl","t":"Ninguna ley lógica implica un “matter of fact”: ni siquiera la existencia de representaciones, juicios u otros fenómenos del conocer.","o":"Kein logisches Gesetz implicirt einen \"matter of fact\", auch nicht die Existenz von Vorstellungen oder Urtheilen oder sonstigen Erkenntnisphänomenen.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento","conciencia"]},{"i":"edmund-husserl-050","a":"edmund-husserl","t":"No se advierte que un psicologismo consecuente obligaría a interpretar las leyes lógicas de un modo totalmente ajeno a su verdadero sentido.","o":"Man beachtet nicht, daß ein consequenter Psychologismus zu Interpretationen der logischen Gesetze nöthigen würde, welche ihrem wahren Sinn von Grund aus fremd wären.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento","conciencia"]},{"i":"edmund-husserl-051","a":"edmund-husserl","t":"Esa verdad está cargada de contenido fáctico; por tanto, no es en absoluto una ley en el sentido propio de la palabra.","o":"Diese Wahrheit ist mit Thatsächlichkeitsgehalt reichlich beschwert, sie selbst ist also nichts weniger als ein Gesetz im echten Sinne des Wortes.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["verdad","conocimiento"]},{"i":"edmund-husserl-052","a":"edmund-husserl","t":"Y así, todas las leyes de las ciencias exactas sobre hechos son leyes auténticas, pero, consideradas desde la teoría del conocimiento, solo ficciones idealizadoras, aunque ficciones con fundamento en la cosa.","o":"Und so sind alle Gesetze der exacten Wissenschaften über Thatsachen zwar echte Gesetze, aber erkenntnistheoretisch betrachtet nur idealisirende Fictionen - obschon Fictionen cum fundamento in re.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento","verdad"]},{"i":"edmund-husserl-053","a":"edmund-husserl","t":"A estas las reducimos luego a ciertos pensamientos exactos de carácter legal auténtico, y así logramos construir sistemas formalmente perfectos de teorías explicativas.","o":"Diese reduciren wir dann auf gewisse exacte Gedanken von echtem Gesetzescharakter, und so gelingt uns der Aufbau formell vollkommener Systeme erklärender Theorien.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento"]},{"i":"edmund-husserl-054","a":"edmund-husserl","t":"Si la legalidad auténtica es, como acaba de mostrarse, un mero ideal en el terreno del conocimiento de hechos, en cambio se realiza en el terreno del conocimiento “puramente conceptual”.","o":"Ist echte Gesetzlichkeit, wie soeben gezeigt wurde, ein bloßes Ideal im Gebiete der Thatsachenerkenntnis , so findet sie sich dagegen realisirt im Gebiete der \"rein begrifflichen\" Erkenntnis.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento","verdad"]},{"i":"edmund-husserl-055","a":"edmund-husserl","t":"Así, la experiencia nos proporciona una conciencia inmediata de la legalidad de nuestro espíritu.","o":"So verschafft uns die Erfahrung ein unmittelbares Bewußtsein der Gesetzlichkeit unseres Geistes.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conciencia","conocimiento"]},{"i":"edmund-husserl-056","a":"edmund-husserl","t":"Nadie dudará de que el conocimiento de las leyes lógicas, como acto psíquico, presupone la experiencia singular, y que tiene su base en la intuición concreta.","o":"Niemand wird bezweifeln, daß die Erkenntnis der logischen Gesetze, als psychischer Act, die Einzelerfahrung voraussetzt, daß sie ihre Grundlage hat in der concreten Anschauung.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conciencia","conocimiento"]},{"i":"edmund-husserl-057","a":"edmund-husserl","t":"Todo conocimiento “empieza con la experiencia”, pero por eso no “surge” ya de la experiencia.","o":"Alle Erkenntnis \"fängt mit der Erfahrung an\", aber sie \"entspringt\" darum nicht schon aus der Erfahrung.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["conocimiento"]},{"i":"edmund-husserl-058","a":"edmund-husserl","t":"Entre las leyes hay también algunas que se refieren a las verdades en general, en las que, por tanto, las verdades son los “objetos” regulados.","o":"Nun finden sich unter den Gesetzen auch solche, die sich auf Wahrheiten überhaupt beziehen, in denen also Wahrheiten die geregelten \"Gegenstände\" sind.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["verdad","conocimiento"]},{"i":"edmund-husserl-059","a":"edmund-husserl","t":"Es absurdo, sin embargo, llamar leyes de hechos a las leyes que valen para las verdades como tales.","o":"Es ist aber absurd Gesetze, die für Wahrheiten als solche gelten, als Gesetze für Thatsachen zu bezeichnen.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["verdad","conocimiento"]},{"i":"edmund-husserl-060","a":"edmund-husserl","t":"Pues una ley de este tipo atribuiría a ciertos hechos, llamados verdades, la aparición y la desaparición, y entre esos hechos debería encontrarse, como uno más, la propia ley.","o":"Da schriebe ein Gesetz gewissen Thatsachen, genannt Wahrheiten, Kommen und Gehen vor, und unter diesen Thatsachen sollte sich nun, als Eine neben anderen, das Gesetz selbst finden.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["verdad","conocimiento"]},{"i":"edmund-husserl-061","a":"edmund-husserl","t":"Y de manera parecida, si quisiéramos interpretar la ley de la verdad como ley de coexistencia, como algo temporal singular y a la vez regla general para todo lo que existe en el tiempo.","o":"Und ähnlich, wenn wir das Wahrheitsgesetz als Coexistenzgesetz deuten wollten, als zeitlich Einzelnes und doch als allgemeine Regel für alles und jedes zeitlich Seiende maßgebend.","l":"de","ob":"Investigaciones lógicas","an":"1900","u":"","te":["verdad","conocimiento"]}],"ruta":"/recursos/voces-que-nos-habitan/","temasRuta":"/recursos/voces-que-nos-habitan/temas/","escuelas":[["cc","Conductuales y cognitivos"],["des","Desarrollo y apego"],["fil","Filosofía"],["ini","Los comienzos"],["ori","Tradiciones orientales"],["pa","Psicoanálisis"]],"epocas":[["clasico","Clásicos"],["moderno","Modernos"]]};
